            { id = 2973868, text = "The Azshari are vile summoners, calling upon the tides to do their bidding." },
            { id = 2976277, text = "The Naga will never break us." },
            { id = 2973864, text = "The Naga. I must find refuge." },
            { id = 2973869, text = "Those who wield the dark magic of the Void call themselves the Shirakess." },
            { id = 2973866, text = "We have you to thank for this brief respite. Our clan is in your debt." },
        } },
    } },
    { who = "Adderis", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1941176, text = "FOR THE LAMPYRE!" },
            { id = 1941178, text = "SHATTERED LIKE GLASS!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2027249, text = "AAAGH!" },
            { id = 2027248, text = "GRRR!" },
            { id = 2027250, text = "HMMM!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1941177, text = "The sounds will take me." },
        } },
    } },
    { who = "Addie Fizzlebog", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1417196, text = "I don't think Hemet himself could've taught me better. I'm happy to hunt with you anytime." },
            { id = 1407492, text = "I need to recover. You go on." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1407485, text = "Let's get him!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1407488, text = "That was exciting!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1504308, text = "How's it going?" },
            { id = 1407484, text = "I'm a real hunter now!" },
            { id = 1407486, text = "I've got this one!" },
            { id = 1407491, text = "Oh... That... Hurts... So much!" },
            { id = 1407490, text = "Ugh. Don't worry about me. I'll catch up. I think." },
            { id = 1407487, text = "We did it!" },
            { id = 1504307, text = "Well, hello there!" },
            { id = 1407489, text = "You better stay dead!" },
        } },
    } },
    { who = "Adelgonn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5707432, text = "As you will." },
            { id = 5707428, text = "Go where you will." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5707430, text = "Come back and share your experiences." },
            { id = 5707433, text = "Follow what drives you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5707431, text = "Forge your own path." },
            { id = 5707435, text = "Heed the call of the unknown." },
            { id = 5707440, text = "Speak freely and honestly." },
            { id = 5707438, text = "The Unbound welcome all." },
            { id = 5707437, text = "Yes, I am the former Stoneward." },
        } },
    } },
    { who = "Admiral Svirax", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1685490, text = "WAS THIS YOUR PLAN?!" },
            { id = 1685488, text = "WHY LET MY VESSELS BLAST YOU APART, WHEN I CAN DESPATCH YOU MYSELF?" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1685486, text = "This is one engagement you will not walk away from!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1685491, text = "All vessels, converge on my position!" },
            { id = 1685485, text = "Canons, begin firing on my mark!" },
            { id = 1685487, text = "How was I outmatched?" },
            { id = 1685489, text = "You've left your flanks exposed!" },
        } },
    } },
    { who = "Advisor Melandrus", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1355006, text = "You can't counter what you can't see!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1355007, text = "I will speed you towards your demise!" },
            { id = 1355014, text = "Never heard my blade coming." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1355009, text = "The wind slices to the bone!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1355013, text = "Another victim of my artistry." },
            { id = 1355011, text = "Bleed for the Grand Magistrates!" },
            { id = 1355010, text = "Death by a thousand cuts!" },
            { id = 1355012, text = "Elisande! Forgive me!" },
            { id = 1355004, text = "Finally! I'll make this quick!" },
            { id = 1355005, text = "How dare you interrupt your betters!" },
            { id = 1355008, text = "If you blink, you bleed!" },
            { id = 1355015, text = "Let your names be forgotten." },
        } },
    } },
    { who = "Advisor Vandros", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1503798, text = "YEAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1332791, text = "I am a conduit of the Nightwell's glorious power! I am Nightborne!" },
            { id = 1332789, text = "I have not survived for ten thousand years just to fall to a swarm of rats!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1332783, text = "Find the vermin and bring me their heads. Leave no stone unturned." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1332781, text = "For the glory of Elisande!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1332775, text = "Alas, blind courage only triumphs in the fairy tales." },
            { id = 1332795, text = "Enough! You little beasts are getting out of hand!" },
            { id = 1332793, text = "Have you vermin ever witnessed such raw power? I think not." },
            { id = 1332785, text = "My, my. Someone has made quite a mess down here. It has been too long since we've purged these catacombs of refuse. It appears we have a rat infestation." },
            { id = 1332779, text = "So brave, but so short-sighted." },
            { id = 1332787, text = "The Grand Magistrix will have your heads for this!" },
            { id = 1332777, text = "Think of this as a mercy killing." },
        } },
    } },
    { who = "Aegira", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1406466, text = "I hope Melba's looking upon me now. How long have I waited for vengeance?" },
            { id = 1406465, text = "My master Melba taught me everything she knew, including the fighting techniques of ancient vrykul-brewer kings and queens." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1406456, text = "Yes, now that's strong, but my master's was still better." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1406457, text = "Eh, good flavor, but it's as weak as rainwater." },
            { id = 1406464, text = "Rideshall fortress lies to the south. I will meet you there. Slyffna flies faster than the wind." },
            { id = 1406476, text = "Still need to get this Saudi excuse for a wagon fixed. Where is Yofang with that ax, a lace leaf?" },
            { id = 1406477, text = "The black brew is running low, Slifna. If Melba were still here, we would never run dry!" },
            { id = 1406475, text = "The golden apple is sitting quite nicely, Slifna." },
            { id = 1406455, text = "This is the right place. We will find the stolen recipe here." },
            { id = 1406458, text = "Ugh, Mother of Odin, that tasted worse than Runehorn curd!" },
            { id = 1406479, text = "You're about two years too late, my friend. Melba is dead." },
        } },
    } },
    { who = "Aegwynn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1591351, text = "This hammer forged ancient wonders and shaped the earth itself. Today, it shatters the bonds of fate that seek to crush us all." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1591272, text = "I sealed each level of this temple so that no invader could descend into its depths. I never anticipated that the Legion would find another way to breach its dark heart." },
            { id = 1591274, text = "My protective wards now bar you away. Each seal can only be opened with one of the Pillars of Creation. Be warned, the demons will stop at nothing to prevent your advance." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1591355, text = "From this stone flowed rivers and seas, the very lifeblood of Azeroth. Today, it washes clean the darkness that scars our world." },
            { id = 1591353, text = "My Echo has guided you as far as it can, champions. In life, I shoulder too many burdens alone, and such hubris cost me dearly. Only by standing together can you overcome the darkness ahead. Farewell." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1591474, text = "In ages past, this shield defended the young world soul against madness and corruption. Today, it serves those who fight for Azeroth." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1591359, text = "The Pillars of Creation are in place. Return to the Cathedral, and I will reveal the ancient secret this temple holds." },
            { id = 1591357, text = "These tears of perfect beauty embody the dream of what our world could be. Today, they purify your hearts for the battle to come." },
        } },
    } },
    { who = "Aelric Leid", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5782863, text = "Yes! YES! NIGHT FALLS! RENALASH BEGINS!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5782862, text = "Join me in the shadows, bring the harbinger joy!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5782796, text = "and your failure at Dalaran." },
            { id = 5782798, text = "Ha Ha Ha ha" },
            { id = 5782871, text = "Harbinger! Do not forsake me!" },
            { id = 5782870, text = "She has taken an interest in you." },
            { id = 5782794, text = "The Harbinger has whispered to me of your arrival." },
            { id = 5782861, text = "The Harbinger manipulates the Kobes through their hunger and the Arathi through their fear." },
            { id = 5782869, text = "The Harbinger spoke of you." },
        } },
    } },
    { who = "Aelthalyste", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1581871, text = "YOU BROUGHT THIS ON YOURSELF!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1581869, text = "You shall be purged from this world!" },
            { id = 1581868, text = "You will feel my wrath!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1581865, text = "I am here to help." },
            { id = 1581873, text = "I will need just a moment." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1581866, text = "Our enemies will drown in shadows!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1581862, text = "You made a wise choice. We will accomplish much together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1581870, text = "The void awaits!" },
            { id = 1581863, text = "What surprises await us?" },
            { id = 1581864, text = "You need not do this alone" },
            { id = 1581867, text = "Your end is nigh" },
            { id = 1581872, text = "Your struggle is over" },
        } },
    } },
    { who = "Aelyith", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1389419, text = "Did that dragon send you, Interloper? Or was it that beggar, Runus?" },
            { id = 1389420, text = "No matter. Soon you will all kneel before Azuna's new prince!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1242737, text = "I need more power!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1389421, text = "Wait! What are you doing?! My siphons!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1389417, text = "Here then, have a taste!" },
            { id = 1389415, text = "Interloper! You're here to steal my mana, aren't you?" },
            { id = 1389418, text = "Picking off my lieutenants? I suppose you think you're clever." },
            { id = 1242743, text = "What's this? Have the peasants come to grovel before their prince?" },
            { id = 1387787, text = "Yes, yes! Surrender your power, dragon! These pools belong to the Nightborne now!" },
            { id = 1389422, text = "You low-born dirt! You don't know who you're dealing with! Mwahahaha! AHAHAHA!" },
            { id = 1242739, text = "You rats aren't fit to touch the hem of my robe!" },
        } },
    } },
    { who = "Aeonormu", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4673410, text = "I will make time for you." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 4673412, text = "Until next time." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4673411, text = "Consider all the timelines." },
            { id = 4674402, text = "It is a long story." },
            { id = 4673407, text = "They say cautious. I say wise." },
            { id = 4673414, text = "Time is passing." },
            { id = 4674401, text = "Ugh. When am I?" },
            { id = 4673409, text = "We cannot lose more time." },
            { id = 4673413, text = "We must find the time." },
            { id = 4674403, text = "We were defending the Temporal Conflux when fissures in time suddenly opened and pulled us through." },
            { id = 4673408, text = "What time is it?" },
        } },
    } },
    { who = "Aethanel", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2924635, text = "FEEL THE STING OF LIGHTNING!" },
            { id = 2924634, text = "WHERE ARE YOU, MY BELOVED?!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2924631, text = "I cannot stand to look at you, Serannus!" },
            { id = 2924637, text = "My heart is finally free!" },
            { id = 2924632, text = "My love, never leave my sight again!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 2924630, text = "Ceramis! Begone from my games!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2924633, text = "I've lost you, Seranas! Return to me!" },
            { id = 2924636, text = "Storms, heed my call!" },
        } },
    } },
    { who = "Aethas Sunreaver", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1370273, text = "You have my thanks, friend." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1370274, text = "I once knew Leandra Sunstrider, a distant relative of King Anasterian. Though she bore the Sunstrider name, in truth her branch of the family held no claim to the throne." },
            { id = 1370286, text = "I remember who you were, but the creature before me now is but a walking corpse!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1370268, text = "Good luck, hero!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370256, text = "Esteemed Archmages of the Council, may I present to you the bearer of Felo'melorn." },
            { id = 1370285, text = "I'm with you, hero. I'll hold Leandred Bay. Focus on destroying that monster of hers." },
            { id = 1370278, text = "Indeed I do, and nothing happens in that citadel unless its master wills it. I would not be surprised to learn he had a hand in this." },
            { id = 1370271, text = "Precisely why I'm here if I can't return to my former position then perhaps the council with at least consider Restoring my access to the city as a show of good faith. I have information to offer" },
            { id = 1370269, text = "Thank you both for meeting me in such an inhospitable location. I assure you that if I were able to meet you in Dalaran, I would." },
            { id = 1370267, text = "The portal will take you directly inside Icecrown. Hurry, it won't last long. I'll follow after you as soon as I can." },
        } },
    } },
    { who = "Agapanthus", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1242751, text = "URGENT MESSAGE FOR SYNEGOS!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1270849, text = "GAH!" },
            { id = 1270848, text = "HMPH!" },
            { id = 1270845, text = "OOF!" },
            { id = 1270844, text = "UGH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1242749, text = "I feared we might lose that one. He was so weak when I found him. Pick him up and take him to Senegos!" },
            { id = 1242747, text = "My keepers are overrun! We will require aid!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1242753, text = "The nightfallen have assaulted the whelplands!" },
            { id = 1242745, text = "These four whelplings need to be treated with ley crystals immediately!" },
        } },
    } },
    { who = "Agatha", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1585797, text = "Even now, my Shayad, tempt your weak-willed mages! Your allies will surrender willingly to the Legion!" },
            { id = 1585795, text = "I will hunt you down! Mark my words!" },
            { id = 1585792, text = "My, you are a strong one. Breaking you will be ever so fun." },
            { id = 1585796, text = "You are too late, hero. Levia's power is mine. Using her knowledge, my minions will infiltrate the Kirin Tor and dismantle it from the inside." },
            { id = 1585794, text = "You shattered my illusion! Insolent wretch!" },
            { id = 1585800, text = "You'll pay for this, you'll pay!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1585791, text = "Come then, hero. Entertain me." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1585798, text = "But first, you must be punished for taking away my little pet! Attack my pretties!" },
            { id = 1585793, text = "No! It cannot be!" },
            { id = 1585799, text = "No! My pretties!" },
            { id = 1585789, text = "So the Kirin Tor wishes to send me more playthings?" },
            { id = 1585790, text = "While Levia has kept me quite...satisfied, it would be rude of me to turn down such a gift." },
        } },
    } },
    { who = "Agent Jones", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1452110, text = "I told you already, I never miss." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1452104, text = "Amber Kiernan was one of our own. I still can't believe we had to kill her." },
            { id = 1452102, text = "These drop boxes are tricky. I've almost got it." },
        } },
    } },
    { who = "Agent Smith", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1452100, text = "How much longer is this going to take?" },
            { id = 1453041, text = "Keep your voice down. There's someone here." },
            { id = 1453047, text = "Quiet down, someone is coming." },
            { id = 1453045, text = "Shh, keep your voice down." },
            { id = 1453043, text = "Shh, we've got company. Act natural." },
            { id = 1452098, text = "We should have killed her back in Sittering Bay. Doing the hit in Dalaran was too risky. We can't afford witnesses." },
            { id = 1452106, text = "When the orders come from Master Sha himself, you don't ask questions." },
            { id = 1452108, text = "You're sure you got her, right? We can't afford to mess this up." },
        } },
    } },
    { who = "Aggra", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 543390, text = "Go with honour." },
            { id = 543397, text = "Stay strong, friend. You know as well as I do, they'll be no help for us within the Firelands." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 543386, text = "He must embrace them and find balance, or this curse will never end." },
            { id = 543400, text = "May the spirits watch over you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 543393, text = "A final vision. Ancestors... Could those be... Our children? This was his deepest desire. To be a father?" },
            { id = 543394, text = "Another vision. I see Go'el, but... it's... it's me. Was I his deepest desire? A mate with which to share his life, his burdens and his joys?" },
            { id = 543408, text = "Mokrah" },
            { id = 543389, text = "Quickly friend, Goel should be just below." },
            { id = 543399, text = "Quickly! Reactivate the totem!" },
            { id = 543449, text = "Speak your mind." },
            { id = 543395, text = "There! Look at him. Frozen in stone. Unmoving. Unfeeling. That look on his face. The resolve. The stubbornness. He gets it when he digs his heels in." },
            { id = 543396, text = "You did what you thought best, Go'el. Fight these doubts. They're devouring your heart." },
        } },
    } },
    { who = "Aggramar", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1679488, text = "ALL WILL DIE IN MY WAKE!" },
            { id = 1679485, text = "NONE CAN STAND AGAINST TASCHELEK!" },
            { id = 1679479, text = "STAND AND DIE!" },
            { id = 1679477, text = "THE FLAMES WILL CONSUME YOU!" },
            { id = 1679484, text = "THE POWER OF CAESARETT WILL CONSUME YOU!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1679481, text = "You may have withstood the flames, but you will not withstand my fury!" },
            { id = 1679482, text = "Your modicum of skill will be insufficient to save you!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1679478, text = "Let the flesh be seared from your bones!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1679487, text = "Drown in flames!" },
            { id = 1679483, text = "Tehsalad's power is unleashed!" },
            { id = 1679480, text = "There is no escape!" },
        } },
    } },
    { who = "Agronox", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1589299, text = "FARDER FOR THE COMPOST HEAT!" },
            { id = 1589300, text = "FOOL FOR THE WORDS!" },
            { id = 1589295, text = "I WILL CRUSH THE LIGHT FROM YOU!" },
            { id = 1589298, text = "YOU DISTURB NATURE'S PERFECTION!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1589296, text = "My tendrils will take you!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1589293, text = "Feel your throat tighten!" },
            { id = 1589302, text = "Mortals seldom appreciate troll beauty." },
            { id = 1589303, text = "Now I shall feed the soil." },
            { id = 1589297, text = "These ancient grounds are not for you!" },
            { id = 1589301, text = "They did not show the proper respect to Major." },
            { id = 1589294, text = "This breath will be your last!" },
            { id = 1589292, text = "Yes, my precious ones, the fell has brought out our true beauty!" },
        } },
    } },
    { who = "Ahnzon", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5146048, text = "DON'T FALL APART!" },
            { id = 5146074, text = "HUNGRY! HUNGRY! HUNGRY!" },
            { id = 5146058, text = "I WAKE! I WAKE! HAHAHA!" },
            { id = 5146080, text = "LIGHTNING TAKES YOU!" },
