        { name = "Conversation", family = "Feelings", lines = {
            { id = 4659224, text = "Are you a friend?" },
            { id = 4659219, text = "Be careful, it's dangerous out there." },
            { id = 4659222, text = "It's good to meet new faces." },
            { id = 4659227, text = "Sometimes I call my fishing pole my thwapping stick. Want to find out why?" },
            { id = 4659221, text = "Thank you for your help!" },
            { id = 4673754, text = "The only thing they took was my friends' lives." },
            { id = 4659225, text = "The wilds have brought you here." },
