    { who = "Akolik", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 901767, text = "I have come to return you to Gros! Surrender your flesh to me!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 901759, text = "Stop, my brothers! Do you not see the beast of burden before you?" },
