    { who = "Akunda", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1998248, text = "The Renishu have poisoned my children. They are weak and clinging to life. Use my power to save them, as you have saved me." },
            { id = 1998249, text = "You will forever be welcome within these walls." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1998256, text = "I am the storm." },
            { id = 1998247, text = "I grow weaker by the moment you must help me before it is too late." },
            { id = 1998258, text = "My dear child, at last you can hear me. A traitor lurks within our temple." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1998253, text = "Do not fear the storm." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1998257, text = "All are welcome here." },
            { id = 1998250, text = "At last. I am free. Thank you, champion." },
            { id = 1998252, text = "Clarity comes after the storm." },
            { id = 1998254, text = "Let the storm guide you." },
            { id = 1998251, text = "The storm is calling." },
            { id = 1998255, text = "What brings you here?" },
        } },
    } },
    { who = "Akunda the Exalted", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2026183, text = "HAHA!" },
            { id = 2026182, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1998324, text = "You are ready to hear Akunda's words, though it must be done alone. Head to the altar and pray when you are ready." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1998316, text = "Fool! You should have run away when you had the chance. The power of Akunda will be mine!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1998318, text = "Welcome, Akunda the Courageous!" },
            { id = 1998319, text = "Welcome, Akunda the Nimble." },
            { id = 1998320, text = "Welcome, Akunda the Serene." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1998321, text = "Akunda will only enter your mind if you've been cleansed." },
            { id = 1998322, text = "Do you seek redemption? Akunda welcomes all." },
            { id = 1998317, text = "Gathering the reagents needed for your communion is the first step towards redemption." },
            { id = 1998323, text = "You'll only find Akunda here. Those who share his name are the only ones permitted to enter his hall." },
        } },
