    { who = "Alchukla", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 798091, text = "YOU WILL BE PUNISHED! YOUR LIFE... ...ALESSON... ...INFUTILITY!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 798087, text = "I was chosen! My blood burns with his power!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 798073, text = "Turn away, weaklings. This be the realm of the Thunder King!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 798075, text = "Destroy them, me brothers!" },
