    { who = "Aldalil", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4082391, text = "You are quite welcome, whoever you are. Now, we are in need of those signatures." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4082390, text = "Wait, who is that? Where is Basim?" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4082392, text = "Ah, yes, thank you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4082389, text = "A friend here may be of help in acquiring Zou's signature." },
            { id = 4082388, text = "A simple matter. In return, we ask only for Kattel Zai's signature." },
            { id = 4082399, text = "Apologies, Almeiser. We desperately need your signature." },
            { id = 4082393, text = "Mises Oasis, the most intoxicating establishment in Tazavesh. Gaining the owner's favor will secure cartel house signature." },
            { id = 4082395, text = "No matter. There are many doors to success. I have friends nearby who may be of assistance." },
            { id = 4082397, text = "Oh, my sir, it is a pleasure. My friends and I are here to..." },
            { id = 4082398, text = "Our path reveals itself, perform well, and our Mice's favor is ours." },
            { id = 4082396, text = "Someone in this market must possess what we seek." },
            { id = 4082394, text = "Zogran, surely our friendship has ascended such necessity." },
        } },
    } },
    { who = "Alexander Treadward", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1956593, text = "I will always be here, dear Lucy." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1956591, text = "At last, I can leave the memories of this place behind." },
            { id = 1956583, text = "Fair winds, friend." },
            { id = 1956584, text = "Keep your sails true." },
            { id = 1956589, text = "Lucy, you've come! Wait, you're not Lucy!" },
            { id = 1956585, text = "May the tides favor you" },
            { id = 1956588, text = "Oh, hello there." },
            { id = 1956592, text = "Thank you, friends." },
            { id = 1956587, text = "What do you need?" },
            { id = 1956590, text = "Why have you come here?" },
        } },
    } },
    { who = "Alexandros Mograine", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3622560, text = "CREXUS'S WILL BE DONE" },
            { id = 3733909, text = "HONORLESS COWARD!" },
            { id = 3622573, text = "I AM NOT ABOVE TURNING YOU TO ASH!" },
            { id = 3733906, text = "I WILL BURY MY BLADE IN YOUR SKULL, TRAITOR! FOR KREXUS!" },
        } },
        { name = "Battle roars", family = "Fighting", lines = {
            { id = 3773039, text = "ARGH!" },
            { id = 3773031, text = "GRRR!" },
            { id = 3773037, text = "HMMM!" },
            { id = 3773035, text = "HUH!" },
            { id = 3773033, text = "UGH!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3773053, text = "HA!" },
            { id = 3773061, text = "HAH!" },
            { id = 3773055, text = "HEH!" },
            { id = 3773045, text = "HIYAH!" },
            { id = 3773063, text = "HOO!" },
            { id = 3773049, text = "HUUU!" },
            { id = 3773041, text = "HYAH!" },
            { id = 3773051, text = "PHEW!" },
            { id = 3773043, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 543514, text = "Darion Mograine! You are barely of age to hold a sword, let alone battle the undead hordes of Lordaeron. I could not bear losing you. Even the thought..." },
            { id = 3622558, text = "I will not suffer this corruption any longer!" },
            { id = 3733863, text = "Maw Walker, you have returned!" },
            { id = 543513, text = "My son, there will come a day when you will command the Ashbringer and with it meet out justice across this land. I have no doubt that when that day finally comes, you will bring pride to our people and that Lordaeron will be a better place because of you. But my son, that day is not today." },
            { id = 3733908, text = "You cannot win, Vyraz. You are outnumbered!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3622563, text = "I await the next battle." },
            { id = 3730913, text = "I can scarcely believe it! The mantle of the Primus!" },
            { id = 3622572, text = "I have little patience for these games!" },
            { id = 3733892, text = "I will never forget your sacrifice, never!" },
            { id = 3622567, text = "My blade is ready!" },
            { id = 543517, text = "My son, my dear, beautiful boy." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3730909, text = "Come, Maw Walker. Let us search the fallen Margrave stores." },
            { id = 543516, text = "Do not forget." },
            { id = 4072391, text = "Forward Necrolords! Burn these traitors to ash!" },
            { id = 3733896, text = "Go on, Maw Walker. I... would like a moment to reflect." },
            { id = 3730912, text = "Wait, this could be something. What say you, Maw Walker?" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3773101, text = "AAARGH!" },
            { id = 3773117, text = "BOO!" },
            { id = 3773103, text = "HOHOHO!" },
            { id = 3773121, text = "OH!" },
            { id = 3773115, text = "OOF!" },
        } },
        { name = "Death cries", family = "Hurt and dying", lines = {
            { id = 3773085, text = "AHHH!" },
            { id = 3773081, text = "DAAAHHH AAAHHH..." },
            { id = 3773079, text = "GAH GAHHH!" },
            { id = 3773087, text = "NO!" },
            { id = 3773083, text = "YEAH UGHHH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3622561, text = "Ambition is nothing without honor." },
            { id = 3733873, text = "An ambush! Cut them down!" },
            { id = 4062773, text = "And I am proud of you, my son." },
            { id = 3622557, text = "Ashes to ashes." },
            { id = 3622571, text = "Cease your prattling!" },
            { id = 3733898, text = "Darion, after all this time..." },
            { id = 3622570, text = "Even in death we must fight." },
            { id = 3728864, text = "Fight until our last! We will not go gently into the night!" },
            { id = 3733887, text = "Forgive me. Let us continue onward." },
            { id = 3728884, text = "Give up this madness! The Primus would not stand for this!" },
            { id = 3730910, text = "Hmm. Nothing of much value to us here." },
            { id = 3733860, text = "If he is of your blood, Draka, then I have no doubt that he did." },
            { id = 3733866, text = "Important matters remain at hand, Maw Walker." },
            { id = 559658, text = "Infidels! They must be purified!" },
            { id = 3733864, text = "It is a great honor to wield the power of the Primus." },
            { id = 3622559, text = "It is in death that we are truly tested." },
            { id = 3730906, text = "Lead the way, Baroness." },
            { id = 3728878, text = "Let us see this done!" },
            { id = 3733869, text = "Neither shall we." },
            { id = 543507, text = "Nothing could have kept me away from here, Darion. Not from my home and family." },
            { id = 3622565, text = "Orders?" },
            { id = 3733890, text = "Please, let us move on." },
            { id = 3733888, text = "Renault, my oldest, my demise." },
            { id = 3733899, text = "Son." },
            { id = 3731935, text = "That beast is incinerating our forces! We'll be overrun!" },
            { id = 3735781, text = "That blast utterly obliterated her!" },
            { id = 3733872, text = "The bulwark is unguarded. Stay vigilant." },
            { id = 3733910, text = "Then we have no time to waste!" },
            { id = 3729888, text = "There will be time for us to speak later, my son. I swear it." },
            { id = 3622569, text = "This land festers. We must cauterize the wound." },
            { id = 3622562, text = "Trample our enemies! Leave nothing but ash." },
            { id = 3733904, text = "VIRAS! Show yourself!" },
            { id = 3622566, text = "We have little time to waste." },
            { id = 3728851, text = "We have our orders. Fight well, Kyrian of Bastion!" },
            { id = 3733874, text = "We have secured the perimeter. Let us regroup with the Paragon." },
            { id = 3728688, text = "We shall see soon enough." },
            { id = 3733907, text = "We will avenge him, here and now!" },
            { id = 3733875, text = "We will see it done, Paragon." },
            { id = 3622564, text = "What do you need?" },
            { id = 3622568, text = "What is my task?" },
            { id = 3728876, text = "Xandria, are you prepared for the true fight?" },
            { id = 3728895, text = "Xandria, I implore you to take Garmel's heart." },
        } },
    } },
    { who = "Alexstrasza", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 543520, text = "AH!" },
            { id = 543528, text = "AHHH!" },
            { id = 543526, text = "HIYAH!" },
            { id = 543521, text = "HUAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4703378, text = "Treasure the gift you have been given." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2976186, text = "Of course, Marithra. You may always speak openly with me." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 543530, text = "HUH!" },
            { id = 543529, text = "OH!" },
            { id = 543525, text = "OW!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2976187, text = "We were sisters. The only two of our brood to survive. Inseparable ever since our birth." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2976192, text = "Accept this gift. May it light a flame within you to burn bright through the darkest times." },
            { id = 575441, text = "All life is to be treasured." },
            { id = 4703382, text = "Do you think I have big mom energy?" },
            { id = 4703377, text = "Fair skies and strong winds." },
            { id = 2976196, text = "From pain we draw strength." },
            { id = 575439, text = "It is the fires within that burn the brightest." },
            { id = 2976191, text = "Long has my flight protected all life on Azeroth, and so shall we continue for as long as we draw breath." },
            { id = 2976190, text = "Neither did she. None of the aspects did. But we rose to the challenge, as will you. Have faith in yourself, Marithra." },
            { id = 4703376, text = "Safeguard all life." },
            { id = 2976188, text = "Some believed that as the smallest among us, she was also the weakest. They were wrong." },
            { id = 2976194, text = "The balance must be maintained." },
            { id = 2976195, text = "The Red Dragonflight will protect this world." },
            { id = 575437, text = "Yes, Champion." },
            { id = 2976189, text = "Ysera was strong in a way most could not understand, but hers was a strength on which Azeroth depended." },
        } },
    } },
    { who = "Alexstrasza the Life Binder", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4609597, text = "Wrathion, you have my gratitude." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4609609, text = "I would have expected you to care more for the protection of helpless eggs, Rathion." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3527591, text = "And Champion, please tell my sister that she is sorely missed, fondly remembered, and deeply loved." },
            { id = 3527588, text = "We were sisters, hatched from the same clutch, inseparable since birth." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4609605, text = "For now, we must remain at the Life Pools and safeguard our future." },
            { id = 4609601, text = "Of course we will, after we see to the safety of the eggs." },
            { id = 4609603, text = "Oh, you do not know her as I do, young one." },
            { id = 3527590, text = "She gave me a gift when we first became aspects. Take it with you and save your friend." },
            { id = 4609604, text = "She is an unpredictable foe." },
            { id = 4609598, text = "Your aid was unexpected, but appreciated." },
            { id = 3527589, text = "Ysera speaks of Kory Alstrals, whom I loved dearly, but I loved none more than her." },
            { id = 3527587, text = "Ysera, it brightens my heart to know her death was not an end, but a new beginning." },
        } },
    } },
    { who = "Algalon the Observer", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 543577, text = "AHEM!" },
            { id = 543579, text = "HUH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 543586, text = "Your actions are illogical. All possible results for this encounter have been calculated. The Pantheon will receive the Observer's message regardless of outcome." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 543591, text = "I do what I must." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 543605, text = "Do not worry about my fate, Bronzen. If the signal is not transmitted in time, re-origination will proceed regardless. Save your world." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 543582, text = "HEH!" },
            { id = 543571, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 543606, text = "It is in the universe's best interest to re-originate this planet should my analysis find systemic corruption. Do not interfere." },
            { id = 543567, text = "Loss of life unavoidable." },
            { id = 543581, text = "Stand back, mortals. I'm not here to fight you." },
            { id = 543570, text = "Translocation complete. Commencing planetary analysis of Azeroth." },
        } },
    } },
    { who = "Algromon", tier = "character", groups = {
