    { who = "Alleria Windrunner", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1678527, text = "Hold Thas'dorah proudly, champion. Know that you have proven worthy of it." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1678523, text = "I would have words with you, Huntmaster." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1678511, text = "Despite our best efforts, the void continues to seep in through the cracks. Seek out the Army of the Light and use their blessings to banish the darkness once again." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1678528, text = "Cirdren and Daneth are safe as well." },
            { id = 1678525, text = "It is clear you wield Daz'Dorah with skill and finesse. You bring honor to the bow and to the memory of those who carried it before you." },
            { id = 1678526, text = "There may come a day when I will have need of my family weapon once again. But for now, at least, I have a different path to follow." },
            { id = 1678524, text = "Vereesa told me you accompanied her on the mission to Niskara, that you risked your own life to rescue me, and prevented her from falling into the Inquisitor's trap." },
            { id = 1678512, text = "We may not be able to restore their sanity, but at least we can prevent more from succumbing." },
        } },
    } },
    { who = "Alliance Commander", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1051008, text = "Do you want to die here? Move!" },
            { id = 1051004, text = "It's reviving the little ones!" },
            { id = 1051003, text = "Quickly! Draw it towards the flames!" },
            { id = 1051006, text = "That doesn't look good!" },
            { id = 1051009, text = "The portal is lost! We must stop this beast before it can escape!" },
            { id = 1051005, text = "The vines are overtaking everything!" },
            { id = 1051007, text = "We are lost! It's pushing us back!" },
            { id = 1050999, text = "We've got its attention!" },
        } },
    } },
    { who = "Alliance General", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1361105, text = "Astounding! Your mastery over demons has given you great power!" },
            { id = 1361113, text = "Summon your Doomguard now!" },
            { id = 1361115, text = "While greater demons like infernals and Doomguards cannot be controlled for long, you can summon one to your side for short periods of time to fight for you." },
            { id = 1361114, text = "You summon Doomguard now to summon this demon." },
        } },
    } },
    { who = "Allianceworker", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1050989, text = "I am ready for that drink." },
            { id = 1050988, text = "My back is aching." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1050984, text = "Ah, good afternoon, Commander." },
            { id = 1050991, text = "Good to see you, Commander." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1050985, text = "Been a long day, Commander." },
            { id = 1050983, text = "Good morning, Commander!" },
            { id = 1050990, text = "Is it just me, or is this work never done?" },
            { id = 1050992, text = "Just a few whacks more." },
            { id = 1050987, text = "Keep up the good work, Commander." },
        } },
    } },
    { who = "Alodi", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1382439, text = "Take my power, champion! Banish this demon back from whence it came!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1382452, text = "And what is your plan?" },
            { id = 1388649, text = "as the Council commands." },
            { id = 1397450, text = "Filthy demons. They feed upon the blue dragonflight. Have all the defenders fallen?" },
            { id = 1382445, text = "It is good to see you, old friend, though I wish it were under better circumstances." },
            { id = 1388656, text = "May the Guardians protect you." },
            { id = 1388642, text = "So be it." },
            { id = 1382446, text = "The Dreadlord's defeat is only temporary. Once he regains his strength in the Twisting Nether, he will seek the Forge again." },
            { id = 1388679, text = "The Guardian stands ready." },
            { id = 1382449, text = "The Hall of the Guardian. It pains me to see it in such disrepair." },
            { id = 1388665, text = "Trust the wisdom of the Council." },
        } },
    } },
    { who = "Alonsus Faol", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1388191, text = "I will hide in shadows no longer." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1388194, text = "I wonder what would happen if you split someone into pure light and pure void. Interested in volunteering?" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1390885, text = "The fine start. The Kirin Tor have given us a permanent portal to Dalaran, as well as one that will bring you from the city back to Netherlight. Good luck!" },
            { id = 1388188, text = "Until next time" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1388195, text = "Baud, I could arrange discourse with a shadow fiend." },
            { id = 1388190, text = "May light and shadow guide you." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1388193, text = "We will accomplish much together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1388192, text = "how may I help you" },
            { id = 1388189, text = "Let us get to work." },
            { id = 1390882, text = "Look! Our hero has returned!" },
            { id = 1390877, text = "With that we are in agreement. Now, speak with Velen. He has an... interesting matter to discuss with you." },
            { id = 1388196, text = "You do know there's an invasion going on, right?" },
        } },
    } },
    { who = "Alora", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1385565, text = "I... I'm alive! By the light, I live again!" },
