    { who = "Althaea", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 6023923, text = "Do you have a passion for fashion?" },
            { id = 6023929, text = "You have one minute left to vote!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 6023927, text = "Come check out the theme and put on an outfit that you think matches it best." },
