    { who = "Aluneth", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1396767, text = "MY ESSENCE WILL NOT BE CONTROLLED AGAIN!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1396765, text = "Come on child, let us wreak havoc upon your foes, and I shall see what you are made of." },
            { id = 1396769, text = "You are not as powerful as she who came before! You cannot succeed!" },
            { id = 1396763, text = "You fancy yourself as worthy to wield me as the previous Guardian? You are but a child to me." },
