        { name = "Boasts", family = "Menace", lines = {
            { id = 1396766, text = "I will not be contained!" },
            { id = 1396768, text = "I will not succumb to your paltry magics!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1396764, text = "You foolishly think you can control its power. So be it." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1396773, text = "Together, we will do great things." },
