    { who = "Amaranthis", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5343398, text = "You cannot even save yourselves." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5321031, text = "Enough bickering! Our combined efforts will expel them from the dream." },
            { id = 5343397, text = "No one defies the Emerald Council!" },
            { id = 5343401, text = "Snicket, take you!" },
            { id = 5321032, text = "The dream will never yield." },
            { id = 5343402, text = "The dream will not tolerate you." },
            { id = 5343399, text = "Those who threaten the dream will fall!" },
            { id = 5321028, text = "Well, it gives us no pleasure. Your transgression must be punished." },
            { id = 5343400, text = "While the council stands, I cannot fall." },
            { id = 5321027, text = "Your presence desecrates these halls, mortals." },
        } },
    } },
    { who = "Amarth the Harvester", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3695361, text = "Are you so eager to share your underling's fate? Your vaunted courage will be your doom." },
