        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3695357, text = "Bonefang will reduce you to dust!" },
            { id = 3695358, text = "Fall before the House of Rituals!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3695355, text = "The Fallen shall serve me again!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3695351, text = "Another soldier in my army." },
            { id = 3695354, text = "He will use us all." },
            { id = 3695360, text = "It will take more than courage to save you now." },
            { id = 3695350, text = "No matter, my minions are endless." },
            { id = 3695356, text = "One final act of service." },
            { id = 3695353, text = "Yet more bodies to harvest. Malthor will be pleased." },
        } },
    } },
    { who = "Amathet Boss", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3168044, text = "Fleshcursed, your kind are unworthy of the titans' gifts." },
            { id = 3168048, text = "Now you will BANG!" },
            { id = 3168046, text = "Time and again you have failed to protect the Titan's works!" },
            { id = 3168045, text = "You have tainted this place long enough! Fall before the Amatheth!" },
            { id = 3196341, text = "You will be purged!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3168049, text = "I grow tired of this ruse." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3196340, text = "Curse it, fools! Will your interference never cease?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3196343, text = "All must be remade as the titans wield it!" },
            { id = 3196342, text = "The Old God's taint reaches every corner of this world! It must be undone!" },
            { id = 3196205, text = "Unworthy vermin! Our keeper will reclaim the forge, and we will purge Azeroth of your corruption!" },
            { id = 3196344, text = "You bring your own doom!" },
        } },
    } },
    { who = "Amathet Caster", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3150186, text = "ALL CORRUPTION WILL BE PURGED!" },
