        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3150182, text = "You are no different from N'Zoth!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3150185, text = "Burn in the fires of purity!" },
            { id = 3150189, text = "corrupted all of you." },
            { id = 3150191, text = "N'Zoth... has... infected you?" },
            { id = 3150184, text = "The Amatheth will cleanse Azeroth." },
            { id = 3150193, text = "The forge must be secured." },
            { id = 3150187, text = "We will re-originate this world!" },
            { id = 3150183, text = "You reek of flesh!" },
        } },
    } },
    { who = "Amathet Warrior", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
