    { who = "Amella", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4680395, text = "Oh, I am glad you are here." },
            { id = 4675466, text = "You have instructed this young one well, adventurer. As they grow and prosper, so shall the shrine." },
            { id = 4675468, text = "You have made a noticeable impact on these whelps' lives. They will always remember the aid you have provided." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4680396, text = "Be careful out there!" },
            { id = 4680401, text = "Huh, now where did that whelpling go?" },
            { id = 4680402, text = "Look after others." },
            { id = 4680397, text = "Oh! Hello adventurer!" },
            { id = 4680399, text = "Oh, do not mind the little ones!" },
            { id = 4680398, text = "Ouch! Careful, young one! Oh, can I help?" },
            { id = 4675467, text = "There are more whelks at the shrine that could use your guidance in their training." },
            { id = 4680400, text = "These whelps are our future." },
            { id = 4675465, text = "What do you mean, the whelplings do not want to fly? This should be second nature to them!" },
        } },
    } },
    { who = "Ammunae", tier = "character", groups = {
