        { name = "Idle", family = "Feelings", lines = {
            { id = 5263029, text = "HAH!" },
            { id = 5263033, text = "HEY!" },
            { id = 5263035, text = "MWAH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5048837, text = "But... what about you, Winglord?" },
            { id = 5049036, text = "Fair skies and strong winds." },
            { id = 5048840, text = "Of course, for the Sundered Flame!" },
            { id = 5048889, text = "Oh, uh, hello?" },
            { id = 5048843, text = "Sarcarath told us you were a monster." },
            { id = 5048846, text = "There were no end to his lies." },
            { id = 5048849, text = "We both are." },
            { id = 5225968, text = "Winglord, it is good to have you back... after we left you in the Titan Vault." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 5263003, text = "HOOOWWW!" },
        } },
    } },
    { who = "Anachronos", tier = "character", groups = {
        { name = "Loyalty", family = "Manners", lines = {
            { id = 543710, text = "As the Wardens of Time, we of the Bronze Dragonflight observe their infinite combinations." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 543711, text = "A recent event, obscured by powerful magics, remains masked even to me." },
            { id = 543708, text = "Are you the mortal on which so much depends?" },
            { id = 543715, text = "Azeroth will burn!" },
            { id = 543716, text = "But the catastrophic outcome is plain." },
            { id = 543706, text = "Countless threads are woven to create the fabric of our timeline." },
            { id = 543713, text = "is that the fate of Azeroth hinges on the deeds of a mortal." },
            { id = 543712, text = "Listen well, mortal." },
            { id = 543714, text = "Only time will tell." },
            { id = 543707, text = "When disruptions are detected by our Watchers, we are charged with their repair." },
            { id = 543709, text = "While the details remain shrouded from our view, one thing we have gleaned." },
        } },
    } },
    { who = "Anarys Lunastre", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1407647, text = "You have come to help Lilith destroy our family! Begone!" },
            { id = 1407652, text = "You have come to help Lyla destroy our family! Begone!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1407646, text = "Get away from there!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1407920, text = "I will hear no more of your scheming! You endanger everything our father worked for!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407649, text = "She wants to preach her traitorous ideals to me further? Fine. Let us go." },
            { id = 1407650, text = "Someone will notice I am missing. They will come looking for me." },
            { id = 1407648, text = "Ugh, who are you?" },
            { id = 1407653, text = "Who are you?" },
        } },
    } },
    { who = "Anasterian Sunstrider", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2401935, text = "Anarala Pelore! You will burn for your actions!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2401936, text = "At least I have a soul, you despicable monster!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2401934, text = "That is far enough, Prince Arthas! Your march ends here!" },
        } },
    } },
    { who = "Anathos Firecaller", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2399650, text = "ALL WILL BE CONSUMED!" },
            { id = 2399656, text = "BEHOLD THE FLAMES OF THE PHOENIX!" },
            { id = 2399653, text = "THE PHOENIX MUST FEAST!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2399655, text = "You will burn to ashes!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2399652, text = "Better watch your step!" },
            { id = 2399659, text = "Enough trifling! DIE!" },
            { id = 2399651, text = "The Phoenix takes many forms!" },
            { id = 2399660, text = "The Phoenix will be reborn!" },
            { id = 2399654, text = "The very might of the cosmos will crush you!" },
            { id = 2399658, text = "Then let us teach them a lesson, shall we?" },
            { id = 2399661, text = "Typical Alliance weakness." },
            { id = 2399657, text = "Well, well. The Alliance's greatest heroes. Stumbling their way into the heart of the troll empire. I fear we can let them proceed no further." },
        } },
    } },
    { who = "Anchorite Lanna", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1997291, text = "GAH!" },
            { id = 1997289, text = "HUH AHHH!" },
            { id = 1997292, text = "HUH!" },
            { id = 1997293, text = "YEAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1963741, text = "I go to the light" },
            { id = 1963746, text = "I take no joy in ending life." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1963745, text = "Be wary. Our enemies have arrived. Let us avoid them if possible." },
            { id = 1963744, text = "Let me help with that." },
            { id = 1963743, text = "Light shines upon you." },
            { id = 1963740, text = "Surrender. Save yourself. A needless death." },
            { id = 1963742, text = "The light greets you." },
        } },
    } },
    { who = "Ancient Aspirant", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4955473, text = "DARKNESS TAKE YOU!" },
            { id = 4955477, text = "I WILL CLAIM VICTORY!" },
            { id = 4955479, text = "KNOW THE PAIN OF DEFEAT!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4955471, text = "I will prove my worth!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4955474, text = "For the Earth, water!" },
            { id = 4955475, text = "For the earth's water!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4955469, text = "Will not fail again!" },
        } },
    } },
    { who = "Andantenormu", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4680427, text = "I wish I could get back to my books." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4684192, text = "Except some of our ranks are missing." },
            { id = 4680423, text = "I'll be deep in my books." },
            { id = 4680429, text = "Is it that time already?" },
            { id = 4680425, text = "It has been a time." },
            { id = 4679832, text = "It is Azeroth." },
            { id = 4680428, text = "So many books, so little time." },
            { id = 4679833, text = "Though, an exceptionally long time ago..." },
            { id = 4680424, text = "We will find time." },
            { id = 4680426, text = "Yes, I have time. For now." },
            { id = 4680422, text = "You know where to find me." },
            { id = 4680430, text = "You made me lose my place. Now where was I?" },
        } },
    } },
    { who = "Andaris Narassin", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1523865, text = "Hah! This is what you bring? An outlander and a pack of mindless, mana-starved corpses? You have fallen on hard times indeed." },
            { id = 1523871, text = "Let us test the mettle of your rebellion. Send your best to face me at Lilith's estate before I bring in more citizens for questioning." },
            { id = 1523907, text = "More withered tricks! I shall not fail Elisande! You will fall!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1523898, text = "You think we didn't notice your skullduggery? Your old tricks are no match for true sorcery." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1523867, text = "As if I would bother with facing you myself. Felborn! Kill them." },
            { id = 1523870, text = "Poor Thalyssra! You try so hard to save your people, yet you cut them off from the one thing that can restore them. I fear Lyleth shall pay the price for your arrogance." },
            { id = 1523903, text = "Training those withered scum. How distasteful. Dalian, defend the entrance. Slay my foes." },
            { id = 1523905, text = "You'll go no further! I'll die before I allow you entrance to the Nighthold!" },
        } },
    } },
    { who = "Anduin", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 543817, text = "I hope you are enjoying your stay in Stormwind." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 543816, text = "Greetings, citizen!" },
            { id = 543820, text = "Hello! Have you come to speak with my father?" },
        } },
    } },
    { who = "Anduin Lothar", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5146393, text = "FALL TO MY BLADE!" },
            { id = 5146409, text = "FOR THE ALLIANCE!" },
            { id = 5146400, text = "LIGHTS TAKE YOU!" },
            { id = 5146401, text = "YOU SHALL FALL!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5146392, text = "Feel my blade's edge!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1523379, text = "Another year of slumber. I wonder if Medivh will ever awaken." },
            { id = 1523381, text = "It couldn't have been helped, you know. We tried to alter it, but it was all part of a larger scheme." },
            { id = 5146406, text = "Light, sustain me!" },
            { id = 1523393, text = "Our friend lies just in here." },
            { id = 5146405, text = "The kingdoms cannot fall!" },
            { id = 5146408, text = "The light guides me!" },
            { id = 5146404, text = "We stand as one!" },
        } },
    } },
    { who = "Anduin Wrynn", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2998643, text = "AHHH!" },
            { id = 2998648, text = "HA!" },
            { id = 2998649, text = "HUH!" },
            { id = 2998645, text = "HWAH UGH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1244997, text = "I trust that your valor and discretion will serve the Alliance well as it always has. With honor, King Anduin Wrynn." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1596663, text = "I can't blame the lad for his choice. My father sacrificed everything to save his people. He was a great king." },
            { id = 798149, text = "I couldn't imagine a crueler tyrant. He enslaved this entire continent." },
            { id = 1596668, text = "I must go to the Broken Shore and see for myself the sacrifice he made." },
            { id = 1596661, text = "I think I know just the spell. Follow me." },
            { id = 617385, text = "I will see you soon." },
            { id = 798139, text = "My friend, if you blindly trust a Black Dragon in the search for greater power, are you any better than Garrosh Hellscream? Please, just be careful." },
            { id = 1596665, text = "My people like me, respect me, but they don't believe in me. Not like they believed in him." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 617381, text = "Stay safe." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 2998680, text = "AWW!" },
            { id = 2998678, text = "NO!" },
            { id = 2998673, text = "OH UGH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1596664, text = "Since you brought my father's compass back to me, I've prayed to the Light for guidance, and to know his spirit is at rest. The Light doesn't answer." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 798141, text = "A chill just went up my spine." },
            { id = 617383, text = "Be careful." },
            { id = 617391, text = "Can you believe the majesty of this place?" },
            { id = 798137, text = "Champion, I know that our people are at war, but if you blindly trust this black dragon in the pursuit of power, are you any better than your Warchief? Please, just be careful." },
            { id = 1244993, text = "Champion, the Skyfire is about to embark on an urgent mission. I must ask that you accompany them." },
            { id = 1596660, text = "I'll need a disguise to move through the city without attracting attention." },
            { id = 798151, text = "I'm not so sure about that, but I can tell you no great empire has ever stood the test of time by crushing its own citizens." },
            { id = 798131, text = "It's a Pandaren board game. The object is for both players to win." },
            { id = 1596666, text = "I've heard the voice of the people, but how do my father's advisors feel? I fear they do not trust me as they did my father." },
            { id = 798153, text = "Remember, the Mogu were overthrown. That should be the lesson of the Thunder King. It's your move, by the way." },
            { id = 1244995, text = "Report to Stormwind Harbor as soon as possible. They are under strict orders not to leave without you." },
            { id = 1596667, text = "Thank you, my friend. I know what I must do to learn the weight of my father's crown." },
            { id = 617393, text = "There's more to this land than meets the eye." },
            { id = 1596662, text = "They're right to be afraid. If we fail to stop the Legion on the broken shore, the demons will strike us here, at our home in Hearth." },
            { id = 798133, text = "To what end? What are you two working towards?" },
            { id = 798135, text = "using a Mogu weapon forge whose powers you barely understand." },
            { id = 617389, text = "We're far from home, friend." },
            { id = 798143, text = "What are you doing? You're not seriously going to eat that!" },
            { id = 798147, text = "What are you talking about? I don't trust you." },
            { id = 798145, text = "What are you trying to pull?" },
            { id = 617405, text = "You know who my father is, right?" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 2998642, text = "GRRR!" },
            { id = 2998639, text = "HAH!" },
            { id = 2998641, text = "UGH!" },
        } },
    } },
    { who = "Ane the Ron", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 543825, text = "SCREAM FOR ME!" },
            { id = 543830, text = "YOUR HOPES ARE LOST!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 598898, text = "HEH!" },
            { id = 598904, text = "HOO!" },
