            { id = 598916, text = "ARGH!" },
            { id = 598919, text = "OOF!" },
            { id = 598907, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 543824, text = "P.D.! No time for a slow death!" },
        } },
    } },
    { who = "Anguish Jailer", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1281135, text = "In this place, you are the hunted." },
            { id = 1281127, text = "Your armies are nothing, Demon Hunter!" },
            { id = 1281123, text = "Your soul will be mine." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1281137, text = "I am your judge, jury, and executioner." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1281139, text = "Ah, another soul for the Legion." },
            { id = 1281141, text = "All mortals will view of the soul engines." },
            { id = 1281129, text = "I'll crack open your flesh and feed upon your soul!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1281125, text = "A new prisoner for the taking!" },
            { id = 1281131, text = "Hahahaha! Into my cage you go!" },
            { id = 1281133, text = "So eager to be enslaved." },
        } },
    } },
    { who = "Angus Ballaster", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1886498, text = "GET BACK, OR YOU'LL BE MEETING ME, AMMA!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1893572, text = "Don't go doggin' no watch now!" },
            { id = 1893573, text = "Get on then! No sense in dragging anchor." },
            { id = 1886499, text = "Wait! You're not one of them!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1886504, text = "Ah, cram it, you foul-tongued nag! Your mother can rot in the bowels of a sea snake!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1886500, text = "Alright, you just lead the way." },
            { id = 1886506, text = "Aye, you be correct there! Lead the way!" },
            { id = 1886503, text = "Just you try. You'll taste my hammer, witch!" },
            { id = 1893575, text = "Mind your tack!" },
            { id = 1893576, text = "What can this old salt do for ya?" },
        } },
    } },
    { who = "Angus Ironfist", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1406501, text = "I see where you get your reputation." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1406500, text = "Ah, good riddance!" },
            { id = 1406499, text = "Hey, I was just about to get him." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1406512, text = "Any day now, hero." },
            { id = 1406495, text = "Couldn't have done better myself." },
            { id = 1406510, text = "Hero! Hey, Hero! Are you alright, mate?" },
            { id = 1406497, text = "Mmm, not bad. Not bad at all!" },
            { id = 1406511, text = "Quick! Take this key and get yourself out of there!" },
            { id = 1406496, text = "The stories were true about you." },
            { id = 1406493, text = "Yeah, that's the stuff. You feel better or what?" },
        } },
    } },
    { who = "Anhuur", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 543834, text = "HA!" },
            { id = 543836, text = "HMPH!" },
            { id = 543860, text = "HWAH HWAH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 543839, text = "AHHH!" },
            { id = 543841, text = "FUUU!" },
            { id = 543840, text = "GAH!" },
            { id = 543847, text = "NOOO!" },
            { id = 543835, text = "YEAH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 543853, text = "A product of your own insolence." },
