    { who = "Ankoan commoners", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2922150, text = "DO NOT CHALLENGE THE WAVEBLADE!" },
            { id = 2922156, text = "IT. IS. MY. TIME." },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2922148, text = "You will drown here!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2922155, text = "I return to the tides." },
            { id = 2922159, text = "My clan lives on." },
            { id = 2922153, text = "My life for my clan." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2922152, text = "Go no further!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2922147, text = "Currents take you!" },
            { id = 2922158, text = "The... journey... ends." },
            { id = 2922149, text = "This is where you die!" },
            { id = 2922151, text = "Your life is forfeit!" },
        } },
    } },
    { who = "Ankoan guards", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2922307, text = "FOR THE WAVEBLADE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2922304, text = "Your spirit will languish here!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
