    { who = "Anub'azal", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5722434, text = "LOOK WHAT THIS GAME'S PULLED IN!" },
            { id = 5782143, text = "WHO DO YOU THINK, MAGGOT?" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 5722384, text = "Be thankful you are useful!" },
            { id = 5789661, text = "Otherwise you will be encumbered with additional forces." },
            { id = 5722402, text = "You are far from home." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5789658, text = "I have redirected forces loyal to me away from the entrance." },
            { id = 5722442, text = "I have use for you." },
            { id = 5722344, text = "My loyalty will never falter." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 5722410, text = "Greetings, Overcrawler!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 5722368, text = "Farewell, for now." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5789660, text = "Dispatch these guards before they can raise an alarm." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5782049, text = "Approach, Intruder." },
            { id = 5722394, text = "Are you friend, foe, or abuse?" },
            { id = 5767107, text = "Everyone! Return to your duties! Now!" },
            { id = 5789698, text = "Finally, this madness is over." },
            { id = 5722332, text = "For Azkahat!" },
            { id = 5722352, text = "Remain an ally." },
            { id = 5722418, text = "This is an interesting development." },
            { id = 5722360, text = "Tread carefully!" },
            { id = 5722376, text = "We will speak again!" },
            { id = 5767114, text = "What an interesting delivery." },
            { id = 5722426, text = "You weren't part of my plans." },
        } },
    } },
    { who = "Anub'azal the General", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5793844, text = "You are dismissed, soldier. I wish to rest a while... ...in view of my dear city." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5793808, text = "Come off the pleasantries, Widow." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 5793841, text = "Xav'kal lies dead at my feet. The strength granted by his vile masters was no match for the true might of Arj'kahhet." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 5793819, text = "Ah, you speak of insurrection." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5834083, text = "Excellent effort. Your martial gravitas reminds me of myself when I was young." },
            { id = 5834092, text = "Fine work, friend overcrawler!" },
            { id = 5854661, text = "Gathering supplies? Marching out? I've heard nothing of this!" },
            { id = 5834090, text = "Rakusha swarm beasts are imperative to the war effort. I expect them to be treated as such." },
            { id = 5834091, text = "Swarmite venom repels intruders and protects Rakuja's threadling eggs. Go harvest some, before I decide you've outlived your usefulness." },
            { id = 5793843, text = "That is why I did this, to remind us all of our true strength." },
            { id = 5793842, text = "tradition, study, discipline. If our kingdom is to survive, then those tenets must remain as its foundation." },
            { id = 5834089, text = "Viceron's incompetence has allowed skitterlings to invade my threadling hollows. Deal with the thieves, and protect my investment." },
            { id = 5793822, text = "We've blinded our tired hearts from the truth, Widow. Ann Sarek is nothing like her mother." },
            { id = 5834082, text = "You're needed on the battlefield. Do not dally." },
        } },
    } },
    { who = "Anub'esset", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1332961, text = "BLEED AND DIE, FERMIN!" },
            { id = 1332959, text = "BUT IT IS MY DESTINY TO RULE I SHOULD NOT RULE!" },
            { id = 1332967, text = "I WILL CRUSH YOUR BONES TO POWDER!" },
            { id = 1332964, text = "TOO EASY IN THE END, HOW DISAPPOINTING." },
            { id = 1332966, text = "YOUR STRENGTH MEANS NOTHING!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1332954, text = "FINALLY FREE! And you will not imprison me again!" },
            { id = 1332955, text = "I crave the smell of freshly spilled blood. How convenient that you are here." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1332958, text = "I cannot hear the Lich King, has he abandoned me?" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1332965, text = "Did you expect me to be a simple obstacle? FOOLS!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1332963, text = "Another one crushed between my pincers!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1332957, text = "A feast for my brethren!" },
            { id = 1332956, text = "Consume their flesh!" },
            { id = 1332960, text = "Only scraps will remain." },
            { id = 1332962, text = "You should have died in Northrend!" },
        } },
    } },
    { who = "Anub'ikkaj", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5769292, text = "ALL MOST TO GLOOM!" },
            { id = 5769293, text = "DARKNESS COMES!" },
            { id = 5769289, text = "LOST IN SHADE!" },
            { id = 5769288, text = "SHADE, TAKE YOU!" },
            { id = 5769291, text = "THE SHADOWS CONSUME!" },
            { id = 5769294, text = "YOU ARE NOTHING AGAINST ASHKAHEAD" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5769284, text = "I still have power enough to defeat you!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5769290, text = "Shadows, gather to me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5769286, text = "I'll feast on you!" },
            { id = 5769285, text = "So you dare to face me? Very well." },
            { id = 5769295, text = "The Arathi will be but the first to fall." },
            { id = 5769282, text = "The Arathi will fall to ruin!" },
            { id = 5769296, text = "They all failed me." },
            { id = 5769287, text = "Your flesh is weak!" },
        } },
    } },
    { who = "Anub'Rekhan", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 544003, text = "I hear little hearts beating, yes, beating faster now, soon the beating will stop." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 544001, text = "Ahhhh, welcome to my parlor." },
            { id = 543999, text = "Closer now. Tasty morsels. I've been too long without food, without blood to drink." },
            { id = 544002, text = "Just a little taste." },
            { id = 544005, text = "Shhh... It will all be over soon." },
            { id = 544000, text = "There is no way out." },
            { id = 544004, text = "Which one shall I eat first? So difficult to choose. They all smell so delicious." },
            { id = 544006, text = "Yes, run! It makes the blood pump faster!" },
        } },
    } },
    { who = "Anub'zekt", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5769338, text = "MY SWORM HANGERS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 5769332, text = "Incompetent drones! I will end you myself!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5769340, text = "My watch ends now." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 5769334, text = "Is that all?" },
            { id = 5769339, text = "Overpowered. Outnumbered. Pathetic." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5769337, text = "Gather my prey to me!" },
            { id = 5769336, text = "Hahahaha! They'll feast upon you!" },
            { id = 5769335, text = "How fragile!" },
            { id = 5769330, text = "Intruders! Find them!" },
            { id = 5769333, text = "You'll falter, my swarm!" },
        } },
    } },
    { who = "Apata High Mountain", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1386239, text = "I hope my brother didn't go after the beast himself. He can be...impulsive." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1386248, text = "Patience, brother. To gaze upon Talonclaw will be a sight to remember. Look! Our friend returns!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1386253, text = "And yet, I am certain we are being watched." },
            { id = 1386246, text = "Calm yourself, Wuho." },
            { id = 1386250, text = "It is done. Let us go across." },
            { id = 1386251, text = "It is eerily quiet." },
            { id = 1386238, text = "Their stealth is maddening! Someone drop a flare!" },
            { id = 1386240, text = "There is his signal! Let us land and see what he learned!" },
            { id = 1386237, text = "These illusions use stealth. A flare could reveal them." },
            { id = 1386243, text = "We must find a way through. Wuho, you and I should examine the wards while our friend searches the harbor." },
            { id = 1386241, text = "Whoa! Have you found the monster?" },
            { id = 1386249, text = "Wonderful! I can just attach them here and..." },
        } },
    } },
    { who = "Apetagonizer", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2428461, text = "Hoard bad! Smash monkey! Who is a good monkey? You are!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2428457, text = "All systems online. Target acquired. Batteries at full." },
            { id = 2428458, text = "Antagonization matrix at maximum capacity. Ready to deploy." },
            { id = 2428456, text = "Ape-Tagonizer 3000 system deployed. Prepare to encourage target." },
            { id = 2429896, text = "Breach detected. Purge unauthorized entities." },
            { id = 2428463, text = "Powered levels failing. Warning. Warning." },
            { id = 2428460, text = "Reminder, do not exceed compassionate thresholds. Shop only for the Alliance." },
            { id = 2428459, text = "Subject's irritation levels rising. Maintain shockification." },
            { id = 2428462, text = "System failure imminent. What a shocking development." },
            { id = 2428464, text = "Systems inoperable need charging cable." },
            { id = 2429897, text = "Warning systems compromised purge purge purge" },
            { id = 2429526, text = "Warning! Warning! Vital signs critical. Injection sequence initiated." },
        } },
    } },
    { who = "Aponi Brightmane", tier = "character", groups = {
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1411556, text = "By the Light! What does that mean for Azeroth?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1388205, text = "Ancestors protect you." },
            { id = 1388203, text = "An'Shey's warmth guide you." },
            { id = 1388210, text = "Bask in the glory of the day." },
            { id = 1388211, text = "Bless your heart." },
            { id = 1388212, text = "Hm, you might be shining a little too brightly." },
            { id = 1388207, text = "It is always darkest just before the dawn." },
            { id = 1388204, text = "Peace and Patience be with you." },
            { id = 1388213, text = "The ancestors would not approve of this." },
            { id = 1388206, text = "Walk always in the light of the sun." },
            { id = 1388208, text = "Warm greetings to you." },
        } },
    } },
    { who = "Apothecary Faranell", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4489368, text = "I AM FORSAKEN" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4489367, text = "Hello!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 4489365, text = "Goodbye." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4492153, text = "It's working! The Plague Eaters are consuming the blight!" },
            { id = 4489473, text = "nothing less than a pure undiluted sample of that plague from deep within its reaches" },
            { id = 4489470, text = "This is my last one, and it's a puny thing. I can make more, but to be effective, they must be formulated to survive the plague!" },
            { id = 4489462, text = "Yes, yes, I will come! But first, behold, as my creation eradicates the blight!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4489364, text = "A little of this... A little of that..." },
            { id = 4489370, text = "Do you know who I am?" },
            { id = 4489369, text = "Do you need something?" },
            { id = 5226986, text = "How cunning." },
            { id = 4492155, text = "Keep going! Whatever happens, we will be ready." },
            { id = 5226985, text = "Science is never perfectly safe, but it won't harm us." },
            { id = 4489477, text = "She won't succeed!" },
            { id = 4489366, text = "Trust in the Apothecaries." },
            { id = 4489463, text = "You may applaud at any time" },
        } },
    } },
    { who = "Apprentice Ardrias", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1404578, text = "You have done everyone a great service, friend. Give Cousin Lilith my regards." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1404576, text = "But master, this man was innocent. His name was cleared. Surely he deserves a second chance." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1404577, text = "Apologies, Master. I am still working on the clasp for the Rust Commission." },
            { id = 1408745, text = "DO come again!" },
            { id = 1404580, text = "Our jewelry is second to none." },
            { id = 1404579, text = "You need my help?" },
        } },
    } },
    { who = "Apprentice Beruun", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5556782, text = "I was afraid of this. It's not her work. It's... it's the T'Shemat itself." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5556796, text = "Atanya may not be ready for the rituals of the Tisha mat, but maybe we can help her?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5557619, text = "Arca non poros! Good fortune and hello!" },
            { id = 5556873, text = "Atania, I sent them to Akindoun. XR Kataru wouldn't want this for you." },
            { id = 5556876, text = "He would want you to be around your people and to show them all you've made, not to stay locked away here." },
            { id = 5556703, text = "It's worth a try, though if the tissue mat is what is putting her in a bad mood, it might not work." },
            { id = 5556791, text = "She lost her father Exar Kataru in the siege. Speaking of him saddens and angers her." },
            { id = 5557620, text = "Someday, I hope my research helps my people." },
            { id = 5556785, text = "The Tisha Mat is a time of remembrance and of letting go of the past." },
            { id = 5557618, text = "Working for high artificer at Tanya is a challenge, one that I am sure will prepare me to be an artificer, like crushing pressure prepares a diamond." },
            { id = 5556779, text = "Yes, hi, Artificer. Come, champion. I will get a crystal for you." },
        } },
    } },
    { who = "Apprentice Marten Webb", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1969721, text = "I appreciate not being dead." },
            { id = 1860875, text = "I tried my best to fight them off!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1905656, text = "A millennia-old spirit bent on vengeance who wants to kill us all. Lovely." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1969717, text = "If anyone could survive, it's him. I'm going to check the lab's gardens, Inquisitor." },
            { id = 1969720, text = "Is it almost over? Please tell me it's almost over!" },
            { id = 1905657, text = "Is no-one going to mention that massive wicker golem, because I feel it should be mentioned." },
            { id = 1969722, text = "Oh, much to do, much to do." },
            { id = 1860876, text = "They came from the woods. We fought. Master Ashton shoved me aside and they took him. We have to get him back!" },
            { id = 1969719, text = "This is insane! Don't go so fast!" },
        } },
    } },
    { who = "Apprentice Mijala Firehex", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 6119192, text = "I heed the call of the Kirin Tor." },
            { id = 6119197, text = "I never had a portal trap me that way. You saved my life, my friend." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6119147, text = "BC if no." },
            { id = 6119206, text = "I'm about to break my wand over your head if you don't quit that." },
            { id = 6119247, text = "Salutations, my friend." },
            { id = 6119276, text = "We can do this! We are Kirin Tor!" },
        } },
    } },
    { who = "Aqir", tier = "creature", ctype = "Aberration", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3196218, text = "ALL DOOM BELONGS TO THE MASTER!" },
            { id = 3194788, text = "WE OUTNUMBER THE STARS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1956760, text = "You will be eradicated!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 3196219, text = "Your pathetic kind will serve N'Zoth or be buried beneath the tombs." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1956765, text = "The coons of lesser creatures must serve or die!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1956766, text = "All are shy, all have superior!" },
            { id = 1956769, text = "Call me so frail, so unworthy!" },
            { id = 1956764, text = "Hunger insatiable! The king feasts!" },
            { id = 1956770, text = "Now's your boon at a single worthy trait among you." },
            { id = 1956767, text = "Oh my god! How is this possible?" },
            { id = 3194787, text = "Our hive descends on Orgrimmar!" },
            { id = 3196221, text = "The Achea are eternal." },
            { id = 1956761, text = "The Ratted Screams will herald his arrival!" },
            { id = 1956763, text = "The Wound Festers! The world putrifies!" },
            { id = 1956762, text = "We have always been in your mind." },
            { id = 1956768, text = "You were the weakest dream." },
        } },
    } },
    { who = "Aqir casters", tier = "creature", ctype = "Aberration", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3151066, text = "BEND TO THE MASTER'S WILL!" },
            { id = 3151070, text = "OBEY THE WHISPERS" },
            { id = 3151072, text = "OBLIVION. COMES. A-A-A-a" },
            { id = 3151067, text = "THIS WORLD IS AT ITS END" },
            { id = 3151075, text = "YOU, TOO, SHALL, DIE!" },
            { id = 3151071, text = "YOUR HOPE IS A LIE!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3151076, text = "My purpose is fulfilled." },
