        { name = "Idle", family = "Feelings", lines = {
            { id = 3160087, text = "ROAR!" },
            { id = 3160086, text = "RRR!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3151069, text = "Nihilotha will rise again!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3151068, text = "Serve N'Zuk, or die!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3151073, text = "Another takes my place!" },
            { id = 3151065, text = "N'Zoth rules all!" },
            { id = 3151074, text = "These armies... are... Legion!" },
        } },
    } },
    { who = "Aqir priests", tier = "creature", ctype = "Aberration", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
