            { id = 3151111, text = "THE VOID AWAITS YOU" },
            { id = 3151109, text = "YOU CANNOT AVOID YOUR DESTINY" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3151118, text = "You have... already... lost..." },
        } },
        { name = "Idle", family = "Feelings", lines = {
            { id = 3160121, text = "HA HA HA!" },
            { id = 3160123, text = "RRR!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3151113, text = "Accept the master's gifts!" },
            { id = 3151108, text = "Behold the fate of your world!" },
            { id = 3151116, text = "Hope will fail you." },
            { id = 3151107, text = "How should I break you?" },
            { id = 3151112, text = "Long have I waited for this." },
            { id = 3151117, text = "The dragon deceives you." },
