    { who = "Aralon", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3748013, text = "on the mask when you are ready. We must find the others.\"" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3692576, text = "Protect the heart at all costs!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3748015, text = "Azelor I feared as much he deserved better than this" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3692826, text = "...for Queen... ...and... ...Grav. Ugh..." },
            { id = 3692824, text = "Awakening… She seeks… Awakening…" },
            { id = 3748018, text = "Guirre, she yet breathes, but what have they done to her?" },
            { id = 3748011, text = "Mortal, over here! I require aid." },
            { id = 3748017, text = "Nara was the fiercest among us. She would never have knelt to the trust." },
            { id = 3748019, text = "Report to Lord Hern. I will guide Gwaiir to safety." },
            { id = 3748016, text = "Tayrus, I'd embrace you, old friend." },
            { id = 3748014, text = "The entire Grove has been possessed. Take care not to be unmasked.\"" },
            { id = 3748012, text = "We will need disguises. Search the area for something we can use." },
        } },
    } },
    { who = "Ara'lon", tier = "character", groups = {
