    { who = "Aranasi Maiden", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1281147, text = "INTRUDERS ON THE BELL HAMMER!" },
            { id = 1281149, text = "VENGEANCE FOR THE BRUDE QUEEN!" },
            { id = 1281155, text = "YOU WILL MAKE A SATISFYING KNEEL!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1281163, text = "Your world will burn!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1281143, text = "My spiders will feast upon your marrow!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1281151, text = "Protect the eggs at all costs!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1281161, text = "Hello, little fly!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1281145, text = "Entrap them, my children!" },
            { id = 1281159, text = "I've caught you in my web!" },
            { id = 1281165, text = "Know where to hide now, Precious!" },
            { id = 1281153, text = "No! Tirana is dead!" },
            { id = 1281157, text = "You made a terrible mistake coming here!" },
        } },
    } },
    { who = "Arator the Redeemer", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1411994, text = "FOR THE LIGHT!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3198244, text = "CHA!" },
            { id = 3198242, text = "HA!" },
            { id = 3198239, text = "HUUU!" },
            { id = 3198237, text = "HYAA!" },
            { id = 3198238, text = "HYAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1411578, text = "I heard rumors that we recovered a message from my father. Are my parents alive?" },
            { id = 1412039, text = "I need to recover. Go on without me." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3198263, text = "AHHH!" },
            { id = 3198264, text = "NOOO!" },
            { id = 3198268, text = "UH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1412037, text = "Grievous wounds. I must recover." },
            { id = 1411996, text = "One by one, our foe shall fall." },
            { id = 1411998, text = "The light smiles upon us." },
            { id = 1411995, text = "The light smites our foes!" },
            { id = 1411579, text = "Yes, I'm alright. That imp mother was getting a little too close for comfort." },
            { id = 1411577, text = "You heard my father. We must act." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 3198231, text = "HAH!" },
            { id = 3198233, text = "NO!" },
            { id = 3198234, text = "UGH!" },
        } },
    } },
    { who = "Arc Consul Velara", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1688350, text = "Enough! You have proven your worth." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1688349, text = "I will not restrain myself. Let us begin." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1710272, text = "AHHH!" },
            { id = 1710274, text = "MMM!" },
            { id = 1710268, text = "OH!" },
            { id = 1710273, text = "PFFT!" },
            { id = 1710271, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1688346, text = "Bear in mind that your performance reflects upon all of us." },
            { id = 1688348, text = "It is as I thought." },
            { id = 1688347, text = "You could stand to do better." },
        } },
    } },
    { who = "Arcanist Keldanath", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1407853, text = "I relish what little sleep I can manage. Tomorrow I begin looking for subjects." },
            { id = 1407862, text = "my spellstone. Someone please use it to carry on my work." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407855, text = "Day 14. The new subject, number 16, is special. His arcane essence is touched by some mysterious power. I have named him Theron." },
            { id = 1407856, text = "Day 16, Breakthrough. Using Theron's essence as the base, I have crafted a spell that calms the Withered. At least, it works sometimes." },
            { id = 1407858, text = "Day 33, low on Archwine, Theron making excellent progress, Shallan remains stubborn. Crystals becoming harder to find." },
            { id = 1407859, text = "Day 40, a massive Ettin trampled through my workshop at Coralloon Manor. Scared him away with magic. I have a feeling he will be back." },
            { id = 1407852, text = "Day 5. Wards prove effective at deterring the Withered, but do nothing for the cacophony of critters and beasts outside. The nights are so loud out here." },
            { id = 1407860, text = "Day 50, the sky has turned black, demons everywhere, and this hunger, this endless hunger." },
            { id = 1407854, text = "Day 9. Still no luck in communicating with the Withered. I must regard this failure not as a measure of ability, but a measure of progress." },
            { id = 1407857, text = "Day twenty-four, I woke to a night elf's blade at my neck. He asked what I was doing to the Withered. Searching for a cure, I replied. He merely grunted and disappeared into the woods." },
            { id = 1407861, text = "Subjects released. I can no longer protect them." },
        } },
    } },
    { who = "Arcanist Valtrois", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1407667, text = "Do you have much experience with leyline energy? I should think not." },
            { id = 1407641, text = "Thalyssra! You cannot be serious! Wasting your time on this... creature?" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1407666, text = "Come, we can examine the feed from down here." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407668, text = "Allow me to educate you on the fundamentals." },
            { id = 1407669, text = "Far below us, rivers of raw arcane power course throughout the land. The leylines are eternal, primal, and impossible to control." },
            { id = 1407670, text = "However, just as one pulls thread from cotton, so too can we draw power from the ley lines." },
            { id = 1407664, text = "if you insist." },
            { id = 1407675, text = "Of course, First Arcanist." },
            { id = 1407672, text = "Restore them, and help us create a new locus of power here in Shal'Aran." },
            { id = 1407671, text = "See here. This is the feed from an aura. And there are many others still lying dormant." },
            { id = 1407642, text = "We should be planning our attack on Suramar." },
        } },
    } },
    { who = "Arch Druid Glaidalis", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1272576, text = "AND DO FALADOR!" },
            { id = 1272574, text = "I AM NATURE'S FURY INCARNATE!" },
            { id = 1272568, text = "I WILL BLEED THE NIGHTMARE FROM YOU!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1272564, text = "Defilers, I can smell the nightmare in your blood. Be gone from these woods or suffer nature's wrath!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1272572, text = "I am the vessel of nature's fury!" },
            { id = 1272584, text = "I just had the strangest nightmare." },
            { id = 1272580, text = "I see now. I am the Defiler." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1272582, text = "The nightmare clouds my thoughts no more." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1272586, text = "Be purified in the light of the stars!" },
            { id = 1272570, text = "By tooth and claw, be purged!" },
            { id = 1272566, text = "Defilers! So it is you who have befouled these woods with a nightmare!" },
            { id = 1272578, text = "The wilds are safe from the nightmare once again." },
        } },
    } },
    { who = "Arch Druid Hamuul Runetotem", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 1384460, text = "Greetings! It is fortunate I found you. Your presence is requested at Moonglade." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1384483, text = "Centabra's camp is on the western shore of the lake. Nerulex was camped on the eastern shore, but he's prone to wandering off, so keep your eyes and ears open." },
            { id = 1384461, text = "I'll meet you there as soon as you conclude your business in Dalaran." },
            { id = 1384484, text = "Malfurion waits for you by the Barrow Dens to the east. Follow me." },
            { id = 1384492, text = "Opening the path to this ancient home of all druids will be no small feat. I hope you're ready for the task." },
            { id = 1384503, text = "Thank you. We barely survived their last attack." },
            { id = 1384523, text = "The demon's assault is relentless. I require aid." },
            { id = 1384525, text = "The Gateway is activating!" },
            { id = 1384506, text = "The Legion has not forgotten their defeat here." },
            { id = 1384486, text = "The Legion's arrival has thrown our world out of balance. I've sensed great unrest within the Emerald Dream." },
            { id = 1384490, text = "Their knowledge of druidism is ancient and unparalleled. Having their might on our side is essential if we are to stop the Legion." },
            { id = 1384488, text = "There are powerful druids in Val'sharah who grew under Cenarius's tutelage after the Great Sundering." },
        } },
    } },
    { who = "Archaedas", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5859643, text = "On Azeroth, the Pantheon sensed a powerful source of corruption. To protect the world soul, they sent us, the Keepers, to lead the titan-forged forces into battle." },
            { id = 5859637, text = "The Pantheon made their way to the nascent world-soul, hoping that their search was at an end." },
            { id = 5859645, text = "Then, led by Aman'thul himself, the titans set towards studying the soul of Azeroth to determine whether it truly was the one they sought." },
            { id = 5859635, text = "This world soul, the most powerful in existence, they would guide to become the greatest titan of all." },
            { id = 5859634, text = "To create order from the chaos of the cosmos, the titans search the great dark beyond for the Prime World Soul." },
            { id = 5859647, text = "Working in tandem, they would bring order to Azeroth and create a means by which the Pantheon could examine the world soul in depth." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5859654, text = "At the Titan's command, we Keepers began the acclamation. Each installation, all linked to the Manifold, produced vast numbers of Titanforged workers." },
            { id = 5859636, text = "In time, they came to sense a mighty presence within the world called Azeroth." },
            { id = 5859644, text = "In time, we rooted out and defeated the threat, imprisoning its last vestiges in the deep places of the world." },
            { id = 5859632, text = "The great titan Khaz'garoth, who granted me the gift of the Forge, has relayed information from the Pantheon about our purpose." },
            { id = 5859646, text = "To aid the Titans, we Keepers were tasked with engineering the Manifold, a vast world-spanning complex of machines, forges, and installations." },
            { id = 5077753, text = "We will await your return!" },
        } },
    } },
    { who = "Archeo Tinkologist Gnome", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2962076, text = "I concur, but that doesn't mean that this is Mechagon." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2957908, text = "Goblins! Quick, break the machines!" },
            { id = 2962074, text = "He's not sending Gila to come get us, is he?" },
            { id = 2957909, text = "This no-mesh technology is way out of your league, simpleton!" },
        } },
    } },
    { who = "Archimonde", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 544144, text = "ALL CREATION WILL BE DEVOURED!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 598934, text = "AHA!" },
            { id = 598937, text = "NOOO!" },
            { id = 598940, text = "UGH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1124421, text = "You have failed this world." },
            { id = 1124427, text = "You have only delayed the inevitable! The Burning Legion consumes all!" },
            { id = 544142, text = "Your soul will languish for eternity!" },
            { id = 1124420, text = "Your souls are mine!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 544149, text = "I am the coming of the end!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1124425, text = "The pitiful light you call upon is powerless against me, child. End this foolishness." },
            { id = 1124431, text = "Worthless mongrel, your miserable race will suffer endlessly for your rebellion." },
            { id = 1124423, text = "Your foolish crusade ends here, mortals. The Legion comes, and with it, this world breathes its dying breath." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 598952, text = "AAARGH!" },
            { id = 598955, text = "AHHH!" },
            { id = 598946, text = "GRRR!" },
            { id = 598958, text = "OOF!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1124430, text = "Destruction comes! Loak! Vorsh! Sorankar!" },
            { id = 1124428, text = "Enough! Your meaningless struggle ends now!" },
            { id = 1124422, text = "Let the echoes of doom resound across this wretched world, that all who live may hear them and despair." },
            { id = 1124429, text = "Look upon the endless forces of the Burning Legion and know the folly of your resistance!" },
            { id = 1124426, text = "Rick, Amenolar, Golad, Mission Amirshi!" },
            { id = 1124424, text = "This meaningless little world has already succumbed to my corruption. The land itself seethes with the Mark of the Legion." },
        } },
    } },
    { who = "Architect Ruffious", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5736146, text = "Is your query crucial? Cycles are short today." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5736137, text = "I need people to dig ore, not their own graves. Hint. Hint." },
            { id = 5708726, text = "My inventory's open for you." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5708731, text = "Come back if you need anything." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 5708729, text = "Greetings, Outlander. Come see what's new." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5736149, text = "Conversation terminated. Be safe." },
            { id = 5708728, text = "Here for a reward?" },
            { id = 5708732, text = "I'll have more soon." },
            { id = 5736140, text = "Make it quick, please. We have a tight schedule." },
            { id = 5736152, text = "Returning to task." },
            { id = 5736143, text = "What task can I perform for you?" },
        } },
    } },
    { who = "Archivist Betha", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 5789455, text = "Good to see a friendly face." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5788594, text = "A solvent was knocked over and dissolved the webbing of our cages. How fortunate." },
            { id = 5789454, text = "Oh, hello there." },
        } },
    } },
    { who = "Archivist Edress", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4665424, text = "I look forward to your research." },
            { id = 4663944, text = "I suspect the Jaradin have instead used their elemental magic to crack the earth beneath the citadel, entering from within Neltharis, the obsidian fortress." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4665423, text = "Come back with more findings!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4663940, text = "Despite some questionable methods, it is hard to deny Wrathion's results. He has worked tirelessly to protect all creatures of Azeroth from numerous threats." },
            { id = 4663948, text = "Erm, please, I would like to accompany you as well. My knowledge of this Citadel could be of much use." },
            { id = 4663946, text = "It is an honor to be in the presence of such an esteemed ally of the Black Prince." },
            { id = 4663947, text = "Sabelian and Rathian have been arguing since you left." },
            { id = 4663949, text = "The walls of the Obsidian Citadel have stood strong for thousands of years." },
            { id = 4663941, text = "These vaults stretch for miles beneath the Citadel. Many powerful weapons and artifacts were locked away here for safekeeping." },
            { id = 4663942, text = "Well, left unattended for so long, it seems these vaults have fallen into disarray." },
            { id = 4663943, text = "Where an aspect failed, Sabelian succeeded. Despite Deathwing's madness, despite the rage of the Grann, Sabelian and his kin survived, allowing us to achieve this moment." },
            { id = 4663945, text = "With that kind of strength, there is no way the Jaradin could have attacked it head-on." },
        } },
    } },
    { who = "Archivist Roh Senara", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4077363, text = "In time you will understand." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4077357, text = "I am in your debt, mortal." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4077364, text = "Take your place at my side, mortal." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4077361, text = "Heed the words of the Archivists, Rosuir. The staff requires both anima and wisdom to function." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4077362, text = "They served the purpose as intended, and their wisdom aids us still." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4077354, text = "Adversity will not impede the purpose." },
            { id = 4077356, text = "Dwell not on loss. Focus on what remains." },
            { id = 4077359, text = "Fear not, Rosweir. My resolve endured." },
            { id = 4077353, text = "Pain is temporary. Experience lasts forever." },
            { id = 4077355, text = "Power must always be tempered by wisdom." },
            { id = 4077360, text = "Recover the load staff. We will await you in a safer locale." },
            { id = 4077358, text = "You must have been sent by Rosweir. I will go to him at once." },
        } },
    } },
    { who = "Archmage Ansirem Runeweaver", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 1370262, text = "Ah, very well. I trust the wisdom of Car Lane's counsel. I vote yes." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370258, text = "How do we know he won't betray the Kirin Tor once again?" },
            { id = 1413878, text = "We do not tolerate misconduct amongst our own conjurer. However, if your accusation against Archmage Vargarth proves malicious, know that the consequences will be severe." },
        } },
    } },
    { who = "Archmage Drenden", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 5723148, text = "Good to see you, champion!" },
