        { name = "Loyalty", family = "Manners", lines = {
            { id = 1679001, text = "Blade and spell, ready to serve the light." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1679000, text = "Anything can be a weapon with the right mindset." },
            { id = 1684263, text = "Arcanos vi a cahachi." },
            { id = 1678997, text = "Keep an eye out for anything useful." },
            { id = 1678999, text = "The Legion will stop at nothing. Be careful." },
            { id = 1684260, text = "We will destroy you, no matter the cost!" },
            { id = 1679002, text = "We will redeem our home." },
            { id = 1684331, text = "You! You're not a demon! Come here and help us kill some!" },
        } },
