            { id = 1405144, text = "I sense you are overwhelmed by my expertise." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1405146, text = "I am willing to bear a mountain of gold that you taste vinegar in all that you drink. plebeian" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1405138, text = "Ah, this is a fine vintage. Seventh generation Manafruit, entangled with slippery night sap flavors and a delicate walnut finish." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1405139, text = "This is a heavy blend of barely ripe Shadowberry and Mana fruit, triple infused with Nightwell essence. It is best appreciated in small sips." },
