        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405145, text = "A savant yourself, I can guess. A very likely story." },
            { id = 1405141, text = "No flavor escapes my notice." },
            { id = 1405148, text = "Only the best will reach Elissande's glass." },
            { id = 1405147, text = "This place is home to the finest vintages." },
            { id = 1405137, text = "This three-year infusion incorporates delightful berry elements with a scintillating melon bouquet. Refreshing, yes?" },
