    { who = "Argus Shivan", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1684305, text = "NOTHING CAN STOP THE MASTER!" },
            { id = 1684304, text = "THIS BEAN IS NOTHING!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1684264, text = "I have broken countless mortals! What chance do you think you have?" },
            { id = 1684307, text = "You are blind to the truth!" },
            { id = 1684261, text = "You dare set foot on his world! You will die!" },
            { id = 1684303, text = "You will not escape your fate!" },
            { id = 1684255, text = "Your corpse will make a fine trophy for the master!" },
            { id = 1684258, text = "Your light will not save you! Not here!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1684267, text = "Don't you see? This is the only way! I will make you understand!" },
