        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1369816, text = "It calls to souls long dead! RISE!" },
            { id = 1369819, text = "Souls of the dead, aid your master!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1369814, text = "Face the fury of the beast!" },
            { id = 1369815, text = "Feel the wrath of the world ender!" },
            { id = 1369818, text = "That voice... Father?" },
            { id = 1369813, text = "Uthalash feasts tonight!" },
            { id = 1369812, text = "Very well! If you so thirst for the power of the scythe, then I will show it to you myself!" },
