        { name = "Conversation", family = "Feelings", lines = {
            { id = 3595079, text = "Fly with wisdom." },
            { id = 3595081, text = "Let us never falter." },
            { id = 3595083, text = "Our purpose is clear." },
            { id = 3595533, text = "The Archon calls, and her collectors answer." },
            { id = 3595532, text = "Though our numbers dwindle, we will never falter." },
            { id = 3595531, text = "Well done. You finally conquered your deepest doubts." },
            { id = 3595530, text = "Your arrival is timely. Pelagos battles not a memory, but his own doubt." },
        } },
    } },
    { who = "Arkhaan", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1688407, text = "WHY THEY NOT LISTEN?!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1688402, text = "My people, once." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1679013, text = "Ah. Oh, yes?" },
            { id = 1688406, text = "Arkhan will make you understand!" },
            { id = 1679011, text = "Close your ears to the whispers." },
            { id = 1688404, text = "It will all be undone! There's nothing but the void!" },
            { id = 1679010, text = "Shh! Did you hear that?" },
            { id = 1679009, text = "Strangers speak strangely." },
            { id = 1688403, text = "Thank you! Thank you!" },
            { id = 1688405, text = "You must know the truth!" },
        } },
    } },
    { who = "Arkonarin Starshade", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5244267, text = "You will not harm him on my watch, fiend!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5244293, text = "I don't have time to sit here and reassure you." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5244292, text = "All that pacing is making me nervous, brother." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5244286, text = "As you command, Warden." },
            { id = 5244240, text = "Haha, go on." },
            { id = 5244266, text = "Lysander look out" },
            { id = 5244242, text = "Lysander, are you..." },
            { id = 5244295, text = "Meet us in Bellwood, champion. We will be waiting for you there." },
            { id = 5244256, text = "Mother and father would be proud, as am I." },
            { id = 5244288, text = "Of course, Warden." },
            { id = 5244285, text = "You're the one always telling me to be strong in the face of adversity, Lysander." },
        } },
    } },
    { who = "Arluelle", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1523951, text = "WE HAVE BEEN DISCOVERED!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1524017, text = "I think I have it now." },
            { id = 1407726, text = "I understand, he never could stay out of trouble." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1524022, text = "Am I doing this right?" },
            { id = 1523953, text = "As you say." },
            { id = 1407725, text = "Ollowin? Is that you? It is so dark..." },
            { id = 1407727, text = "Thank you. I will remember this." },
            { id = 1524019, text = "That feels much better." },
            { id = 1407724, text = "Who is there?" },
        } },
    } },
    { who = "Arluin", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1405150, text = "I accept your gratitude, by the way." },
            { id = 1405151, text = "I like the way you think, Lunasta." },
            { id = 1405149, text = "I will go home. I have no business among such esteemed individuals." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1405152, text = "Now that, that is more like it. It so happens that I am the perfect living soul for this job." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405153, text = "Always a pleasure do things my way and she'll be advisor before dinner" },
            { id = 1405159, text = "Are you lost?" },
