    { who = "Arthas", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1503740, text = "GRRR!" },
            { id = 1503741, text = "HIYAH!" },
            { id = 1503742, text = "HMMM!" },
            { id = 1503739, text = "HMPH!" },
            { id = 544366, text = "HYAH!" },
            { id = 544333, text = "UGH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2400759, text = "Citizens of Quel'Thalas, I have given you ample opportunities to surrender, but you have stubbornly refused. Know that today, your entire race and your ancient heritage will end." },
            { id = 1397166, text = "Rage against the nightmare. Struggle as you will." },
            { id = 4072758, text = "Uther, do you have a moment?" },
            { id = 1397139, text = "What? An intruder? You won't stop me. Frostmourne will be mine!" },
            { id = 1397138, text = "Yes, you are right. I will bear any curse to have my revenge." },
            { id = 1397158, text = "You believe that you are in control, that your will is your own." },
            { id = 1397161, text = "You imagine yourself to be free, but you will always be his instrument." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4072618, text = "Honestly, yes. I see your devotion to the light and feel doubt cloud my heart." },
            { id = 4072757, text = "I do what I must for Lordaeron." },
            { id = 1397143, text = "I see only darkness before me." },
            { id = 544357, text = "I will not allow this plague to spread." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1503752, text = "Back!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 544374, text = "AHHH!" },
            { id = 544385, text = "ARGH!" },
            { id = 544342, text = "GAH!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1397140, text = "Aaaargh! The darkness... I can't... I..." },
            { id = 544337, text = "Argh! Damn you, Malganis! Cough. Cough. Cough. Father. Jaina. I have failed, Lordaeron." },
            { id = 1397165, text = "The darkness does not die." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1503738, text = "HEY!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1397155, text = "See the spirits writhe and twist." },
            { id = 1397162, text = "So many fallen kings, silent in their numberless graves." },
            { id = 2400755, text = "You may have been formidable once, but I sense your soul fading, your life force flickering weakly, a flame I will gladly extinguish." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 544384, text = "A small sacrifice for the greater good." },
            { id = 4072605, text = "Damn it, Uther! As your future king, I order you to purge this city!" },
            { id = 2400757, text = "Death itself has come to claim the high home of the elves!" },
            { id = 1397163, text = "Even the mighty are rendered nameless by time." },
            { id = 1397164, text = "Every king must kneel before death." },
            { id = 1397142, text = "Feel the icy chill of death around you!" },
            { id = 4072622, text = "Haha, it always does." },
            { id = 2400754, text = "Invincible!" },
            { id = 544378, text = "Lordaeron will be saved." },
            { id = 544350, text = "May the light have mercy, for I will not." },
            { id = 1503748, text = "NAH!" },
            { id = 2400756, text = "Not for long." },
            { id = 1397137, text = "Nothing will stand in the way of my vengeance!" },
            { id = 1503753, text = "Thank you. Thank you." },
            { id = 1397157, text = "The dead outnumber the living, and always will." },
            { id = 1397156, text = "The numberless shades, forsaken by time." },
            { id = 4072607, text = "Then I must consider this an act of treason." },
            { id = 544383, text = "This city will be cleansed." },
            { id = 4072602, text = "This entire city must be purged!" },
            { id = 2400753, text = "Witness the end. The removal of the final barrier." },
            { id = 1397159, text = "Yet you do as he commands." },
            { id = 1397160, text = "You exist by his whim alone." },
            { id = 4072619, text = "You've taught me so much, Uther, but I sometimes wonder if I'm truly meant to walk this path." },
        } },
    } },
    { who = "Arygos", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 544405, text = "I have agreed to this meeting, Worldbreaker, but at great risk. If this is discovered..." },
            { id = 544410, text = "I was raised at the feet of my father." },
            { id = 544407, text = "I watched as he steered us through adversity, never flinching from difficult decisions." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 544406, text = "Fools! Neltharion take you all!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 544412, text = "Brothers, we must take what is ours. Under my leadership, this flight will rise again, beyond the glory of our past, onwards to an even greater destiny. I will see to it." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 544415, text = "And once this new order is established, my place will be secure, yes?" },
            { id = 544404, text = "He put the needs of this flight first and foremost." },
            { id = 544413, text = "Our future promises even greater threats." },
            { id = 544414, text = "Our history has been wrought with great challenges." },
            { id = 544409, text = "Some called my father mad, but even in his darkest hours, his vision was clear." },
            { id = 544408, text = "These circumstances demand a powerful leader." },
            { id = 544411, text = "We gather to determine the fate of our troubled flight." },
        } },
    } },
    { who = "Arzaal", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5557639, text = "Do not be afraid." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5557317, text = "The Tishamat. I... Thank you. But surely my presence would cast a shadow over the sacrament." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5557323, text = "As you wish, prophet." },
            { id = 5557256, text = "Hatun is right. Something is hidden here. And I will reveal it." },
            { id = 5557262, text = "Maledeth enchil! Maev racketiros!" },
            { id = 5557184, text = "Of course. Khatun, take the stargaite shard. It will guide you towards any fel magic of Manari origin." },
            { id = 5557116, text = "Their opportunism ends today. I will slaughter each one personally, if needs require it." },
            { id = 5557066, text = "This corruption caused by the Exodar crash feels... strange." },
            { id = 5557250, text = "This Satyr camp appears abandoned, but the fel resonance is stronger here than anywhere else on the island." },
            { id = 5557640, text = "Yes, what is it?" },
            { id = 5557166, text = "Yes. These crystals were made into fell-spreaders. No satyr could do that. A Manari artificer made them. I know it." },
        } },
    } },
    { who = "Asara", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1686513, text = "His fate was ours to decide. You will pay for your insolence, mortals!" },
            { id = 1692897, text = "Ignore him, sister! Focus on your duty! These souls are nearly ready to join Aggramar in the Master's service." },
            { id = 1685501, text = "You cannot escape the shadows!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1686519, text = "Enough of this! Let the shadows claim them all!" },
            { id = 1685504, text = "There is no light that can pierce my shadow." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1686517, text = "Perhaps the Nathrezim has grown too familiar with the Torment of Flames, my sisters." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1686515, text = "Lack of faith is his undoing. The fel will consume the unworthy." },
            { id = 1685500, text = "You look so vulnerable trembling in the dark." },
            { id = 1685503, text = "You were right to fear the dark." },
        } },
    } },
    { who = "Ascended Projection", tier = "character", groups = {
