    { who = "Ashendir Hartwood", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5228017, text = "WE HAVE EMBRACED THE FLAME! LET THE FLAME EMBRACE YOU!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5328473, text = "My flame... will burn... Eternal..." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5328458, text = "A mere drusil will fall to flame!" },
            { id = 5228020, text = "A singular tear could never extinguish the flame!" },
            { id = 5328470, text = "Firak shall open the way!" },
            { id = 5228078, text = "The fires of change have arrived, and yet you cling to your stagnant ways." },
            { id = 5228011, text = "The flame consumes all! Embrace its power!" },
