    { who = "Ashildir", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1244105, text = "I am sorry, Hiro. I have doomed us both." },
            { id = 1238997, text = "I know your worth. I will grant you an audience with a year." },
            { id = 1244091, text = "It is done, Helya! We have fulfilled your bargain, and we will collect our payment!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1244109, text = "Ugh! Disgusting! This plan better work, spirit!" },
            { id = 1244115, text = "Your spirit feels weaker. What has she done?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1244097, text = "Her hold is weakening. She cannot keep us here!" },
            { id = 1244107, text = "Perhaps this cowering wretch might be of some use." },
            { id = 1239018, text = "Seek your fate in a vault, champion. May a year be your wings." },
            { id = 1244111, text = "Such a revolting disguise! My armor still reeks of seaweed!" },
            { id = 1238247, text = "What is this? The hero of Helheim seeks entrance to the Vault?" },
            { id = 1239015, text = "You may proceed, but know that a year may not regard you as I do." },
            { id = 1244101, text = "Your terms were met, Helya. It seems even you must honor your word." },
        } },
    } },
    { who = "Ashtongue Stalker", tier = "character", groups = {
