        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3571290, text = "Bring me more wine! But stay where you are." },
            { id = 3571266, text = "You are a terrible leader, King Rin!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3571291, text = "I am far too perfect and beautiful to be defeated!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3571292, text = "You ill-mannered and unfashionable fools will get what's coming to you!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3571289, text = "Run right, but go left!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3571261, text = "Con time. Well then, I'll just kill the tree!" },
            { id = 3571267, text = "How dare you!" },
            { id = 3571259, text = "Lay siege to the World Tree!" },
            { id = 3571288, text = "Stand still, but keep moving!" },
        } },
