    { who = "Astralite Visara", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1967737, text = "HAHA!" },
            { id = 1967734, text = "HRRR!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1959770, text = "Gloves on! We mustn't get our hands dirty." },
            { id = 1959774, text = "Goodness me, how frightfully unladylike!" },
            { id = 1959776, text = "How dare you bleed on me! Oh, do be more careful." },
            { id = 1959771, text = "How utterly... unsatisfactory." },
            { id = 1959775, text = "Oh, how unfortunate. For you, Alliance. We will put you in your place soon enough." },
            { id = 1959772, text = "Oh, it is you. Hello." },
            { id = 1959773, text = "Tsk, tsk. Let me fix that." },
        } },
    } },
    { who = "Ataanya", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5550615, text = "If you are here to interrupt me, be advised that I have an arc welder and zero patience." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5556870, text = "I tell you to leave, and instead you rob my father's grave!" },
            { id = 5556882, text = "My father was Draenor's greatest artificer." },
            { id = 5556697, text = "My work is here, in Shattrath. I will not put it on hold to attend some archaic holiday." },
            { id = 5556773, text = "My work is very precise. I don't need a clumsy novice's hands in it." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5550619, text = "Get the crystal from Beroon, then get out of my workshop." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 5556867, text = "Ah, what is wrong with you?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5556700, text = "As I told Rammel, the schematics are ready, but if he is waiting for me at the Exodar, he can keep waiting." },
            { id = 5556776, text = "Berun! Get the crystal. You, take it to Rammul. Tell him I have my reasons for not attending the Tishamat." },
            { id = 5556864, text = "Ugh, for light's sake, why are you back?" },
            { id = 5556770, text = "Ugh, you! If I needed help, I would have asked for it." },
        } },
    } },
    { who = "Athanos", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3588428, text = "I hope you have enjoyed this interaction." },
            { id = 3588216, text = "You have been weighed. You have been measured." },
            { id = 3588214, text = "Your efforts are insufficient, aspirant." },
            { id = 3588218, text = "Your path to glory will be a long one." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3588427, text = "Go forth and serve." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3588426, text = "Continue your progress." },
            { id = 3588213, text = "Error. Humility sequence terminated." },
            { id = 3588212, text = "Initiating humility sequence." },
            { id = 3588219, text = "It is not yet time for you to ascend." },
            { id = 3588429, text = "Until I am needed again." },
            { id = 3588217, text = "You require more training." },
            { id = 3588215, text = "Your training is incomplete." },
        } },
    } },
    { who = "Athissa", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1242829, text = "FIND THAT TYBESTONE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1242817, text = "Your orders are clear! Find the Tidestone and return it to her glory, Queen Azshara!" },
            { id = 1242825, text = "Your Queen Azshara wills it, and so shall it be done!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1242827, text = "Hey Kyle! Seize them!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1242821, text = "Enough of this! The Tidestone will be ours!" },
            { id = 1242811, text = "How perfectly convenient! The brainless oaf led us right to the Tidestone!" },
            { id = 1242819, text = "Our queen beneath the tides can reassemble the pieces!" },
            { id = 1240588, text = "Pardesh! Rally the rest of our forces! I shall make short work of this minor interruption!" },
            { id = 1242815, text = "pillage the ruins" },
            { id = 1242831, text = "Scour the sands!" },
            { id = 1242823, text = "Slay anyone and anything that gets in your path!" },
            { id = 1242813, text = "These creatures only pretend to understand its power. The Tides Stone belongs to Azshara, her radiance, the light beneath the tides!" },
        } },
    } },
    { who = "Athrikus Narassin", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1405878, text = "Ah, reinforcements at last. You have the Book of Medivh? I expected Jergosh, but you will do. Still, your timing could have been better." },
            { id = 1405860, text = "You have yet to experience my true power!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1405888, text = "I can sense unrest nearby. Let us investigate. Come along." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1405889, text = "There, the unquiet dead bar our path. Get that spirit out of my way, will you?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405866, text = "A great master? Which of us is to wield the scepter?" },
            { id = 1405887, text = "Came up empty? No Nagars either, I see. Not to worry. We all know how the lower echelons of our group scramble for position. Enough nonsense. What we seek is here." },
            { id = 1405890, text = "Hmm, yes, I see. This entry clearly speaks of a void terror. It must have consumed the eye in the Twisting Nether. Quickly! Let us get to Baradun Hold!" },
            { id = 1405881, text = "In his infinite wisdom, Nagaas here sent his only remaining disciple to scout below. I suggest you find out what happened to him while we search elsewhere." },
            { id = 1405876, text = "Insolent orc, you should have awaited my arrival" },
            { id = 1405880, text = "It matters not. Gul'dan knows the eye is here, but Tor Barad is huge and overrun. I believe an important document, a manifest of prisoners, is located in this block." },
            { id = 1405868, text = "It seems we are to be foes after all. Pity, you would have made an excellent servant." },
            { id = 1405861, text = "Slain by a low-born, though beneath me." },
        } },
    } },
    { who = "Atolia Seapearl", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3006672, text = "Don't have all day." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3006664, text = "No living thing deserves to be enslaved by Azshara. Break the chains! Break the slavers! Break the Naga!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3006663, text = "A band of naga slavers has invaded the area. Cheer those snakes apart!" },
            { id = 3006665, text = "Looks like the Tortollans have cooked up a new plan to deal with these brutes. I say you give it a shot!" },
            { id = 3006666, text = "Not bad! I got a bit dizzy just watching you!" },
            { id = 3006668, text = "See you around!" },
            { id = 3006662, text = "That's the stuff! Keep up the good work!" },
            { id = 3006669, text = "Try not to be too reckless." },
            { id = 3006661, text = "We need to keep this passage safe for our scouts! Close up those vents!" },
            { id = 3006671, text = "Well, out with it." },
            { id = 3006670, text = "You need me, you know where to find me." },
        } },
    } },
    { who = "Attumen the Huntsman", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1513492, text = "I have become the Hunted." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1513494, text = "My quarry never escapes!" },
            { id = 1513487, text = "My trophy collection grows!" },
