        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1513491, text = "Rise up, Midnight! Stab them into dust!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1513497, text = "Ah, faithful Midnight. For many years, our countless hunts provided gain for the Master's Table." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1513493, text = "Four Branks! Charge!" },
            { id = 1513489, text = "They had no chance! I kill for a living!" },
            { id = 1513495, text = "Time to face my quarry toe-to-toe" },
