    { who = "Auchwarden", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1033709, text = "A foul force has penetrated these sacred chambers." },
            { id = 1033711, text = "No! No, she cannot! My mind is not my own!" },
            { id = 1033707, text = "Okunai, secure this chamber." },
            { id = 1033710, text = "Scout ahead while we establish a foothold." },
