    { who = "Aumyza", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4077675, text = "I suggest playing your instruments rather than fighting with them!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4077682, text = "Stop the performance! There's no one left to hear it." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4077681, text = "Ah, the next band has arrived. Please, take the stage. And remember, I am quite generous with those who managed to entertain my guests." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4077686, text = "A round of applause, please, for our next musical act!" },
            { id = 4077685, text = "Any more performers in the audience?" },
            { id = 4077684, text = "Cartel Sol's underhanded dealings have not escaped my attention. You may have my signature, as long as you never again bring destruction to my oasis." },
            { id = 4077683, text = "It has been an age since I witnessed such a vigorous show. My establishment would not survive another." },
            { id = 4077676, text = "So, it will be a true battle of the bands!" },
            { id = 4077680, text = "That concludes the musical stylings of the Synthstorm swingers." },
            { id = 4077677, text = "They should have learned to play before this performance." },
            { id = 4077678, text = "Who let in these novices?" },
        } },
    } },
    { who = "Auralia Steelstrike", tier = "character", groups = {
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 5724552, text = "The darkness comes, we are prepared." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5724571, text = "For the Empire." },
            { id = 5725049, text = "We are the holders of hope." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5724533, text = "Always be prepared." },
            { id = 5859508, text = "Excellent job. We'll put these to good use. May the flame light your way." },
            { id = 5727716, text = "General, it would be inappropriate of me to let you know that they are doing well and look forward to their grandmother visiting for dinner." },
            { id = 5727719, text = "I've sent over multiple official requests for an answer. They've ignored them all." },
            { id = 5727718, text = "running very low on consecrated alchemy. The Priory missed its last shipment. I think they're hoarding." },
            { id = 5725161, text = "Sacred Flame, guide your way, friend." },
            { id = 5859507, text = "The crystals embedded in this cliff face shine with Belladar's radiance. Our key flame crystals require their retrieval." },
            { id = 5725068, text = "We must prepare for Belladar to shift." },
        } },
    } },
    { who = "Auriaya", tier = "character", groups = {
