    { who = "Avatar of Sethraliss", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1957542, text = "RIDE IN AGONY!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1957539, text = "I will rend your souls!" },
            { id = 1957540, text = "The Hex is shattered, but the temple's defenses have awakened." },
            { id = 1957549, text = "You have my gratitude, heroes." },
            { id = 1957548, text = "Your lives were meaningless, and in death you are forgotten." },
            { id = 1957547, text = "Your screams will echo for eternity!" },
