        { name = "Boasts", family = "Menace", lines = {
            { id = 1957546, text = "I hold dominion over all!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1957550, text = "Though it will be some time before my full power is restored, the curse that prevented my return has been broken." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1957541, text = "Restore me, and I will disable them!" },
            { id = 1957545, text = "The storm has broken, and I am myself again. Thank you." },
