    { who = "Barnes", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1517692, text = "WELCOME, LADIES AND GENTLEMEN, TO OUR O" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1513302, text = "Can the fair Bella learn to love the surly brute? Or will a ghastly curse claim the lives of the prince and his servants?" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1513400, text = "Divided by generations of enmity, they are brought together by passion for dance. And violence!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1513401, text = "As the song of their love rumbles across the fields, will it end in triumph or tragedy? And now, on with the show!" },
            { id = 1513300, text = "Good evening ladies and gentlemen. We proudly welcome you to this evening's feature presentation." },
            { id = 1513398, text = "Ladies and gentlemen, welcome to this evening's feature presentation!" },
            { id = 1513303, text = "See for yourself whether the rose of passion blooms beneath a beastly veneer. And now, on with the show!" },
            { id = 1513301, text = "Tonight, a tale of romance and rage, one which will prove once and for all if beauty is more than skin deep." },
            { id = 1513399, text = "Tonight, we meet two lovers born on opposite sides of Sentinel Hill." },
        } },
    } },
    { who = "Baron Braunpyke", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5769511, text = "BY MY HOLY HAMMER!" },
            { id = 5769507, text = "SHIELDED BY FLAMES LIGHT!" },
