        { name = "Mockery", family = "Menace", lines = {
            { id = 5769504, text = "Of course you fool!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5769509, text = "By fire, I am healed!" },
            { id = 5769506, text = "By my shield!" },
            { id = 5769513, text = "By the Emperor's will!" },
            { id = 5769512, text = "Flame cleanse you" },
            { id = 5769508, text = "Flame's Wrath, heal me!" },
            { id = 5769510, text = "Glory guides my hammer!" },
