        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1589320, text = "Their souls shall bear the torment of defeat for all eternity." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1588745, text = "Born soon, and you think I am the cruel one." },
            { id = 1589318, text = "Physical pain? Bah! Mental anguish is the true weapon. Was it not the key to turning rockies?" },
            { id = 1589325, text = "Resistance will only bring pain!" },
            { id = 1589319, text = "Sooner than expected, but no matter. Our work begins." },
            { id = 1589323, text = "Why endure this pain? Kneel to the Legion!" },
