    { who = "Bella", tier = "character", groups = {
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1513329, text = "No! Our dinner's together! Those hours in the library! Oh, Brute, I love you!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1513322, text = "If you didn't yell all the time, I wouldn't run away!" },
            { id = 1513333, text = "It is you! Come, my love, off to our happily ever after!" },
            { id = 1513319, text = "Never! I only dine with gentlemen, not a brute like you!" },
