            { id = 1998406, text = "Hey, you! Yes, you. Are you the one that's been asking around about the General?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1998407, text = "Alright when you're ready, but let's not waste time. Bakira won't last long in the sands." },
            { id = 1998403, text = "She's here! She's alive! RAKIRA!" },
            { id = 1998401, text = "Someone in this strange temple must know something." },
            { id = 1998411, text = "The serpent men? I thought they hid mostly beneath the dunes." },
            { id = 1998400, text = "Ugh! Ugh! Hiro, is that you? Where are we?" },
            { id = 1998410, text = "Up ahead! I see the pass. Fly low and keep an eye out for any sign of Rakira." },
            { id = 1998408, text = "We need to travel to the swamp. As long as we stay in the air and out of sight, we shouldn't have too much trouble." },
            { id = 1998405, text = "What have they done to you?" },
