        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1311076, text = "WE WILL TAKE THE KEYSTONE!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1311078, text = "I did not make it this far just to die on this rock!" },
            { id = 1311074, text = "I will not let you down." },
