        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1311081, text = "Do not give in to the power of the Legion." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1311075, text = "For Lord Illidan!" },
            { id = 1311080, text = "If we do not meet again, die well." },
            { id = 1311079, text = "Remember, nothing is more important than the Legion's destruction." },
            { id = 1311071, text = "Thank you. Back into the fight." },
            { id = 1311073, text = "The Burning Legion will fall." },
            { id = 1311082, text = "Trust in Lord Illidan's plan." },
