    { who = "Bloodseeker Jochunga", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1953333, text = "Get down! Her rig is coming!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1953334, text = "Good! He believes we are dead. We need... a new plan." },
            { id = 1953330, text = "Great Riek, we beg for mercy, almighty one. Spare us!" },
            { id = 1953328, text = "Haha! It's working! Keep stopping! Keep stopping!" },
            { id = 1953336, text = "Oh no! It's Eric!" },
            { id = 1953331, text = "Oh, all right. Very well then. Now!" },
            { id = 1953335, text = "This is it. Either the plan works, or we are dead." },
            { id = 1953329, text = "Ugh, I think my leg is broken." },
            { id = 1953684, text = "Watch yourself now. I need you alive." },
            { id = 1953337, text = "What are you doing?" },
            { id = 1953338, text = "Your disguise is gone, but why does man still work? Hmm, I think this changes things." },
        } },
    } },
    { who = "Bo", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3584273, text = "I believe we are finished. How do you feel?" },
            { id = 3584276, text = "I won't stop fighting until you show me your new skill!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3584270, text = "Come, let us meditate and unlock our inner potential." },
            { id = 3585542, text = "Take care of yourself." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3584271, text = "Close your eyes. Find your center." },
            { id = 3584275, text = "Impressive. Your skills have grown tremendously. Let's return to camp." },
            { id = 3584274, text = "Let me see what you've learned." },
            { id = 3584272, text = "Let the world fade away." },
            { id = 3585540, text = "Maintain your balance." },
            { id = 3585543, text = "Persistence can win any battle." },
            { id = 3585544, text = "Power comes through focus." },
        } },
    } },
    { who = "Bobby Howlis", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1951910, text = "GAAH!" },
            { id = 1951909, text = "GRRR!" },
            { id = 1951912, text = "HA!" },
            { id = 1951914, text = "HEH!" },
            { id = 1951911, text = "HMPH!" },
            { id = 1951908, text = "HRRR!" },
            { id = 1951905, text = "RRR!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1864083, text = "Ha! Time to hunt!" },
            { id = 1864085, text = "No! I'll never go back to that cell! NEVER!" },
            { id = 1864084, text = "You're the one who's supposed to bleed." },
        } },
    } },
    { who = "Boja", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1385572, text = "Aye, she be outside directin' her demons to load up more captives. I be havin' a score to settle with her. So if you be aimin' to take her out, count me in." },
            { id = 1385571, text = "Many thanks again, mon, for getting me out of here." },
            { id = 1414898, text = "Taz Dingo! Thank you for getting me out there!" },
            { id = 1385573, text = "You two can yell at each other later. It'd be time to get out of this place." },
        } },
    } },
    { who = "Boku", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4676055, text = "I walk a path of peace. It would not be wise to offer me… alternatives." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4677669, text = "Destroy these graverobbers and return our ancestors to their rest, before they are forced to fight in Balakar's name." },
            { id = 4676049, text = "Follow your heart." },
            { id = 4676047, text = "Go where the wind takes you." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4677666, text = "They have desecrated the graves of our first ancestors, Tyra and Maruk." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4676050, text = "Bless you. Stay safe." },
            { id = 4676054, text = "Calm heart, clear vision." },
            { id = 4677663, text = "Clan Ukel has allied with Clan Nokud. Today, they will regret that alliance." },
            { id = 4676048, text = "Fair skies, friend." },
            { id = 4676051, text = "Oh, did you want to talk to me?" },
            { id = 4676052, text = "See what others cannot." },
            { id = 4676053, text = "Your name is whispered on the wind." },
        } },
    } },
    { who = "Boldbrew", tier = "character", groups = {
        { name = "Victory", family = "Fighting", lines = {
            { id = 851997, text = "Ah, that was a close one, thank ye!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 851993, text = "Haha! Take this, you blue-skinned hag!" },
            { id = 851995, text = "Heh, tryin' to roast me, ya snaggle-toothbone biter! I'll show ya!" },
            { id = 851999, text = "There's only a few of us left. The ones they don't eat, they butcher at some big altar. It's just northwest of here. If you hurry, you might be able to save some. Sorry, I don't know anything more." },
            { id = 851991, text = "You ain't cookin' me, you long eared snowhopper!" },
        } },
    } },
    { who = "Boltcog", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 545220, text = "HA!" },
            { id = 545222, text = "UGH!" },
            { id = 545221, text = "YEAH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 545228, text = "HUH!" },
            { id = 545230, text = "OW!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 545242, text = "Bullcog owns you!" },
        } },
    } },
    { who = "Bolvar", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3669942, text = "It is that very presence I sense lurking beyond the shattered sky above." },
            { id = 3669924, text = "That is where you must go if you are to save those Sylvanas has taken Together we can open the way" },
            { id = 3669922, text = "When the Banshee shattered the helm, it tore a gaping wound through the veil between our world and the Shadowlands." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3669937, text = "I could sense a dark presence at the edge of my consciousness. Not Arthas. Not Nezul. Something else." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3669925, text = "Place the shards of domination around the circle of runes. Then the ritual can begin!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3669890, text = "A far more pressing threat is at hand, and we must prepare to face it." },
            { id = 3605021, text = "Be at ease. I am Bolvar Fordragon. These knights and I are here to help." },
            { id = 3669923, text = "During my vigil upon the Frozen Throne, I caught fleeting glimpses into the realms of death. Among them, I saw a place of inescapable darkness." },
            { id = 3669889, text = "Enough! The war is over. We can ill afford to start another." },
            { id = 3638213, text = "It seems the Jailer has been pulling the strings of fate on our world as well." },
            { id = 3620380, text = "This is most dire news. We must not let war ravage this plane and unravel all that we have done." },
            { id = 3669926, text = "When the helm rested upon my head, it took all my will to keep its insidious power in check. Many times, I nearly faltered." },
        } },
    } },
    { who = "Bonesmith Heirmir", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3762942, text = "HA!" },
            { id = 3762928, text = "HIYAH!" },
            { id = 3762930, text = "HUAAAGH!" },
            { id = 3762932, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3744020, text = "Gah! Well, I forged it, but clearly you are the only one meant to wield it. Go on then!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3763000, text = "OOF!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3744016, text = "Ah, he enchanted the blade. Of course he did. You might want to get ready for a fight." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3744018, text = "Just how many souls did he forge into this thing?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3744012, text = "Hmph. Whatever his reason, a blade's no good without a hilt. Time to get to work." },
            { id = 3744010, text = "Is that? It can't be." },
            { id = 3744017, text = "Keep those things off me while I work. This is a test of your skills as well as mine." },
            { id = 3744013, text = "Nothing is given. Everything is earned. That includes the materials for your hilt." },
            { id = 3744011, text = "So this was the cause of all that commotion, a blade and a message from the Primus himself." },
            { id = 3744019, text = "The Enchantment's final guardian! Vanquish it and claim your Runeblade!" },
            { id = 3744015, text = "The Primus may have taught me a lot about the Forge, but I've learned a thing or two myself since then." },
            { id = 3744009, text = "Ugh! Can't you see I'm busy?" },
            { id = 3744014, text = "Well, are you ready to start or not?" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 3762916, text = "HMPH!" },
            { id = 3762918, text = "HUUU!" },
            { id = 3762920, text = "UGH!" },
        } },
    } },
    { who = "Bonetusk", tier = "character", groups = {
