        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1905697, text = "This poor soul's been dead for ages. Let's look east for the supply cart." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1956620, text = "Roughneck work ain't always glamorous, but it pays." },
            { id = 1905703, text = "Seems they got dragged that way, up the glacier to the northwest." },
            { id = 1905701, text = "This guy don't seem too bright." },
            { id = 1905700, text = "This guy really ruffles me feathers!" },
            { id = 1956621, text = "Time to nab another graffin! Mount up!" },
            { id = 1956619, text = "We got a big order for grief and saddles, but we need more fur. Get to work!" },
            { id = 1956623, text = "Wendigo number's been risin' on the glacier. Get out there and do somethin' about that!" },
            { id = 1905699, text = "What about rucksacks? Looks like we've found the right place." },
        } },
    } },
    { who = "Bouldercrag the Rockshaper", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2399177, text = "UNTIL WE MEET AGAIN" },
