        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4673983, text = "A kalashi flamecaster is forcing the river into a frenzy. Cut him down before the waters boil away." },
            { id = 4658993, text = "I'm glad we met, friend." },
            { id = 4658999, text = "It's always good to meet someone new." },
