        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1960262, text = "Kill him faster! I want blood!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1960266, text = "All right crew, bring me blood, my lovely, lovely blood! I suppose there's some loot in it for you two." },
            { id = 1960263, text = "All that blood, we stirred." },
            { id = 1960267, text = "An island brimming with creatures, and people, and things, and... And HARD! Go get me some blood!" },
            { id = 1960265, text = "Horde blood, my favorite. Crew of mine, you know what to do!" },
            { id = 1960264, text = "Oh, hello there! Sage a needle your blood? Surely you could spare a bit." },
            { id = 1960268, text = "Quick! Get me a bucket! There's no board to waste!" },
        } },
    } },
    { who = "Broken", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
