        { name = "Conversation", family = "Feelings", lines = {
            { id = 545565, text = "Luck to you!" },
            { id = 545599, text = "This is right!" },
            { id = 545570, text = "What do you want?" },
            { id = 545564, text = "Yes, yes, what?" },
            { id = 545597, text = "You come back sometime." },
            { id = 545569, text = "You must not give up." },
            { id = 545577, text = "You're gone now." },
            { id = 545594, text = "You're very strange." },
        } },
    } },
    { who = "Broker Curator", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3570862, text = "ENJOY TEMPORAL STASIS!" },
            { id = 3570861, text = "MIND YOUR STEP!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3570856, text = "With a single swing of this relic, words shatter!" },
            { id = 3570855, text = "With this power, reality crumbles!" },
            { id = 3570852, text = "You cannot bargain with death!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3570858, text = "Arcane power courses through me!" },
            { id = 3570851, text = "Destruction is guaranteed!" },
            { id = 3570857, text = "Infinite armies are mine to command!" },
            { id = 3570860, text = "The lifts open! Prepare to pay the ultimate price!" },
            { id = 3570859, text = "The power of this relic makes gods tremble!" },
            { id = 3570853, text = "The warp beckons!" },
        } },
    } },
    { who = "Brokers", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4069455, text = "FOR CARTEL ZO!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4069440, text = "You have been randomly selected for death." },
            { id = 4060700, text = "You will receive your cut, of course, minus some nominal handling fees." },
