    } },
    { who = "Broll Bearmantle", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1406687, text = "My strength is yours, Archdruid. Together we will protect the Wilds." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1406690, text = "Don't worry, I'm here!" },
