        { name = "Loyalty", family = "Manners", lines = {
            { id = 1406722, text = "We work well together, hero!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1406732, text = "Good work, stay strong!" },
            { id = 1406684, text = "Selendra, can we still recover the idol?" },
            { id = 1406730, text = "That one wasn't so tough." },
            { id = 1406692, text = "The idol! It's gone!" },
            { id = 1406694, text = "To the Shrine Druid! Our help is needed." },
