            { id = 1406697, text = "We're on the right track! Keep searching!" },
        } },
    } },
    { who = "Bromach", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4661730, text = "GET OUT HERE AND SMASH HIM!" },
            { id = 4661731, text = "STONEWALL DROBS, ATTACK!" },
