        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4661744, text = "Bromark, the chief here, gonna smash you!" },
            { id = 4661748, text = "Bromock warned you! Bromock always right! Ha Ha Ha ha!" },
            { id = 4661728, text = "Now you see a chieftain's power!" },
            { id = 4661726, text = "Now you're gonna be sorry!" },
            { id = 4661727, text = "Puny ones won't stop Bromark!" },
