        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2013846, text = "Sea to sea, ashes to ashes, tide to tide, may your souls find peaceful currents." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2013854, text = "Be wary, heroes. Some unseen evil still lurks in the dark. We must press on to remove its influence from the shrine." },
            { id = 2013855, text = "By the Tide Mother!" },
            { id = 2013848, text = "Master! Stop this madness at once! The Kul Tiran fleet must not fall to darkness!" },
            { id = 2013843, text = "Quickly, heroes! Stop them before the fleet is lost!" },
            { id = 2013852, text = "Something is not right. Darkness still festers here." },
            { id = 2013842, text = "Stormsong has twisted this sacred place. We must press on and undo his foul work." },
