        { name = "Conversation", family = "Feelings", lines = {
            { id = 2015746, text = "If you listen to the tides, you can learn much about the world." },
            { id = 2015750, text = "It is not just the tides that are upset." },
            { id = 2015744, text = "May the sea carry you swiftly." },
            { id = 2015743, text = "Never stray from the sea." },
            { id = 2015745, text = "The tides return, always." },
            { id = 2015747, text = "Tides guide you." },
            { id = 2015749, text = "You know not who you anger." },
