    { who = "Brynnsahce", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5096316, text = "I was just thinking about your mighty deeds!" },
            { id = 5095668, text = "My queen! Elder Honeybelt has found the lost-up landers!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5096307, text = "Alright, Stiplander, welcome!" },
            { id = 5095969, text = "Anyway, I'll be your guide-in-loam. Let me show you why Elder Honeypelt chose me as her monster hunter apprentice." },
            { id = 5095671, text = "Elder Honeypelt! You've returned! Tell me everything!" },
            { id = 5096312, text = "Ho! Hey, uplander!" },
            { id = 5095665, text = "She's back! HE'S BACK!" },
            { id = 5095963, text = "Smelling your reactions to everything in L.O.A.M. made me appreciate the familiar in a whole new way! Way to go, uplander!" },
            { id = 5095966, text = "Whoa! You smell completely different to anything I've ever smelled. Even elder Honeypelt doesn't come back with scents this unexpected." },
            { id = 5096310, text = "Whoa, you smell of adventure!" },
        } },
    } },
    { who = "Build Abom T", tier = "character", groups = {
