        { name = "Conversation", family = "Feelings", lines = {
            { id = 5332776, text = "Brock is fixated on the wellspring of life. That is all I learned." },
            { id = 5321605, text = "By wing and claw" },
            { id = 5321595, text = "Change of plan?" },
