    { who = "Bwonsamdi", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 545744, text = "HMM!" },
            { id = 545739, text = "HMPH!" },
            { id = 545742, text = "YEAH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 545752, text = "UGH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1875101, text = "Ah, Selassie. She be dawdlin' among the living for too long now. Do whatever it takes to bring her soul to this soul, so very patient Loa. Hmm?" },
            { id = 1875099, text = "Champion, deal with that witch. Them dancing bone she call minions, them agafal are the true lord of the dead." },
            { id = 1875096, text = "Hehehe, how about a deal, hmm? You bring I the soul of another Loa, then I get you Torgasviren, eh?" },
            { id = 1875095, text = "Let me guess, hmm, you want to speak to the soul of poor Torga?" },
            { id = 1875098, text = "Toga! Your spirit be needed here! Puck your head out your shell, man!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1875104, text = "Ha Ha Ha ha! I know this voice. And these gifts. Very nice. Come in. Come in." },
            { id = 1875102, text = "Heh Heh Heh heh, look at that. Maybe you wouldn't have time after all, man. Heh heh heh, come here with chat back in the temple. Old Bwonsamdi just might have an offer for you." },
            { id = 1875105, text = "Ho Ho Ho ho! A priest! Heh heh! If you ever consider a change of fate, you be sure you let ol' Bo and Sam dinner. Ya hear?" },
            { id = 1875103, text = "Ho ho, that's a mighty sword! Oh, old one Samdi feelin' spry now, ha ha ha! Yes, the power's been growin'!" },
            { id = 1875100, text = "Well, hello there, Hansabu. You're here to pay your debts?" },
            { id = 1799662, text = "What are you doing here man? It's not your time to pass on...yet." },
            { id = 1875097, text = "You got a little fire in that belly, Talanji. But me help I go cost you." },
        } },
    } },
    { who = "Cairne Bloodhoof", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2911902, text = "You have helped this champion restore balance to the spirit realm, and balance is what we strive for." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2911904, text = "I know, but we must wait for another time." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2911901, text = "Our way seeks not destruction, but harmony. We need both light and shadow to see what lies before us." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2911900, text = "No, my son. Let it be." },
            { id = 2911905, text = "We are proud of you, my son. Remember always that the Earth Mother watches over you. And so do we." },
