    } },
    { who = "Calia Menethil", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1411504, text = "You won't be alone on this journey." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1388221, text = "I once hid in a muddy ditch for two days while slavering ghouls patrolled the area. Your prattle does not faze me." },
            { id = 1388219, text = "I stand ready to help." },
