        { name = "Conversation", family = "Feelings", lines = {
            { id = 3049446, text = "for Lordaeron." },
            { id = 3049445, text = "Honor the past, but embrace the future." },
            { id = 1388218, text = "How can I assist you?" },
            { id = 1388217, text = "It's just Calia now." },
            { id = 1388220, text = "Sometimes I miss the beautiful court of Lordaeron and my father." },
            { id = 1388222, text = "Taranis would have had you thrown out of here faster than he did Medivh." },
            { id = 1388214, text = "Walk in the light." },
        } },
    } },
    { who = "Callie Carrington", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1593336, text = "Ah! My head!" },
            { id = 1593338, text = "I... can't go on..." },
            { id = 1593339, text = "Jared, he... he's gone. We need to fall back until reinforcements arrive." },
            { id = 1593335, text = "No way I'm staying behind! The attacks on my town must be stopped!" },
            { id = 1593337, text = "Pleasure working with you. Thanks for saving our town." },
            { id = 1593340, text = "Things are still a bit foggy, but I can stand and fight!" },
            { id = 1593342, text = "This don't seem right. Where am I?" },
            { id = 1593341, text = "What's happening? Blood feels like it's boiling. I, I." },
        } },
    } },
    { who = "Callisto Windsor", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6119203, text = "I'll do whatever I can for the Kirin Tor." },
            { id = 6119208, text = "I've studied too hard and too long to give up." },
