    { who = "Captain Delaryn Summermoon", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2000895, text = "Azerite has surfaced amongst the ruins of Darkshore. We cannot let the Horde get their hands on it." },
            { id = 2000903, text = "Even underwater, those Azerite powder kegs are still quite dangerous. I want you to detonate them before they can float to the surface. Try to keep yourself in one piece, would you?" },
