            { id = 3485370, text = "Keep your distance from your enemy and hit them with Frost Bolt." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3485377, text = "Excellent one more time a druid can effectively dispatch their foes with proper use of moon fire" },
            { id = 3485378, text = "Good, keep using Wrath while Moonfire deals damage. Wait for the right time to use Moonfire again." },
            { id = 3485379, text = "Moonfire will damage your opponent over time use wrath while your foe is affected by Moonfire" },
            { id = 3485376, text = "Use Moonfire at the start of combat. It deals damage to your foe over time." },
            { id = 3485373, text = "Well done! Fire Blast's Instant Cast makes it perfect to use in Melee range. Let's practice this again!" },
            { id = 3485375, text = "You can cast Fire Blast instantly, which makes it an excellent tool in close-quarters combat." },
            { id = 3485374, text = "You're getting the hang of this. Let's do it one more time before you face the Quillbore." },
        } },
