    { who = "Captain Greenbelly", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1984576, text = "ENOUGH OF THIS! KILL THEM NOW!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1997326, text = "HMMM!" },
            { id = 1997328, text = "HRRR!" },
            { id = 1997329, text = "HUUU!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1984580, text = "I see the Alliances are here, and they're still breathing! Let's fix that!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1984577, text = "Give... nothing... back!" },
            { id = 1984582, text = "Loot and plunder, ha ha ha! Dorp, shoot anything that moves! Sneaky Pete, give those Alliance scum a good stabbin'! And get me that azerite!" },
            { id = 1984583, text = "Someone check the body for swag" },
            { id = 1984581, text = "There's treasure on that island that isn't aboard my ship yet! Move it, you layabouts, and take the Alliance's loot, too!" },
            { id = 1984579, text = "This island needs looting, boys! Hop to it! I hate having to wait!" },
            { id = 1984575, text = "You'll be easier to loot when you're DEAD!" },
        } },
    } },
    { who = "Captain Jarod Shadowsong", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1474963, text = "I am no hero, Captain, but I will gladly stand by your side." },
            { id = 1474961, text = "I am not sure I am comfortable with this Master Illidan." },
            { id = 1475003, text = "I can only hope their sacrifice is worth it." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1474959, text = "A worthy battle. I could never have defeated a dreadlord on my own." },
            { id = 1495620, text = "Are we no better than the monsters we fight?" },
            { id = 1474957, text = "Illidan! I believe a dreadlord resides within the mausoleum. Your help is gladly received." },
            { id = 1474965, text = "Master Illidan, you fight with such power!" },
            { id = 1476201, text = "The battle is joined, Master Illidan." },
            { id = 1474973, text = "This place was built to withstand almost any assault, but no one could have predicted the strength of the Legion." },
        } },
    } },
    { who = "Captain Jolly", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
