    { who = "Captain Keg Leg", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5545692, text = "LUCK BE ON YOUR SIDE NEXT TIME, SAILOR!" },
            { id = 5545695, text = "YOU BETTER SCOOT AND LOOT, YOU SCURVY DOGS!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 5545680, text = "That was the most beautiful plundering I've ever seen!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5545689, text = "Ahoy there! Hope you're ready for a bit of... plundering fun!" },
            { id = 5545683, text = "All hands on deck! There be treasure awaitin'!" },
            { id = 5545669, text = "It's time to earn your keep, you bilge rats!" },
            { id = 5545672, text = "It's time to see what ye sea dogs are made of!" },
            { id = 5545663, text = "Last one back's eatin' leftover sardines!" },
            { id = 5545686, text = "Lucky what we have here, another scab out for a quick coin, eh?" },
            { id = 5545698, text = "The plundering adventure's about to begin!" },
            { id = 5545659, text = "Well I'll be a sailor's backside, ye actually won!" },
            { id = 5545666, text = "Well, well, watch this! Here to have some fun, hmm?" },
        } },
    } },
    { who = "Captain Kelra", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
