    { who = "Captain Krick Wrenchnozzle", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1500125, text = "GAH!" },
            { id = 1500124, text = "HA!" },
            { id = 1500126, text = "OOF!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1248098, text = "Already? How'd they get so many here so fast?" },
            { id = 1248108, text = "Alright Horde troops, this is your stop! A beach lined with demons! Bring her in! Snappy now!" },
            { id = 1248094, text = "Any messages from Orgrimmar?" },
            { id = 1248102, text = "Cut through those waves, Blackwater! We're pirates, we own these seas! Keep us steady!" },
            { id = 1248071, text = "Smell that sea air! It feels good to be out in the open water again!" },
            { id = 1248090, text = "There's an old goblin sayin' that goes, the best bets use other people's money." },
            { id = 1248104, text = "What's that ahead?" },
