            { id = 1858486, text = "Drink up, you scurvy dogs!" },
            { id = 1858495, text = "I'll be needin' another drink before I can stomach you lot again!" },
            { id = 1858493, text = "Learn to hold your drink, matey!" },
            { id = 1858487, text = "This barrel's topped! Catch!" },
            { id = 1858485, text = "This round's on me!" },
