    { who = "Captain Rezokun", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1992458, text = "We are almost done. You are doing well!" },
            { id = 1992460, text = "You are nearly there. Just keep your heads down for a little longer." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1992452, text = "Hey! Keep your eyes open! We have got company out here!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1992457, text = "Gather what you can, we will have to shove off soon!" },
            { id = 1992455, text = "It looks like that Kulturian ship is almost full. We're going to have to leave soon." },
            { id = 1992451, text = "Look out! A courtieran ship has made landfall!" },
            { id = 1992454, text = "Ooh, things are about to get a bit more interesting." },
            { id = 1992453, text = "Some new friends just showed up. Ha ha ha." },
            { id = 1992462, text = "The detector is on. Check your map for Azerite concentrations." },
            { id = 1992461, text = "The device is up. You should be able to see all the Azerite now." },
            { id = 1992459, text = "The hull is nearly full. Just a bit more and we will be done!" },
            { id = 1992456, text = "The other ship looks like it will be leaving soon. We must move fast." },
        } },
    } },
    { who = "Captain Roderick Brewston", tier = "character", groups = {
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1995466, text = "The Horde is attacking our position at Northfold Crossing. I say they deserve some, uh, tanks for their hospitality." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1995461, text = "A number of our Griffin Riders have been felled. Keep an eye open for survivors in the field." },
            { id = 1995468, text = "High Perch is under attack, might I suggest sending the Horde tumbling back down the hill?" },
            { id = 1995467, text = "Horde forces approach the circle of elements. Perhaps we should treat them to a magic lesson." },
            { id = 1995463, text = "Horde forces have entered Stromgarde. Protect your commander and show them the way out, would you?" },
            { id = 1995462, text = "Horde soldiers incoming! Do your best to hold them off, yes?" },
            { id = 1995458, text = "Massive earth elementals spotted on the eastern hill!" },
            { id = 1995464, text = "Newstead is being attacked by the Horde! Let's put an end to their horseplay!" },
            { id = 1995460, text = "Stone Giant Fosruk is currently stomping along the southeastern roads. Don't get caught underfoot." },
            { id = 1995465, text = "The Horde marches on Valachor Pass! That's our front doorstep. Go give them a proper welcome." },
            { id = 1995457, text = "We seem to have stirred the hornet's nest. The Horde is sending everything they've got!" },
            { id = 1995459, text = "What say we pound it into shape and stick it on the Horde's front line?" },
        } },
    } },
    { who = "Captain Scarloc", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 545885, text = "DID YOU REALLY THINK YOU WOULD LEAVE HERE ALIVE?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 545887, text = "I don't know what Blackmoor sees in you. For my money, you're just another ignorant savage." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 545883, text = "Thrall will never be free!" },
            { id = 545886, text = "You're a slave. That's all you'll ever be." },
        } },
    } },
    { who = "Captain Tread Sparknozzle", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2913762, text = "I know what I said! Anyway, you are the first gnomish elite aerial rangers, and you will show Azeroth everything we gnomes can accomplish." },
            { id = 2913763, text = "Rangers! You have more than proven gnomish aerial might! The Alliance will no doubt call upon gear in the future!" },
            { id = 2913759, text = "You are Gnomeregan's finest soldiers, paragons of gnomanity, the best examples of gnomish ingenuity and determination." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2913760, text = "And so, you four will be the first to take to the skies as Gnomish Aerial Elite Rangers and..." },
            { id = 2913764, text = "But first, every elite unit requires a proper uniform. Wear the colors of Gnomeregan with Pride, Ranger!" },
            { id = 2913761, text = "Excuse me, soldier?" },
        } },
    } },
    { who = "Captain Yathae Moonstrike", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1596628, text = "RETRIBUTION RAINS DOWN!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1596621, text = "You are ever-impetuous, Kasparian." },
            { id = 1596630, text = "You are in my sights!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1596625, text = "I get to strike first next time!" },
            { id = 1596620, text = "My arrows are always ready, Kasparian." },
            { id = 1596629, text = "My mark is upon you." },
            { id = 1596623, text = "My Quarry Falls!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1596627, text = "No more dawdling Kasparian victory shall be mine" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1596622, text = "Bit slow on that kill sister" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1596624, text = "Inefficient, but effective." },
            { id = 1596626, text = "No! I should have... won!" },
        } },
    } },
    { who = "Captured Pirate", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1452080, text = "I think I just soiled myself. Oh, please don't kill me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1452070, text = "I'll... I'll never tell ye!" },
            { id = 1452076, text = "It was SI7! They offered us the riches of Stormwind in exchange for Amber Cairn and" },
            { id = 1452072, text = "Now that you mention it, he does look somewhat familiar." },
            { id = 1452074, text = "Oh god, no! I've heard of you! Please don't kill me!" },
        } },
    } },
    { who = "Caretaker Wh B Ng", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1584087, text = "Unable to comply. Sanitation protocol cannot be aborted. Visitors may be in a corrupted state. If you are hearing whispers of unknown origin, please step directly into the searing light." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1584078, text = "Accessing current count of known seekers, free!" },
            { id = 1584082, text = "Alert! Void energies detected! Initiating sanitation protocol!" },
            { id = 1584075, text = "Allow me to show you!" },
            { id = 1584080, text = "Invasive, corruptive entities have bombarded this planet since its shaping. Attrition due to combat fatalities gradually reduced the numbers of Seekers. Now, only these are known to remain." },
            { id = 1584069, text = "Life farm scan in progress!" },
            { id = 1584071, text = "No essential life forms detected! Resuming scan!" },
            { id = 1584073, text = "Speakers that is verified welcome speaker. Have you come to retrieve the seekers?" },
            { id = 1584068, text = "Systems active! Visitors detected!" },
        } },
    } },
    { who = "Caria Felsoul", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1345741, text = "WITNESS THE MIGHT OF THE OLD DRUCKY!" },
            { id = 1345742, text = "YOUR DESTINY AWAITS!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1345740, text = "For every soul I claim, my power grows! I will rule this world, all worlds!" },
            { id = 1345744, text = "I will claim your soul, even if I have to tear it from your lifeless corpse!" },
            { id = 1345748, text = "The Legion is only the beginning! My blades call upon power from beyond!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1345747, text = "I will claim every soul on this pathetic world!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1345746, text = "The ritual is nearly ready. Stop them, you mongrels!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1345743, text = "Do you not see? Kil'jaeden offers power Illidan never could!" },
            { id = 1345745, text = "I. Will. Be. Reborn." },
            { id = 1401385, text = "I'll reduce this entire canyon to rubble if I have to!" },
            { id = 1345739, text = "Oh, I thought I sensed a paltry whelp, wondering where it shouldn't." },
            { id = 1401387, text = "Sarah! Terrar! They approach! Do not fail me!" },
        } },
    } },
    { who = "Carlo Greasegrind", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 6178357, text = "Come on, chop chop! We're getting paid commission, not hourly!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 6178383, text = "Hey! That thing snagged my lunchbox earlier!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6178360, text = "Alright, we're starting up! Let's move it, people!" },
            { id = 6178386, text = "Better shovel harder! One minute, and we are outta here!" },
            { id = 6178371, text = "Can you not? Wait! That's not what I use!" },
            { id = 6178355, text = "Now get those shovels movin' if you wants to share in the trash!" },
            { id = 6178401, text = "Oh, for the lover! Get that out of here!" },
            { id = 6178387, text = "One minute left on this one! Finish it up!" },
            { id = 6178358, text = "These trash piles ain't gonna scavenge themselves!" },
            { id = 6178359, text = "Whatever you finds, you keeps. Get shoveling!" },
            { id = 6178384, text = "Whoa, that is a big one!" },
            { id = 6178385, text = "Wrap it up! I ain't spending more than another minute here!" },
        } },
    } },
    { who = "Casadh", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3691570, text = "Anima blooms within the garden. Though only a sapling, your boughs support and shade us all." },
            { id = 3691572, text = "It is a special place, a glen of rejuvenation, of lost souls given chance anew." },
            { id = 3691568, text = "Some grant solidarity of growth, others quality of yield. Use them wisely and the spirits will blossom." },
            { id = 3691573, text = "Weak and utter spirits who slumber within, their rebirths uncertain as the rain." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3691574, text = "Time's river rushes forward, its currents swift and strong. Alone I drown, together we swim." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3691575, text = "A tender touch and gentle care must guide them to their destiny. Ours will be the efforts that nourish them." },
            { id = 3691566, text = "Along your path have spranted all manner of catalysis, each one a different womb to be stoned." },
            { id = 3691567, text = "Catalysts lie scattered across the realms eternal, leaves in the wind, waiting to be found." },
            { id = 3691576, text = "Here grow white seeds unlike any other. Your skills must grow with them. I will cultivate both." },
            { id = 3691577, text = "Humour. The purview of younger beings. My apologies." },
            { id = 3691569, text = "The grove thanks you and thrives, so shall its wild seeds, much more tending awaits us." },
            { id = 3691571, text = "The Grove whispers its welcome through the branches of its walk." },
        } },
    } },
    { who = "Casters", tier = "creature", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3388308, text = "YOU WILL NEVER ESCAPE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1045599, text = "We are all doomed." },
            { id = 3388303, text = "Your soul will save!" },
            { id = 3388304, text = "Your soul will serve!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3388310, text = "Behold true despair!" },
            { id = 3388300, text = "Defiance shall be punished!" },
            { id = 1041409, text = "No! He will awaken!" },
            { id = 1123750, text = "They are here! Hurry! Gul'dan demands we finish this!" },
            { id = 1058169, text = "We have not yet purified the water!" },
        } },
    } },
    { who = "Cataloger Coralie", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5789461, text = "Take some pictures, if you can." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5789462, text = "Have you seen the flora here?" },
            { id = 5789460, text = "If only I had my camera..." },
            { id = 5789463, text = "Quite the adventure." },
            { id = 5788591, text = "The guards near us were arguing about new orders. Then they just... walked off." },
        } },
    } },
    { who = "Cataloger Kieule", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4643028, text = "I did not mind at all. While waiting, I captured some vibrant images of the coastal wildlife." },
            { id = 4667613, text = "I love the wildlife here." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4667609, text = "Don't get too awestruck out there." },
            { id = 4667608, text = "Go capture some memories!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4667607, text = "A picture is worth a thousand words." },
            { id = 4667606, text = "Always document what you find!" },
            { id = 4667611, text = "Everything is so beautiful." },
            { id = 4667610, text = "Interested in a snapshot?" },
