        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1370543, text = "Rhaegar, this may be the most powerful fighter you have ever brought to the arena." },
            { id = 1370533, text = "You are fast, dork, but not fast enough." },
            { id = 1370541, text = "You have bested me." },
