        { name = "Farewells", family = "Manners", lines = {
            { id = 634286, text = "Alright, until next time!" },
        } },
        { name = "Laughter", family = "Fun", lines = {
            { id = 852760, text = "HEH HEH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 634284, text = "Aye, travel well." },
            { id = 1370551, text = "I'll be honest, those things scare me." },
            { id = 1370514, text = "Incredible form. A fighter in perfect harmony with the elements." },
            { id = 1370528, text = "Is that so? We shall see who the real hero of the storm is around here. But first, I need a partner." },
            { id = 634294, text = "Is trouble brewing?" },
            { id = 1370536, text = "Lele, look out!" },
            { id = 634282, text = "May your journey be long." },
            { id = 1370530, text = "Oh no, Lily. I do not think" },
            { id = 634302, text = "Oh yeah, this stuff will put hair all over you." },
            { id = 634290, text = "Sit down, have a drink." },
            { id = 634292, text = "So, got any stories?" },
            { id = 634306, text = "To ask why I drink is to ask why I am fat. It is because I drink. Perhaps there is a better question." },
            { id = 634304, text = "You wanna know what's better than drinking a beer, brewing your own beer, and then drinking it, and then drinking another beer, and then punching somebody in the snout. That's what." },
        } },
    } },
    { who = "Chief Engineer Ishkar", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1685512, text = "I have calculated your alms of survival. ZERO!" },
            { id = 1685510, text = "I hope you enjoy my inventions." },
            { id = 1685518, text = "I tire of this labor, it will be more satisfying to have my machines tear you apart!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1685515, text = "It appears I need to take a more hands-on approach." },
            { id = 1685513, text = "It appears you need a lesson in pain. Allow me to instruct you." },
            { id = 1685511, text = "Watch your step!" },
            { id = 1685517, text = "What result were you expecting?" },
        } },
    } },
    { who = "Chief Telemancer Oculeth", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1405172, text = "I have detected a large number of teleportation spells targeting your location." },
            { id = 1405171, text = "I have enabled a teleporter for you. You haven't a lot of time. Locate the pad and get out of there!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405174, text = "Give me a moment. I am locking in your location now." },
            { id = 1407701, text = "Good trick, but warping a space around your body like that." },
            { id = 1407698, text = "Good. If we overcharge enough coils, the entire system will fail-safe into a lockdown." },
            { id = 1407693, text = "Here we are, my old sanctuary." },
            { id = 1407695, text = "Intruders! How did they get in here?" },
            { id = 1407694, text = "Strange. The defenses are offline." },
            { id = 1405173, text = "The network is responding to a new beacon. Ah, hello again." },
            { id = 1407696, text = "The Scoil taps into the ancient ley lines, cranking up to full power." },
            { id = 1407697, text = "There are more coils in the chamber below, and more intruders, I imagine." },
        } },
    } },
    { who = "Chieftain Hatuun", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1678471, text = "Those fiends capture my people and subject them to heinous rituals! We will no longer be hunted! Help us bring the fight to the Legion!" },
            { id = 1678464, text = "Those steeds are vital in our battle against the demons. You have my thanks for safeguarding them." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1678443, text = "Even when tortured by the Legion, my people rebel against their accursed crusade. The demons may break their bodies, but never their wills. Go, release their spirits so that they may find peace." },
            { id = 1678451, text = "Our people are being used as fodder for vile rituals. Destroy these monstrous creations and help us honor the remains of our dead." },
            { id = 1678472, text = "The lives and souls of my people are safer, thanks to you." },
            { id = 1678457, text = "The Menari torment my kind with their fel magic rituals. Let their dark words be purged. In fire." },
            { id = 1678444, text = "The spirits of those who resist the Legion inspire us all." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1678463, text = "As the Legion encroaches upon the hunting grounds of the Panthera, the starving beasts have grown more aggressive. Thinner numbers before they wipe out our Talpakurts." },
            { id = 1678452, text = "Now the ones we have lost can find rest." },
            { id = 1678458, text = "The scorched parchment you left behind will remind the Legion that our resistance cannot be silenced. Thank you." },
            { id = 1678865, text = "Verlinde, at long last you returned to the home you abandoned." },
            { id = 1678867, text = "We changed. Just as Argus did. We endured. What choice did we have?" },
        } },
    } },
    { who = "Chieftain Kohana", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2911869, text = "Some of us are still wanderers at heart. You have done much in your travels to honour your ancestors." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2911871, text = "Balance has been restored and I must bid you farewell, but the spirits will always watch over you." },
            { id = 2912200, text = "Spirits greet you." },
            { id = 2911851, text = "The spirit realm is out of balance. Dark spirits are crossing over into the mortal world." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2912197, text = "An'Shei watch over you." },
            { id = 2911870, text = "Look upon this land and know that the peace and harmony found here are also within you." },
            { id = 2911850, text = "Oh, young one, how I wish we could have met under different circumstances." },
            { id = 2911868, text = "Our people once lived as nomads. It was not long ago that we settled in these lands." },
            { id = 2912199, text = "Strive for balance." },
            { id = 2911852, text = "There will come a time for us to speak, but first, you must warn our people of this threat." },
            { id = 2911872, text = "Wherever the great hunt leads you, may our gifts remind you of your tribe and your home. Walk with the Earth Mother." },
            { id = 2912198, text = "You bring honor to your ancestors." },
        } },
    } },
    { who = "Chieftain Tachuk", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2911884, text = "Some of us are still wanderers at heart. You have done much in your travels to honor your ancestors." },
        } },
