            { id = 2912182, text = "Spirits greet you." },
            { id = 2911860, text = "The spirit realm is out of balance, dark spirits are crossing over into the mortal world." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2912179, text = "An'Shei watch over you." },
            { id = 2911885, text = "Look upon this land and know that the peace and harmony found here are also within you." },
            { id = 2911859, text = "Oh, young one. How I wish we could have met under different circumstances." },
            { id = 2911883, text = "Our people once lived as nomads. It was not long ago that we settled in these lands." },
            { id = 2912181, text = "Strive for balance." },
            { id = 2911861, text = "There will come a time for us to speak, but first you must warn our people of this threat." },
            { id = 2911887, text = "Wherever the great hunt leads you, may our gifts remind you of your tribe and your home. Walk with the Earth Mother." },
            { id = 2912180, text = "You bring honor to your ancestors." },
        } },
    } },
    { who = "Chihuahuadogpet", tier = "character", groups = {
