        { name = "Greetings", family = "Manners", lines = {
            { id = 634428, text = "Greetings wanderer" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 852011, text = "The elements are undying. Make use of your time before they rise again." },
            { id = 852005, text = "The veil of shadows has lifted." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 634366, text = "Ah! Ah! Ah! I'm doing it! Run!" },
            { id = 634426, text = "Are you well?" },
            { id = 634424, text = "Do you seek my counsel?" },
            { id = 852001, text = "Heal the prince, but do not forget to keep yourself alive." },
            { id = 634420, text = "Hope is eternal." },
            { id = 634368, text = "It seems hope has triumphed, after all." },
            { id = 852015, text = "Let the challenge begin. Hero, you must keep the Black Prince alive with your skills as a healer." },
            { id = 634372, text = "Meet me near the statue at the center of the temple grounds. We will speak there." },
            { id = 634422, text = "Peace be with you." },
            { id = 634370, text = "There is no time for celebration. Many followers of the Way still battle outside." },
            { id = 852009, text = "Use the blood of the world to regenerate yourself. You can do this." },
            { id = 634418, text = "We must never give in to despair." },
        } },
    } },
    { who = "Children", tier = "creature", groups = {
