            { id = 546134, text = "BAAH!" },
            { id = 546112, text = "GRRR!" },
            { id = 546118, text = "OH!" },
            { id = 546094, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1058459, text = "Death comes! We know it well!" },
            { id = 1058450, text = "Do you feel the power they're drawing on? It's the Nalu in the grand." },
            { id = 1058457, text = "Gaze into the abyss! It sees you. It knows." },
            { id = 1058460, text = "The end draws closer. This is our purpose." },
            { id = 1058453, text = "The night consumes us! We have won! All will be as foretold!" },
            { id = 1058451, text = "We should subjugate these Pale Orcs! An intruder! Let's leave!" },
            { id = 1058456, text = "Your reign has come to an end! The infinite night begins! Darkness comes!" },
