        { name = "Conversation", family = "Feelings", lines = {
            { id = 3581917, text = "Awool! You're okay!" },
            { id = 3581922, text = "It's done! It's done! Meet you outside the Glen!" },
            { id = 3581914, text = "Nasty buzzards! They change forms to scare us!" },
