            { id = 3581915, text = "They're helping us, Rudy!" },
            { id = 3581924, text = "To the tree! To the tree! We'll all be safe at the tree!" },
            { id = 3581913, text = "We must save them! Hurry!" },
        } },
    } },
    { who = "Chopper Redhook", tier = "character", groups = {
