            { id = 3192175, text = "Awaiting user input!" },
            { id = 3192173, text = "End of line" },
            { id = 3192276, text = "Excellent! Now we use the data to synchronize the units with the subject's neural oscillations." },
            { id = 3192280, text = "Kelsey is procuring a replacement heart unit as we speak!" },
            { id = 3192274, text = "Repairing the occupant will require the most advanced hardware. I will await your return!" },
            { id = 3192174, text = "State your intent!" },
            { id = 3192275, text = "These components require modification. In the meantime, Erasmund has requested your assistance." },
            { id = 3192176, text = "What is your inquiry?" },
