        { name = "Conversation", family = "Feelings", lines = {
            { id = 4661689, text = "Can you feel your fate closing in?" },
            { id = 4661693, text = "In all timelines, you fail to stop me." },
            { id = 4661691, text = "The sands will scour you from this timeline!" },
            { id = 4661568, text = "This disk may hold the secret to the aspects regaining their power, and we cannot allow that to happen." },
            { id = 4661566, text = "What have we here, Alexstrasza's lap dogs, I suspect?" },
