    { who = "Chronomatic Anomaly", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1349939, text = "THE WHEELS OF TIME TURN AGAINST YOU" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1349945, text = "My time has come." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1349942, text = "Feel like time is standing still?" },
            { id = 1349946, text = "It was only a matter of time." },
            { id = 1349944, text = "Precise. Perfect. Inevitable." },
            { id = 1349937, text = "So linear. So limited." },
