    { who = "Chyrus Paragon of Humility", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3596741, text = "She must pay for her hubris." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3596829, text = "I only hope we are not too late. If the Archon falls..." },
            { id = 3597096, text = "My life in service." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3597095, text = "Always remember to dust yourself off and try again." },
            { id = 3596830, text = "Bastion would be hers." },
            { id = 3597093, text = "Support those around you, and they will support you." },
            { id = 3596827, text = "The Forsworn are en route to Elysian Hold. We must return at once." },
            { id = 3596828, text = "The rest of our forces are retreating to the hold as well." },
            { id = 3597094, text = "We all stumble." },
            { id = 3596793, text = "We will keep their reinforcements at bay. Push onward!" },
            { id = 3596831, text = "We will prevent any more of her army from advancing on the Archon. I swear it." },
            { id = 3597050, text = "You must defeat Lasonia at any cost." },
        } },
    } },
    { who = "Claire Campbell", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1411501, text = "I no longer take their name or their values." },
            { id = 1445186, text = "I will be redeemed." },
            { id = 1411502, text = "I wish to aid my fellow priests in their fight against the Burning Legion." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1412380, text = "I'm ready to leave this place and never look back." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1445183, text = "How can I help?" },
            { id = 1411500, text = "Just do it already. I would rather die than spend another day living a life built around your twisted beliefs." },
            { id = 1445184, text = "May the light shine upon you." },
            { id = 1412453, text = "Search deep for your inner strength." },
            { id = 1411503, text = "You gave me a chance to redeem myself, and I will spend my life trying to do so." },
        } },
    } },
    { who = "Clarelle", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5328595, text = "Spruce Crown, you have been walking this path every waking moment. Take some time to water your own roots." },
            { id = 5328600, text = "You are getting sentimental, you old oak." },
        } },
        { name = "Boasts", family = "Menace", lines = {
