        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 5328591, text = "Insects everywhere! Shoo them away or they will decimate the leaves!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5328590, text = "Get these giant raindrops to the flowers. The poor things are parched." },
            { id = 5328589, text = "Help me get this water to the rain-starved flowers all around us!" },
            { id = 5328596, text = "Stop! They're going to hurt the tree!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5328604, text = "All our greatest foes are here! Fire, invaders, pests, and weeds! Put a stop to them!" },
            { id = 5328592, text = "No! Gather his dreams back up before they get away!" },
            { id = 5328593, text = "Spruce crown keep your dreams under control heroes help collect the pieces of his dream" },
            { id = 5328594, text = "They are coming to rip apart everything we have nurtured!" },
