    { who = "Commander Gar", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1058370, text = "RELEASE THE IRON STARS!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1058375, text = "HA!" },
            { id = 1058376, text = "HAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1058372, text = "Argh! Unbelievable! You will die for your insolence! I'll tear you limb from limb!" },
            { id = 1058373, text = "No! I will die before I let you take what is mine! You will not win this war! Aaaah!" },
            { id = 1058369, text = "You will never withstand the might of Gok!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1058365, text = "Huh, there it is. There's my artifact. How foolish of me to trust Brack with something so valuable." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1058374, text = "Ha Ha Ha ha" },
            { id = 1058367, text = "Ha Ha Ha ha! So be it! Iron Horde, advance!" },
            { id = 1058366, text = "It's a shame that you're too late to stop me. Surrender the artifact, and I will allow you to escape with your lives." },
            { id = 1058368, text = "See what weapons I have in my arsenal!" },
        } },
    } },
    { who = "Commander Jarod Shadowsong", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1241653, text = "I refuse to believe it. Lord Ravencrest cannot be working with Gul'dan." },
            { id = 1241661, text = "I will take out the guards inside the prison. Get those keys and meet me within the cells." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1242887, text = "You always did think too highly of yourself. Another foolish death, then, if you insist." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1241696, text = "Despite our attempts to extract information, the Warden remained stubbornly resistant. Could they be talking about Maiev?" },
            { id = 1241577, text = "Despite what they say, these people need help. Defend their farms and we will ease their suspicions." },
            { id = 1242883, text = "His loss was tragic for us all. We owe him everything." },
            { id = 1241859, text = "It is just as I feared. Lord Ravencrest's remains are gone." },
            { id = 1242881, text = "Lord Ravencrest died long ago, but I will always revere him as my mentor." },
            { id = 1242885, text = "Never mind that. I heard what happened in the Vault of the Wardens. Luckily, my hair can't get any grayer." },
            { id = 1241698, text = "That's Maya's weapon. She was here." },
            { id = 1241694, text = "This one met a grisly end. No sign of Maiev here." },
            { id = 1241685, text = "What a tragic waste. Even in death, he only wanted to protect our people." },
        } },
    } },
    { who = "Commander Lethanak", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4662861, text = "FOR THE LIFE BINDER!" },
            { id = 4662866, text = "THE SHRINE GUARD PROTECT" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4663838, text = "I am trusting you with the lives of my brethren." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4662860, text = "Protect your allies!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4662865, text = "Anything to report?" },
            { id = 4662867, text = "Do I look like I have time for you?" },
            { id = 4663837, text = "Primalists can have no quarter in our homeland. Thank you for teaching them a lesson." },
            { id = 4663836, text = "This once placid spring is now pushed to bursting by the primalists. Destroy them before they flood the whole valley." },
            { id = 4662863, text = "What's the situation?" },
        } },
    } },
    { who = "Commander Lindon", tier = "character", groups = {
