    { who = "Commander Lorna Crowley", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1243866, text = "Wait! She may have inflammation!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1244157, text = "Champion over here! Quick! Before the dregs catch your scent!" },
            { id = 1244153, text = "Champion, it's good to see you. Raikoule aren't known for their hospitality." },
            { id = 1243858, text = "Hop on! We'll check every ship if we have to!" },
            { id = 1239151, text = "It's no use! The ammunition has caught fire! Quickly up the stairs!" },
            { id = 1243862, text = "No sign of her. Let's keep looking." },
            { id = 1244155, text = "Psst! Over here!" },
            { id = 1243856, text = "Slay these unholy creatures, for the Alliance!" },
            { id = 1243868, text = "So many bats!" },
            { id = 1243870, text = "The Skyfire is being overrun! Come on, we have to help!" },
            { id = 1243864, text = "Those are royal guards! This must be her flagship! Seize the captain!" },
            { id = 1243860, text = "Watch yourself down there. That doesn't look like Westfall stew in those cauldrons." },
        } },
    } },
