    { who = "Constable Henry Framer", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1861955, text = "YOU WILL BE HEREBY TRIED FOR" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1861727, text = "Miss Waycrest, you are free to go. With my apologies." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1861726, text = "Attention! It has been determined that another witch was in fact responsible for the curse in Fletcher's Hollow." },
            { id = 1861954, text = "Lucille Waycrest, you stand accused of practicing witchcraft and of inflicting a curse upon the village of Fletcher's Hollow." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1861999, text = "Are you quite finished? I'm becoming impatient!" },
            { id = 1862001, text = "As is customary, the Lady Waycrest has chosen the tests she will undergo to prove her innocence of the accused crime of witchcraft." },
            { id = 1861997, text = "At last! Let's get on with it!" },
            { id = 1862000, text = "Finally! The trial can commence!" },
            { id = 1861998, text = "Has Miss Waycrest determined how she wishes to be tested?" },
            { id = 1861978, text = "More interruptions! What is it this time?" },
            { id = 1861980, text = "Ms. Waycrest stands accused of witchcraft. We will not turn her over unless she is absolved of this crime." },
            { id = 1861957, text = "Oh, how I loathe interruptions! What is your business here, Mainlander?" },
        } },
    } },
