    { who = "Consular Celestos", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1444399, text = "I am at your service." },
            { id = 1407239, text = "I will begin the preparations for Thunderon's rebirth. Find me when Thunderfury has been recharged." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1407262, text = "Thanks to you, Thunderfury has been restored, and Thunderon's spirit can finally be released." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1444397, text = "How may I assist you?" },
            { id = 1444401, text = "Let the winds guide you." },
            { id = 1407263, text = "Look to the heavens and witness the rebirth of Thunderon, the Windlord!" },
            { id = 1406847, text = "Quickly, shaman! Hand me the Blessed Blade and Thunderon will return!" },
            { id = 1444405, text = "The heavens await your command!" },
            { id = 1444395, text = "The wind has whispered your name." },
            { id = 1406851, text = "There has been no peace here since the death of Alakir, shaman." },
            { id = 1444403, text = "Where there is wind, so am I." },
            { id = 1411904, text = "You call upon the winds?" },
        } },
    } },
    { who = "Control Room Drakonid", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5052316, text = "I will purge the entire crucible before I let you have it!" },
            { id = 5052314, text = "You will serve nicely as new test subjects." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5052315, text = "Do you really think you can wrest control of these halls from me?" },
            { id = 5052305, text = "During my time serving Neltharion, I assisted him in creating many powerful elements." },
            { id = 5052310, text = "How exemplary! Congratulations!" },
            { id = 5052307, text = "In the quest to perfect Neltharion's armor, we went through many iterations." },
            { id = 5052311, text = "It was my honor to evaluate the development of Neltharion's Draxir." },
            { id = 5052306, text = "One of these instruments could be of great service to you, though it may not distinguish between friend and foe." },
            { id = 5052303, text = "Permission to suggest an alternate tactic?" },
            { id = 5052309, text = "There is no need to delay. Even greater treasures await within Scale Commander." },
            { id = 5052308, text = "This is one of our mower's successful attempts. While imperfect, it will be more than enough to destroy these interlopers." },
            { id = 5052312, text = "Unfortunately, they were too volatile to control, but where others see failure, I see opportunity." },
        } },
    } },
    { who = "Cordana", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1282849, text = "VENGEANCE WILL BE MINE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1282843, text = "I will not be stopped! I have fought too long, suffered too much! Victory must be mine!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1282835, text = "I knew she had that artifact secreted away after the events at the Black Temple." },
            { id = 1282845, text = "My powers have grown since joining the Legion. Here, let me show you." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1282833, text = "And now you fools have brought me the key. I'll thank you to hand it over, willingly or otherwise." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1282841, text = "beaten? How? You are nothing." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1282809, text = "May the night shroud me in shadow." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1282847, text = "All night elf children learn to love the dark." },
            { id = 1282837, text = "How utterly predictable. Maiev is nothing if not persistent." },
            { id = 1282851, text = "Watch your step, it's a long way down." },
            { id = 1282839, text = "Your death was inevitable." },
            { id = 1282853, text = "Your downfall is inevitable." },
        } },
    } },
    { who = "Cordana Felsong", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1322754, text = "Judge me all you like, sister, but you cannot stop us." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1048056, text = "I don't trust this place." },
            { id = 1389694, text = "I have what I was after, but I stayed just so that I could put an end to you once and for all." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1323103, text = "Come do your best. Nightglaive has been undergoing some changes." },
            { id = 1048050, text = "Don't let down your guard." },
            { id = 1048052, text = "Don't let the Archmage down." },
            { id = 1242903, text = "Kill them, Malinov!" },
            { id = 1048049, text = "Stay alert." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1242911, text = "Ah, we've been expecting you. How is Khadgar?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1048048, text = "Always vigilant." },
            { id = 1048051, text = "Azeroth depends on us." },
            { id = 1242909, text = "Be wary, an old friend is here." },
            { id = 1048053, text = "Commander" },
            { id = 1242905, text = "Feel the fel energy course through!" },
            { id = 1242907, text = "Felsworn Nightglaive, prove yourself! I have other matters to attend to." },
            { id = 1389692, text = "How utterly predictable. I knew that you would come." },
            { id = 1322772, text = "Hurry then, the Wardens are coming with the Illidari in tow." },
            { id = 1048054, text = "Ishmaelah" },
            { id = 1048058, text = "Ishnu Allah, Commander. Over here." },
            { id = 1322787, text = "So he is the key to Azeroth's downfall." },
            { id = 1048059, text = "The outpost is only a short distance up the hill. Come, the Archmage awaits." },
            { id = 1323105, text = "We are ready for you!" },
            { id = 1048057, text = "What news?" },
            { id = 1048055, text = "What say you?" },
        } },
    } },
    { who = "Cork Fizzlepop", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3585705, text = "Ready to make some gold?" },
            { id = 3585702, text = "Take it sleazy!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3585708, text = "Hey, hey! Quit it, will ya?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3586105, text = "And that's why I always bet on the Horde! Let's scram!" },
            { id = 3585709, text = "Can't you see I'm in the middle of scheming?" },
            { id = 3585704, text = "I'll be seeing you later!" },
            { id = 3586104, text = "Oh, you're in for it now, pal!" },
            { id = 3585703, text = "Pleasure doin' business with ya." },
            { id = 3585707, text = "Time is money, friend!" },
            { id = 3585710, text = "We goblins know a thing or two about explosives. Hehe, care for a demonstration?" },
            { id = 3586106, text = "You must be Warlord Brekka, Soldier's mother! She always said you'd save our hides!" },
            { id = 3585706, text = "You need it, I got it." },
        } },
    } },
    { who = "Corsair Cannoneer", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4070147, text = "A cam is a dragon!" },
            { id = 4070140, text = "Argh! We brought out the big guns, Cap'n!" },
            { id = 4070142, text = "Aye, aye, Captain!" },
            { id = 4070146, text = "Our captain is a dragon?!" },
            { id = 4070144, text = "Right away, Cap'n!" },
            { id = 4070139, text = "We brought out the big guns, Captain!" },
        } },
    } },
    { who = "Coryn", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1506021, text = "ACHOO!" },
            { id = 1506022, text = "HUH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1411283, text = "Meet me atop the sanctum when you are ready to die, whelp!" },
            { id = 1405178, text = "You cannot match me! I am your better!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1411282, text = "I have no need to hide behind a champion. I will defend my own honor." },
            { id = 1405181, text = "I will have what is owed me!" },
            { id = 1405180, text = "I will reclaim my honor! I invoke the ancient rite, Talashar!" },
            { id = 1405177, text = "I will wrestle my title from your champion's lifeless hands, Lyleth!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405176, text = "Filthy backstabbing cretin! That title should have been mine!" },
            { id = 1405175, text = "You impinge upon my honour! You besmirch my name with baseless accusations!" },
        } },
    } },
    { who = "Councilward Merrix", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5708356, text = "Do you have an appointment?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5708353, text = "I bid you welcome." },
            { id = 5708354, text = "I serve the titans unswervingly." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5708362, text = "Go where the edicts lead." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5708360, text = "Must go. Apologies." },
            { id = 5708352, text = "The edicts must be followed." },
            { id = 5708361, text = "The Eternal Titans sculpt your path." },
            { id = 5708358, text = "Very good to meet you." },
            { id = 5708359, text = "We must talk later." },
            { id = 5708355, text = "You address the Council Ward of Dawnagul." },
            { id = 5708350, text = "You know what the edicts don't say? That I can't turn around and kick you down the corway!" },
        } },
    } },
    { who = "Count Clessington", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4925404, text = "NO! I CANNOT FALL! UNIXIA PROMISED MORE! MOOOOOORE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4925398, text = "You cannot resist me! You cannot fight back! Come defias!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4925392, text = "Cecilia, you've never understood. Onyxia promised our family power. We deserve to rule!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4925395, text = "I've waited long enough! The kingdom will be mine! Feel the power of Onyxia!" },
            { id = 4925401, text = "No! I will rule! I will be king! Come forth! Fight! Fight!" },
            { id = 4924586, text = "We must turn Northshire. Join us, and we march on Stormwind. For the Defias!" },
        } },
    } },
    { who = "Courier Larkspur", tier = "character", groups = {
        { name = "Farewells", family = "Manners", lines = {
            { id = 1397631, text = "She is ready to take you to Ranger-General Windrunner. Good luck, Commander." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1388725, text = "We serve the Ranger General." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
