    { who = "Crusader Renn", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3636418, text = "I await your signal." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3636419, text = "Get to your positions! These grounds will be ours soon enough!" },
            { id = 3636411, text = "Let's get moving." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3636420, text = "Stand together. They won't let us take it without a fight." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3636408, text = "Forgive me, but I believe that to be antiquated thinking, Justicar. We must act now, before it is too late." },
            { id = 3636409, text = "If we continue to delay, our opportunity may be lost." },
            { id = 3636414, text = "Rest well, friend." },
            { id = 3636412, text = "There. The camp is just ahead." },
        } },
    } },
    { who = "Crushto", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 994849, text = "GET THAT ONE!" },
            { id = 994841, text = "MY SLAVES! THOSE WERE BLOODMALL PROPERTIES!" },
            { id = 994851, text = "RUN AWAY, LITTLE ONES! AH-HA-HA!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 994855, text = "HMMM!" },
            { id = 994857, text = "RRR!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 994843, text = "HOHOHOHO!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 994839, text = "Guards! Stop yapping! Start smashing!" },
            { id = 994835, text = "Hmm, yeah. Come here! I'll put you in chains!" },
            { id = 994853, text = "Slaves! Fight or die!" },
            { id = 994845, text = "Yeah! Not fit for capture!" },
        } },
    } },
    { who = "Cudgelface", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3609419, text = "I don't want to get ate!" },
            { id = 3609513, text = "I hate you a LIVELY one!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3609510, text = "Don't trust them things. None of them got sent here by accident, eh?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3609375, text = "Oh, don't skip the boot. Down to the morn never to come back. Take this poor soul for example. He's on his final warning." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3609514, text = "Hair for sweat? Oh, not ghost." },
            { id = 3609373, text = "Oh, I don't agree with their sinstone." },
            { id = 3609357, text = "This one looks... funny!" },
            { id = 3609511, text = "Watch the skies, they are watching you." },
            { id = 3609512, text = "What's someone like you doing in a place like this?" },
            { id = 3609376, text = "Won't even admit it, there's something wrong. Still thinks he's someone important." },
        } },
    } },
    { who = "Cyana Nightglaive", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1281343, text = "IT'S YOU WHO WON'T SURVIVE, DEMON WITCH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1281335, text = "I will never be taken prisoner again. Never!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1281351, text = "Did we bring enough of us?" },
            { id = 1281347, text = "Hurry! Kane has already launched the attack on Tarana!" },
            { id = 1281337, text = "I. Will. Not. Give. In." },
            { id = 1281349, text = "I'll secure the exit portal back to the Black Temple, once the others fly up here." },
            { id = 1281353, text = "Lord Illidan chose you to lead. I follow." },
            { id = 1281345, text = "More. I want more power." },
            { id = 1281355, text = "The fel energy is everywhere, it's hard to resist!" },
            { id = 1281357, text = "There are too many of them!" },
            { id = 1281341, text = "They outnumber us by an order of magnitude. Can we defeat them?" },
            { id = 1281339, text = "Yes, let's be certain to take care of that." },
        } },
    } },
    { who = "Cyanigosa", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 546659, text = "DOLORON WILL FALL!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 546656, text = "AHHH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 546657, text = "I will end the Kirin Tor!" },
