        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 546675, text = "HUH!" },
            { id = 546662, text = "OOH!" },
            { id = 546665, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 546680, text = "So ends your defiance of the Spellweaver!" },
            { id = 546676, text = "We finish this now, champions of the Kirin Tor!" },
        } },
    } },
    { who = "Cyranus", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2931790, text = "LEAVE MY KEN, A.S.M.L.!" },
            { id = 2931796, text = "MY AIM IS UNEARNED!" },
            { id = 2931795, text = "YOU WILL KNOW MY PAIN!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3008606, text = "HIYAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2931791, text = "I cannot bear the sight of you! Begone!" },
            { id = 2931797, text = "My torment has ended." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 2931789, text = "Hey, Chanel! I hope to never glance at you again!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2931794, text = "Athenel, I need you! Show yourself!" },
            { id = 2931793, text = "Where are you, my love? I must see you now!" },
            { id = 2931792, text = "Your visage soothes me, Eithanil!" },
        } },
    } },
    { who = "Cyril White", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1861952, text = "I must have you to thank. I never thought I would awake from that accursed state." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1862809, text = "Beware the witch's curse." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1861899, text = "Due to several recent, um, disappearances, a new curfew will be strictly enforced in Fallhaven." },
            { id = 1862808, text = "Fair winds and following seas." },
            { id = 1861953, text = "Fallhaven is in your debt, stranger. Please, tell us how we can repay you." },
            { id = 1861900, text = "For your protection, all villagers are expected to retire to their homes no later than sundown." },
            { id = 1862807, text = "Grim tidings, I fear." },
            { id = 1861901, text = "In addition, we have received reports of dangerous creatures in the foothills. Anyone with business outside the town limits is urged to use caution." },
            { id = 1861902, text = "Please report any suspicious persons or activity to Mayor White at once." },
            { id = 1861951, text = "Ugh... what... what is going on?" },
            { id = 1862806, text = "What brings you to Foulhaven?" },
        } },
    } },
    { who = "Cyrus", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2007632, text = "I have a bad feeling about this. Our scouts on patrol should have returned long ago. Investigate the cause of the delay." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2007643, text = "Be careful out there, Talia. I don't trust those hooded sages one bit." },
            { id = 2007634, text = "Drustvar has witches, and apparently Nazmir has liches. Take out this fiend's army and whatever is empowering it!" },
            { id = 2007635, text = "Good work. That Lich has been attacking our scouts with its forces. Now we should be able to focus on the Horde." },
            { id = 2007641, text = "Hmph. That will teach the Horde not to mess with our Marines. Good work." },
            { id = 2007637, text = "I've got a hunch that the Naga have more plan than this. Keep your eyes out for them." },
            { id = 2007636, text = "Naga! They've terrorized this world long enough! Put a stop to whatever they're doing." },
            { id = 2007640, text = "One of the Proudmoore officers has cornered a dark ranger. Assist him!" },
            { id = 2007633, text = "Sometimes. It seems like this whole swamp is out to get us. Good thing you're up to the challenge." },
            { id = 2007639, text = "That one's always a bit of a shock for a new cadet. Ah, don't worry. It builds character." },
            { id = 2007638, text = "With the current shortage of iron, even our training munitions can't afford to be wasted. Our Marines have devised the perfect way of retrieving them." },
        } },
    } },
    { who = "Daakara", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 546701, text = "DUUU!" },
            { id = 546697, text = "GAH!" },
            { id = 546686, text = "HEY!" },
            { id = 546696, text = "UGH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 546698, text = "AHHH!" },
            { id = 546684, text = "EH!" },
            { id = 546700, text = "HAHAHAHA!" },
            { id = 546693, text = "OW!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 546685, text = "Oh, let me introduce you to me new brothers, Fang and Claw! Heh Heh Heh heh!" },
            { id = 546711, text = "Oh, now me got some new tricks, like me brother bear. Waaah! Yeah! Hahahaha!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 546707, text = "Ha Ha Ha ha" },
            { id = 546712, text = "Heh heh heh, la mo going to fall like you! Heh heh, ha ha ha ha!" },
            { id = 546710, text = "Oh, look you, dead. Ha Ha Ha ha" },
            { id = 546688, text = "This is why they call me... ...INVIGIBLE! HAHAHA!" },
            { id = 546691, text = "You don't have to look to the sky to see the Dragonhawk!" },
        } },
    } },
    { who = "Daelin Proudmoore", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1989714, text = "You stood and watched as those animals cut me down. What has your betrayal earned you?" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1989717, text = "They took your father betrayed your king and you did nothing Will you abandon all your allies to the horde?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1989716, text = "The Horde are nothing more than monsters. No surprise they've turned on you." },
            { id = 1989715, text = "You sided with mongrels over your own flesh and blood!" },
        } },
    } },
    { who = "Daelya Twilightsbane", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3584343, text = "Divine Shield will protect you against the altar's dark magic." },
            { id = 3584342, text = "Step forward, paladin. The light will aid you in your time of need." },
            { id = 3584341, text = "Trust in the Light, Brave Paladin." },
        } },
    } },
    { who = "Daetan Swiftplume", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5479391, text = "YOU THINK YOU CAN WING THIS?!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5479394, text = "Here's today's feather forecast!" },
            { id = 5479395, text = "I'm... calling... FOUL!" },
            { id = 5479393, text = "Quack under the pressure!" },
        } },
    } },
    { who = "Dagnar Stonebrow", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1369951, text = "Suffer well, old friend." },
            { id = 1369912, text = "These bloody demons are gonna learn a new meaning of suffering when I get free! A beast called Xalanor carries the keystone that unlocks these bindings. Free me, and I'll help you slay the bastards!" },
            { id = 1369927, text = "What? Don't you have any sense of duty to aid your fellow knights?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1369923, text = "Listen, we don't have much time. They took Margrave to the Citadel. We're gonna have to break in there to get him out." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1369918, text = "Ahaha! That's much better!" },
            { id = 1369945, text = "Another bunch of them headed our way!" },
            { id = 1369931, text = "Flash is sliver! Fine! I'll help ye! But I'll rescue Marguerite first chance I get!" },
            { id = 1369948, text = "Here they come!" },
            { id = 1369936, text = "I'll be taking this for meself!" },
            { id = 1369906, text = "Spare me your gentle words, however, I've not had my final death yet!" },
            { id = 1369939, text = "What are you waiting for? Get a move on!" },
        } },
    } },
    { who = "Dagran Thaurissan Ii", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5723133, text = "I hope Granddad's all right. I never got to spend much time with him." },
            { id = 5723635, text = "I hope it works, speaker. Truly." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5723585, text = "But it's not working. It's breaking down." },
            { id = 5723612, text = "Can I ask you another question, Speaker Brint?" },
            { id = 5723607, text = "Can you give me a rough estimate?" },
            { id = 5723580, text = "Did the Titans build all these machines?" },
            { id = 5723582, text = "Do you worship the machines?" },
            { id = 5723610, text = "Fantastic. I'm much obliged. Hmm. Where to start?" },
            { id = 5723609, text = "How long has Dornagol been here?" },
            { id = 5723637, text = "I'm sorry to hear that." },
            { id = 5723207, text = "Kaz Olgar? The Titan Installation Mention in Uldaman's Records?" },
        } },
    } },
    { who = "Daio the Decrepit", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1397476, text = "I expected no less from one who wields crippling ice magic, but how about a foe as skilled in spellcasting as yourself?" },
            { id = 1397479, text = "I gave Erechtsus a piece so he could attune his ritual to demonic energies. You may have what remains of the stone. May it bring better luck to you." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1397478, text = "For the final piece of the puzzle, a simple stone. A stone from Balador's realm, left here by chance during one of his many ambushes." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1397475, text = "Easily defeated, but deadly in large numbers. Perhaps something that hits a little harder?" },
            { id = 1397477, text = "Hmm, well fought, but Balador has been hunting mages for untold ages. Facing him will require mastery of all your abilities." },
            { id = 1397474, text = "Very well. Let us begin. Perhaps something easy to start. A few imps, perhaps?" },
        } },
    } },
    { who = "Daliah the Doomsayer", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 599204, text = "AHHH!" },
            { id = 599219, text = "HYAH!" },
            { id = 599207, text = "YEAH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 599222, text = "NOOO!" },
            { id = 599201, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 546747, text = "Completely ineffective, just like someone else I know!" },
            { id = 546742, text = "It is unwise to anger me!" },
            { id = 546739, text = "You chose the wrong opponent!" },
        } },
    } },
    { who = "Dame Blaumeux", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 546780, text = "I do hope they stay alive long enough for me to... introduce myself." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 546778, text = "Come, Zeliek. Do not drive them out. Not before we've had our fun." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 546775, text = "The first kill goes to me! Anyone care to wager?" },
        } },
    } },
    { who = "Danath Trollbane", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1995282, text = "I purchase ours. This is your last chance, Blood Elf. Surrender, and I might just spare your life." },
            { id = 1995281, text = "I purchase ours. We're well on our way to dealing with these interlopers." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1391569, text = "Get out of here, champion! I'll find my own way!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1995284, text = "Alliance banners fly over Newstead once more." },
            { id = 1995280, text = "Control over Galsan's load means a limitless supply of iron that should come in handy." },
            { id = 1391568, text = "Look out! Evasive maneuvers!" },
            { id = 1391565, text = "Look there upon that terrible sight. How many disasters must we face before we can at last find peace?" },
            { id = 1995285, text = "Now, siege engines, blast down that gate! This vile orc will know the meaning of Alliance justice!" },
            { id = 1995278, text = "Perfect. Highlands Mill will provide us the lumber we need to rebuild Stromgarde." },
            { id = 1391567, text = "This place is filthy with corruption. I fear a long campaign awaits us." },
            { id = 1995283, text = "We have secured High Perch. We will soon sack Argorok and reclaim what is rightfully ours." },
            { id = 1995279, text = "Well done, we have recaptured the circle of elements." },
        } },
    } },
    { who = "Danica the Reclaimer", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1370160, text = "Hard-grim, Alric! Odin has judged you worthy for his halls! Come with me to glory!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1370011, text = "Welcome to Skyhold! Hear the brave live on forever!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370180, text = "A valorous sacrifice, but it is not yet your time." },
            { id = 1370014, text = "Across the fae, lies the arena of glory. Fair warriors vie for supremacy in epic combat. Before us, lies the great mead hall. Fair drink and stories flow freely." },
            { id = 1373831, text = "Are you worthy of Odin's gaze?" },
            { id = 1370013, text = "Behind you lies the Eye of Odin, which peers across all of Azeroth. This way lies the Forge, where the mightiest weapons of the Valarjar are crafted by Helgar, the greatest smith in the halls." },
            { id = 1373829, text = "Glory to Odin!" },
            { id = 1373826, text = "Glory to you on the battlefield!" },
            { id = 1373827, text = "May Audin's gaze give you strength." },
            { id = 1370015, text = "Odin awaits ahead. I will go forth and announce you. Be respectful." },
            { id = 1373828, text = "Strife to be worthy." },
        } },
    } },
    { who = "Daniel Poole", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1990632, text = "THIS IS A NIGHT FOR CULTUREERS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1990636, text = "And this likely won't be a clean fight, ha ha, so keep your distance, Sally! Now, are we ready?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1990637, text = "Aww, oopsie daisy!" },
            { id = 1990639, text = "Ears and noses will litter the floors today!" },
            { id = 1990634, text = "Friends, we gather today to see which of these bandits, these goons, these ne'er-do-wells have the right to call themselves true culturans!" },
            { id = 1990641, text = "No, no, no! Good save! Good save!" },
            { id = 1990640, text = "Oi! Now, now! There will be blood! Have patience! Heh Heh Heh heh!" },
            { id = 1990643, text = "Oi, oi, it's not over until it's over!" },
            { id = 1990642, text = "Oi, quiet down now! Fight's not over yet!" },
            { id = 1990635, text = "Only the last one standing will have earned that honor!" },
            { id = 1990633, text = "This is a day for cult heroes!" },
            { id = 1990638, text = "You die! But not as a true Kulturian!" },
        } },
    } },
    { who = "Dantalionax", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1275423, text = "YOUR SKIN CRAWLS!" },
