    { who = "Dargrul", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1276155, text = "I can shape the world just as the titans did!" },
            { id = 1274560, text = "I want these tauren off my mountain!" },
            { id = 1274586, text = "I want this Shahn Roneer to tell the others. Tell them their doom will come once I master this hammer." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1276144, text = "The Tauren believed you were prophesized to seize my hammer! Mwahahaha! Pathetic!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1276415, text = "The molten soul of Azeroth engulfs you!" },
            { id = 1276214, text = "The mountain will gnaw on your bones!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1276417, text = "Ha Ha Ha ha, I mountain will swallow you whole!" },
            { id = 1276419, text = "It is time to end this." },
            { id = 1276150, text = "Let them come. Witness the fate of those who stand against one worthy of wielding the power of a titan!" },
            { id = 1276289, text = "The earth heaves and roars at my command!" },
            { id = 1274565, text = "You dare challenge me?" },
            { id = 1274843, text = "You want my hammer? Come dig for it!" },
