    { who = "Defias Lieutenant", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4925316, text = "The Defias answer to me now!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4924580, text = "No reparation is enough. The stonemasons deserve every coin in every coffer of Stormwind City. Klassington will lead us there." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4925387, text = "Gah! The Defias needs their new leader! I will not fall here!" },
            { id = 4924583, text = "So, you finally show yourself, Van Cleef, and with a Stormwind dog in tow. See, Defias? See how she will make us all lap dogs of Stormwind!" },
        } },
    } },
    { who = "Degar Bloodtotem", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
