    } },
    { who = "Delthanar Sagewood", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1247037, text = "You have my gratitude traveler." },
            { id = 1247049, text = "You! You have saved me!" },
