    { who = "Demons - feminine voice", tier = "creature", ctype = "Demon", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1404532, text = "Hide for now. I will find you soon." },
            { id = 1404529, text = "You are our playthings, little one. Remember that." },
            { id = 1404537, text = "You can run, but you cannot hide sweetling." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1404527, text = "You make the most amusing pet, little elf." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1404536, text = "Come out, come out, little one!" },
            { id = 1404531, text = "Get used to groveling, Nightborne." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1404534, text = "Hmm, maybe nothing after all." },
            { id = 1404530, text = "Kneel before your betters, whelp!" },
            { id = 1404528, text = "Know your place, worm." },
            { id = 1404533, text = "Very well. Enjoy your freedom while it lasts." },
            { id = 1404027, text = "Very well. Enjoy your freedom. For now." },
