    { who = "Demons - masculine voice", tier = "creature", ctype = "Demon", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1404499, text = "You cannot hide forever." },
            { id = 1404502, text = "You will learn your place." },
            { id = 1404504, text = "Your lives are ours to take." },
