        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1404506, text = "Let your death serve a lesson to those who defy the Legion!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1404497, text = "Enough! We will hunt later!" },
            { id = 1404505, text = "Gul'dan permits the rest of you to live, for now." },
            { id = 1404496, text = "Hmm, something isn't right." },
            { id = 1404495, text = "Well, well, what have we here, a thief?" },
