        { name = "Loyalty", family = "Manners", lines = {
            { id = 1102422, text = "All must serve or die!" },
        } },
    } },
    { who = "Derek Proudmoore", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2737100, text = "You, Mother, and Tundra all endured so much. I'm pleased you have each other again, but... Where does my path lead?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2737102, text = "I can't come home, can I?" },
            { id = 2737099, text = "I know about father. The Horde spewed lies to poison me against you, but Bane explained the truth of what happened." },
            { id = 2416153, text = "I remember the battle. Orchids Dragonriders, our decks consumed by flame. I felt a blaze of agony, and then, ah, darkness." },
            { id = 2416154, text = "I was... I was dead, wasn't I? But for how long? I am not quite alive, and yet... Oh, I don't understand this. Oh, please! Yes, you please! How is this possible?" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2737104, text = "Will you come with me, Jaina? I... I don't know if I can do this alone..." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 2416155, text = "Tell me! Tell me where is my father! My mother! Jaina! Tandred! Please, please, I'm so alone! Don't, don't leave me alone!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2415168, text = "Hah! Ugh! Ugh! Ugh!" },
            { id = 2737097, text = "Jaina, I can hardly believe it's you. When I said sail, you were a child. And now, Lord Admiral." },
            { id = 2416152, text = "Please. Help me. I... I don't know what's happened. What's been done to me." },
            { id = 2416156, text = "What? What is this? Why am I... What have you done to me?" },
        } },
    } },
    { who = "Dervishian", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4821087, text = "HEH HEH HEH HEH" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4643443, text = "I know we have faced an enemy like this before, but I only recall flashes, fragments." },
