        { name = "Idle", family = "Feelings", lines = {
            { id = 4821103, text = "HUAGH!" },
            { id = 4821101, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4643229, text = "A very long time, by the look of our creche." },
            { id = 4643380, text = "Fair skies and strong winds, Evoker!" },
            { id = 4662042, text = "Fair skies and strong winds, friend." },
            { id = 4643227, text = "In here, evoker!" },
            { id = 4643232, text = "Neltharion can explain what has happened. I am certain of it." },
            { id = 4643223, text = "Something is very wrong here. We must find our wingmates this way" },
            { id = 4643438, text = "The Ebon Scales are under siege by Wild Drakes, Terrasek, and Elementals. I overheard the name, Primalists." },
            { id = 4643505, text = "We need to grab that dragon's attention so the Evanscales can strike." },
            { id = 4643222, text = "Wha... Wha... Evoker... What has happened? Who did this to us?" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 4821085, text = "HAHA!" },
