            { id = 4563063, text = "Folicitations to you." },
            { id = 4612834, text = "Have we met?" },
            { id = 4577007, text = "Honor the life binder." },
            { id = 4577008, text = "Honor the Lifebinder" },
            { id = 4577009, text = "Honour the LifeBinder." },
            { id = 4612830, text = "Is there something you need?" },
            { id = 4703268, text = "Is this what heroes do on Azeroth these days, after all?" },
            { id = 4612857, text = "Let us speak." },
            { id = 4574040, text = "May your life be long." },
            { id = 4699104, text = "Our legacy will be renewed." },
            { id = 4703267, text = "Our numbers may be few, but we still outnumber you." },
            { id = 4576997, text = "Replenish the Isles." },
            { id = 4574036, text = "See you in your dreams" },
            { id = 4563072, text = "Sometimes I amaze myself with... well, with how smart I am." },
            { id = 4563051, text = "Tell me what you find." },
            { id = 4699106, text = "The Black Dragonflight will protect this world once again." },
