    { who = "Dread Admiral Eliza", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1392320, text = "ENOUGH! I'LL RUN YOU THROUGH!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1504488, text = "HA!" },
            { id = 1504487, text = "HEH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1392318, text = "I have already seen my destiny. You are not a part of it!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1392319, text = "I am the scourge of the seas, the fear in Sailor's heart! You are NOTHING!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1392317, text = "It will be my pleasure." },
            { id = 1392305, text = "Release the giant! I have business to attend to within the temple." },
            { id = 1392304, text = "So, you're the one who stole my ship and killed my crew." },
            { id = 1392314, text = "The dreadblades have claimed entire fleets, impenetrable fortresses have gushed rivers of blood by their will. To utter their name instills fear in sailors' hearts." },
            { id = 1392315, text = "They know no equal. I know no equal. Turn back now and you may yet live to tell the tale." },
        } },
    } },
    { who = "Dread Captain Lockwood", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1941111, text = "ANOTHER NUTS IN ME BLADE!" },
            { id = 1941110, text = "I SALE TO UNCHARTED WATERS!" },
            { id = 1941106, text = "I'LL CARVE YOU TO RIVEN'S!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1941102, text = "All cannons! Fire!" },
            { id = 1941109, text = "All hands, attack!" },
            { id = 1941103, text = "Decimator rounds! Fire!" },
            { id = 1941104, text = "Here's lead in your gut!" },
            { id = 1941113, text = "The city is ours, mates!" },
            { id = 1941107, text = "Ugh! I tire of this!" },
            { id = 1941112, text = "Your innards'll tangle for me, master! Heh Heh Heh heh!" },
        } },
    } },
    { who = "Dread Captain Tattersail", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1243466, text = "SHOW YOURSELVES YOU COWARDS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1239155, text = "And your ship is already doomed!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1239077, text = "My guess? She landed somewhere up the coast and continued on foot." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1242289, text = "Come on, you bilge rats! I'll give you a burial at sea!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1507739, text = "ARGH!" },
            { id = 1507737, text = "UGH!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1239153, text = "You're too late. The Dark Lady is already gone." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1239075, text = "Damn it! We're sitting ducks out here!" },
            { id = 1245017, text = "News from Captain Dreadwake, m'lady. They have found the temple." },
            { id = 1245019, text = "The Oblivion has landed nearby. They are building fortifications now and will be ready to lay siege at your command." },
            { id = 1243464, text = "We got the queen into a rowboat, but she didn't want an escort. Told us to stay behind and fight." },
        } },
    } },
    { who = "Dread Commander Arganoth", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1248408, text = "DO NOT LET THEM REACH THE SPIRES!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1380110, text = "NOOO!" },
            { id = 1380109, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1248438, text = "The master will mend my flesh again and again. You have not won. You cannot win. We are endless! We are Legion!" },
            { id = 1248418, text = "You will pay for this transgression! The Legion is endless! Inferno!" },
            { id = 1248432, text = "Your souls will fuel the Soulforge!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1248434, text = "I will flay the flesh from your bones!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1248422, text = "You wish to face the might of the Legion? Ha! Very well. The Master will reward me for your souls." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1248428, text = "The Legion will crush you! Inferno!" },
            { id = 1248406, text = "You march to your doom!" },
        } },
    } },
    { who = "Dread Knight", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1376288, text = "BEHOLD THE MIGHT OF THE BURNING LEGION!" },
            { id = 1376290, text = "MORTAL FILTH! YOU WILL STAIN THIS WORLD NO MORE!" },
            { id = 1376292, text = "SPREAD OUT! LEAVE THEM NOTHING!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1376298, text = "Your lives mean nothing! I will relish ending them!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1376296, text = "I accept your challenge, mortals! Time to see just how fragile you truly are!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1376294, text = "Wipe them out! All of them!" },
        } },
    } },
    { who = "Dread Rider Cullen", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1244169, text = "I feel like that guy having a dragon is a bad thing." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1244167, text = "Hey! Over here! I've got a plan!" },
            { id = 1244163, text = "Hey, it's you! I'm getting stir-crazy here. Please tell me we're going in." },
            { id = 1245414, text = "Hey, you're on your own from here. Good luck." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1242301, text = "Hang on tight and try not to scream. Duchess has very sensitive ears." },
            { id = 1245412, text = "Now's our chance! Let's get up that tower!" },
            { id = 1242299, text = "That should be enough. Get up to the top deck." },
            { id = 1244165, text = "This way! There's a good spot right here!" },
            { id = 1244171, text = "Yeah, finally some action!" },
            { id = 1242297, text = "You heard Nathanos, NO SURVIVORS!" },
        } },
    } },
    { who = "Dreadlord", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1594812, text = "ENOUGH OF THESE GAMES!" },
            { id = 1594818, text = "ENOUGH OF THIS GAME!" },
            { id = 1594811, text = "WE WILL NOT BE STOPPED!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1594815, text = "Perish before the might of the Legion!" },
            { id = 1594817, text = "You are too late, little druid! We will use your power of flight to bring down Dalaran!" },
            { id = 1594810, text = "You will not interfere with our plans. Conrathoth's power will belong to the Burning Legion! Fall before our might!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1594814, text = "My work is complete, puny monks. Your order has already fallen!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1594816, text = "Legion! With this idol, the cowardly mortals floating city will no longer protect them." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1581064, text = "I'll have these creatures devour your soul, piece by piece!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1581063, text = "What is this disturbance? I will not tolerate further delays in preparing these creatures!" },
            { id = 1594813, text = "You're ordered to report to the battlefield at once. Take out those demons shredding our front lines." },
        } },
    } },
    { who = "Dreadscar Torturer", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1499853, text = "GAH!" },
            { id = 1499849, text = "HEY!" },
            { id = 1499856, text = "HUH!" },
            { id = 1499854, text = "NYEH!" },
            { id = 1499855, text = "UGH!" },
            { id = 1499851, text = "WHOOSH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1393661, text = "Savor your words while your mind can still form them, worm." },
            { id = 1393664, text = "Yes, I can feel your mind breaking." },
            { id = 1393663, text = "Your silence cannot last forever, warden!" },
        } },
    } },
    { who = "Dream Dryad", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5328986, text = "ANSWER THE CALL OF THE WILD" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 5328983, text = "Wonder where you will." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5328981, text = "Find your own trail." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5328987, text = "Dream beneath the trees." },
            { id = 5328984, text = "heal and grow." },
            { id = 5328985, text = "Life is all around us." },
            { id = 5328989, text = "Most come here seeking dreams. Would you prefer a nightmare?" },
            { id = 5328982, text = "Rest until you awaken." },
            { id = 5328988, text = "Walk gently on the Earth." },
        } },
    } },
    { who = "Dreamweaver", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3743399, text = "AHHH!" },
            { id = 3743405, text = "COUGH!" },
            { id = 3743397, text = "FRAH!" },
            { id = 3743395, text = "HYAH!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3641577, text = "Come, we'll show you how to care for a wild seed and watch its spirit dream." },
            { id = 3641578, text = "Let's start with a younger one. It arrived just before the drought and needs a little extra attention." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3743461, text = "AH!" },
            { id = 3743453, text = "D'OH!" },
            { id = 3743463, text = "EEEH!" },
            { id = 3743465, text = "OOF!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3641571, text = "Since the drought started, there hasn't been enough anima to go around. We've had to make some... hard choices." },
            { id = 3641570, text = "Wildseeds need caretakers to give them anima. Without it, the spirits inside can't be reborn." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3641579, text = "All thanks to our helpful new friend!" },
            { id = 3641572, text = "Good. You finish up here, I'll look for the missing caretakers." },
            { id = 3641568, text = "No, no. This won't please the Queen at all." },
            { id = 3641575, text = "Oh, and thank you again. Whatever world you're from, they're lucky to have you." },
            { id = 3641569, text = "Thank you, friend. These pools are anything but tranquil lately." },
            { id = 3641573, text = "The plants ate them? Not again." },
            { id = 3641574, text = "Use my dagger to open the plants and free the others. We'll meet you in Tir Na Val." },
            { id = 3641576, text = "We've all been eaten by plants before, it happens." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 3743389, text = "GASP!" },
            { id = 3743385, text = "HA!" },
            { id = 3743387, text = "HAH!" },
        } },
    } },
    { who = "Dredger Bully", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3448797, text = "I get you a sinstone yet?" },
            { id = 3448792, text = "I got the best prices you can find out here." },
            { id = 3448787, text = "I look like some mack-foot to you in need of poking and prodding! I know my gig, you know yours!" },
            { id = 3448796, text = "I said you was a mole-woke. How's that work?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3448795, text = "Fancy footer, eh? Can I have them when you die?" },
            { id = 3448791, text = "Got the best goods you're bound to find, just don't ask too many questions." },
            { id = 3448790, text = "Grey as stone, and cheap as... stone." },
            { id = 3448798, text = "How much for your teeth?" },
            { id = 3448794, text = "Huh, thought you'd be more fleshy." },
            { id = 3448788, text = "Listen up, fang food! Keep your nose low and your feet quiet or it's the mire for both of us!" },
