            { id = 3743617, text = "The darkness must wane." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3743616, text = "For Queen and Grove." },
            { id = 3743619, text = "In nature, all are one." },
            { id = 3743615, text = "It is done. I will hold this ground." },
            { id = 3743618, text = "Night embrace you." },
            { id = 3743610, text = "The Drust dare lay claim to this grove! Show them no mercy!" },
            { id = 3743608, text = "The Drust have turned my people into mindless beasts. Work with my ally Amberfoot to defend Ardenweald." },
            { id = 3743609, text = "though it comes at great cost, the balance must be restored. Thank you." },
