    { who = "Droman Oulfarran", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3486096, text = "I. Cannot. Control. It." },
            { id = 3486089, text = "Ingra Malak falls silent. The forest sighs in gratitude." },
            { id = 3486091, text = "Place your faith in the weird." },
            { id = 3486095, text = "Please, survive this." },
            { id = 3486085, text = "Terna scythe withers as the Gorm feast. Balance must be restored." },
            { id = 3486092, text = "The forest yearns for your victory, mortals." },
            { id = 3486093, text = "The Roots. They. Do. Not. Listen." },
            { id = 3486086, text = "The time for play has passed. The winds urge us forward." },
            { id = 3486087, text = "This fate was not to be." },
            { id = 3486090, text = "You must run. My mind betrays me." },
            { id = 3486094, text = "You. Must. Endure." },
