    { who = "Ebonhorn", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2965011, text = "I am free of my father's madness. We seek to wield the essence in defense of Azeroth." },
            { id = 2965000, text = "I see. This forge will unlock the power of each essence." },
            { id = 2965005, text = "I too have sent something deep beneath Highmountain, in the caverns that were once Neltharion's lair." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 2965002, text = "Well met, Speaker Magni. In my Tauren form, I am known as Ebonhorn. As the Construct said, I am here to help." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2965009, text = "A Stonelord from Deepholm? This is worse than I feared. Their kind still harbors enmity toward the Black Dragonflight." },
            { id = 2965004, text = "Champion, what brings you here?" },
            { id = 2965006, text = "Let us investigate the matter. Navarra can bring us directly to the source of the disturbance." },
            { id = 2965001, text = "May the might of the Black Dragonflight aid you in restoring this world." },
            { id = 2965003, text = "Neltharion was once tasked with protecting Azeroth. It is my duty to see the essence carry on that legacy." },
            { id = 2965010, text = "Stonelord, I am Ebonhorn, protector of Highmountain. We have come to claim the essence you now hold." },
            { id = 2965007, text = "The Azerite empowers you, champion!" },
            { id = 2965008, text = "Well fought, champion. The essence is yours to claim." },
        } },
    } },
    { who = "Ebonhorn Narrator Bunny", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1277248, text = "At the Call of Crassus, he defied the Legion and defeated many demons with the Eaglespear." },
            { id = 1277360, text = "Even the Lord of the Forest, Cenarius, recognized Hull's greatness. He bestowed him with a blessing that we carry with us to this day, the Horns of Ekaro." },
            { id = 1277308, text = "He returned to his homeland after the War of the Ancients, and it was renamed in his honor." },
            { id = 1277250, text = "Holmes' prowess in combat was unmatched." },
            { id = 1277306, text = "Home cast Tichondrius out of this world with the eaglespear." },
            { id = 1277246, text = "Home was the strongest of champions and first of our tribe." },
            { id = 1277252, text = "Perhaps they were correct in their belief that Holm's love of fighting was too strong." },
            { id = 1277254, text = "Some believe Holm's bloodlust was too strong." },
            { id = 1277256, text = "They sing of Huln's thirst to spill demonic blood." },
        } },
    } },
    { who = "Ebyssian", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 4726256, text = "HA!" },
