            { id = 4726254, text = "HMPH!" },
            { id = 4726250, text = "HUH!" },
            { id = 4726252, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1384385, text = "Maela, I am still the same Spiritwalker you have known your entire life. Know that regardless of what happens, I serve the High Chieftain." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 4726382, text = "MMM!" },
