        { name = "Idle", family = "Feelings", lines = {
            { id = 4726296, text = "BOOM!" },
            { id = 4726298, text = "GAAAH!" },
            { id = 4726300, text = "OOOHHH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1389489, text = "Which gives me great honor to say this next part. Maela Highmountain, I hereby pronounce you High Chieftain. Long may you stand." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 4726228, text = "AHHH!" },
