    { who = "Echo of Nerzhul", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1397186, text = "Take up the blade, Arthas Menethil. Embrace your destiny." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1397188, text = "Let the darkness consume you. Feast upon the souls of the damned!" },
