    { who = "Eitrigg", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1391560, text = "I must speak with you, the matter is urgent." },
            { id = 1582230, text = "My axe grows thirsty!" },
            { id = 1391563, text = "My thanks, champion. I will seek out Thrall and see if he can help." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1391561, text = "It concerns High Overlord Saurfang. I fear he plans to bring doom upon himself." },
