    { who = "Elder Ara", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4330907, text = "I believe that pilgrimage is in order." },
            { id = 4288089, text = "I have enough problems!" },
            { id = 4288084, text = "I will be here when you need another favor." },
            { id = 4330896, text = "I will help you if you help me." },
            { id = 4330912, text = "I will travel ahead. Meet me outside of Provis Esper." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 4288083, text = "Good luck in your future endeavours." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4330917, text = "The forge. Majestic, is it not?" },
            { id = 4330921, text = "Up ahead! I think I see something amidst the rubble!" },
            { id = 4288088, text = "You may speak." },
        } },
    } },
    { who = "Elder Asani", tier = "character", groups = {
