    { who = "Elder Cassaphine", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5341854, text = "My heart burns with renewal!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5341864, text = "The flowers slowly turn to flame, the petals are not consumed, but they burn brightly!" },
            { id = 5341862, text = "The Lords of Fire return and bring new life!" },
            { id = 5341866, text = "The portals are open! The flames are here!" },
            { id = 5341865, text = "To aid a friend, or to seek renewal." },
