    { who = "Elder Poa", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4659194, text = "Your tale will be remembered." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4659200, text = "I said stop that! Were you raised in a cave?" },
