        { name = "Greetings", family = "Manners", lines = {
            { id = 4659198, text = "Hello! Speak up now!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4659197, text = "Ah! A new story to hear!" },
            { id = 4685188, text = "But Trolls, there are no trolls here!" },
            { id = 4669510, text = "Great fish gather in droves! Go! Gather meat for us and bring back stories of your exploits!" },
            { id = 4659195, text = "Now, you be careful out there!" },
            { id = 4659199, text = "Oh, good day, young one!" },
            { id = 4659192, text = "Pass my stories along!" },
            { id = 4669639, text = "What a tale to tell! It's a feasting pot! A story of great strength against the ocean!" },
            { id = 4659193, text = "What? Good-bye? Oh, yes. All right then." },
