    { who = "Elementals", tier = "creature", ctype = "Elemental", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1025246, text = "THE FURY HAS BROKEN FREE!" },
            { id = 1034580, text = "YOU SON OF A..." },
