    { who = "Elerethe Renferal", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1354941, text = "SCREAM FOR ME!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1354933, text = "Now YOU have become prey!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1354927, text = "I recall my final moments, surrounded by those I had trusted. Your satisfied sneers as I drew my last breath!" },
            { id = 1354931, text = "Your faces no longer appear familiar. Did you truly deserve my wrath?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1354943, text = "I'll adorn my web with your bones!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1354923, text = "Betrayers! Liars! Murderers! Hasamuul sent his lap dogs to fetch his knife from my back!" },
            { id = 1354925, text = "Do you remember murdering me, or have you grown so used to slaughter that my cries of agony are long forgotten?" },
            { id = 1354945, text = "Feel the crush of my talons!" },
            { id = 1354929, text = "Revenge is said to be sweet, but I taste only bitterness." },
            { id = 1354935, text = "Scary scary little rat!" },
            { id = 1354939, text = "Such juicy morsels!" },
            { id = 1354937, text = "There is nowhere left to hide!" },
        } },
    } },
    { who = "Elfyra", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1524825, text = "AHHH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1513453, text = "I don't have any friends. Well, apart from you, Galindra." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1513448, text = "Come see my minions, and let them be heard!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1513451, text = "That was quite a commotion." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1513450, text = "For the first time, I feel wicked!" },
            { id = 1513445, text = "Together, we're unlimited!" },
            { id = 1513452, text = "We all deserve a chance to fly! Hey, do you really think the wizard will de-greenify me?" },
            { id = 1513447, text = "You deserve a chance to fly!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1513449, text = "Elekomomen, Utunbuntu, Rotukelaromen!" },
            { id = 1513444, text = "How beautifully... tragic." },
            { id = 1513454, text = "No one mourns the wicked!" },
            { id = 1513446, text = "Sorry to bring you down!" },
        } },
    } },
    { who = "Elisande", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1352995, text = "The threads of time answer to me!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1352998, text = "I control the battlefield, not you!" },
            { id = 1352991, text = "I could not allow my people to starve. To waste away without its energy sustaining us. So a bargain was struck." },
            { id = 1352988, text = "I foresaw your coming, of course. The threads of fate that led you to this place. Your desperate attempt to stop the Legion." },
            { id = 1352989, text = "My people faced a similar dilemma. I peered into all possible futures in search of an answer. And found only one." },
            { id = 1352992, text = "Now I see a future where the Legion is victorious and my people endure. This is the thread that must be preserved. I will do everything in my power to make it so." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1352999, text = "Let the waves of time crash over you!" },
            { id = 1352990, text = "The Legion's victory is inevitable. Every timestream shows it to be so. Had we resisted, they would have taken the Nightwell by force and left us bereft of it." },
            { id = 1352997, text = "Time itself heeds my call." },
            { id = 1352996, text = "Will you race through time, or be trapped in an endless eternity?" },
            { id = 1352993, text = "Your deaths ensure the future of the nightborne. Come forward then. Let us speed you towards your fate." },
            { id = 1352994, text = "Your timelines end here!" },
        } },
    } },
    { who = "Elite Goblin Mech Jockey", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3006744, text = "Killing youse guys is gonna earn me a huge raise!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3006746, text = "Beware, beware this, toots!" },
            { id = 3006742, text = "So much for that promotion!" },
            { id = 3006743, text = "Well, Well, Well, if it ain't sneaky spy guy and sea captain lady lord." },
        } },
    } },
    { who = "Elma", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5782028, text = "I must heed the call!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5708569, text = "Come see me at the show tonight." },
            { id = 5708574, text = "Don't expect an inscription." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 5782031, text = "Ah, we are all slain!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5708576, text = "Hands off! You're weathering me!" },
            { id = 5708573, text = "Here to adore me." },
            { id = 5708571, text = "Leaving so soon." },
            { id = 5782037, text = "Now we venture into the ringing deeps. The machine speakers will neither help nor hinder us." },
            { id = 5782034, text = "The canyons in Hollowfall are getting darker, but the song is getting stronger. We must light the way!" },
            { id = 5782025, text = "The song is louder still! But the Nerubians! There are so many!" },
        } },
    } },
    { who = "Elothir", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1241565, text = "I sense great pain in the heart of Val'sharah. If Shaladrassil is in danger, I must go and lend my aid." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1241561, text = "Come closer traveler, the forest has whispered of your arrival." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1270817, text = "Be one with nature." },
            { id = 1241563, text = "Daughters of Cenarius, I go to aim your father. Please, watch over this blade until I return." },
            { id = 1270815, text = "May your roots run deep." },
            { id = 1270812, text = "Plant the seed, and I will aid you with what little strength I have left." },
            { id = 1270819, text = "The forest bleeds you." },
            { id = 1270813, text = "The forest is with you." },
            { id = 1241579, text = "Who is it that approaches? My eyes are filled with darkness." },
        } },
    } },
    { who = "Elsia", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 798273, text = "You are here. The Regen Lord has asked about you specifically. Are you ready to go?" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 798259, text = "Stay strong." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 798263, text = "Anaria Shola" },
            { id = 798257, text = "for Silvermoon." },
            { id = 798265, text = "Glory to the Sindori." },
            { id = 798277, text = "He united the Mogu, defeated the other Pandaren races, and founded a glorious nation with the slave labor of those he conquered." },
            { id = 798267, text = "Our fate is in our hands." },
            { id = 798269, text = "Our people will persevere." },
            { id = 798275, text = "Pandaren legends tell of Lei Shin, the Thunder King. He was the brutal founder of the Mogu Empire over 12,000 years ago." },
            { id = 798255, text = "Shirella Rahn" },
            { id = 798261, text = "We do what we must." },
            { id = 798271, text = "We must seize every opportunity." },
        } },
    } },
    { who = "Eluxara Darkscorn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1522832, text = "You will have the time you need, Watcher." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1522830, text = "A pathetic attempt at disguise! Now you will pay with your life!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1522826, text = "Your resistance is irrelevant!" },
            { id = 1522828, text = "You're too late!" },
        } },
    } },
    { who = "Emaedi Autoblast", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2913649, text = "I never miss a shot." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2913642, text = "Always ready to fly!" },
            { id = 2913640, text = "Elite Aerial Rangers, sir!" },
            { id = 2913639, text = "Excited to be working with you, Commander." },
            { id = 2913647, text = "Got a new target?" },
            { id = 2913644, text = "I'll be waiting!" },
            { id = 2913643, text = "Locked and loaded." },
            { id = 2913641, text = "You said Aerial Elite Rangers, which would be G-A-E-R, if you wanted G-E-A-R." },
        } },
    } },
    { who = "Embar Firepath", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4641932, text = "My rage burns on!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4641931, text = "Fire consumes all!" },
            { id = 4641925, text = "Fire is a hungry child. It must always be fed." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4641924, text = "Aranag failed. The aberrations will soon be upon us." },
            { id = 4641930, text = "Flaming Steel, sear your flesh!" },
            { id = 4641928, text = "I'll purify you!" },
            { id = 4641926, text = "It will consume your corpses for days." },
            { id = 4641934, text = "Nothing but ash remains." },
            { id = 4641933, text = "You'll burn nicely, hahaha" },
            { id = 4641929, text = "Your flesh erupts in flame!" },
        } },
    } },
    { who = "Emberon", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4661651, text = "Activating additional defenses." },
            { id = 4661657, text = "Directive Keep Vault secure." },
            { id = 4661654, text = "Incinerating undesirable elements." },
            { id = 4661662, text = "Objective successful. Area secure." },
            { id = 4661658, text = "Purging protocols activated." },
            { id = 4661659, text = "System shutdown imminent." },
        } },
    } },
    { who = "Emberthal", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4643377, text = "I awakened. The rest of my Drakthir did not." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4643417, text = "As I made my way here, I spotted dragons in the sky. Friend or foe, I cannot say." },
            { id = 4643421, text = "Dervisian, scout the creche of the Ebon Scales. Syndra Thresh and the Evoker will seek the healing wings." },
            { id = 4643422, text = "Fly with caution my friends, dragons are watching." },
            { id = 4643555, text = "His cultists speak of unleashing a storm." },
            { id = 4643379, text = "May their names be ever remembered." },
            { id = 4643420, text = "The truth will reveal itself in time. For now, focus on getting our wingmates to safety." },
            { id = 4643439, text = "Then our people are in even more danger than we thought." },
            { id = 4643566, text = "This is our home." },
            { id = 4643559, text = "Were you sent by the Earth Water?" },
            { id = 4643560, text = "Where is Neltharion?" },
            { id = 4643558, text = "Why should we trust you?" },
        } },
    } },
    { who = "Emeni", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3728608, text = "NOBODY CROSSES ME, ESPECIALLY NOT BIRDS!" },
            { id = 3721463, text = "TIME FOR SOME SLAUGHTER!" },
            { id = 3746780, text = "YOU ARE DISMISSED!" },
            { id = 3746782, text = "YOU ARE SPEAKING TO A PRINCESS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3746775, text = "I trust you are ready, Maw Walker. Break those liches apart!" },
            { id = 3746776, text = "Surely you have other duties to perform." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3746773, text = "Such pitiful barriers are hardly an obstacle for me. We push forward." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3746774, text = "A wasted effort! My constructs will weather any storm they can conjure!" },
            { id = 3746778, text = "Be swift and nimble, like me." },
            { id = 3746781, text = "Do you know how many rivals I have slain?" },
            { id = 3746779, text = "When in doubt... SLAUGHTER EVERYONE!" },
            { id = 3746777, text = "Yell if you need me to save you!" },
        } },
    } },
    { who = "Emeriss", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1349969, text = "TASTE THE NIGHTMARE'S CORRUPTION!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1500200, text = "AH!" },
            { id = 1500203, text = "AHHH!" },
            { id = 1500198, text = "HA!" },
            { id = 1500204, text = "YEAH!" },
            { id = 1500202, text = "YES!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1349974, text = "Hope is a disease of the soul. This land shall wither and die!" },
        } },
    } },
    { who = "Emmarel Shadewarden", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1382726, text = "Please walk with me, Hunter." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1382728, text = "As we arrived here to build the Trueshot Lodge, the eagle spirit, Onara, appeared and gave her blessing. From that day forth, we called this mountain Talon Peak." },
            { id = 1382724, text = "up in the sky. Behold! Oh, Nara! The spirit of the eagle has returned." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1382721, text = "We are the eagle on the wind." },
            { id = 1382720, text = "We are the Watchers in the wild." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1382723, text = "For ours is the Unseen Path." },
            { id = 1382729, text = "Over the centuries, most of my fellow Watchers have been lost. The few of us remaining sought out heroes worthy to heed the call when the Unseen Path was needed once again." },
            { id = 1388699, text = "Thank you for your service." },
            { id = 1382725, text = "The Unseen Path is reborn." },
            { id = 1382727, text = "The Unseen Path was founded after the War of the Ancients to safeguard the people of Azeroth. From these broken isles, we watched for the Legion's return." },
            { id = 1382722, text = "We walk the lonely road." },
        } },
    } },
    { who = "Emperor Dagran Thaurissan", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 6023145, text = "BEHOLD THE MIGHT OF MY EMPIRE!" },
            { id = 6023139, text = "I AM THE EMPEROR!" },
            { id = 6023137, text = "YOU ARE NOTHING!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 6023144, text = "Your insolence will be punished!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 6023142, text = "I will not be denied!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 6023133, text = "Thank you for removing those foolish senators." },
            { id = 6023136, text = "Your efforts are utterly pointless fools. You'll never be able to defeat me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6023143, text = "FLEA before me!" },
            { id = 6023135, text = "Prepare to meet your doom, upper hands of Ragnaros's most powerful servant." },
            { id = 6023140, text = "The fire below burns to my will!" },
            { id = 6023141, text = "The ground betrays you!" },
        } },
    } },
    { who = "Emperor Korthek", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2006318, text = "You do your parts, General, and I will do mine." },
            { id = 2006319, text = "You will die in these dunes!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2006321, text = "I am the true power of the Sethrak!" },
            { id = 2006325, text = "I did not force anyone to follow me, Vorek. Our people are conquerors." },
            { id = 2006322, text = "I wonder, Vorik, if you're here, who's guarding the keys in your temple?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2006324, text = "He will raise Mithrax, and we will conquer all of Azeroth!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2006323, text = "Insured my victory, no matter what happens here. General Jacquerset already has my key, and by now, I suppose he has yours as well." },
            { id = 2006320, text = "You face the might of Korthak, the Eternal Emperor!" },
