    { who = "Erik the Swift", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4661550, text = "NO ONE STEALS FROM US! TIME TO TEACH THESE LUNKHEADS A LESSON!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
