    { who = "Erunak Stonespeaker", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1370764, text = "Come with me. The depths await." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1370776, text = "You underestimate the shaman I have brought." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 1370766, text = "The Naga are tormenting that sea giant. How should we proceed?" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1370347, text = "We can fight this, but we must work together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370346, text = "Do you see? It's working. This world will fight for itself if we give it the tools to do so." },
            { id = 1370765, text = "During the Cataclysm, I spent many terrible weeks as a prisoner in the Abyssal Maw. I have no desire to return there, but I know the place well." },
            { id = 1370768, text = "Fear not, my enormous friend. The Earthen Ring is here." },
            { id = 1370777, text = "If the Scepter is here, this may be our only chance to capture it and turn its power against the Legion." },
            { id = 1370345, text = "It just needs a little boost. Shaman, can you help?" },
            { id = 1370771, text = "Shaman, speak with him. Perhaps we can gain a new ally down here." },
            { id = 1370762, text = "Sharastal, the Scepter of Tides is steeped in legend. Through its power, Azshara enabled her followers to live in the sea." },
            { id = 1370769, text = "We mean you no harm, giant." },
        } },
    } },
    { who = "Esara Verrinde", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1408667, text = "Wonderful. I'm ready to fight whenever you are." },
            { id = 1502881, text = "You are a shining example of the strength of the new Tirisgarde. To our newest Archmage!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1408675, text = "I could use my sword, but I'd hate to dull it on the likes of you!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1408677, text = "Greetings. What's new?" },
            { id = 1408676, text = "Hello, have you found anything interesting lately?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1408619, text = "Always. But why the warning?" },
            { id = 1411910, text = "Enough talk. Time for action." },
            { id = 1408674, text = "I'm just as good with a sword as I am with spells. Any preference?" },
            { id = 1502884, text = "Keep your eyes open, friend." },
