    { who = "Essence of Eonar", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1689805, text = "Release them, champions, or your struggle will be for naught." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1689830, text = "For countless ages my spirit has lingered here, safe from the dark titan's grasp. But he has found me at last, and comes to claim my power." },
            { id = 1689825, text = "My resistance wanes. Should Sargeras prevail, all life will fall to darkness." },
            { id = 1689826, text = "The last of my strength ebbs away. I will not be able to stop them." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1689803, text = "Champions, hear me. The Legion has breached my Sanctuary, and my defenses will soon be overrun. Stand with me now, lest Sargeras claim his prize." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1689829, text = "Welcome, Bortos, to my sanctuary." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 1689824, text = "Defeat them before they reach me, or all is lost." },
            { id = 1689804, text = "The tormented cries of the Pantheon ring out from deep within the core of Argus." },
