    { who = "Evelyn Pare", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1861812, text = "I don't know what they're up to, but the magic coming out of that place seems to sap your very life away." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1861804, text = "Let's hope you brought an army in that pack of yours." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1861801, text = "Welcome to Fletcher's Hollow, Mainlander. Sorry for the mess, but we've got a bit of a witch problem on our hands." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1861811, text = "A word of warning, Mainlander. Avoid the mine at all costs." },
            { id = 1861805, text = "Alright boys, let's secure this road so we can get these bystanders out of harm's way." },
            { id = 1861807, text = "Looks like they're on to us. Protect the civilians!" },
            { id = 1861809, text = "Looks like they're sending in the big guns. Brace yourselves, boys!" },
            { id = 1861806, text = "Mainlander, take a position with them and hold off any attacks from the town." },
            { id = 1861808, text = "More attackers from the town! Hold your position!" },
            { id = 1861810, text = "That's the last of the villagers. With any luck, they'll make it to Fallhaven unscathed." },
            { id = 1861802, text = "Unless you plan on helping out, I suggest you move along." },
            { id = 1861803, text = "You hear that, boys? The Mainlander's gonna help us take our town back." },
        } },
    } },
