        { name = "Threats", family = "Menace", lines = {
            { id = 548390, text = "You will pay with your life!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 5556831, text = "He fought the darkness there, but it followed him in death. Light his tomb, so that he may see once more." },
            { id = 5556837, text = "May Callios no longer fear the darkness, and the Light ease his pain." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 5556840, text = "Ah, Restelon. Larohir's mentor. His is a bloody story of betrayal. Let us commune with him now." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5556819, text = "He defended Shattrath until his dying breath. Spirits seek his protection still. Alas, we must return them to rest." },
            { id = 5556805, text = "Meet me in the upper reaches. We will commune with the spirits there to prepare them for the journey." },
            { id = 5556816, text = "This is the tomb of Exarch Larohir, the Prophet's general. We will commune with him first." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 548386, text = "Serve your penitence!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5556834, text = "Callios has agreed to the Tishamhat. Seal his urn." },
            { id = 5556822, text = "He gives his consent. Seal the urn with the Mark of Dore." },
            { id = 5556843, text = "He unwittingly gave the orcs the weapon that destroyed him, and Telmor. We must dispel the shades of his guilt." },
            { id = 5556828, text = "Let us commune now with Exarch Kelios, the first Vindicator and Bastion of Keribor." },
            { id = 548394, text = "Let your mind be clouded!" },
            { id = 5556825, text = "May the Tish'amath relieve Laarohir of the guilt he feels at not saving all of Shattrath." },
            { id = 548393, text = "Now, you'll stay for eternity!" },
            { id = 5556799, text = "Thank you, Nimeran. I take it you can see me now, champion?" },
            { id = 548392, text = "There's no turning back now!" },
            { id = 548389, text = "These walls will be your doom!" },
        } },
    } },
    { who = "Executioner Gore", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
