    { who = "Faerin Lothar", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5724786, text = "If you are lost in darkness, we are here to help." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5724764, text = "Don't give in to fear." },
            { id = 5713237, text = "Wait, if your grandfather was king of this Stormwind, then" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5724748, text = "A beacon in the dark." },
            { id = 5713238, text = "Anduin, my new friend, are you a king?" },
            { id = 5724534, text = "Be strong, my friend." },
            { id = 5724732, text = "Despite everything, the Arathi find joy." },
            { id = 5724572, text = "In my heart, there is fire." },
            { id = 5713235, text = "Oh no, don't you start using formalities on me. My family is noble, but it's been long since we've seen Great Fortune." },
            { id = 5713236, text = "To think I had relatives in the old world. Wonderful! I hope I can live up to such legends." },
            { id = 5724553, text = "We carry the flame into the unknown." },
            { id = 5713231, text = "You know the name?" },
        } },
    } },
    { who = "Faerlina", tier = "character", groups = {
