    { who = "Fahrad", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 573969, text = "Don't trust this one, Your Highness. No one is that good." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 573963, text = "Ha! A lucky blow against an unprepared opponent." },
            { id = 573979, text = "If he succeeds in looting the whole of Gilneas, there is no telling where he'll hide next. Now is the time to strike." },
            { id = 573967, text = "Indeed, my prince, hidden in plain sight." },
            { id = 573973, text = "Shall we execute him, my prince?" },
            { id = 573965, text = "She allowed herself to be defeated. The others will not be so weak." },
            { id = 573983, text = "She surrounded herself with a small army of deranged dragon cultists. They may not be right in the head, but they're well-armed and dangerous." },
            { id = 573985, text = "This one? Mingle with the Archmages of Dalaran. Ha! I'd pay to see that." },
            { id = 573981, text = "We've just located her here, in the caverns beneath Karazhan. Fearful for her life, she is researching arcane secrets buried beneath the Foundation." },
            { id = 573977, text = "Your first target is here, in the ruins of Gilneas. I've lost some of my best men already. Let's see if you can fare any better." },
            { id = 573971, text = "Your Highness, we caught this beast snooping around the caves just outside the compound." },
        } },
    } },
    { who = "Falara Nightsong", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1332672, text = "I have sacrificed everything. What have you given?" },
            { id = 1332673, text = "My life is dedicated to destroying the Burning Legion." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1332667, text = "Don't give in to the power of the Legion." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 1332674, text = "We are all that stands between the Legion and Annihilation." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1332671, text = "Azeroth must not fall" },
            { id = 1332669, text = "Death to the Legion!" },
            { id = 1332675, text = "Did you just touch me?" },
            { id = 1332666, text = "If we don't meet again, die well." },
            { id = 1332670, text = "Lord Illidan knows the way." },
            { id = 1332665, text = "Remember, nothing is more important than the Legion's destruction." },
            { id = 1332668, text = "Trust in Lord Illidan's plan." },
