        { name = "Conversation", family = "Feelings", lines = {
            { id = 2403579, text = "Everyone's safe and sound. I knew ye were the one for the job! Haha!" },
            { id = 2403580, text = "Ha! That'll teach them. We won't have any of their ugly ships clogging up our skies. No way!" },
            { id = 1402097, text = "More on the horizon! Spread out before they reach the gates!" },
            { id = 2403576, text = "The Horde's kidnappin' our people! Get up to that airship, and bring them back home!" },
            { id = 1402099, text = "Their numbers keep growing! We'll watch the skies overhead! Clear them out down below!" },
            { id = 2403577, text = "Those Horde invaders think they can bring an airship into our skies? That's an insult to all Gryphon Riders! Show them who owns the air!" },
            { id = 2403578, text = "Well, well. It seems the Horde needs to be reminded who controls the skies. That's us. We do. Take them down!" },
            { id = 2403581, text = "WILD HAMMER! Oh, and for the Alliance!" },
            { id = 2413832, text = "Woo-hoo! Look at that mess! The Horde won't be bombing Drustvar anymore, that's for sure!" },
        } },
    } },
    { who = "Fandral Staghelm", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 548636, text = "BEHOLD! THE RAGE OF THE FIRELANDS!" },
            { id = 548666, text = "BLAZE OF GLORY!" },
            { id = 548640, text = "LEAVE NONE ALIVE, SAVE MALFURION! HE IS MINE!" },
            { id = 548626, text = "NOTHING BUT ASH!" },
            { id = 548667, text = "THE MASTER'S POWER TICKS ON MANY FORMS!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 548614, text = "ACHOO!" },
            { id = 548616, text = "GRRR!" },
            { id = 548619, text = "NNN!" },
            { id = 548620, text = "NOOO!" },
            { id = 548647, text = "RRR!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 548621, text = "You may be this world's greatest shaman thrall, but you are only mortal. This is my master's curse upon you, turning your great bond with the elements into your undoing!" },
            { id = 548630, text = "You will learn in due time, my daughter. Come with me. Together we will bring vengeance to those who have wronged us." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 548623, text = "I have come for you, Malfurion." },
            { id = 548642, text = "I was rescued by some new allies. I'm sorry I was not here sooner." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 548634, text = "GAAAWWW!" },
            { id = 548615, text = "OOF!" },
            { id = 548625, text = "RAAARGH!" },
            { id = 548649, text = "ROAR!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 548638, text = "Not so fast, son of Durotan. You and your allies have certainly set us back, but the hour of Twilight cannot be averted!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 548628, text = "Burn everything! Leave no survivors!" },
            { id = 548627, text = "Death? Hahahaha! Who said anything about death?" },
            { id = 548656, text = "Ha Ha Ha ha" },
            { id = 548641, text = "Ha Ha Ha ha! So much power!" },
            { id = 548629, text = "I'm sorry. Are we interrupting?" },
            { id = 548624, text = "one who shares your pain, one who offers you the power to assuage it." },
            { id = 548652, text = "Soon all of Azeroth will burn!" },
            { id = 548631, text = "There is one true path. The Path of Flame!" },
            { id = 548651, text = "Very well! Witness the raw power of my new lord!" },
            { id = 548643, text = "Your anger is not misguided." },
        } },
    } },
    { who = "Farseer Drekthar", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4954153, text = "Hah, you are worthy indeed, but these old bones won't make it to Kalimdor. Another will have to preside over the Kosharg." },
            { id = 4954105, text = "No need to worry, young Duroc. When you complete your Omrigor, your path will reveal itself." },
            { id = 4954126, text = "You are right. It has been long. Too long. Many orcs no longer feel they belong to a clan." },
            { id = 4954165, text = "Your strength speaks for itself. You are more than ready. Far, seer." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4954120, text = "Face the might of the Frostwolves and the strength of the elements!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4954168, text = "A title long overdue." },
            { id = 4954147, text = "An honor, but one I wish to see you prove yourself worthy of." },
            { id = 4954099, text = "But I am not yet finished." },
            { id = 4954096, text = "Doros, Drakon, you did well." },
            { id = 4954355, text = "Elements, hear my call." },
            { id = 4954159, text = "Not you, Agralan." },
            { id = 4954102, text = "Show me your true strength, champion!" },
        } },
    } },
    { who = "Farseer Nobundo", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1370857, text = "You are the chosen defender of Azeroth. May your wisdom guide this circle to victory. And may the power of the weapon you wield crush those who would bring chaos to this land." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1370856, text = "Take your place among the Circle, Farseer. The Earthen Ring is forged anew, and with it, we rekindle hope for this world." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1370858, text = "Step this way, Farseer. The Tauren tell of hidden chambers below that may serve as a base of operations." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370335, text = "It is ready! Everyone focus on the pillar, quickly!" },
            { id = 1373757, text = "The elements will never forsake us." },
            { id = 1370349, text = "There are ancient safeguards here. We must use them." },
            { id = 1370854, text = "This Astro portal will return you to Dalaran whenever you wish, Farseer. I will keep it open, so that you may return here anytime." },
            { id = 1373756, text = "We must never forget." },
            { id = 1370348, text = "We need weapons capable of overcoming the Legion." },
            { id = 1370855, text = "We stand at the precipice of oblivion, but we do not stand alone. Come forward, shaman." },
            { id = 1373758, text = "With faith there is a way." },
        } },
    } },
    { who = "Farseer Ori", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2993402, text = "We understand. You are not to blame for your actions." },
            { id = 2993401, text = "You will recover in time, Adaro." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2993404, text = "I have foreseen our victory." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2993403, text = "All will be explained in time." },
            { id = 2993398, text = "An unconventional approach. Let us hope for its success." },
            { id = 2993409, text = "Face the water's wrath!" },
            { id = 2993399, text = "Here, I can sense that this is where we need to be." },
            { id = 2993406, text = "Neptune lawn grants us strength" },
            { id = 2993400, text = "Such strange power held within that weapon." },
            { id = 2993405, text = "The elements stand with us." },
            { id = 2993407, text = "The tide comes for you." },
            { id = 2993408, text = "Your demise draws near." },
        } },
    } },
    { who = "Faruu", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4330949, text = "Ah, I believe you have found parts of a translocator key. At least that is what we have called them." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4330951, text = "A fascinating artifact, but I doubt it can function with the forge in its current state." },
            { id = 4330950, text = "From what we surmise, they channel the energy that flows from the creation catalyst to the forge." },
        } },
    } },
    { who = "Fatescribe Roh Kalo", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4074254, text = "STARE INTO THE INFINITE!" },
            { id = 4074251, text = "THE WRONG SCREAM FOR ABLEVION" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4074247, text = "I need a scroll from the vault, and the alibi to fuel its magic." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4074244, text = "Arvada, forgive me, but I have need of this animal." },
            { id = 4074243, text = "He has found us. Korthir is in grave heaven." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4074253, text = "Ah... Save it... At last..." },
            { id = 4074246, text = "An illusion? Yes, that might work. Hide in plain sight. Employ your own tactics against them." },
            { id = 4074245, text = "Eternal ones, grant me your guidance and wisdom." },
            { id = 4074250, text = "God's fall at the time of a king!" },
            { id = 4074248, text = "May the papas shield me, and may they never find me." },
            { id = 4074249, text = "The Loom weaves your destruction!" },
            { id = 4074252, text = "They are covered! The door opens!" },
        } },
    } },
