        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2529607, text = "Nailed in the shadow of his glory." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2529609, text = "Cower before his might!" },
            { id = 2529614, text = "Let their flesh become an offering of atonement." },
            { id = 2529603, text = "Quake in fear of his endless strength." },
            { id = 2529612, text = "They are insolent, unworthy of his guilt." },
