    { who = "Fel Commander Azgalor", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1248771, text = "KEEP THEM AWAY FROM THE SPIRES!" },
            { id = 1248792, text = "YOU WILL ALL BURN!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1248802, text = "The master will mend my flesh again and again! You have not won! You cannot win! We are endless! We are legion!" },
