    { who = "Fel Lord", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1594870, text = "FOR CRUEL! FOR THE BURNING LEGION!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1594879, text = "Fragile mortals, bow before the might of the Burning Legion!" },
            { id = 1594877, text = "Hahahaha, bow before the might of the Burning Legion! Your efforts are meaningless, mortals." },
            { id = 1594875, text = "You cannot defy the will of the Legion, Art Mage! All will perish!" },
            { id = 1594878, text = "You meddle with powers you do not understand, mortal! Your unwillingness to bow will be your end!" },
            { id = 1594872, text = "Your armies will all fall before my Lord Drax!" },
            { id = 1594880, text = "Your world crumbles around you mortals. We cannot be stopped!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1594876, text = "FOOLS! Gaze into the skies BEYOND as the end of your world approaches!" },
