        { name = "Conversation", family = "Feelings", lines = {
            { id = 1594871, text = "The Endless Flame comes for you! It cannot be stopped!" },
            { id = 1594873, text = "You test my patience! Die, cretin!" },
            { id = 1594874, text = "You walk into your own death." },
        } },
