        { name = "Conversation", family = "Feelings", lines = {
            { id = 2981823, text = "Azara has minions across all of Nazdatar." },
            { id = 2981826, text = "But the Zanjir are the ones who should worry you the most." },
            { id = 2981820, text = "Do I know you?" },
            { id = 2981822, text = "I'm glad you found us. I didn't have a chance to thank you for saving our hides back there." },
            { id = 2981819, text = "Oh! Hey there!" },
            { id = 2981825, text = "Some of the Naga have learned to harness the Void. They call themselves the Shurikas." },
            { id = 2981818, text = "Speak softly, please." },
            { id = 2981824, text = "The Azari summoners can force the tides to do their evil bidding." },
            { id = 2981816, text = "The ocean is our home too!" },
