    { who = "Fenris", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 996459, text = "COREHOLE! JOGTAR! DROKECAR! MOVE IN FROM ALL SIDES! GARGRACK HOLT FOR NOW!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 996461, text = "Yatta! No! You will be avenged!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 996463, text = "Bring me that one's head!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 996453, text = "Ah, stinking animals! All of you, sleeping with your dogs!" },
            { id = 996441, text = "Ah, the brothers, Frostwolf. I knew we would reunite on the battlefield someday." },
            { id = 996457, text = "Animals, your clan is finished. The Iron Horde already comes." },
            { id = 996451, text = "Reinforcements, slay the Frostwolf Pops!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 996443, text = "Or don't you recognize your eldest brother?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 996449, text = "A small chieftain of an insignificant clan. I saw what father didn't, that we could be so much more!" },
            { id = 996445, text = "Chilton, devour them!" },
            { id = 996455, text = "Orcs are meant to be masters of beasts, masters of all!" },
            { id = 996447, text = "The Iron Horde is all the family I need." },
        } },
    } },
    { who = "Feroz", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
