    { who = "Field Commander Ignax", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5062174, text = "GIVE THEM NO QUARTER! VICTORY TO THE BLACK DRAGON FLIGHT!" },
            { id = 5062186, text = "THE BALASTEER DESTROYED!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5077456, text = "A disgusting remnant of our past. Thank you... ...for helping put them to rest." },
            { id = 5062195, text = "A group of Jaradin have broken off to attack the nests." },
            { id = 5077459, text = "A primalist is rousing the elements in the caldera. It would be a shame if someone turned their own power against them, wouldn't it?" },
            { id = 5077468, text = "A swarm of moths is drawing near the central beacon, blocking the light we use to navigate. Mount up, and knock them from the skies!" },
            { id = 5062164, text = "Attention soldiers! We must press the Jaradin forces! Do not let them seize the battlefield!" },
            { id = 5062192, text = "Commander, our scouts have found Dragonnest to the east." },
            { id = 5077471, text = "Excellent work, soldier. I can see your results from here." },
            { id = 5062183, text = "Glory to the Black Dragonflight!" },
            { id = 5062142, text = "Put your weapons down! This one's friendly." },
            { id = 5062189, text = "Soldiers! Send for the Dragonlords! Our victory is near!" },
        } },
    } },
    { who = "Fightlord San", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4484764, text = "I never said you would fight me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4484763, text = "Haha! There will be blood!" },
            { id = 4484767, text = "Meet me down below, and I'll empower your Ransor." },
            { id = 4484766, text = "Well thought! I admit I did not expect such a battle from you!" },
        } },
    } },
    { who = "Finna Bjornsdottir", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1411079, text = "DESTROY OUR ENEMIES!" },
            { id = 1411084, text = "PUT YOUR BACK INTO IT!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1411083, text = "You are fierce for one so small, dwarf. What happened here?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1411082, text = "Feel my wrath!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1411080, text = "Crush these invaders!" },
            { id = 1411078, text = "The temple is completely overrun! Let us crush these demons!" },
            { id = 1411758, text = "Therefore, Locke, strike from above!" },
            { id = 1411760, text = "This is no ordinary mortal! Our leader was chosen by Odin himself!" },
            { id = 1411076, text = "We need to keep moving!" },
            { id = 1411077, text = "Who is that fighting so fiercely ahead?" },
        } },
    } },
    { who = "Finna Torbjornsdottir", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1370169, text = "I say we kill the demon instead. Little hero, you have proven yourself a worthy ally. Will you stand with us? Even though it could mean our deaths." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1370163, text = "I almost broke a sweat, but not quite. What else do they have?" },
            { id = 1370174, text = "I can still fight." },
            { id = 1370171, text = "I will salute your courage in the halls of Valor or over this monster's corpse." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370159, text = "A Valkyr approaches. We must greet her with respect. Come, heroes." },
            { id = 1370155, text = "Harvey didn't say they would be so short." },
            { id = 1370158, text = "May the Valkyr claim you, Hargrim." },
            { id = 1370167, text = "Well, will you look at that?" },
        } },
    } },
    { who = "Firelord Smolderon", tier = "character", groups = {
        { name = "Victory", family = "Fighting", lines = {
            { id = 1416851, text = "The Burning Legion will fall! The demons are no match for the fury of the elements!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407190, text = "As a symbol of my allegiance, I shall send my servant Scaldius to aid the Earthen Ring." },
            { id = 1407191, text = "The Burning Legion shall tremble before the terror of the Fire Lord!" },
            { id = 1407189, text = "Well done, Farseer. Emberscar is mine, and those who oppose my rule lay silenced." },
        } },
    } },
    { who = "Firim", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4285650, text = "I will clean their secrets!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4285640, text = "Leave me to my thoughts." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4285648, text = "Do you see the patterns, the fractals?" },
            { id = 4285643, text = "The glories of the first ones will be revealed." },
            { id = 4285646, text = "The mysteries of this land await!" },
            { id = 4285651, text = "The wonders of Zarath-Mortis are endless!" },
            { id = 4285644, text = "There is always more to learn." },
            { id = 4285649, text = "What do you seek?" },
            { id = 4285645, text = "Will I ever truly know everything?" },
            { id = 4285642, text = "Xerath Mortis holds much to discover." },
            { id = 4285641, text = "You can never research too much." },
            { id = 4285647, text = "You're interrupting my research!" },
        } },
    } },
    { who = "First Arcanist Thalyssra", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1407663, text = "I scavenged a few more mana crystals while you were out. Set him down over here." },
            { id = 1407660, text = "I shall do my best to keep Theron off the line." },
            { id = 1405184, text = "My robes. I've missed these. I hope they still fit." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407658, text = "Arcane Communion forms a bomb that transcends physical space." },
            { id = 1407657, text = "Can you hear me? Do not be alarmed." },
            { id = 1407662, text = "He is withering." },
            { id = 1405186, text = "It would be best if they did not know who I was conversing with before." },
            { id = 1405185, text = "Just in case the library does not survive Elisande's insanity, I will keep an eye on these tomes." },
            { id = 1407643, text = "That is precisely what I am doing." },
            { id = 1405183, text = "They are rifling through my drawers, thieving rats! Please, recover my belongings." },
            { id = 1405187, text = "You've done it. Guard it well until you can return to me." },
        } },
    } },
    { who = "First Mate Degauza", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1392308, text = "ALL WILL KNOW THE BLADES OF DREDD ADMIRAL INLIGHT BLYRE!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1503538, text = "HA!" },
            { id = 1503540, text = "HUH!" },
            { id = 1503541, text = "YEAH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1392291, text = "Swab the dicks till they shine, you dirty bags of bones! The dread admiral demands perfection!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1392288, text = "How did you get past me crew? Useless! The lot of ya!" },
            { id = 1392290, text = "Is that the best you can do? Meet that swabbers fight better!" },
            { id = 1392307, text = "It took half our crew to subdue this creature. Let's see what it does to you." },
            { id = 1392287, text = "Now that's an offer I can't refuse! Fall back to the temple! They can have this pile of driftwood!" },
            { id = 1392289, text = "The rest of the dread fleet is on its way! What's your plan, then?" },
            { id = 1392306, text = "With pleasure, Admiral." },
        } },
    } },
    { who = "First Mate Wavesinger", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1248021, text = "It appears to be a great source of fel energy. I have never seen anything like it." },
            { id = 1248009, text = "King Wren and the Stormwind Fleet arrived several hours ago. Reports indicate heavy fighting." },
            { id = 1248017, text = "There is a foulness in the air, and we are headed directly towards it." },
        } },
    } },
    { who = "Fizzi Tinkerbow", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 2913590, text = "Good to see you, Commander!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2913583, text = "I've got a gadget for every occasion!" },
            { id = 2913582, text = "I've really been looking forward to this. I can't wait to get started!" },
            { id = 2913585, text = "Looking forward to the next test flight!" },
            { id = 2913591, text = "Testing one, two, three. Can you hear me, Commander?" },
            { id = 2913586, text = "There's always room to tinker!" },
            { id = 2913584, text = "Time to get to work!" },
            { id = 2913588, text = "What's our current trajectory?" },
        } },
    } },
    { who = "Flamebender Kagraz", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 998157, text = "ANOTHER FALLS TO MY BLADE!" },
            { id = 998147, text = "LET FLAME KISS YOUR TENDER FLESH" },
            { id = 998141, text = "THAT'S ENOUGH! YOU WILL BURN! YOU WILL ALL BURN!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 998139, text = "Eknor! You are an embarrassment to your clan!" },
            { id = 998155, text = "Ha Ha Ha your bodies will make good kindling" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 998137, text = "My work. You've interrupted my work!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 998145, text = "Glory to the Black Rock!" },
            { id = 998153, text = "Quickly, Aknor! Bring me another! Blackhand will not tolerate any delays." },
            { id = 998159, text = "Too hot for you?" },
        } },
    } },
    { who = "Flameweaver Koegler", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 633731, text = "DIE IN A FIRE!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 633695, text = "AHHH!" },
            { id = 633699, text = "GRRR!" },
            { id = 633709, text = "MMM!" },
            { id = 633705, text = "UGH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 633737, text = "AAARGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 633735, text = "Purge my fire!" },
            { id = 633733, text = "Wrath of the Dragon!" },
            { id = 633693, text = "You, too, shall be turned to ash!" },
