    { who = "Fleet Admiral Tethys", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1388247, text = "Let's have a chat!" },
            { id = 1388242, text = "Stop by anytime!" },
            { id = 1388244, text = "Take it easy." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1392174, text = "Ah, there's our final member! Welcome to the crew!" },
            { id = 1388245, text = "Good to see ya!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1388243, text = "Be seeing ya!" },
            { id = 1392170, text = "Give me your ear, friend. I got a plan that's guaranteed to put worthy blades in them hands." },
            { id = 1388246, text = "I'm all ears." },
            { id = 1388241, text = "Keep your sights on the horizon." },
            { id = 1392186, text = "Something's off about this here, bro." },
            { id = 1392173, text = "That'd be a fine choice. Come here, I'll share the finer details of my plan over a mug or two." },
        } },
    } },
    { who = "Fleet Master Seahorn", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 6179585, text = "Ready for action!" },
            { id = 6179574, text = "Steady as she goes." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 6180680, text = "Dark use will pay! I'll serve your eviction notice personally, Captain!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6179597, text = "As you were." },
            { id = 6180548, text = "Gah, those scurvy, dark-fused dogs! I'd kill them myself if they weren't already dead!" },
            { id = 6180547, text = "I'm up here! Get me loose from these chains!" },
            { id = 6180715, text = "Ugh! Oh, what kind of bro is that?" },
            { id = 6179595, text = "Who's on deck?" },
            { id = 6179607, text = "You ever seen someone keelhauled on dry land?" },
        } },
    } },
    { who = "Flintlocke", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 549190, text = "Go on then. I'll be right here." },
            { id = 549193, text = "Stop that! Stop that you! Tug it out!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 549194, text = "Are you out of your mind?" },
            { id = 549196, text = "Keep your powder dry and your ale cold!" },
            { id = 549192, text = "Less talk, more shootin'!" },
            { id = 549195, text = "Okay, get!" },
            { id = 549188, text = "What now then?" },
        } },
    } },
    { who = "Flip Quickcharge", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3192233, text = "You have my ear!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 3192230, text = "Until next time!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3192365, text = "Defibrillate at will!" },
            { id = 3192364, text = "Done. Go ahead and flip the switch." },
            { id = 3192363, text = "Excellent! I just need a moment to calibrate the circuit." },
            { id = 3192229, text = "Have a good one!" },
            { id = 3192366, text = "Uhh, did it work?" },
            { id = 3192232, text = "Well, hello there!" },
            { id = 3192231, text = "What can I do for you?" },
        } },
