    { who = "Flynn Fairwind", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1995973, text = "I see a ship with gold… everything. Yep, definitely Zandalari. The Horde's here, so keep an eye out." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1995978, text = "Hey, uh, so it looks like we've got a Lord of the Elements here looking for the same Azerite we are. I'm just gonna hang out below deck while you deal with this... situation." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1983799, text = "Ahem, avarced ye bloated barnacle, we've come for your booty!" },
            { id = 1995975, text = "Horde must have found this place too. The ship just docked." },
            { id = 1995970, text = "Hull's half full of Azerite. Keep it up. You're doing great." },
            { id = 1983802, text = "It's, uh, kind of a long story. How about a drink?" },
            { id = 1995977, text = "Looks like the Azerites caught the eye of some elemental forces. There's probably a lord after our stash. But finders keepers, am I right?" },
            { id = 1995974, text = "Uh, looks like we've got Horde. Watch your backs out there, okay?" },
            { id = 1995971, text = "We're at the halfway mark! Keep that momentum going and we'll be out of here in no time!" },
            { id = 1995969, text = "We're halfway there, team. Now, uh, don't let me down." },
            { id = 1995972, text = "We've got some, uh, horde ships arriving. You might want to speed things up a bit." },
            { id = 1995976, text = "Whoa! This is not normal weather for this climate. All this Azerite must have gotten the attention of an elemental lord. Be careful. Or kill them. Or both!" },
        } },
    } },
    { who = "Foereaper", tier = "character", groups = {
