        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3160385, text = "Throw down your tools and raise up your fists!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3160394, text = "Alright! I give! You win!" },
            { id = 3160387, text = "Are you finally ready to hear our demands?" },
            { id = 3177076, text = "Have something to say?" },
            { id = 3177074, text = "Walk away while you can!" },
            { id = 3177075, text = "What do you want?" },
            { id = 3160386, text = "What's this? Someone from Orgrimmar?" },
            { id = 3160388, text = "When I'm Warchief, Peons will be respected members of the Horde!" },
            { id = 3160393, text = "You challenge the future warchief of the Horde, I'll cut you down to size!" },
            { id = 3160391, text = "You hear that? The Horde's finally listening to us!" },
