        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3588199, text = "Come, I have need of your hands." },
            { id = 3588200, text = "Hold the armor steady now." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3587823, text = "We live in service, not only to our own, but to the many souls of the universe who seek our aid." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3588190, text = "Did you make a list, Seeker?" },
            { id = 3588185, text = "Fascinating to have seen so much in so little time." },
            { id = 3588192, text = "Good. I found you some help." },
            { id = 3588196, text = "If you could tidy up a bit, I will have this forge lit in short order." },
            { id = 3588198, text = "Sika will show you how to operate the forge." },
            { id = 3588182, text = "So the rumors were true. Come, let me look at you." },
            { id = 3588194, text = "Stewards exist exclusively to be of aid to us. They become rather depressed when they cannot perform their duties." },
            { id = 3588197, text = "There we are." },
        } },
    } },
    { who = "Forgemaster Bazentus", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4667715, text = "May your weapons strike true!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4669375, text = "A leader is like a finely forged sword. They must be balanced, strong, and of pure metal." },
            { id = 4667713, text = "Keep your fires stoked and the forge hot!" },
            { id = 4667716, text = "May your armor hold fast!" },
            { id = 4667717, text = "That's quite a weapon." },
            { id = 4669374, text = "The Forge of the Earthwater is close. It is possible." },
            { id = 4667721, text = "This is not the way to forge new friendships!" },
            { id = 4669376, text = "Though I like Rathian, he is untempered. Sibelion has been forged in fire. I believe he is what we need in a leader." },
            { id = 4667719, text = "Try not to get underfoot." },
            { id = 4667714, text = "We'll speak more later." },
            { id = 4667720, text = "Well, look what the bellows blew in!" },
            { id = 4667718, text = "What well-crafted armor!" },
