        { name = "Conversation", family = "Feelings", lines = {
            { id = 631062, text = "He'd be dyin' time now!" },
            { id = 631110, text = "Heh heh heh, that had to hurt." },
            { id = 798357, text = "Lei Shen's power makes us stronger!" },
            { id = 798363, text = "Leshane, let us prove to you the might of the Zandalari. We will crush these intruders where they stand!" },
            { id = 798343, text = "Let me share this gift with ya." },
            { id = 798347, text = "The Thunder King will reward us for stopping ya!" },
