            { id = 2738001, text = "Give these Alliance dogs no quarter! Strike them down and bring back their banners as trophies! Lok'tar ogar!" },
            { id = 2739829, text = "Ha! See how the Alliance cowers in fear of you! We march on Ashenvale!" },
            { id = 2737998, text = "It's a fine day for battle. Today, glory will be ours!" },
            { id = 2737999, text = "Readier blades, champions of the Horde! Victory is the only outcome our Warchief will accept!" },
            { id = 2739828, text = "We have the Alliance backed into a corner! Finish the fight!" },
