        { name = "Conversation", family = "Feelings", lines = {
            { id = 1052928, text = "Better kill me quick. You don't have much time." },
            { id = 1052925, text = "Got you! Hahahaha! Hahahaha!" },
            { id = 1052930, text = "Gul'dan takes what he wants, always. I am nothing." },
            { id = 549539, text = "I'm not that good with self-control." },
            { id = 549560, text = "I've killed for less." },
            { id = 1052932, text = "Just kill me and be done with it, Archmage!" },
            { id = 549543, text = "Keep your voice down!" },
            { id = 1052923, text = "Oh, following my trail, you're strong and crafty. I love a good hunt." },
            { id = 1052927, text = "Still on your feet? Oh, you're a tough one." },
            { id = 1052926, text = "The poison is like fire in your veins, isn't it? Don't worry, it will all be over soon." },
            { id = 1052924, text = "The trail ends. Oh, where did she go?" },
            { id = 1052921, text = "You're a brave one, coming after me all alone." },
            { id = 1052929, text = "You're too late! Nothing can save your Archmage now!" },
