    { who = "Garrosh", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 896012, text = "BEHOLD, MY GLORIOUS DESTINY! AH HA HA HA HA! AH HA HA HA HA!" },
            { id = 895996, text = "I WILL DESTROY EVERYTHING YOU HAVE EVER LOVED!" },
