    { who = "General Draven", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3591465, text = "I see only Denathrius' lies!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3591464, text = "Go mortals! I will hold her off!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3501903, text = "As you command, Lord Chamberlain." },
            { id = 3591460, text = "Beware mortals, devourers are swarming through the breach in the castle wall." },
            { id = 3591462, text = "Denathrius has been draining its light to wield against his foes. We will wield it against him instead." },
            { id = 3591463, text = "Not today, Carl!" },
            { id = 3591469, text = "Our target lies deep within the prison. Let none stand in your way." },
            { id = 3591466, text = "Quickly, mortals! Escape with Zorale!" },
            { id = 3591468, text = "The large one must be the alpha. Slay it, and the others will scatter." },
            { id = 3591461, text = "The prisoner is down below. Zarali, one of the Naaru who invaded the Ember Ward. The others presumed it slain." },
            { id = 3501901, text = "This mortal will not become another puppet of the master!" },
            { id = 3591467, text = "What are you doing? We are not leaving without the prisoner!" },
        } },
    } },
    { who = "General Erodus", tier = "character", groups = {
