    { who = "Generic Arathi", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 6159053, text = "I didn't hear a call to battle, I heard a hymn of healing." },
            { id = 6159065, text = "I don't want to go to war again. I want to go home. We're closer to our homelands than ever before." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 6159059, text = "You need to trust the earthen and the goblins, they are not our enemies. We need to work together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6159050, text = "Excellent. That's the kind of support we'll need to bolster our troops. We could strengthen our defenses." },
            { id = 6152144, text = "Hmm. My sacred crystals could help harmonize your readings, but you'll need more power." },
            { id = 6152231, text = "That sounds like the kind of inspiration we'd receive from Belladar." },
            { id = 6159062, text = "That's the difference between you and me. You build, I protect. And mark my words, we will need that protection." },
            { id = 6152230, text = "This morning the Siren Crystal sang a reverent hymn to me, a restorative anthem from a bygone age." },
            { id = 6152165, text = "This Singing Crystal is remarkably like Belladar. We should treat it with reverence." },
            { id = 6159056, text = "We're not going to war. It's coming to us. When the others seize that crystal, we'll need more guards." },
            { id = 6152227, text = "What are you making? You seem...inspired." },
            { id = 6152232, text = "Yes. Its music soothed me. Now I'm crafting more healing crystals. They'll bring solace to our empire." },
        } },
    } },
