    { who = "Gonk", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1863693, text = "Continue, and you shall be my next prey." },
            { id = 1994500, text = "Say to the other Loa, I will hunt the gardens for more invaders to slay." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1863692, text = "I am Master of Sheeps, Puckstrider, and Lord of the Hunt." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1863687, text = "Bring strength to your pack." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1994498, text = "Greetings, little hero. Have you come to join me in slaying these heretics?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1863690, text = "Have you come to bargain?" },
            { id = 1863694, text = "If you plan to run, just remember, I can open doors." },
            { id = 1863688, text = "May your enemies never smell you coming." },
            { id = 1994507, text = "Rally to me, Pak. It's time to end this." },
            { id = 1863689, text = "Tell others of me" },
            { id = 1863691, text = "What brings you before the Lord of the Hunt?" },
            { id = 1994499, text = "You heretics! Dare enter my lair! I will bury you here!" },
        } },
    } },
    { who = "Gorak Tul", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2000735, text = "ALL LIFE ENDS" },
            { id = 2000739, text = "DEATH CONSUMES ALL!" },
            { id = 2000734, text = "NO ONE CAN OPPOSE ME!" },
            { id = 2000738, text = "NONE WILL ESCAPE MY VEDRANCE!" },
            { id = 2000736, text = "SUCCUM TO THE DARKNESS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2000730, text = "Interlopers! You meddle in affairs beyond your ken!" },
            { id = 2000732, text = "Perish here amid the rubble, or be torn apart by my vassals. You will not live to see my victory." },
            { id = 2000731, text = "You cannot stop me from reclaiming what is mine!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 2000733, text = "You were nothing!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2000740, text = "Death cannot hold me." },
        } },
    } },
    { who = "Gorak Zhar", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3723642, text = "FOOLS! YOU ARE BUT INSECTS BEFORE GOROK ZAR!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3723645, text = "Ardenweald will be ours! You cannot stop us!" },
            { id = 3723637, text = "Yet we grow strong while those who kneel before you are left to wither" },
            { id = 3723640, text = "You will watch as I claim your throne and crush the heart of the forest in my grasp!" },
            { id = 3723963, text = "Your death will herald our return!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3723639, text = "I do not need the pity of a fading queen!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3723647, text = "Leave their husks to rot!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 3723643, text = "Pathetic little creatures, you struggle in vain." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3723638, text = "One by one, we will claim every grove, every fae, every soul." },
            { id = 3723646, text = "Their anima will feed our victory!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3723641, text = "Roar! Vile queen! The trust will never be vanquished!" },
            { id = 3723644, text = "Thros will engulf this realm!" },
        } },
    } },
    { who = "Gorechop", tier = "character", groups = {
