    { who = "Gorvold the Looter", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1390353, text = "I returned in disgrace and sought to wash away my failure in the blood of others." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1390349, text = "I died to ease the pain of my failure. Why do you disturb me?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1390351, text = "It seems you compelled me to answer. My journey took me to Stormheim, to a tomb of warrior kings." },
