    { who = "Grand Lector Enaara", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1679062, text = "FITA THONUS GOMURA" },
            { id = 1684262, text = "YOU ARE BEYOND REDEMPTION!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1684265, text = "Wretched souls, your defeat shall come swiftly!" },
            { id = 1684256, text = "You will find no salvation, traitors!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1679068, text = "I hear the rumors, you know, that I am bloodthirsty and I conduct myself in a manner unbecoming of the priestess." },
            { id = 1679069, text = "I say, what's wrong with blood? We all need it. Except the traitors. That's why we take theirs." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1679063, text = "Stay safe, and slay many demons!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1684259, text = "By light be purged!" },
            { id = 1679066, text = "Do you require assistance in exterminating our foes?" },
            { id = 1679064, text = "Each demon you slay is one fewer we must face." },
            { id = 1679065, text = "If you can walk, you can fight." },
            { id = 1679067, text = "Killing demons makes you feel good. Killing demons makes you feel alright." },
        } },
    } },
    { who = "Grand Mada Ateena", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1881699, text = "STRUGGLE! FIGHT! YOUR SUFFERING FEEDS ME, MASTER!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1881709, text = "Can't stop what's coming! No hope for Zuldazar! No hope for you! G'hon Wix! G'hon Rises!" },
            { id = 1881707, text = "High reeks serve G'huun! You cannot pay for this insult! After Zuldazar, the Horde be next." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1881703, text = "I give you this one chance to submit to the Blood God. Surrender or be destroyed." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1881705, text = "Rise, minions! Rise and destroy this fool, Loa!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1881706, text = "Ah, the hero, you hear, just like Gaon whispered, I gonna enjoy this!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1881701, text = "Your soul for me master, your soul for G'huun!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1881704, text = "Bold words, but you be meeting the same fate as all who refuse G'huun." },
            { id = 1881702, text = "But on Sunday, at last, you left the safety of that ruin." },
            { id = 1881700, text = "By cahoon, I be reborn!" },
            { id = 1881710, text = "Ha Ha Ha ha! Poor Telangi! We be the children of a powerful Loa! You're never gonna win like this, child!" },
            { id = 1881708, text = "You dare kill our Loa, we're gonna hunt you down, torture, and bleed you dry!" },
        } },
    } },
    { who = "Grand Magister Rommath", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1801068, text = "I am rather busy." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1801059, text = "Do not let outsiders interfere." },
            { id = 1801067, text = "Do not squander resources." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1801060, text = "Be about your work." },
            { id = 1801064, text = "It would be unwise to oppose us." },
            { id = 1801058, text = "Respect our customs." },
            { id = 1801065, text = "The Sunwell must be protected." },
            { id = 1801061, text = "We build our future upon the backbone of tradition." },
            { id = 1801062, text = "We have overcome much." },
            { id = 1801066, text = "What is it?" },
        } },
    } },
    { who = "Grand Marshal Tremblade", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2923749, text = "The Horde appears to have a significant presence in the area. Be on your guard. I doubt they will hesitate to strike." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2923746, text = "Fall back for now, champions. We may have lost this battle, but we must conserve our strength and remain vigilant." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2923744, text = "Ashran is ours excellent work champions" },
            { id = 2923747, text = "Champions, Nazjatar is hostile territory, and it is imperative that we establish control over the region." },
            { id = 2923740, text = "Heroes of the Alliance, our mission is to secure Ashran and the ancient artifacts scattered across it." },
            { id = 2923738, text = "Horde shamans have summoned a deadly elemental. Eliminate it before it can reach Storm Shield." },
            { id = 2923745, text = "One of the Horde's warriors has been viciously attacking our soldiers. Find them and take them down." },
            { id = 2923739, text = "Our druids have awakened an ancient of war. Follow it into battle and crush the Horde." },
            { id = 2923748, text = "Our scouts have marked several key strategic locations. Do whatever it takes to secure them for the Alliance." },
            { id = 2923743, text = "There can be no peace with the Horde." },
            { id = 2923742, text = "We cannot allow the Horde to obtain the power found on this island. For the Alliance." },
            { id = 2923741, text = "While some of you push into enemy territory, the others will search for and retrieve the artifacts before the Horde does." },
        } },
    } },
    { who = "Grand Master Vole", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3481106, text = "IS THAT ALL?! I THOUGHT WE WERE IN FOR A SHOW! WHAT A DISAPPOINTMENT!" },
            { id = 3481110, text = "LET THE BLOODSHAD BEGIN!" },
            { id = 3481113, text = "WELCOME, ONE AND ALL, TO THE THEATRE OF PAIN!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3784856, text = "GAH!" },
            { id = 3784854, text = "HA!" },
            { id = 3784852, text = "HEH!" },
            { id = 3784848, text = "HMMM!" },
            { id = 3784846, text = "MWAH!" },
            { id = 3784844, text = "ROAR!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3543126, text = "It will take more than mere brawn to pass this challenge! Let's see if you have brains as well!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3784908, text = "HEY!" },
            { id = 3784912, text = "RAWR!" },
            { id = 3784902, text = "YEAH!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3481112, text = "It seems these upstarts think they can compete with the best combatants in all of Maldraxxus! Ha! I'll believe it when I see it!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3481108, text = "A short end to a short legend!" },
            { id = 3481111, text = "Either way, this should prove entertaining! Bring in the challengers!" },
            { id = 3481109, text = "Ha! That must have hurt!" },
            { id = 3481105, text = "How unexpected! It seems our little pups have some bite after all!" },
            { id = 3481104, text = "Now that the preliminaries are over, the real trials can begin!" },
            { id = 3543125, text = "Our challengers have passed the first trial, but they're still a long way from the title!" },
            { id = 3481107, text = "So much for our vaulted contender!" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 3784838, text = "MMM!" },
            { id = 3784834, text = "NOOO!" },
        } },
    } },
    { who = "Grand Proctor Beryllia", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3511851, text = "Your kind are so fascinating, with so many secrets to uncover." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3511853, text = "I really must thank you, Zerali. You make for an excellent specimen." },
            { id = 3511845, text = "My patience is wearing thin!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3511852, text = "Ah, so you do feel pain. How intriguing." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3511843, text = "Anima has quite a singular effect on the Naaru." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3511850, text = "Finally! Now, the rally. Where were we?" },
            { id = 3511846, text = "How dare you interrupt my research?" },
            { id = 3511847, text = "So. Much. Left. To discover." },
            { id = 3511849, text = "There is nothing I can learn from you." },
            { id = 3511844, text = "Time for a different approach!" },
            { id = 3511842, text = "Zraly, care to demonstrate what we have learned?" },
        } },
    } },
    { who = "Grand Vizier Jarasum", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1708815, text = "RAWR!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1686427, text = "Your arrogance will be your undoing!" },
