        { name = "Conversation", family = "Feelings", lines = {
            { id = 1686431, text = "Hmm, it is finished then." },
            { id = 1686429, text = "Travelling outsider, your arrogance was your undoing." },
            { id = 1686430, text = "You face Jarasun, Grand Vizier of the Conservatory!" },
