    { who = "Grandmaster Vorpil", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 551085, text = "I serve with pride!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 551083, text = "Good. A worthy sacrifice." },
            { id = 551087, text = "I'll make an offering of your blood!" },
            { id = 551081, text = "You'll be a fine example for the others." },
