    { who = "Granny Marl", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1241735, text = "I see him! Good job with those stun grenades!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1369360, text = "Stay on your toes!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1369362, text = "Goodbye!" },
