    { who = "Gravax the Desecrator", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1241511, text = "BEAR WITNESS FOOLISH ELVES! I WILL CRUSH YOUR CHAMPION!" },
            { id = 1241771, text = "REND THE FLESH FROM THEIR BONES AND DRAIN THE LIFE FROM THEIR MORTAL BODIES!" },
