        { name = "Victory", family = "Fighting", lines = {
            { id = 1241765, text = "At long last, destruction has come to this pathetic world!" },
            { id = 1241773, text = "Pray to your pathetic goddess! Let her listen to your cries of agony!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1241763, text = "Enjoy this moment, mortals. It shall be your last!" },
            { id = 1241513, text = "No! How can this be?" },
            { id = 1245294, text = "Such a small, fragile body, yet it holds such power!" },
