    { who = "Greeter Praetor", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3594655, text = "Hmm. I do not believe you are authorized to view this memory." },
            { id = 3594657, text = "Please remove yourself from the locus at once, or you will be removed." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3594653, text = "I advise you to return those scrolls to their proper places, only for sworn are authorized to browse the collection." },
            { id = 3594656, text = "I am inclined to eject you from the locus, if you insist on meddling." },
            { id = 3593880, text = "I exist to answer all your questions." },
            { id = 3594658, text = "I seem to be ex-experiencing an error." },
