    { who = "Grif Wildheart", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1386008, text = "Hold on! We're coming in for a landing!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1386006, text = "That was quite an adventure, eh?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1386017, text = "Seems Bruce wants the Legion out of here as much as we do. Work night and day to find this tomb." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1386014, text = "According to ancient texts we translated back in the Explorers League, Titan Strike focuses the power of storms into blasts of energy." },
            { id = 1386007, text = "Alright Huey, let's get back to Dalaran!" },
            { id = 1386013, text = "Bran introduced me to Proustaka not long ago. That dwarf sure has a way with the worlds, huh? He can even charm a vrykul!" },
            { id = 1386010, text = "Hop on and let's get moving! Ol' Huey don't bite! Much, heh heh!" },
            { id = 1386015, text = "If that's true, it could do some serious damage to the Legion. Spores will find out soon enough!" },
            { id = 1386016, text = "I'll introduce you to Prestaga when you're ready." },
            { id = 1386012, text = "Make yourself comfortable. It's a bit of a ride to Stormheim." },
            { id = 1386009, text = "Oh, easy Huey, easy." },
            { id = 1386011, text = "To shield rest!" },
        } },
    } },
