    { who = "Grimla Fizzlecrank", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 6175394, text = "I haven't seen scrap like that since the Great Scrappening! Nice work!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 6175395, text = "Heya! There's loads of scrap ripe for the pickin' in the heaps! Go in there and grab some, will ya?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6175236, text = "Can you believe what this city is coming to? We got a rat problem! Deal with it, will ya?" },
            { id = 6175216, text = "Energy is what plants crave! Battery style! Thanks for giving me a hand." },
            { id = 6175235, text = "Finally! Someone around here who actually fixes things instead of causing more problems!" },
            { id = 6175230, text = "Machinery's going berserk again! Help us get it back in line!" },
            { id = 6177918, text = "Nice work letting the slime return to the filth, as nature intended." },
            { id = 6175391, text = "Oh hey, you got him to come around. Good on ya. Here's your cut." },
            { id = 6177915, text = "Overflowing barrels of slime are all over the vatworks! Empty them and let the slime run back into the river, and complete the slime cycle!" },
            { id = 6175229, text = "They just needed to chill their engines a bit. Thanks for your help!" },
            { id = 6175218, text = "We don't got real plants here in Undermine, but we got the next best thing. Fix them up so they shine nice and bright." },
            { id = 6175388, text = "You're pretty world-wise, ain't ya? I got a MOOC inspector that could use the help of someone with brains. Go talk to him?" },
        } },
    } },
    { who = "Grizzek Fizzwrench", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2961904, text = "I think he's saying we're expendable." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2961986, text = "Take it easy!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2961984, text = "Alright, get going!" },
            { id = 2961990, text = "Could always use a hand!" },
            { id = 2961989, text = "How ya doin'?" },
            { id = 2961992, text = "Must be nice not having anything better to do." },
            { id = 2960145, text = "Right, the radiation from Nomura-Gan, where I am definitely from." },
            { id = 2961987, text = "See you around, pal." },
            { id = 2961988, text = "Something on your mind?" },
            { id = 2961905, text = "Told you not to say anything!" },
            { id = 2961985, text = "We all got work to do." },
            { id = 2961991, text = "What are you working on?" },
        } },
    } },
    { who = "Grommash", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1058156, text = "If you dare challenge me, I will be wating into man jungle. You will find only death beyond these gates." },
            { id = 1058152, text = "What good are stars and visions against steel and powder? Make a worthy offering or your people shall die." },
            { id = 1058151, text = "You have no place in my iron horde! Go back to your little village near Zul. You can watch the stars while the iron tide washes over you." },
            { id = 1058150, text = "Your dark star has fallen, and now serves the Draenei. You are a disgrace." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1058147, text = "I told you, get out!" },
            { id = 1058155, text = "I will remember this day, heroes. I will remember your names and your faces. And when the time comes, I will carve you limb from limb!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1058146, text = "I've seen enough, fight your own battles, oh great and powerful king!" },
            { id = 1058149, text = "N'Zhul, your army is scattered, your fortress in ruins!" },
            { id = 1058154, text = "The Iron Horde is never beaten! I will never surrender!" },
            { id = 1058157, text = "There is no place to run, outsiders! This is my world! We will find you!" },
            { id = 1058153, text = "Well done, Ner'zhul. We attack Karabor soon. Summon forth the Dark Star." },
        } },
    } },
    { who = "Grommash Hellscream", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
