    { who = "Grumbol Grimhammer", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2414962, text = "Ha Ha Ha ha! Hyah! Seeing those smoking orcs flying sky high brings this old dwarf tears of joy. You have my thanks." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 2404288, text = "Ah, now that was a fight! But they didn't even see you coming, did they? Ha Ha Ha ha!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2404285, text = "Blasted boneheads thought they could sneak right under our bearded noses! Get in there, and stomp them flat!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2414959, text = "A squad of our soldiers has been waylaid by some slimy horde of good-for-nothings. What are you waiting for? Get in there!" },
            { id = 2414961, text = "It's high time we rained down some destruction on those lily-livered croc-kissers. Level it all!" },
            { id = 2404287, text = "Magni's beard! The Horde's been stockpiling a lot of Azerite. Let's smash him up and take it all!" },
            { id = 2404289, text = "Phew! I can't tell if those mangy orcs smell worse dead or alive!" },
            { id = 2404286, text = "Some stinkin' orcs are tryin' to move through our territory, but I can smell them from miles away! Rough them up!" },
            { id = 2414960, text = "Those swine-smooching pig heads are congregating around some powerful Azerite. Can't let them get their grubby hands on it now, can we?" },
            { id = 2404290, text = "You've done it! We'll put that Azerite to good use!" },
        } },
    } },
    { who = "Grummles", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 640130, text = "AH!" },
            { id = 640216, text = "HA HA!" },
            { id = 640224, text = "HA!" },
            { id = 640120, text = "OH YEAH!" },
            { id = 640212, text = "RAWR!" },
            { id = 640214, text = "WAH!" },
            { id = 640132, text = "WOOF!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 640260, text = "I know fortune when I smell it." },
            { id = 640178, text = "I once smelled a lucky-do so powerful, I woke up with a hangover." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 640200, text = "AHHH!" },
            { id = 640190, text = "EEE!" },
            { id = 640294, text = "HEH!" },
            { id = 640186, text = "NO!" },
            { id = 640298, text = "UGH!" },
            { id = 640188, text = "YEAH!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 640272, text = "Ah, a foot rub! Also very good luck." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 640160, text = "Farewell, friend of the Grummels!" },
            { id = 640316, text = "Many farewells!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 640332, text = "Gee, I always clean a yak shoe three times before a long journey, everyone knows that." },
            { id = 640158, text = "Good fortune to all friends of the Grummels!" },
            { id = 640314, text = "Good fortune to our friends!" },
            { id = 640252, text = "Good fortune, my friend." },
            { id = 640264, text = "Have I got a lucky do for you." },
            { id = 640322, text = "Hehe, many greetings!" },
            { id = 640170, text = "How many greetings!" },
            { id = 640270, text = "It is good fortune to give money to a grummel." },
            { id = 640162, text = "May your feet find good trails!" },
            { id = 640254, text = "May your yak always be clean." },
            { id = 640330, text = "Never put a sleeping yeti paw in hot water. Very, very dangerous." },
            { id = 640166, text = "Oh!" },
            { id = 640262, text = "The nose knows!" },
            { id = 640334, text = "Uh, bad luck to keep poking, Grummel. Very, very bad luck." },
            { id = 640168, text = "What's your lucky do?" },
            { id = 640268, text = "You seek the wisdom of the Grummel?" },
            { id = 640326, text = "You smell of good fortune!" },
            { id = 640176, text = "You smell too good to be lucky." },
        } },
    } },
    { who = "Grumnus Steelshaper", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2401864, text = "I see you're no stranger to blacksmithing. You've got this." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2401862, text = "Strike the metal to shape it!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2401861, text = "Clear out of the forge!" },
            { id = 2398079, text = "Even if we could smelt the metal, no dwarf can endure that kind of heat. Not even a dark iron!" },
            { id = 2398078, text = "I'm not sure we can reforge the armor, Bran. The Great Forge would need to be much hotter than any of us have ever seen." },
            { id = 2398080, text = "Our friend here has to stay in stone form for a long stretch of time in order to withstand an intense amount of hate." },
            { id = 2401863, text = "Quakes the metal in the water!" },
            { id = 2401865, text = "You may not be a blacksmith, but follow my instructions and you'll be fine." },
            { id = 2401866, text = "You've done it!" },
        } },
    } },
    { who = "Grunt Throg", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3584264, text = "Hitting your enemy will break the spell. Attack Herbert to get him back to normal." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3584381, text = "I am not fond of fel magic, but I trust that whatever you do is for the Horde." },
            { id = 3584350, text = "I don't know much about the light, but when a spirit calls, you answer." },
            { id = 3584268, text = "I don't think I learned anything from that." },
            { id = 3584263, text = "I know this tactic! You keep one foe polymorphed while you focus on the other!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3585732, text = "Go with honor." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3584382, text = "The spirit of an ancient warrior must have much to teach you. Learn it well." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3585731, text = "For the Horde!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3584380, text = "Drizza surely had to evade danger in such hostile territory. You stealth to do the same." },
            { id = 3584260, text = "I'd rather not be turned into a sheep." },
            { id = 3584351, text = "Thank you. We can't give the recruits a proper burial, but you can still perform their last rites." },
            { id = 3584355, text = "You've saved many a life today. They won't soon forget it." },
        } },
    } },
