    { who = "Guardian Msheke", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2908481, text = "going back into my shell." },
            { id = 2908485, text = "Gonk takes pride in our pack!" },
            { id = 2908482, text = "Gonk welcomes all!" },
            { id = 2908480, text = "More pray for gunk!" },
