    { who = "Guardian Velomir", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4686692, text = "I will make my way to the bridge in the middle of the garrison. Meet me there when you are done." },
            { id = 4680452, text = "It is good you are here." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4680453, text = "I am thankful for your arrival." },
