    { who = "Gurgthock", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1858552, text = "A champion that sleeps with the fishes, literally. The freehold fanatic, the master of the jagged jawbone jab, the powerful pugilist predator, Trothac the shark puncher!" },
            { id = 1858551, text = "Amazing! These sweaty scallop legs found a way to best Griffin Steffen! Um... There is only one challenger left, and he needs no introduction!" },
            { id = 1858544, text = "And entering the ring, we have the amazing, the incredible, the magnificent, the what, what, the really?" },
            { id = 1858547, text = "From the sewers of Freehold comes a tortollan brigand who makes it his duty to turtley hurt you. He is the dynamo of defense, the sergeant of shell shock, the hell-yet-in-a-half-shell Ludwig!" },
            { id = 1858545, text = "It's a greased-up pig? I'm beginning to think this is not a professional setup! Ah well, grab the pig, and you win!" },
            { id = 1858548, text = "Ludwig goes down what a fight these smelly buccaneers are Resilient and they better be because their next challenger is the epitome of brutality" },
            { id = 1858543, text = "Ouch! Okay, okay! Gather round for a show of unbridled ferocity! Coming to you from parts unknown! The mysterious, the dangerous, the slightly unkempt, the band of smelly buccaneers!" },
            { id = 1858542, text = "Ouch! Why'd you poke me? Oh, oh, wake up, Woden! We're on!" },
            { id = 1858550, text = "The hungry, hungry harbingers of doom, the brutal bisect of blubber and birds, the deadly double destroyers, GRIFFEN STEVEN!" },
            { id = 1858546, text = "Well, look at that! They caught a pig. Maybe we should move on to a more threatening challenge." },
            { id = 1858549, text = "Without further ado, here comes a dangerous duo from across the sea, a peerless pair of gladiatorial beasts that strikes fear in the hearts of the most stalwart warriors." },
        } },
    } },
    { who = "Gurtogg", tier = "character", groups = {
