    { who = "Hadwin Tyrs Guard Exemplar of Justice", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5226461, text = "Brute? Oh, I see how it is. Yeah, well this brute will kill more of whatever's behind that portal than you." },
            { id = 5226539, text = "If you don't want it done to you, then don't do it. It's really that simple." },
