    { who = "Haleh", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 5014788, text = "Greetings. Did you need something?" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 5014785, text = "Safe travels, my dear." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5014784, text = "Be careful out there." },
            { id = 5020831, text = "It seems you already know who I am, though we have never met." },
            { id = 5020836, text = "Oh, no, thank you. I have a specific way of doing things. You don't need to trouble yourself." },
            { id = 5020826, text = "Really, there must be something useful in this dratted book! Why title yourself Secrets of Aberrations if all you present is common knowledge? Ugh!" },
            { id = 5020827, text = "Sintragoosa… it can't be… are you an illusion?" },
            { id = 5014783, text = "Thank you for your input." },
            { id = 5020834, text = "This was once a home for many blue dragons, including myself. I would like to believe it still can be, after my work is finished here." },
            { id = 5020830, text = "Well, I do intend to answer the call, however, as you can see, I have much unfinished business here in Winterspring." },
            { id = 5014787, text = "What is it?" },
            { id = 5014786, text = "Yes? What can I do for you?" },
        } },
    } },
    { who = "Hamuul", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 551579, text = "AHHH! AHHH! AHHH!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 551551, text = "AHHH!" },
            { id = 551528, text = "HA!" },
            { id = 551533, text = "HYAA!" },
            { id = 551538, text = "UGH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 551552, text = "You killed dozens of my students. You will pay for what you've done!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 551550, text = "I release you from this fate. May you finally find your peace in death." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 551527, text = "Hold them back! We need to buy more time!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 551531, text = "HMPH!" },
            { id = 551554, text = "OOO!" },
            { id = 551546, text = "RAWR!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 551563, text = "We serve the land." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 551569, text = "A flame druid. She is dangerous, Malfurion. You know her." },
            { id = 551526, text = "Always temper your strength with wisdom." },
            { id = 551577, text = "And I have come for you, Leyara." },
            { id = 551576, text = "Druids! Hold your fire! She is unarmed!" },
            { id = 551530, text = "Huh? What is this? I can't move! Someone help!" },
            { id = 551545, text = "I'm sorry that I did not arrive sooner, though you seem to have held your own quite well." },
            { id = 551553, text = "May the winds guide you." },
            { id = 551534, text = "Stand strong! Only a bit longer." },
            { id = 551567, text = "We'll meet you back in camp." },
            { id = 551557, text = "You! You're the one from the portal! The Druid of Flame!" },
        } },
    } },
    { who = "Hannan", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 6219908, text = "then you will walk it alone." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 6219910, text = "I do not understand your conviction, Orwenna." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 6219907, text = "You've put us all in grave peril." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6116741, text = "Continue! Orwenna, we must retreat and speak." },
            { id = 6219909, text = "May the ancient roots of our people ever thrive beneath your steps." },
            { id = 5778058, text = "Roots guide you home, stranger." },
            { id = 6219905, text = "The others and I are returning to the Cradle to seek forgiveness." },
            { id = 6116732, text = "This is not the time for visions, Orwenna. Our people need help right now." },
            { id = 6219906, text = "We followed you and your visions this far." },
            { id = 5778061, text = "What is it?" },
        } },
