    { who = "Harbaron", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1274949, text = "BEND AND BREAK YOUR SOUL I'LL TAKE" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1274965, text = "Another blood debt claimed, another soul cast into the abyss." },
            { id = 1274947, text = "New passengers, new souls, I will guide you to the depths of Helheim for a small price. Your flesh and blood!" },
            { id = 1274969, text = "The flesh burdens the soul, a nuisance that must be frayed from your bones." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1274957, text = "All who enter Hellheim must pay the blood price. Resist if you wish. In the end, I always get my payment!" },
            { id = 1274963, text = "As I said, I always get my payment." },
            { id = 1274967, text = "Everyone must pay the blood price!" },
            { id = 1274959, text = "Helia will make you pay. In the end, everyone pays." },
            { id = 1274953, text = "Life. Death. I am but one ripple in the eternal ebb and flow." },
            { id = 1274961, text = "No one rides for free!" },
            { id = 1274955, text = "Now it is I who must pay the blood price!" },
            { id = 1274951, text = "You see now the weakness in your mortal shell?" },
        } },
    } },
