    { who = "Harlan Sweete", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1858609, text = "Taller men than you have opposed me, but they always came up short!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1858612, text = "I love the sound of corpses hitting the deck." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1858604, text = "All hands on deck!" },
            { id = 1858615, text = "Alright lads, gather their valuables! After I've had my pick, you can fight for the scraps." },
            { id = 1858606, text = "Canons! Blast these scurvy dogs to bits!" },
            { id = 1858613, text = "Check their teeth for gold, boys. The rest is shark food." },
            { id = 1858607, text = "Men, equate these scallywags with our heavy guns!" },
            { id = 1858611, text = "No one better touch my booty!" },
            { id = 1858605, text = "Swab the deck with their gizzards!" },
            { id = 1858608, text = "Think you can stand against me, swine? Allow me to educate you." },
            { id = 1858614, text = "You fell victim to one of the classic blunders! Never go against sweets when booty is on the line!" },
