    } },
    { who = "Havi", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1244245, text = "Inside you will find paths and more." },
            { id = 1244229, text = "You are not the only one seeking the edges. I suggest you hurry!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1242287, text = "Back from the dead are we? Outstanding! Really? Truly impressive!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1244247, text = "In House Valt, the Bone Speakers keep the dead. They will not help you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1242285, text = "Are you worthy? Only the gods may decide." },
            { id = 1244233, text = "But it will get you started. Find me near Aggramar's plot, and I will put your strength to the test." },
            { id = 1244243, text = "Forge a key in the blood of champions, and perhaps the lock will turn." },
            { id = 1244241, text = "Jotnar is its lock and glory is its key." },
            { id = 1244249, text = "Seek Vidar, earn your judgment, and pass the trial of valor." },
            { id = 1244231, text = "Strength alone will not win what you seek." },
            { id = 1244239, text = "The vote before you holds not gold, but wisdom." },
            { id = 1242283, text = "You seek the ages. But will you claim it or die trying? There is no compromise in this." },
        } },
    } },
    { who = "Hawkmaster Nurong", tier = "character", groups = {
