    { who = "Haydrias", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 551637, text = "His aspect shifts once again. You are losing him." },
            { id = 551635, text = "You have done the impossible, shaman. You have stilled the vortex within him without losing yourself internally. Your love for him must be very great." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 551638, text = "Greetings, travelers. The tides of destiny have brought you far from the bright world above. I know what it is you seek, and it lies there before you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 551636, text = "Your world shaman is already lost to the Dark Fathoms. He exists now only to consume. Tortured by the currents of the life he longed for, but never knew." },
            { id = 551634, text = "Your world, shaman, has become a vortex of longing and desire. See how his heart devours everything within its proximity. Tread lightly, traveler, lest you too be consumed." },
        } },
    } },
    { who = "Hazak the Unfallen", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
