        { name = "Conversation", family = "Feelings", lines = {
            { id = 3482361, text = "Hardly a test of my skills!" },
            { id = 3482359, text = "I'm tired of easy victories!" },
            { id = 3482363, text = "New challenges! Ha! We'll see how long you can last!" },
            { id = 3482365, text = "You had best make this interesting!" },
