    { who = "Headteacher Doragosa", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4689470, text = "YOU HAVE BEEN EXPELLED!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4689467, text = "Greetings, New. Who are you? You are not registered here. This room is only for students. Head to the registrar at once!" },
            { id = 4689468, text = "You have been educated." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4689466, text = "Hmm. We have been gone for some time. The growth here. Ah, the way should be clear. Please head to my office and wait. I hear new students that require my personal attention." },
            { id = 4689462, text = "It appears some new students have trickled in after you. They seem interested in our sports field. Help them sort out clearing the place. It is in quite a state." },
            { id = 4689469, text = "Knowledge is power!" },
            { id = 4689464, text = "Our history professor Max Dormu is almost ready for lessons. Do see if there is anything he needs assistance with." },
            { id = 4689471, text = "Such unruly students." },
            { id = 4689465, text = "The botany professor seemed to be in need of a little more aid than I thought. If you could assist them, I will see about opening my office and getting you all registered." },
            { id = 4689460, text = "These are sacred halls of learning only those registered may access them" },
        } },
    } },
