    { who = "Helcular", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1408845, text = "Do not waver, bring them down!" },
            { id = 1408847, text = "Hold your ground! Give no quarter!" },
            { id = 1408843, text = "Rise, champions! Heed the call of battle! The Burning Legion sets its sights on Cairne Mill!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1408839, text = "Forsaken! Allies! The hour to stand against the Burning Legion is at hand! Prepare yourselves!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1408861, text = "Make sure this one pays for its impudence!" },
            { id = 1408853, text = "More of them! Do not let fear cause you to shirk your duty!" },
            { id = 1408857, text = "Muster your might focus your attacks bring down this foul creature at once" },
            { id = 1408859, text = "Relieve this demon of its head! The tide will turn in our favor!" },
            { id = 1408855, text = "Such brutish force, they grow stronger! Do not falter!" },
            { id = 1408849, text = "The demons come! Make them pay!" },
            { id = 1408841, text = "The Legion approaches. Muster your strength and ready your incantations, for war has arrived!" },
            { id = 1408851, text = "Their strength surges. Whether you fight for god, king, or gold, take them down." },
        } },
    } },
    { who = "Helix", tier = "character", groups = {
