    { who = "Herald Xarbizuld", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1382617, text = "You survived the Summoners! Such determination! A pity you won't live to experience our glorious cathedral!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1382647, text = "I give my life for the Inquisition!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1382658, text = "What delightful banter! The High Inquisitor will be pleased to host such spirited guests!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1382645, text = "Now I shall measure your worth!" },
            { id = 1382690, text = "You believe yourselves worthy to enter the cathedral? Then come forth and be tested!" },
            { id = 1382646, text = "You may have the honor of meeting the High Inquisitor, if you get past me." },
            { id = 1382648, text = "You stand on the threshold of oblivion! Your lives belong to the Inquisition!" },
        } },
    } },
    { who = "Heraldvolazj", tier = "character", groups = {
