    { who = "Herbert Gloomburst", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3585758, text = "STAY MODERATELY SAFE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3584266, text = "Observe. Your polymorphed foe will wander around. Use that time to finish off whoever is left." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3584267, text = "I suppose you'd better hit frog to break the spell." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3584246, text = "An ice mode? Oh sure! I've got plenty ever since the... accident." },
            { id = 3584258, text = "Here's an example of Polymorph!" },
            { id = 3584257, text = "I'd get the book myself, but a good mage knows when to delegate." },
            { id = 3585759, text = "See you around!" },
            { id = 3584261, text = "That's the kind of thinking that prevents learning!" },
            { id = 3584259, text = "Throg, assist me. We will both attack our recruit and teach them how to use polymorph." },
            { id = 3584269, text = "Well, I wasn't teaching you now, was I?" },
            { id = 3584265, text = "You're a loose cannon recruit. I'm impressed. Let's get back to camp." },
            { id = 3584262, text = "You've got two foes attacking you now, even the odds with Polymorph!" },
        } },
    } },
    { who = "Hess High Mountain", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1277604, text = "The Underking's forces assault Snowblind Mesa. Come, march the warpath with me, and let us show them the might of Highmountain.\"" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1277262, text = "Together, we are Highmountain." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1277258, text = "A glorious day is upon us." },
            { id = 1277606, text = "For High Mountain!" },
            { id = 1277630, text = "So Huln never backed down, no matter the enemy?" },
            { id = 1277260, text = "We entered this place as three tribes. Now we are one." },
            { id = 1274620, text = "We need to be out there searching for the hammer. Tradition can wait." },
            { id = 1274576, text = "What? How? The whole time!" },
            { id = 1277664, text = "When you face the worms, call to us, and we shall be there." },
        } },
    } },
    { who = "Hexlord Raal", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1863867, text = "It is like my Loa always says, if you cannot see the source of corruption, go higher!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1863869, text = "I will call out the best spots, and you can have the honor of tossing down a sentry totem." },
            { id = 1863875, text = "I will leave you with Lottie. Let her know the cause of all this trouble may lie within Zanchoul itself." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1863871, text = "That was when we got our first taste of real blood magic. Not that petty nonsense practiced by the lesser tribes." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1863870, text = "A few years back, this whole land shook during the cataclysm. Our northern gates fell, and swarms of blood-thrown savages poured through." },
            { id = 1863874, text = "Hmm, something feels different. I sense a great power resonating inside Zenchul." },
            { id = 1863866, text = "Lottie's method is too grounded for my taste. I prefer a pterodactyl's eye view." },
            { id = 1863877, text = "May Pakku spy your enemies before they spy you." },
            { id = 1863876, text = "May the winds of war be ever in your favor." },
            { id = 1863873, text = "Not a week goes by that we do not see some Zandalari turning to blood magics. Learn from those heretics in Nazmir." },
            { id = 1863872, text = "Our defenses grow weaker. Princess Talanji has been asking for more troops, but her father has not acted fast enough, and she has turned to the Horde." },
            { id = 1863868, text = "We shall ride Ata the Winglord on this journey. Hop on and keep your eyes open!" },
        } },
    } },
    { who = "Hiddenmaster", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 631202, text = "Mm-hmm." },
            { id = 631200, text = "What is it?" },
            { id = 631198, text = "Yes." },
        } },
    } },
    { who = "High Arcanist Savor", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5782074, text = "We'll head to the wagons, but I hope you have a real plan in mind." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5782123, text = "I would like to point out that this one was not my fault." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5782112, text = "and call all those spiders over there down on our heads." },
            { id = 5782110, text = "Keep holding it for science." },
            { id = 5782082, text = "Maybe not ever, Mera." },
            { id = 5782117, text = "Spiders, Meera. Spiders." },
            { id = 5782072, text = "We're over here." },
        } },
    } },
    { who = "High Astromancer Solarian", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 551810, text = "FOR THE SUNWELL!" },
