    { who = "High Borne Ghost", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2978111, text = "I serve the queen!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2978117, text = "Glory to Azshara!" },
            { id = 2978119, text = "The voices! Make them stop!" },
            { id = 2978113, text = "You dare strike a highborn?!" },
        } },
    } },
    { who = "High Botanist Telarn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1412579, text = "Your corpse will make a fine compost." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1412584, text = "The sun warms my beauties, but it shall scorch your bones!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1412581, text = "Can you hope to stand against the three primal forces that shape life itself?" },
            { id = 1412577, text = "Death is merely part of the great cycle." },
            { id = 1412587, text = "It seems I have a bit of pruning to do!" },
            { id = 1412578, text = "More food for the worms!" },
            { id = 1412582, text = "Now you face three aspects of life, even as your cycle is about to end." },
            { id = 1412585, text = "Someone water my plants." },
            { id = 1412580, text = "Suramar owes its beauty to my blooms. I alone have mastered the delicate intertwining of magic into nature's grand cycle." },
            { id = 1412576, text = "Wherever will I store all this fertilizer?" },
            { id = 1412583, text = "Wither in my heat, little weeds!" },
        } },
    } },
    { who = "High Commander Goodchilde", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1500671, text = "AH!" },
            { id = 1500673, text = "GAH!" },
            { id = 1500670, text = "HA!" },
            { id = 1500674, text = "HYAH!" },
            { id = 1500675, text = "MWAH!" },
            { id = 1500669, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1416890, text = "Should you fall, know that your sacrifice will bring me great glory this day!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1416893, text = "My faith has forsaken me?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1416889, text = "The Scourge has risen against us! Send the invaders back to their graves!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1416892, text = "By the power of the Light, I will banish you, Scourge!" },
            { id = 1416891, text = "You defile the sanctity of this chapel with your presence! The Holy Light shall burn you!" },
        } },
    } },
    { who = "High Commander Halford Wyrmbane", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2019089, text = "We need your aid to secure this area. My forces are unable to take it themselves." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2019095, text = "I lost some of my soldiers to a foe nearby. Avenge their deaths!" },
            { id = 2019096, text = "My scouts report a dangerous foe nearby. I need you to neutralize it." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2019097, text = "A powerful foe is in the vicinity. Eliminate it. Show no mercy!" },
            { id = 2019091, text = "Excellent tactics. We will be able to make use of this area soon." },
            { id = 2019090, text = "Fine work. These resources will supply the 7th Legion for a long time to come." },
            { id = 2019087, text = "Seventh Legion scouts have determined that this location is of extreme importance. Clear it out for our use." },
            { id = 2019088, text = "Several of my soldiers have fallen trying to take the nearby area. End the threat there now." },
            { id = 2019094, text = "The Seventh Legion has received word of a powerful foe nearby. Dispatch it at once." },
            { id = 2019086, text = "The Seventh Legion requires resources located nearby. Secure them through whatever means necessary." },
            { id = 2019093, text = "You honor those of the 7th Legion who have fallen. We will make good use of this area." },
            { id = 2019092, text = "You've done well. Leave the rest to my soldiers." },
        } },
    } },
    { who = "High Commander Kamses", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3168068, text = "Brigands, your kind are not welcome here." },
            { id = 3168074, text = "You cannot be serious! I will not partner with grave robbers and bandits!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3196204, text = "It seems the Amethyst are retreating back to their tombs. They were fools to challenge Rabkahhen." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3198052, text = "Strike them down wherever possible, but focus on key objectives and enemy champions to deal the most damage." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 3198055, text = "That was a blow they will not soon forget. Continue to thwart the efforts of our enemies." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3198053, text = "Well struck, defeating the enemy's champions will break their morale and send them scurrying back to the shadows." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3198056, text = "Seizing the enemy's resources will bring their supply chain to a halt. Give them nothing to reinforce their armies." },
            { id = 3196202, text = "The Amethet are mustering for another assault on the Halls of Origination. Break their ranks and scatter them to the winds." },
            { id = 3196206, text = "The Emethet are advancing! Protect the Forge at all costs!" },
            { id = 3198054, text = "This appears to be a place of importance to our enemy. Do what you can to disrupt their operations." },
            { id = 3198051, text = "With each passing day, new enemies descend upon Ul'dum. We must drive them from the sands." },
        } },
    } },
    { who = "High Elder Cloudfall", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1406491, text = "Master, you have witnessed with your own eyes the Legion's capability for destruction." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1406523, text = "I will return with you to the Wandering Isle. From there, we will devise a plan." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1411603, text = "Our champions might be able to follow our enemy's movements. I only hope we can find my students before it's too late." },
            { id = 1406492, text = "The monastery is saved, but our work is far from over." },
        } },
    } },
    { who = "High Exarch Turalyon", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1453201, text = "For ages, I have hunted the Burning Legion across the stars." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1678540, text = "I agree. It's been a long time, but as I recall, it was your turn to buy the drinks, Kadgar." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1416661, text = "Farewell, son. Do not lose faith, for it is in the darkest moments that the light shines brightest." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 1416659, text = "You must gather the defenders of the Light, Eretor. Keep the Light alive. Fight! Or all is lost." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1678470, text = "Nice shooting! With that cursed ship out of commission, we can focus on other fronts." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1416658, text = "If you can hear this, I have an important message." },
            { id = 1453203, text = "In retribution, the dreadlord Balnazar has been sent to Azeroth to destroy all that I hold dear." },
            { id = 1678469, text = "The Legion is arming a Devastator to fire on the Xenedar. We need you to commandeer it." },
            { id = 1678538, text = "We feared for you as well, Khadgar, but I think part of me knew it would take more than the explosion of a planet to slow you down." },
            { id = 1416660, text = "We hope you can forgive us for leaving, but we did it out of love for you. To ensure your safety and the survival of our world, we chose to make this sacrifice." },
        } },
    } },
    { who = "High Explorer Dellorah", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3195798, text = "Are you on another adventure?" },
            { id = 3195799, text = "Fancy meeting you here!" },
            { id = 3196272, text = "Fascinating! It looks like they've activated some kind of solar device. I wonder what it does." },
            { id = 3196273, text = "Look! They're re-assembling those Broken Watchers, so that's how they're getting them." },
            { id = 3195793, text = "So many ruins to explore!" },
            { id = 3196271, text = "The League appreciates your help, hero. Now let's see what these amethyst are all about." },
            { id = 3195795, text = "The league isn't going to run itself!" },
            { id = 3168431, text = "The league's got your back too!" },
            { id = 3195796, text = "Well, time to get to work." },
            { id = 3195794, text = "What secrets are these sands hiding?" },
            { id = 3195800, text = "You seen anything... interesting?" },
        } },
    } },
    { who = "High General Rakeesh", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1448010, text = "Ah, the fated heroes have arrived. It would appear that you have bested me, Velen." },
            { id = 1448007, text = "For a profit, you are doing a very poor job of making predictions." },
            { id = 1448002, text = "You think you've won? You will know the taste of defeat, even if it means my own death!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1448003, text = "I am here now to prepare a place for you, amidst the ruin of tomorrow." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1448012, text = "Enough! Sisters, end this nonsense!" },
            { id = 1448004, text = "In my master's house, smolder the burning husks of a thousand worlds! I am here now to prepare a place for you, amidst the ruin of tomorrow!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1448009, text = "But before I surrender and face the judgment of the Light, there is one last thing I must do." },
            { id = 1448008, text = "Can you know victory without first knowing defeat? Come, fail, die!" },
            { id = 1448001, text = "From the mouth of Argus comes your doom! For soon the Annihilator will have its fill, and detonate with the force of a collapsing star! Nothing but ash will be left where we stand!" },
            { id = 1448006, text = "Hah! It makes music when you beat it! What a delightful creature! I will enjoy ending its existence." },
            { id = 1448005, text = "It will be your faces that I see in my last waking moments, a final agonizing memory, before I am turned to ash and cast into oblivion. I welcome it." },
            { id = 1448011, text = "Karzak! I call upon you! Finish them!" },
        } },
    } },
    { who = "High Inquisitor Qormaladon", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1382623, text = "Another will take my place." },
            { id = 1382619, text = "another windrunner for my collection oh the secrets you confess to me" },
            { id = 1382642, text = "The Inquisition sees all! Every truth, every lie!" },
            { id = 1382620, text = "This barissa should prove useful, until she breaks. You, however... Well, every mortal life must end." },
            { id = 1382618, text = "You mortals have endured so much to rescue your precious Alleria. Come forth and reap your reward!" },
            { id = 1382622, text = "You refuse to surrender? How splendid. We did not anticipate the high elf would bring along so persistent an ally." },
        } },
    } },
    { who = "High Inquisitor Whitemane", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1444637, text = "In Undeath, my true purpose is manifest." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1455907, text = "Atonement! I doubt that such a thing exists for me." },
            { id = 1455903, text = "I... I live? Is the anguish of death over?" },
            { id = 1455909, text = "Indeed we shall." },
            { id = 1455913, text = "The Light has ravaged his body. There is nothing we can do for him." },
            { id = 1444639, text = "There is no peace for the unliving." },
            { id = 1444635, text = "We do what the living cannot." },
            { id = 1444629, text = "What do you seek?" },
            { id = 1455905, text = "Why then? Why have you done this to me?" },
            { id = 1444633, text = "You need only ask." },
        } },
    } },
    { who = "High King Maulgar", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
