        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1522911, text = "More bones for Vereena!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 551843, text = "Grun of a real power in Outland!" },
            { id = 1522917, text = "Ha Ha Ha ha!" },
            { id = 1522915, text = "Wow, what killed you so fast?" },
