    { who = "High Lord Bolvar Fordragon", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3771158, text = "HA!" },
            { id = 3771148, text = "HIYAH!" },
            { id = 3771146, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4323587, text = "Would you have journeyed to Icecrown if you knew?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4323591, text = "I know, and for the pain it caused you, I will always feel sorrow. I pray that one day, you can forgive me for it." },
            { id = 4323559, text = "I won't waste this chance, Talion. I promise you." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 4323554, text = "I believed I would be trapped in that ice forever, holding the Scourge at bay. I thought that was the only path left for me. I dared not hope for anything more." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3771212, text = "AHEM!" },
            { id = 3771200, text = "AHHH!" },
            { id = 3771198, text = "ARGHHH!" },
            { id = 3771208, text = "GAH!" },
            { id = 3771210, text = "OOF!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4322417, text = "Do whatever you can to aid the Oracle. The fate of the Shadowlands depends on your success." },
            { id = 4254143, text = "The jailer, he who tormented so many, who long ago set in motion the plague of undeath on our world, has finally been destroyed." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4323664, text = "Without the Helm of Domination to control them, the Scourge roams leaderless. Nothing remains to temper their aggression." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4323557, text = "A view, that the daughter I loved with all my heart, would find me and see only a monster." },
            { id = 4323585, text = "The man I was did die that day. The dragon's fire sealed my purpose." },
            { id = 4323666, text = "We cannot allow any of them to seize command and unite their forces. The Ebon Blade must remain vigilant." },
            { id = 4323555, text = "When the helm was broken, and I was free, I... I was afraid." },
            { id = 4323589, text = "Which is why you could not know, I had to make that sacrifice to keep you and the rest of the world safe from that place, from that power." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 3771142, text = "GRRR!" },
        } },
    } },
    { who = "High Lord Darion Morgraine", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4323667, text = "And so we shall. Though Azeroth may never truly be rid of the Scourge, we will keep them in check. You have my word." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 4323671, text = "Sometimes, the greatest act of service is to be present for those who need us. Until we meet again, Highlord." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4323665, text = "Indeed. The mightiest among them already vie for supremacy, like vicious warlords in the wake of their king's death." },
            { id = 4323669, text = "No Bolvar, let the Frozen Throne sit vacant. The Knights of the Ebon Blade will safeguard the Citadel in your stead. Taelia needs her father." },
        } },
    } },
    { who = "High Lord Tirion Fordring", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1272609, text = "Find the strength within you." },
            { id = 1241279, text = "Leave me. You must hurry, before more come. Go!" },
            { id = 1248592, text = "Stay back! It's a trap! The light will protect me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1271604, text = "Champion! By the light, you must vanquish this foul demon!" },
            { id = 1241265, text = "Champion, come closer." },
            { id = 1241215, text = "Champion, you must retrieve the Ashbringer." },
            { id = 1272607, text = "Courage is our greatest weapon." },
            { id = 1241281, text = "No! The light burns in my heart! I will never surrender!" },
            { id = 1272611, text = "Put your faith in the light, and all is possible." },
            { id = 1248598, text = "The light will... AAAAAAHHHHHHH" },
            { id = 1241261, text = "You must become the Ashbringer." },
            { id = 1241263, text = "You must take up the blade. You must stop the Legion." },
        } },
    } },
    { who = "High Maulsorcking", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 998255, text = "ITS POWER GROWS BEYOND COMPRIHENSION! HAHAHA!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 998251, text = "Enough! Long have the Sorcerer Kings guarded these chambers! Today, you will see our secret power!" },
            { id = 998241, text = "You have seen but a fraction of my power! Behold the ancient magics unearthed by my empire!" },
            { id = 998233, text = "You will learn why I am king, and you are little more than peasants." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 998243, text = "King's Guard, to my side. I must focus my power and awaken the stone." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 998253, text = "Guards! Remove these peasants!" },
            { id = 998235, text = "I'm tired of this! Be gone!" },
            { id = 998247, text = "Its energy overflows! Soon it will be unleashed!" },
            { id = 998239, text = "Look upon the tools of your demise, the ancient stones grant me unimaginable power!" },
            { id = 998245, text = "Such power! It takes form to destroy you!" },
            { id = 998249, text = "The boundless power of the stones flows through me! Your destruction comes!" },
            { id = 998257, text = "You can never challenge my rule! I command the power of the stones and know no equal!" },
        } },
    } },
    { who = "High Mountain Brave - masculine voice", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1375740, text = "LOOK TO THE SKIES!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1375743, text = "Greetings traveler" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1375738, text = "Together, we are Highmountain." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1375737, text = "Beware the deep places of the Earth." },
            { id = 1375747, text = "Do you feel the change in the wind?" },
            { id = 1375742, text = "High Mountain Stands" },
            { id = 1375748, text = "Hmph!" },
            { id = 1375745, text = "It is a day for flying." },
            { id = 1375739, text = "May your rivers be ever bountiful." },
