    { who = "High Mountain Ettin", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1274907, text = "I DID THE DIFFERENT POT! NO, MY TURN!" },
            { id = 1274911, text = "SMASH HIM! CRASH HIM!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1274913, text = "I don't like you! I don't like you either!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1274895, text = "Let's cook it! Nah nah nah! Eat it more!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1274899, text = "Hard on outside! Chewy inside!" },
            { id = 1274909, text = "Is it tasty? Oh yeah, once we get it out of that crunchy armor shell... YUM!" },
            { id = 1274905, text = "Oh, we get it! No, we get it!" },
            { id = 1274901, text = "Ooh, juicy snack! Let me first be first!" },
            { id = 1274903, text = "This my place! Let's eat!" },
            { id = 1274893, text = "Ugh, should we let live? Nah." },
        } },
    } },
    { who = "High Mountain Warbrave", tier = "character", groups = {
