    { who = "High Overlord Saurfang", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 551866, text = "HUAH!" },
            { id = 551872, text = "UGH!" },
            { id = 551891, text = "YEAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 901781, text = "I tried to tell him, to tell him that Hellscream betrayed us, cast aside a Warchief's responsibility to his own people, but Nazgrim, too loyal, too proud." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 901785, text = "Go on, find Thrall. Finish this. I will live." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 551886, text = "AHHH!" },
            { id = 551883, text = "EW!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 901773, text = "Ah, more of Vol'jin's revolutionaries. You've made it." },
            { id = 901779, text = "Ah, Nazgrim. A great leader and a fine warrior. He valued his oath to the Warchief more than his life." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 901783, text = "Damn Hellscream, his ambition tore our horde apart." },
            { id = 901775, text = "Have you found Thrall? I am badly hurt. He insisted on going ahead alone." },
            { id = 901777, text = "Tell me, how goes the battle up above? What of Nazgrim? Speak to me!" },
        } },
    } },
    { who = "High Prelate Rata", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2575544, text = "Heretics! They must pay for this with their lives!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2575547, text = "I will guard Talanji. Do what you must to end this nonsense." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2575535, text = "Her spirit will be weighed and measured in the eyes of the Loa." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2575552, text = "In due time, Princess, the sooner the Loa grant you the throne, the better for Zandalar." },
            { id = 2575533, text = "It has been centuries since our people have crowned a new ruler." },
            { id = 2575554, text = "King Rastakhan surrounded himself with traitors and snakes. Talanji has chosen her advisors wisely." },
            { id = 2576873, text = "Loa's Light guide you." },
            { id = 2575548, text = "Say the word, and I will execute these traitors!" },
            { id = 2575550, text = "The rest will soon meet the lore they so abhor." },
            { id = 2575539, text = "This rabble must be taught the proper respect, your highness." },
            { id = 2575534, text = "To claim her throne, Talanji must undergo our most sacred rite." },
            { id = 2575569, text = "We are unharmed, despite the white widow's intentions." },
        } },
    } },
    { who = "High Priest Amet", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3196238, text = "The visions abate, and the Black Empire wanes. For now, you have given us hope, champion." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3196236, text = "Champion, we must stop them here and now. Bring an end to the Old Gods machinations." },
            { id = 3196237, text = "The dark visions have come to pass. The Black Empire rises in Uldum. We must push it back before it is too late." },
        } },
    } },
    { who = "High Priestess Ishanah", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1506146, text = "GAH!" },
            { id = 1506148, text = "HUUU!" },
            { id = 1506147, text = "RAWR!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1506155, text = "AHEM!" },
            { id = 1506154, text = "OOF!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1411962, text = "Adal, grant us strength!" },
            { id = 1411487, text = "May the light guide your way." },
            { id = 1411963, text = "The light shines upon us." },
            { id = 1411964, text = "The Naaru are with us, always." },
        } },
    } },
    { who = "High Speaker Eirich", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5738519, text = "You speak the truth? Your artifact will repair the awakening machine?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5726867, text = "I have nothing to say to you." },
            { id = 5726870, text = "I merely tolerate you. When that ends, I have an entire realm of workers ready to enact my will. Remember that." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5726868, text = "Are you still here?" },
            { id = 5726862, text = "Be more mindful of my time." },
            { id = 5738522, text = "Because of me." },
            { id = 5726864, text = "More wasted time." },
            { id = 5726865, text = "Now you can go bother someone else." },
            { id = 5726869, text = "Whatever you want, it can't be important." },
            { id = 5727854, text = "When a fly annoys me, I swat it." },
            { id = 5726866, text = "Yes, thank you for whatever it was you did." },
            { id = 5738525, text = "Yes, yes. All earthen will awaken!" },
        } },
    } },
    { who = "High Tinker Mekkatorque", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1995546, text = "YOU'VE GOT IT!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1995545, text = "I don't have many of them, but the ones I do are at your disposal!" },
            { id = 1995544, text = "My machines are at your command!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1995543, text = "Indubitably! I brought some extra machines for backup! Feel free to give them a spin!" },
        } },
    } },
    { who = "High Wakener Aargon", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1688726, text = "You are unworthy." },
            { id = 1689424, text = "Your efforts thus far are... Lacking." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1688728, text = "I suppose that qualifies as a victory." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1688727, text = "A fool's errand, but I will indulge you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1688725, text = "Continue like this, and you may well scrape by." },
        } },
    } },
    { who = "High Warlord Cromush", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2400919, text = "Today we shatter our enemies! Fight with honor, hero!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 2400928, text = "The Alliance cowards flee! All lines, push forward for the Horde!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 2400927, text = "The Alliance's convoys are poorly guarded. They should be no match for you. Strike them down!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2400924, text = "Blood and thunder for the Horde!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2400923, text = "Kul'Tiras will fall, for your Warchief, Loctar Ugar!" },
            { id = 2400929, text = "Lok'tar! Glory and honor to the Horde!" },
            { id = 2400925, text = "No matter the field or the foe, we fight with honor, hero! Show these Alliance dogs what it means to be Horde!" },
            { id = 2400918, text = "Now is the time to strike a Grommakar!" },
            { id = 2400920, text = "Our forces have the advantage, for now. Press the attack and break the enemy's will before they recover!" },
            { id = 2400922, text = "The Alliance has dramatically increased their presence in this region. Do not fear unfavourable odds, beat them!" },
            { id = 2400921, text = "The Alliance was sloppy and arrogant to send so few. Make them regret their mistake." },
            { id = 2400926, text = "We can strike a blow at the enemy supply lines here! Keep your focus on the target, soldier! Look, Norosh!" },
        } },
    } },
    { who = "High Warlord Najentus", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 551936, text = "YOUR SUCCESS WAS SHORT LIVED!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 551932, text = "HMMM!" },
            { id = 551927, text = "RRR!" },
            { id = 551926, text = "UGH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 551943, text = "You will die in the name of Lady Vashh!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 551939, text = "OOF!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 551937, text = "Time for you to go." },
        } },
    } },
    { who = "High Warlord Volrath", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2923783, text = "The Alliance Druids be bringin' an ancient of war into battle! We got to take it down! Now!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2923787, text = "We gonna keep the ancient power here, out of the Alliance's hands, no matter what, for the Horde!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2923789, text = "Asheron be ours, man! Well done!" },
            { id = 2923792, text = "Champion! Nazjatar be a dangerous place. We best be getting it under Horde control." },
            { id = 2923785, text = "Champions of the Horde! The Warchief be wantin' Ashran and all of its artifacts. It be up to us to secure the island." },
            { id = 2923793, text = "Gonna mark some key locations around the area. Keep hold of them, no matter what you gotta do!" },
            { id = 2923784, text = "Our shamans be summonin' a mighty elemental to fight beside us. The Alliance don't stand a chance." },
            { id = 2923788, text = "Peace with the Alliance. Never mind." },
            { id = 2923786, text = "Some of you gonna take the fight to the Alliance. The others, find those artifacts before our enemies can get to them." },
            { id = 2923791, text = "That be enough for now. Better to lose one battle and fight another day. We still be having much to do here." },
