    { who = "Hireek", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2138735, text = "RRR!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1869358, text = "My faithful, stay your hand. Come forth, divilers, and meet your hand. Your blood shall feed G'huun." },
            { id = 1869364, text = "You are strong, but none stand against the might of a lower." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1869356, text = "I will feast upon your flesh and offer your soul to my master." },
            { id = 1869361, text = "I will... What? Poison? What have you done to me?" },
            { id = 1869362, text = "My master's power flows through me! It will purge me of your infection!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1869359, text = "Mercy! Foolish insect! We will obliterate you as well as Zuldazar!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1869363, text = "ENOUGH! I will feast upon your broken bones!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1869365, text = "All that bravado, only to die in my lair. I shall consume the remains, once I recover." },
            { id = 1869360, text = "Hah! What can you hope to do against me? I am Lord of the Sky!" },
            { id = 1869357, text = "Step forward! I alone shall deal with you!" },
            { id = 1869366, text = "This pleases me. Bring more to my lair. I must commune with the master." },
        } },
    } },
