    { who = "Hobart Grapplehammer", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3087502, text = "Do you have a question?" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3087500, text = "Back to the drawing board!" },
            { id = 3087498, text = "Run along now!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3087501, text = "A new assistant! Excellent!" },
            { id = 3087497, text = "Ambition is the mother of invention!" },
            { id = 3089727, text = "If that bloviating buffoon thinks I'll simply surrender my greatest invention, then he is sorely mistaken." },
            { id = 3089726, text = "That contract is null and void! You forged my signature!" },
            { id = 3089728, text = "The X-52 personnel armor will revolutionize the goblet arms industry!" },
            { id = 3087499, text = "We have field tests to conduct!" },
            { id = 3089729, text = "With your help, I can finally commence the next phase of testing!" },
            { id = 3087504, text = "Yes? What is it?" },
