            { id = 1411732, text = "Gorim! Odin has sent his champions to aid us!" },
            { id = 1411087, text = "She will not get away with this!" },
            { id = 1411755, text = "The fel energy. It is gone." },
            { id = 1411733, text = "They keep coming! Crush one and another takes its place! I will try to stem the flow! The passage to the north leads up to the balcony! Assist Thorim!" },
