        { name = "Conversation", family = "Feelings", lines = {
            { id = 1277640, text = "Both the hammer and deathwing were tools of the titans. I doubt I could kill him, but I may be able to banish him." },
            { id = 1277628, text = "By the power of the Titans, I banish you from this land, Earthwarder!" },
            { id = 1277632, text = "Good. He must not be allowed to gather his strength so close to our homeland. We must drive him from his lair." },
            { id = 1384377, text = "Keep them off of me, just a little longer! One of the eggs is starting to hatch!" },
            { id = 1384379, text = "Look, one survived. Such a small thing. And with little black horns." },
            { id = 1384375, text = "Not all of these eggs shall survive, but those that do should be free of Deathwing's corruption." },
            { id = 1382380, text = "So Deathwing wants this titan hammer kept secret? Perhaps this is the weapon we need to challenge the beast." },
            { id = 1277618, text = "Stand your ground, war braves!" },
            { id = 1277622, text = "Then we must find weapons not made by mortals. Igrul, is there any tool or trinket that Deathwing kept from your people? Something he would not trust you to touch." },
            { id = 1384397, text = "There is more than one way to deal with corruption." },
            { id = 1277636, text = "This is a Titan Waygate, what lies beyond." },
        } },
    } },
