    { who = "Igrul the Scalebane", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1277634, text = "A hammer! Deathwing eats any of my people who get near it." },
            { id = 1277638, text = "Enough stalling! We must slay the beast and set my people free!" },
            { id = 1277620, text = "Gah, my people did not make this goblin trash. We only strapped it to that worm's hide. No weapon of mortal make can penetrate these metal plates." },
            { id = 1277624, text = "Hmm... I may know of something." },
            { id = 1277626, text = "Now home, while the dragon is weakened!" },
            { id = 1384399, text = "The Guardians! They are awaking!" },
            { id = 1384395, text = "These eggs are corrupted! We should destroy them now!" },
        } },
    } },
    { who = "Ilgynoth", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1360543, text = "You have failed those who needed you." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1360539, text = "Come, little ones, savour your fear as we feast upon it." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1360545, text = "Welcome, Death. Do not fight it." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 1360547, text = "The pain of flesh is fleeting. True torment lasts forever." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1360537, text = "A presence. Something new. Yet familiar. Yesssssss" },
            { id = 1360540, text = "At last, the feeding hour." },
            { id = 1360542, text = "Oblivion offers solace, take the gift, take it." },
            { id = 1360541, text = "Rejoice. The end comes soon." },
            { id = 1360546, text = "Release your grip on hope." },
            { id = 1360538, text = "Your coming was foretold in the rings, the long circle is nearly complete." },
            { id = 1360544, text = "Your light sputters out." },
        } },
    } },
    { who = "Illidan Stormrage", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1412180, text = "BECOME A VESSEL OF DARKNESS!" },
