        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1966598, text = "Champion if I may have a word with you, I would like your assistance" },
            { id = 1966601, text = "Ha! And here we are, fighting back!" },
            { id = 1966604, text = "It seems as if the Kul Tirans and the Steel are... civilians? Sailors and some farmers?" },
            { id = 1862499, text = "Thank you, sir. What do you require of me, m'lady?" },
            { id = 1862542, text = "We will get him back. Just sit." },
            { id = 1966592, text = "We've not a moment to waste. Falkenhurst hasn't been heard from in days." },
        } },
