            { id = 1862784, text = "We'll put the coven down!" },
            { id = 1862779, text = "Where's the battle?" },
            { id = 1862238, text = "While I don't buy into all this hocus-pocus, anything is better than sitting here waiting for the coven to kill us all." },
            { id = 1862785, text = "You having a good time there?" },
