        { name = "Conversation", family = "Feelings", lines = {
            { id = 800923, text = "Amani tribe, avenge ye fallen warlords in the name of Zul'jin!" },
            { id = 800917, text = "Drakkari tribe! Show them the might of the Frozen North!" },
            { id = 800919, text = "Gurubashi Tribe, send their bloated corpses down the river with your jungle poisons!" },
            { id = 800905, text = "Ha Ha Ha ha! Now it be my turn! You gonna see what it means to be a War God!" },
            { id = 800913, text = "Now witness the true might of the Beastward, the Call of the Chooka-horridon, Kalamaste!" },
            { id = 800911, text = "The tribes have assembled! Ye face not one force, but the combined might of all the troll empire! The hand of Zul will span all the continents of Azeroth once again! And Ylissa races will know pain!" },
            { id = 800921, text = "To the Rocky Tribe! Flee their flesh with the fury of the sands!" },
            { id = 800915, text = "Your skull gonna make a fine ornament for my tasks!" },
