    { who = "Jani", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1997681, text = "Go! Find your way down the road to the best spot. Plant this coin in the middle of the road. But be careful not to let the hungry predators be seeing you." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1997676, text = "Greetings, rich man, and what you be bringin' to the shrine of scavengers today?" },
