        { name = "Conversation", family = "Feelings", lines = {
            { id = 1997680, text = "Beware of spiders, my little sword. I may be the god of secrets, but Yazma be the mistress of spies. She loves to keep her scattering pests within my domain. Always hunt me, Jiren." },
            { id = 1997677, text = "Ha Ha Ha ha" },
            { id = 1997683, text = "May you always be finding friends in low places! Ha ha ha!" },
            { id = 1997682, text = "Not so big and strong now, eh? Go, my minion! Go and find your rat-man, Alfon, who told ya to kill my kind! Bite him, and earn your rich man form again!" },
            { id = 1997678, text = "Not so big and strong now, eh? Go, my minion. Go and find the rat man, Nokano, who told you to kill my kind. Bite him and earn your rich man form again." },
            { id = 1997686, text = "Remember, you find something shiny, you bring it down to old Johnny." },
            { id = 1997679, text = "See you soon! Ya be dead again! Nyeh heh heh heh heh!" },
            { id = 1997685, text = "When ya go, can I be havin' ya stuff?" },
