    { who = "Jhorn the Mad", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1041390, text = "TIME TO SPILL BLOOD AND DIE FOR HYMAL! THE BATTLE OF RED SPIRES... BEGINS!" },
