        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1041389, text = "Now, playing our mighty king, scream his name and bash his skull for the shadow of Heimel, champion of games, Volgore!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1041386, text = "This is gonna be a mistake! These puny squishies be the scourge of the grand! They look like Alec Pudu!" },
