    { who = "Joanna", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1586376, text = "and I no longer sense the shadow within you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1585938, text = "Along with Xylem's other apprentices, I have been working to pinpoint his location. I believe we have found him in the Eye of Eternity." },
            { id = 1586370, text = "Archmage Xylem, you've returned!" },
            { id = 1585944, text = "Beware, Hero, the Archmage may not greet you with his usual jovial demeanor." },
            { id = 1585939, text = "From that location, Xylem could use the focusing iris to wreak untold havoc on Azeroth's ley lines." },
            { id = 1585959, text = "His portal is unstable, but an echo of it remains." },
            { id = 1585960, text = "It will take time, but we may be able to use it to reach him." },
            { id = 1585946, text = "The grimoire's hold on him has grown stronger of late. He has become paranoid and obsessive." },
            { id = 1585940, text = "The mages of the Kirin Tor can open a temporary portal to his location. You must put an end to Xylem's madness, but please spare his life if you can." },
        } },
    } },
    { who = "Joma", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2007102, text = "YOU'RE DOING GREAT, DAD!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2007100, text = "All right, Dad, we've waited long enough. You have to get on this horse." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2007099, text = "I like this one! I think it's the prettiest! Dad?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2007108, text = "Dad says sometimes big people get scared. Do you get scared?" },
            { id = 2007104, text = "I'm so proud of my dad!" },
            { id = 2007106, text = "Okay, but you're gonna come back, right?" },
            { id = 2007105, text = "Okay, I'll see you later!" },
            { id = 2007098, text = "This one looks nice!" },
            { id = 2007097, text = "What about this one, Dad?" },
            { id = 2007107, text = "Whoa, look at the pretty ponies!" },
            { id = 2007101, text = "You got it, Dad! Hold on tight!" },
        } },
    } },
    { who = "Jorak", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1998705, text = "I deserve my fate." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1998706, text = "If I can help, I will." },
            { id = 1998701, text = "Jack Rosette's to blame for this, not me. Rokira's the only reason I'm still alive." },
            { id = 1998704, text = "May the sands swallow my sins." },
            { id = 1998702, text = "Some things cannot be undone." },
            { id = 1998703, text = "The sands are never going to be safe." },
            { id = 1998699, text = "This cannot be the only road we can take." },
            { id = 1998700, text = "This must be the place. I can see a structure ahead." },
            { id = 1998708, text = "Those only exist in the mind, not the dunes." },
            { id = 1998697, text = "We should head south. The temple is somewhere within those hills." },
            { id = 1998707, text = "What do you need?" },
            { id = 1998709, text = "What is that screeching coming from your mouth?" },
        } },
    } },
    { who = "Jotun", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1390739, text = "You are strong! Perhaps you can end my unceasing vigil." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1390733, text = "Leave this place. Loken's curse compels me to slay the allies of Tyr. Until he comes to collect Tyr's spark, I must defend it." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1390734, text = "You leave me no choice! I must destroy you!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1390735, text = "The pain, it frees my mind of the curse, for the moment." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1390737, text = "Here is the spark, take it and flee, keep the memory of my fallen friend alive." },
            { id = 1390736, text = "Loken's enchantment won't let me die. We have only a moment before I fall into madness again" },
        } },
    } },
    { who = "Jrokgar", tier = "character", groups = {
