        { name = "Conversation", family = "Feelings", lines = {
            { id = 1936530, text = "This large husk needs me. Feats go home." },
            { id = 1936533, text = "Yes, struggle, resist, G'huul hungers for your spring." },
            { id = 1936535, text = "Your efforts, futile. I am untouched. What? No! No!" },
            { id = 1936534, text = "Your efforts, meaningless, unadventable." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 2025150, text = "GRRR!" },
            { id = 2025147, text = "NOOO!" },
