    } },
    { who = "Justicar Julia Celeste", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1505012, text = "ACHOO!" },
            { id = 1505011, text = "HA!" },
            { id = 1505013, text = "HEH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1411611, text = "You are alive, Boros, and that is what matters. Come, let us return to Light's Hope Chapel." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1417492, text = "I agree. They will not suspect our united force. We will have the upper hand." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1411610, text = "Wait. We don't know the strength of our enemy. Who knows what you're rushing into?" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1472483, text = "Balnazar will not suspect a united force. The Conclave and the Order of the Silver Hand, fighting together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1417503, text = "Fearless is my charge, Highlord. For the Order." },
            { id = 1412452, text = "The light guides my sword." },
            { id = 1411612, text = "Very well, Highlord. I will give an accurate account of our army and our operations." },
        } },
    } },
    { who = "Justicar Mariel Trueheart", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3563932, text = "FOR THE CRUSADE" },
            { id = 3563929, text = "UNTIL WE MEET AGAIN!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3636444, text = "We must not allow the cold to deter our efforts. Seek warmth among allies, champion." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3563930, text = "Always be at your best." },
            { id = 3563933, text = "How may I help you?" },
            { id = 3677164, text = "May this blessing bestow victory upon us!" },
            { id = 3636410, text = "There is still much to be done, hero. Crusader Ren here will assist you in your next endeavors." },
        } },
    } },
    { who = "Kaalu", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1058805, text = "They also subjugate my children, forcing them to fight and die. What might you have us do?" },
            { id = 1058803, text = "You there, scroll keeper. You are not of the raven speakers. Why do you stand before me?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1058802, text = "I sense one who is not of the flock. Come closer, child." },
            { id = 1058800, text = "My cries will rattle your enemies like thunder! Guide my aim and strike them down!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1058806, text = "Anzu always was meddling in the affairs of mortals. One would think I might learn from his mistakes." },
            { id = 1058807, text = "Very well, Scrawlkeeper. My flock is yours." },
            { id = 1058804, text = "You flatter me, but darkness weighs upon your thoughts. Speak, child!" },
        } },
    } },
    { who = "Kadros Frostgrip", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4643916, text = "Enjoy your final moments. I will." },
            { id = 4643912, text = "Your faces will be frozen in horror forever." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4643919, text = "Come, sister, our mistress awaits." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4643911, text = "Frost does not care who falls into its icy embrace." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4643914, text = "Be wrapped in the blizzard's icy embrace!" },
            { id = 4643917, text = "C-cold! So c-cold!" },
            { id = 4643918, text = "Frozen to perfection!" },
            { id = 4643910, text = "Soon, the incarnates will be unleashed on a world in need of our rule." },
            { id = 4643913, text = "to Thea! Protect the Storm Eater!" },
        } },
    } },
    { who = "Kaelthas Sunstrider", tier = "character", groups = {
