    } },
    { who = "Kalecgos", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 6365593, text = "Do not worry. This is not the end of the Kirin Tor." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 4754699, text = "AHHH!" },
            { id = 4754695, text = "GRRR!" },
            { id = 4754713, text = "OOF!" },
            { id = 4754715, text = "PFFT!" },
            { id = 4754711, text = "UGH!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 552973, text = "Welcome, we've been expecting you." },
