        { name = "Idle", family = "Feelings", lines = {
            { id = 4754550, text = "FUUU!" },
            { id = 4754554, text = "HUH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 552962, text = "But praise alone will not suffice." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 552966, text = "Brothers, sisters, Aragos speaks of our troubled past." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 552974, text = "But I would contend that we are at least partly to blame for the scars we bear." },
            { id = 6365592, text = "Call on me again and I will follow." },
            { id = 6365596, text = "I'll see if I can conjure up more later." },
            { id = 552983, text = "Oh. Argh. Ooh. Argh!" },
            { id = 552979, text = "Present me your staff, that we may endow it with great power." },
            { id = 552965, text = "Something about you seems familiar." },
            { id = 6365602, text = "The Dragon Isles, Khaz-al-ghar. Just how many more islands have we misplaced that we will find again?" },
            { id = 552968, text = "We thank you, friend of the blue dragonflight." },
            { id = 552972, text = "What brings you to me, mortal?" },
            { id = 552970, text = "What is the meaning of this?" },
            { id = 552976, text = "You seem troubled." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 4754538, text = "HRRR!" },
            { id = 4754540, text = "HUAGH!" },
        } },
    } },
    { who = "Kalisthene", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3802416, text = "HEH!" },
            { id = 3802408, text = "HIYAH!" },
            { id = 3802410, text = "HUH GAH!" },
            { id = 3802418, text = "HUH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3591397, text = "I have other duties to attend to. Your steward can repair the beacon at your request." },
            { id = 3591385, text = "I understand, Claire. We must call the Polymarch. He can present you to the Archon." },
            { id = 3588367, text = "I will be watching you, mortal." },
            { id = 3588369, text = "I would have you speak." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3588236, text = "Go in service, aspirants. Archon's eyes upon you all." },
            { id = 3588366, text = "Go in service." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3802470, text = "AHHH!" },
            { id = 3802476, text = "NO!" },
            { id = 3802466, text = "NOOO!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3588365, text = "Arkhan's eyes upon you." },
            { id = 3588235, text = "As a token of gratitude, she wishes to offer you a gift. Do you accept?" },
            { id = 3588370, text = "State your purpose." },
            { id = 3588232, text = "We meet again, mortal." },
            { id = 3588234, text = "You arrived in Bastion with dire news, which I have shared with the Archon. She thanks you for your service." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
