        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1581924, text = "Until next time!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1581928, text = "Do you really want to wake the demon?" },
            { id = 1581920, text = "How can I help?" },
            { id = 1581930, text = "It is an honor to fight alongside such power!" },
            { id = 1581929, text = "Jubeka should have banished you instead." },
            { id = 1581926, text = "Surely the leader of the Black Harvest does not have time to waste like this." },
            { id = 1581925, text = "What is wrong with you?" },
        } },
    } },
    { who = "Kanthor", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1384153, text = "You are stronger than you look, monk, but I will not be defied. Jorvanax, keep that portal open!" },
            { id = 1384152, text = "You cannot hide from me, monk. Try as you might, but your monastery will burn." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1384151, text = "I see you, monk. Your struggle is for naught. My forces will purge your order from the face of this world." },
        } },
    } },
    { who = "Karam Magespear", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1592529, text = "I will protect the realm!" },
            { id = 1592531, text = "I will smite our foes!" },
            { id = 1592530, text = "My shield is yours." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
