    { who = "Katherine Proudmoore", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2060294, text = "I ask you now to put your faith in my daughter Jaina, the true Lord Admiral of Kul Tiras." },
            { id = 2018536, text = "I have no time for idle chatter." },
            { id = 2018538, text = "I will hear you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2060295, text = "and to renew our bond with the Alliance, whose heroes have saved us from our own unmaking." },
            { id = 2018535, text = "Ask no favours." },
            { id = 2018534, text = "By wind and by sea, we remain free." },
            { id = 2018533, text = "Cool terrors shall weather any storm." },
            { id = 2060292, text = "Division has made us vulnerable. We are beset by enemies from within." },
            { id = 2018537, text = "Speak your terms." },
            { id = 2060291, text = "Thank you all for coming. I shall keep this brief." },
            { id = 2060293, text = "The Horde, too, has made its intentions clear. Those savages would see us burn." },
            { id = 2060296, text = "What say you?" },
        } },
    } },
    { who = "Kathranatir", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1406165, text = "DID YOU REALLY THINK YOU COULD DEFEAT ME, LITTLE MAJOR? I AM INVINCIBLE!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1503768, text = "HI!" },
            { id = 1503769, text = "HUH!" },
            { id = 1503770, text = "HURRAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1382442, text = "Count your days, mage! I will return!" },
            { id = 1382434, text = "You will not escape so easily, little mage!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1388750, text = "I will consume your soul!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1382441, text = "Fool! The Legion will know your secrets!" },
            { id = 1382429, text = "Pitiful wretch, you should have brought an army. What can one little mage do against the might of the Nathrezim?" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1382431, text = "You are pathetic! Your feeble spells cannot stop me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1382440, text = "I've had enough of you, Felstorm! Prepare to meet your end!" },
            { id = 1382430, text = "The Forge of the Guardian will be mine!" },
        } },
    } },
    { who = "Katy Stampwhistle", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4280687, text = "You have a good day now!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4082543, text = "Help! This place is a disaster! Some nincompoop ran in here with drones chasing after him!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4280688, text = "No one sends love letters anymore." },
            { id = 4082547, text = "No problem at all! Now to find a way back to Azeroth... ...after I make a few process improvements around here." },
            { id = 4082546, text = "Oh, you mean this? There are dozens of them all over the floor! Here, take one!" },
            { id = 4065924, text = "One of the postal portals has opened!" },
            { id = 4065925, text = "Please keep the destruction to a minimum!" },
            { id = 4082544, text = "Somebody help! This place is a disaster!" },
            { id = 4065926, text = "This is a terrible way to run a post office." },
            { id = 4065927, text = "Ugh, corpses in the delivery room are usually a bad thing." },
            { id = 4082545, text = "Ugh, thank you! I've never seen a mailroom so disorganized!" },
            { id = 4065923, text = "Watch out! Those ticking parcels are gonna blow!" },
        } },
    } },
    { who = "Kayn Sunfury", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1243017, text = "Nice weapon you have there. Speak with Jason Alari if you'd like to help." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1241255, text = "The demons underestimate your power. Punish them for their hubris!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1240614, text = "You, Korvass and Sayana, attack the Legion from within. Then, we will wipe them out together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1281769, text = "Activate all three gateways and summon in the rest of our forces." },
            { id = 1243021, text = "Archmage Khadgar, an unexpected surprise!" },
            { id = 1281767, text = "Hmm. It would appear that they're on to us." },
            { id = 1281771, text = "I'll cut a hole through the demons and meet you in the volcano." },
            { id = 1281566, text = "Now, let's see about activating that gateway." },
            { id = 1281568, text = "Sayana. Jace. Alari. Find the Keystone." },
            { id = 1243019, text = "There's no time to land! You must dive headlong into the fray! Go!" },
            { id = 1241213, text = "Veritas is well-guarded. We need to take out the wards projecting that barrier" },
            { id = 1241223, text = "You've been spotted! Push forward! Quickly!" },
        } },
    } },
    { who = "Kazir", tier = "character", groups = {
