            { id = 6119157, text = "Did the Council send you to seize my tomes again?" },
            { id = 3731965, text = "Interlopers! You will not escape your fate!" },
            { id = 3735633, text = "Minions, destroy these meddlers!" },
            { id = 3735319, text = "No one enters these walls without my knowledge. You will not leave here" },
            { id = 3620429, text = "No, I think not. You have served your purpose. Now I must serve mine.\"" },
            { id = 4072968, text = "Rise, Mawsworn! You are called to the Banished One's service!" },
            { id = 553112, text = "Who dares violate the sanctity of my domain? Be warned, all who trespass here are doomed!" },
