    { who = "King Anduin Wrynn", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1406276, text = "FOR THE ALLIANCE!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1467381, text = "for the Alliance above all." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1467379, text = "A just cause is always worth fighting for." },
            { id = 1406273, text = "Before you stands a true champion, who has won many great victories in the name of the Alliance." },
            { id = 1406271, text = "Champion, please, step forward." },
            { id = 1406275, text = "So come friends, lend me your voices, join me in honoring our champion." },
            { id = 1467375, text = "Sometimes we must fight for what we believe in." },
            { id = 1467369, text = "Stormwind honors your service to the Alliance." },
            { id = 1467371, text = "Stormwind will endure." },
            { id = 1406274, text = "The ancient weapon they wield is a symbol of hope to those we have sworn to protect." },
            { id = 1406272, text = "We have gathered here to recognize your valor in battle. Turn and approach your peers." },
        } },
    } },
    { who = "King Anoth", tier = "character", groups = {
