    { who = "King Phaoris", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3176239, text = "TO THE WEST, ANOTHER THREAT BLOOMS" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3168070, text = "It would seem you are not the only ones." },
            { id = 3168075, text = "You will obey your king. All who would fight for Uldum are allies of Ramkahan." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3176242, text = "I fear that these visions are but the harbinger of something far more dire." },
            { id = 3168073, text = "I propose in accord with those here today that we band together and defend our home." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3176241, text = "And worst of all, our priests are plagued by unrelenting nightmares." },
            { id = 3176238, text = "In their eyes, all others are corrupted by the curse of flesh, and are enemies of the makers." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3168077, text = "Very well. Together, we will vanquish all who threaten our home, for old Doom." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3168071, text = "It is clear that Ramkhan cannot face these menaces alone." },
            { id = 3196553, text = "It is imperative that they be kept away from the forge." },
            { id = 3176240, text = "Though we suspect they hail from on Karaj, they are unlike any Karaji or Silithin we have faced before." },
            { id = 3176237, text = "We know little of the Amaphet, save that they believe themselves the sole defenders of the Titan's great works." },
        } },
    } },
