    { who = "King Rastakhan", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 2018728, text = "Welcome to Zuldazar!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2018720, text = "A gift for old Bonsamdi!" },
            { id = 2018727, text = "Be your predator, or prey." },
            { id = 2018723, text = "Habutu, Zolani, take the speaker of the Horde and ensure the war party is safe. Today is not the final day of my reign." },
            { id = 2018726, text = "May your foes tremble in your presence!" },
            { id = 2018724, text = "Rezan grant you strength" },
            { id = 2018722, text = "Talanji, take the Horde champion and master our forces there. I will work with Kragwa to secure the Sliver." },
            { id = 2018717, text = "The Blood Gate is overrun. Quickly! We must crush as many of these invaders as we can before they reach the city." },
            { id = 2018718, text = "There are so many." },
            { id = 2018721, text = "Too many are getting past us. Make for the bridge to Dazar'alu. We can force them into a choke point." },
        } },
    } },
    { who = "King Thoras Trollbane", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1416877, text = "I will do whatever it takes to preserve peace on Azeroth." },
            { id = 1416863, text = "My son, where is Galen?" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1416866, text = "Then I have failed as both a father and a king." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1416896, text = "The Realm of Shadow offers little respite to the souls of the wicked." },
            { id = 1416876, text = "Who are you that raised fallen kings from the earth? Speak." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1416935, text = "Even in a lifetime of war, I have never before seen such sacrifice." },
            { id = 1416867, text = "Is there a shortage of steel in this future world?" },
            { id = 1416868, text = "Then leave it to rust. I care not." },
            { id = 1416895, text = "Those who terrorize the innocent have no place in this world or the next." },
            { id = 1416865, text = "What has become of Stromgarde?" },
            { id = 1416864, text = "Where is the prince who murdered his king?" },
        } },
    } },
    { who = "King Tor", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1275598, text = "I deem you... unworthy." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1275596, text = "Seems I underestimated you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1275600, text = "Quickly! Let us put an end to these miscreants!" },
        } },
    } },
    { who = "King Varian Wrynn", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1248501, text = "FOR THE ALLIANCE!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1248578, text = "I get the feeling this fight isn't over yet." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1248495, text = "Back where you came from!" },
            { id = 1248474, text = "Form up, Alliance! We push them back to the portal! For Azeroth!" },
            { id = 1248460, text = "Hold fast, Alliance! We will not fall this day! Push them back to the portal!" },
            { id = 1248485, text = "one demon at a time. With me, Alliance! Leave nothing standing!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1248466, text = "Again, Jaina, it's good to see you safe." },
            { id = 1248582, text = "All forces, to Jaina!" },
            { id = 1248478, text = "Heal the wounded! We can't rest here for long!" },
            { id = 1248499, text = "We're halfway there! Take heart, Alliance!" },
            { id = 1248497, text = "We're pushing them back! Don't let up!" },
            { id = 1248487, text = "You're from the Crusade? What happened? Where is Tirion?" },
        } },
    } },
    { who = "King Varianwrynn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 852065, text = "It's heartening to see you here, Moira. You have my thanks." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 852059, text = "I can only imagine what foul business the Zandalari have with them." },
            { id = 901845, text = "I can't take much more of this!" },
            { id = 852063, text = "My champions will go. They will see what can be done and rescue who they can." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 852067, text = "Hmm. Farewell, Queen Regent." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 852071, text = "For that I'm glad. The Bronzebeards and Wildhammers will regret not having been here to share in your glory." },
            { id = 901849, text = "Ha ha ha! A mighty blow!" },
            { id = 852057, text = "This is where my agents track the Zandalari." },
            { id = 852069, text = "Well fought. I see the Dark Irons are as formidable as ever." },
            { id = 852073, text = "Well, you've done just that. Come, let us return to Ironforge and announce your victory to the Council." },
            { id = 852061, text = "Yes. This weather is not natural." },
        } },
    } },
    { who = "King Voras", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1312703, text = "AHH!" },
            { id = 1312705, text = "AHHH!" },
            { id = 1312700, text = "HI!" },
            { id = 1312702, text = "PFFFTTT!" },
            { id = 1312701, text = "YEAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1281871, text = "My queen's brood will hatch soon." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1281869, text = "They've slain me, my queen." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1281867, text = "Oh, want your little broken Trani back?" },
        } },
    } },
    { who = "King Ymiron", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1446125, text = "I HATE YOUR DAMN GODS!" },
            { id = 1446124, text = "I WILL SPEAK ON YOUR GRAVE!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 553292, text = "HMMM!" },
            { id = 553300, text = "MOOORRR!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1446126, text = "I would die a thousand deaths to see you suffer!" },
            { id = 553293, text = "You have failed your people!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1446117, text = "My hatred burns." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1446118, text = "Get it over with already!" },
            { id = 1446120, text = "Leave me be already!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 553299, text = "AHHH!" },
            { id = 553295, text = "BOOM!" },
            { id = 553303, text = "GAH!" },
            { id = 553297, text = "GRR!" },
            { id = 553291, text = "NOOO!" },
            { id = 553308, text = "YEAH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1446119, text = "If the Legion does not kill you, someday I will!" },
            { id = 1416791, text = "No, no! I am King Ymiron! I am not a servant!" },
            { id = 553304, text = "There is a reason I am king!" },
            { id = 553294, text = "You invade my home and then dare to challenge me? I will tear the hearts from your chests and offer them as gifts to the Death God, Ruab Nyagabor!" },
            { id = 553309, text = "Your death is only the beginning!" },
        } },
    } },
    { who = "Kintessa", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4317376, text = "TERROR SHALL CLAIM YOU!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4317380, text = "I have toyed with you long enough!" },
            { id = 4317382, text = "I want more time!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4317386, text = "Barely an inconvenience." },
            { id = 4317377, text = "Horror Grits You!" },
            { id = 4317379, text = "How fun! More playthings!" },
            { id = 4317375, text = "Let fear take control." },
            { id = 4317385, text = "MORTAL after all." },
            { id = 4317381, text = "Survival is not an option!" },
            { id = 4317378, text = "Trust no one." },
            { id = 4317383, text = "You deceived me." },
        } },
    } },
    { who = "Kintessa Kah Than", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4079202, text = "I am pleased we found each other, Maw Walker." },
            { id = 4079201, text = "I enjoy watching you dispatch the mawsworn so efficiently." },
            { id = 4079198, text = "I will meet you in the ruins. Thank you for assisting my search." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4073885, text = "Kill them, Maw Walker!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4079197, text = "A drop page remains, but he does not. Where have you gone, thankscribe?" },
            { id = 4079199, text = "Amazing. Have you always had such power? Or was it learned somewhere?" },
            { id = 4079203, text = "Hmph. That is clearly useless." },
            { id = 4073882, text = "Indeed we have." },
            { id = 4073886, text = "Oh, and make it quick, as a sign of gratitude." },
            { id = 4073883, text = "Thank you for all your valuable assistance, mortal!" },
            { id = 4073884, text = "You can ask him yourself once we arrive in Torghast. He is quite eager to meet you." },
            { id = 4079200, text = "Your ability to conquer your enemies is inspiring." },
        } },
    } },
    { who = "Kira Iresoul", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1406202, text = "I know some who would choose the pursuit of power over the needs of others." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1406203, text = "We can use the Bloodstone. It will be powerful enough to control the sisters when they're in a weakened state." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1406329, text = "Give me a moment to inspect this beast, and I can discover its weaknesses." },
            { id = 1406201, text = "I'll help, of course. Unlike you, I do not abandon a fellow warlock when they might need me most." },
            { id = 1406200, text = "It has indeed, and you should keep that in mind the next time you attempt to speak to me." },
            { id = 1411902, text = "I've got this." },
            { id = 1406330, text = "These scales are unlike anything I've seen." },
            { id = 1406331, text = "This demon has clearly been bred to be resistant to both magical and physical attacks." },
            { id = 1406199, text = "Use the bloodstone!" },
            { id = 1406198, text = "You did right by your fellow warlocks, which is commendable and surprising." },
        } },
    } },
    { who = "Kirin Tor Gatekeeper", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1056938, text = "Lady Proudmoore has expressly forbid Horde from entering Kirin Tor grounds." },
            { id = 1056937, text = "No outsiders allowed. Lady Proudmoore's orders." },
            { id = 1056939, text = "Very well, Archmage. As you wish." },
        } },
    } },
    { who = "Kiro", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2006373, text = "I found an ancient totem in the court of Zakrajan that has the power to raise the dead. Take it to the Bone Pits and use it to dig up some buried treasure." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2006375, text = "King Rakataka is terrorizing Bonetrail Gulch. He's too powerful to attack head-on, but he has an insatiable appetite. He'll eat himself to death if you keep feeding him." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2006366, text = "Mira, ready the wagon and be prepared to pick up supplies at the port. Our new allies can ride along and continue their search." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2006370, text = "Be safe, Meera. Our wagons don't always do well on the ancient troll roads." },
            { id = 2006374, text = "Good work. Gold coins from the ancient troll empire are worth a fortune. Here's your cut." },
            { id = 2006376, text = "Good work. May we never forget the brave Gulch Beetles that heroically sacrificed their lives to save us all from the terror of King Rakataka." },
            { id = 2006377, text = "It's impossible to grow crops in Voldun without fertilizer. We usually collect it from hyenas, but they haven't been leaving much lately. Try feeding them to speed things up." },
            { id = 2006368, text = "Nicely done. That will surely set them back." },
            { id = 2006365, text = "Nisha, thank the sands you're safe." },
            { id = 2006372, text = "She may not survive for long. Her wounds are severe." },
            { id = 2006367, text = "The Sethrak are expanding their empire, taking over the plains where our people once lived. We must put a stop to their rapid conquest!" },
            { id = 2006371, text = "This is risky, Nisha. The Faithless will know we're up here." },
        } },
    } },
    { who = "Kirygosa", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5019463, text = "I suspect you must have important business here." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5014793, text = "Stop by any time." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 5014791, text = "Ah, a new visitor." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 5014794, text = "Safe travels to you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5014790, text = "It's good to meet you." },
            { id = 5019467, text = "Look around you. Can you see why I fell in love with Pandaria?" },
            { id = 5019462, text = "Oh, I think I know of you. News of your exploits have reached even this humble village. We are honored to have you." },
            { id = 5014792, text = "Please, take care." },
            { id = 5019466, text = "Yes, I have a daily routine. I know all the villagers. I even have my own house." },
            { id = 5019464, text = "Yes, I have heard." },
            { id = 5019465, text = "You certainly took your time to pay me a visit." },
        } },
    } },
    { who = "Kisha", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1881987, text = "Let's see, scroll of eternal return sound right?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1881992, text = "About time! I thought we were the only ones who cared about Torga being dead." },
            { id = 1881994, text = "Fine, see if I care. Ugh, he acts like he built this place." },
            { id = 1881989, text = "Fine. Hmm. Here it is. Scroll of Invisibility. This has to be it." },
            { id = 1881990, text = "I'm just standing here? Okay, how's this? Does this count as pilgrim-ing?" },
            { id = 1881996, text = "Look, just keep going down this road, don't wander off, and you'll find Torga. He's a giant turtle. Hard to miss." },
            { id = 1881988, text = "Oh, dear. This one looks like it's written in the old god's language. Where did you come across something like this?" },
            { id = 1881983, text = "Oh, this has the makings of the best story ever experienced by a tortollan! Avenging Aloha, and killing the avatar of some monster!" },
            { id = 1881991, text = "Ooh, happy now? Am I moving around enough for you?" },
            { id = 1881986, text = "Ugh, this could take all day! Princess, you don't realize how many scrolls this old timer has." },
            { id = 1881995, text = "Ugh, what do you care what I'm doing? Don't criticize how I choose to do this pilgrimage." },
            { id = 1881993, text = "You should stay and help us figure out a plan. The blood trolls are too much for you to fight." },
        } },
    } },
    { who = "Kivarr", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3748186, text = "My cage has three separate locks, each with its own key. I think the trust might be afraid of me." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3748194, text = "Destroy those things quickly!" },
            { id = 3748196, text = "Stay with us, Gwaya! This curse is nearly broken!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3748190, text = "Meet me at the heart of the forest to complete the ritual. Good hunting, both of you!" },
            { id = 3748192, text = "We cannot wait for Aralon. If we do not break the curse now, Guaya will be lost forever." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3748191, text = "Aralon has yet to return with the satchel. I fear he may be in danger... or worse." },
            { id = 3748193, text = "Be ready, Maw Walker. Goraxar's sorcery will not be easily purged." },
            { id = 3748195, text = "Keep at it! The dress sold upon her is weakening!" },
            { id = 3748189, text = "Maw Walker, you gather the Nox root. Errolon, we will need a witch's satchel. Stealing one from the Drust will be a perilous task." },
            { id = 3748188, text = "Meet me back at my den. I will do whatever I can to assist you." },
            { id = 3748187, text = "Perfect timing you two, though you did cut it close." },
        } },
    } },
    { who = "Klaxxi", tier = "creature", ctype = "Aberration", groups = {
