    { who = "Kleia", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3729263, text = "HA!" },
            { id = 3729265, text = "HEH!" },
            { id = 3729251, text = "HIYAH!" },
            { id = 3729255, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3613193, text = "The Kyrian are known for their outstanding patience and calm under pressure. Even so, you are testing me right now!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3533840, text = "I understand. Thank you, Palomarck." },
            { id = 3533838, text = "My friend, I... need to reflect on this. I will meet you back at the hold." },
            { id = 3533845, text = "My weapon and my wings are yours." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3533837, text = "The Forsworn are foolish if they believe they can stop us. I will head to the Overlook." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3729333, text = "AH!" },
            { id = 3729319, text = "AHHH!" },
            { id = 3729331, text = "UGH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3533839, text = "Why do we continue to ferry souls when we know they are being sent straight to the Maw?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3533844, text = "Change is coming, and we must change with it." },
            { id = 3613195, text = "Have you ever requested a steward to not help you? I made one cry once. Just let them chase their bliss, you know?" },
            { id = 3533836, text = "Incredible. But nothing seems amiss. Are we truly witnessing his final moments?" },
            { id = 3533835, text = "We are here to aid you. Let us see your final moments." },
            { id = 3533841, text = "We must get this information to the Archon. Meet me at Hero's Rest." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 3729241, text = "AHH!" },
            { id = 3729245, text = "HMMM!" },
            { id = 3729243, text = "RRR!" },
        } },
    } },
    { who = "Koa", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3501857, text = "Don't let go Cole!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3501859, text = "Birds of a feather, stay together!" },
