        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1255508, text = "AAARGH!" },
            { id = 1255515, text = "ACHOO!" },
            { id = 1255506, text = "RAWR!" },
            { id = 1255514, text = "WAAAGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5726641, text = "And now your ankle's off!" },
            { id = 5726644, text = "Be nice to cobalt!" },
            { id = 5726645, text = "Be nice to cobwebs!" },
            { id = 5726637, text = "No one from you!" },
