    { who = "Koda Steelclaw", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1244541, text = "I am in your debt, hero. Come, let us destroy these demons together!" },
            { id = 1241929, text = "I will open the way for you, but be careful. I sense powerful magic down below." },
            { id = 1241935, text = "I will travel to the Grove of Cenarius shortly, hero. Thank you for your help here." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1244569, text = "Another wave of attackers, hold the line!" },
            { id = 1269764, text = "Anu Dora" },
            { id = 1244571, text = "Fresh adversaries approach. Fight on!" },
            { id = 1241559, text = "Give me a moment to catch my breath, hero. The long years of vigil have taken their toll." },
            { id = 1269765, text = "In Cenarius's name." },
            { id = 1244585, text = "Let me bear the brunt of Ysera's attacks, hero. You can rely on me. I am quite sturdy." },
            { id = 1244573, text = "New foes incoming! Brace yourselves!" },
            { id = 1241927, text = "The dream was clouded with such darkness." },
            { id = 1244577, text = "We have no choice. Ysera must die. She would agree, were she in her right mind." },
        } },
    } },
    { who = "Kodethi", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4662082, text = "I believe in planning, not luck." },
            { id = 4662086, text = "I calculated the odds of you annoying me, and it's one hundred percent." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4662080, text = "Back to my calculations!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 4787295, text = "AAARGH!" },
            { id = 4787321, text = "AHHH!" },
            { id = 4787297, text = "RRR!" },
            { id = 4787319, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4662081, text = "Fair skies and strong winds to you." },
