        { name = "Greetings", family = "Manners", lines = {
            { id = 3692716, text = "Hail, mortal! Lady Moonberry speaks highly of you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3692710, text = "Aim true and strike down our prey!" },
            { id = 3692714, text = "Our foes bear useful equipment and provisions. How kind they are to bring them to us." },
            { id = 3692712, text = "Our quarry lies slain. A clean strike, mortal. Well done." },
            { id = 3692711, text = "Our scouts have been tracking some dangerous prey. The hunt begins." },
            { id = 3692718, text = "These vile creatures will know the fury of the Wild Hunt!" },
            { id = 3692715, text = "What once would harm the forest will now be used in its defense. Well done." },
            { id = 3692713, text = "You fight with unbridled ferocity. They will remember it." },
