        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1993589, text = "Hang on, Scratchy! Help is on the way!" },
            { id = 1993629, text = "I'm out of here!" },
            { id = 1993595, text = "It's gonna be okay, Scratchy. Just wait there!" },
            { id = 1993593, text = "Jump down, Scratchy! I'll catch you!" },
            { id = 1993598, text = "Mummy, who's that lady?" },
