    { who = "Kultiran Raid Sailor - masculine voice", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2431953, text = "BOMBS ARE IN PLACE!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2431951, text = "Charge is set!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2432140, text = "Lord Admiral Proudmoore was as gallant as they come. She offered the Horde every chance to turn back." },
            { id = 2431962, text = "Maybe afterwards, we'll give you a proper tour. It's a lovely place." },
            { id = 2431952, text = "The deck is rigged to explode!" },
            { id = 2431963, text = "Watch that jawing back there prisoner!" },
            { id = 2431961, text = "We'll take you to the brig. You're on your own from there." },
            { id = 2431960, text = "We've been hunting for this one. A prize indeed." },
            { id = 2432143, text = "When it looked like the Horde might get the upper hand, the Lord Admiral turned the tables!" },
            { id = 2431964, text = "You ain't leaving my island with that foul wench!" },
        } },
    } },
    { who = "Kurdran", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 553536, text = "IT'S HAMMERING TIME!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
