    { who = "Kyrestia the Firstborne the Archon", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3552567, text = "ascended repel this assault paragons with me" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3555161, text = "Agreed. For the good of the Shadowlands, each mortal must choose a covenant." },
            { id = 3555158, text = "With the Primus gone, and Denathrius a traitor, our pantheon has been broken, and doom comes for the Shadowlands." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3555153, text = "You speak for Revendreth. Where is your sire? Where is our brother Denathrius?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3552559, text = "Aspirant Kleia, step forward." },
            { id = 3552568, text = "Devos must be stopped!" },
            { id = 3552564, text = "Devos, you lead this rebellion?" },
            { id = 3555157, text = "Long ago, we stood as one to imprison that... monster." },
            { id = 3567630, text = "Mortals! Take up my spear!" },
            { id = 3552560, text = "Not only are you a mentor to those around you, but also a stalwart defender of Bastion." },
            { id = 3552561, text = "Now you join the ranks of the ascended" },
            { id = 3555150, text = "The maw grows, surging with power. How did this come to pass?" },
        } },
    } },
    { who = "Kyrian", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3670017, text = "YOU WILL NOT EVADA GRASP, MORTALS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3670011, text = "Struggle all you like, mortals. You cannot escape your fate!" },
            { id = 3670020, text = "These allies of yours are insignificant! You will all end up in chains!" },
            { id = 3670012, text = "Your chains will be eternal!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3670021, text = "It is useless to resist!" },
            { id = 3670019, text = "There is nowhere to run! Nothing escapes the Maw!" },
            { id = 3670018, text = "Your cell awaits, mage. The jailer has plans for you!" },
        } },
    } },
    { who = "Kyrian Almost Fallen", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3476740, text = "Is there no hope?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3476744, text = "I don't know what to do." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
