            { id = 3574367, text = "I wonder if this island will kill me, again." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3574372, text = "Let's see if we can find one of those rituals." },
            { id = 3574364, text = "Stay alive for whatever that's worth" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3574369, text = "Welcome to the party!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3574373, text = "A dark pit, and darker magic. I think we found the ritual." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3574366, text = "Have fun facing certain deaths" },
            { id = 3574368, text = "Never a dull moment with the Horde!" },
            { id = 3574375, text = "Oh good, you made it out!" },
            { id = 3574370, text = "Quit it unless you want to be dead, too" },
            { id = 3574371, text = "Quite the storm. Probably hit the first boat, too." },
            { id = 3574374, text = "You're the only hope those survivors have left no pressure" },
        } },
    } },
    { who = "Lang the Cunning", tier = "character", groups = {
