        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 621971, text = "BOOORRR!" },
            { id = 621979, text = "GRRR!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 622005, text = "Our clan holds true to the ways set forth by the ancients. We deserve the king's favor above all others." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 622003, text = "These other clans aren't worthy of your time, great king." },
            { id = 622019, text = "This is the might of Hothak." },
        } },
    } },
    { who = "Lanigosa", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1390740, text = "If you desire, I can take you back to your city in the sky. I will return later for Galford's remains." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1388301, text = "I should get back to it." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1390742, text = "I am truly sorry. It looks as though your friend was crushed. What could have..." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1390732, text = "There, a bit of magic to help you follow in Galford's footsteps. Good luck!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5062278, text = "Blue is best." },
            { id = 1388303, text = "F.L.I.L.L. is best." },
            { id = 1390731, text = "Galakrond's Rest can be dangerous. Perhaps a tracking spell will be of use." },
            { id = 1390741, text = "I've been looking all over for you. Have you found- Oh no." },
            { id = 1388300, text = "See you around!" },
            { id = 1388304, text = "What brings you out here?" },
            { id = 1390743, text = "What is this essence the giant speaks of? I would have words with you." },
        } },
    } },
    { who = "Laochen", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 634843, text = "HWAH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 634913, text = "AHEM!" },
            { id = 634899, text = "AHHH!" },
            { id = 634901, text = "MUHAHAHA!" },
            { id = 634903, text = "UGH UGH UGH!" },
            { id = 634909, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 634987, text = "Got something to show me?" },
            { id = 634947, text = "Mm-hmm." },
            { id = 634945, text = "See you!" },
            { id = 634997, text = "That's so tired." },
            { id = 634993, text = "Well, that's not annoying." },
            { id = 634985, text = "What's going on?" },
            { id = 634983, text = "Yeah?" },
            { id = 634995, text = "You don't quit, do you?" },
        } },
    } },
    { who = "Lapisagos", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4643365, text = "BEG FOR THE MERCY OF YOUR ARCANE PRISONS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4643367, text = "You are... out of... time..." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4643364, text = "I have spent ages guarding you aberrations!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4643241, text = "Come forth, loyal servants of Malygos!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4643307, text = "If they will not sleep, then they must be destroyed." },
            { id = 4643242, text = "Show no mercy to these aberrations!" },
            { id = 4643366, text = "The Blue Dragonflight will push you back in your place." },
            { id = 4643306, text = "The Drakthir are relics of a forgotten past. They have no place in Azeroth." },
            { id = 4643226, text = "The Drapthear are breaking free! Contain them!" },
            { id = 4643363, text = "You dare defy the will of Malygos?" },
        } },
    } },
    { who = "Larodar Keeper of the Flame", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5343506, text = "REVEL IN FLAME" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5343505, text = "Bask in fire!" },
            { id = 5321018, text = "Bear witness to the purity of flame and be consumed." },
            { id = 5343501, text = "Flame protects the faithful!" },
            { id = 5343508, text = "Guardians protect me!" },
            { id = 5321016, text = "The age of dreaming comes to an end." },
            { id = 5343504, text = "The inferno burns within me." },
            { id = 5321017, text = "This seed will be the ember that burns the world." },
        } },
    } },
    { who = "Lasan Skyhorn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1274857, text = "If you are ready to depart, Aviash can fly you to Thunder Totem." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1274851, text = "I have already ordered my eagle riders to make for Thunder Totem. You may find the air a bit thicker with feathers soon." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1274626, text = "Come champion, let us pluck this witch queen from her throne." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1274630, text = "Ha! Now that was a battle!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1274847, text = "Together, we are Highmountain!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1277244, text = "As Highmountain, we are one!" },
            { id = 1274855, text = "Good! I am not one for ceremonies, so let's get this over with." },
            { id = 1274849, text = "Let it be known that I, Lassan Skyhorn, Chieftain of the Skyhorn Tribe, once again declare my allegiance to Highmountain." },
            { id = 1274616, text = "Skyhorn! Take to the air and show these harpies and their rocks the meaning of battle!" },
            { id = 1274614, text = "Skyhorn, to me!" },
        } },
    } },
    { who = "Lashk", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1883723, text = "Of course! I've got scrolls older than you are! In case you haven't looked through my stuff." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1883728, text = "I never told you that story? Oh, it was amazing. Let's see where to begin." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1883726, text = "Ha! I knew I had that somewhere. This'll keep us hidden enough to sneak around the blood trolls. Just stay close to me." },
            { id = 1883732, text = "Nah, this place isn't so bad. We're on a pilgrimage, and I have a feeling you're gonna make it harder than it has to be." },
            { id = 1883727, text = "No! Did you even bother reading it? But, uh, keep that handy. We'll need it when we're done with this mess." },
            { id = 1883729, text = "Okay, fine, you can come along. But keep the noise down. This is a pilgrimage, not a party." },
            { id = 1883735, text = "Those things will be the death of you. They're nastier than the blood trolls we encountered on the last pilgrimage." },
            { id = 1883731, text = "Well, it was gonna be a pilgrimage for Trotolans to hear Torga's stories, but I guess you can come with us." },
            { id = 1883734, text = "Well, look at that. The others are finally getting off their shelves to come down." },
            { id = 1883736, text = "Yeah, well, we're not looking to join any causes, but we won't stop you from walking with us." },
            { id = 1883725, text = "Yeah, yeah, we're coming." },
            { id = 1883724, text = "You know, I think we might actually kill this herald of C'Hoon." },
        } },
    } },
    { who = "Latosius", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1514110, text = "HAH!" },
            { id = 1514114, text = "HRRRTTT!" },
            { id = 1514112, text = "RAAAGH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1514117, text = "COUGH!" },
            { id = 1514116, text = "HUH!" },
            { id = 1514119, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1334362, text = "Guards! Hold them off! We must prepare!" },
        } },
    } },
    { who = "Laurent", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 3643096, text = "Ah, here is one. Buried in the ash." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3643090, text = "Excuse me, hello! Over here, in the shadows. I could use your assistance." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3643101, text = "Fragments should never be discarded, they can be used to repair nearly any broken mirror." },
            { id = 3643092, text = "Just a moment, I will need my cloak before we head into the light." },
            { id = 3643099, text = "Mirrors are a magical network of sorts." },
            { id = 3643093, text = "Much better, though it does have a putrid stench." },
            { id = 3643094, text = "Now, come along. I will show you how to locate mirror fragments." },
            { id = 3643091, text = "Please do hurry. I cannot enter the light without my cloak." },
            { id = 3643095, text = "The only thing this wretched light is good for is making the fragments easier to find." },
            { id = 3643097, text = "To the untrained eye, all mirror shards look identical. But I can tell by the glint alone where that shard came from." },
            { id = 3643100, text = "Travel between them is possible, so long as each is made from the same type of glass." },
            { id = 3643098, text = "Up ahead. I see another." },
        } },
    } },
    { who = "Lea Stonepaw", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1384630, text = "I will heal you, Guardian!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1384482, text = "Let's get going." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1384465, text = "Great Ursul, wise bear of the woods, this daughter of the wilds calls to you. Please accept these humble offerings and grant us an audience." },
            { id = 1384473, text = "I've seen what this hero can do. I will gladly help." },
            { id = 1384462, text = "Mighty Ursul, our ancient foe has returned. My companion has traveled here to seek your aid in recovering the claws of Ursoc." },
            { id = 1384464, text = "Now that we have Ursul's blessing, we can travel into the Emerald Dream and retrieve the claws. Come, let's not waste a single minute!" },
            { id = 1384629, text = "Stand within my healing circle, Guardian, and be restored." },
            { id = 1384628, text = "The Moonwell water is essential. Don't leave the Dream Grove without it. I'll await your arrival in Grizzly Hills." },
            { id = 1384557, text = "We shall meet again. May Elune guide our paths." },
            { id = 1384480, text = "We should get back to the Dreamgrove. The Ark Druid will know how to unlock the power of the claws." },
            { id = 1384481, text = "We're past the wards, but what's going on here? Could the nightmare have spread to Ursoc's lair?" },
            { id = 1384600, text = "You're not one of my pack. What brings you to the Den?" },
        } },
    } },
    { who = "Lead Foreman Krome", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 6180263, text = "I got some new puppies to try out, and I don't mean the hyena." },
            { id = 6180266, text = "My service awards!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6180265, text = "Time to try the shiny new weapons!" },
        } },
    } },
    { who = "Leandro Royston", tier = "character", groups = {
        { name = "Mockery", family = "Menace", lines = {
            { id = 1970829, text = "I need volunteers to head up to Ashton's place. He might be able to rig up some flares." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1970831, text = "Don't let any of those monsters through! We killed their behemoth, but we lost too many boats." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1970827, text = "healers need to rotate out and get some rest. That means you too, Kristen." },
            { id = 1970825, text = "If she does that, she'll have my full support." },
            { id = 1970833, text = "Keep it up, people! We're holding those bastards off!" },
            { id = 1970832, text = "Night's coming. Be sure to keep those watchfires going. Call out if you need more fuel." },
            { id = 1970830, text = "Once you've had a rest, switch out with someone else on the barricade. We must outlast these fiends." },
            { id = 1970826, text = "Reinforce the barricade, use anything that isn't nailed down, and when that runs out, start pulling up the nails!" },
            { id = 1970828, text = "See that the children are fed first, then feed the injured." },
            { id = 1970824, text = "She has? I thought they were just a legend." },
            { id = 1970823, text = "We cannot thank you enough for showing up when you did, Lieutenant." },
        } },
    } },
    { who = "Left", tier = "character", groups = {
        { name = "Farewells", family = "Manners", lines = {
            { id = 4681119, text = "She's going to cause a lot of trouble if she's left alone. Good luck." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4667578, text = "I'll be here." },
            { id = 4667584, text = "Keep it up and you'll need a bodyguard." },
            { id = 4667582, text = "Mmm. I'm a fighter, not a talker." },
            { id = 4667577, text = "On your way then!" },
            { id = 4667585, text = "Setting Garrosh free started a war, but we needed that war to prepare for the Legion." },
            { id = 4667583, text = "The prince is my priority." },
            { id = 4667581, text = "This better be important!" },
            { id = 4681118, text = "This meat grinder is a good leader, and she's riding high from that victory at the outpost. Her soldiers adore her." },
            { id = 4667580, text = "What is it?" },
            { id = 4667579, text = "You cross the prince, you cross me." },
        } },
    } },
    { who = "Legion Ghost Eredar Caster", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1684702, text = "NOGGERS. WILL. RISE." },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1684695, text = "Suffer for your folly!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1684697, text = "Run while you can." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1684703, text = "Argus will rise!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1684699, text = "The Eredar reigns!" },
            { id = 1684705, text = "There is nowhere to run." },
            { id = 1684701, text = "Why is it dark?" },
        } },
    } },
    { who = "Legion Ghost Eredar Melee", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1684762, text = "Run, while you can." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1684769, text = "Argus will rise!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1684763, text = "Brother, while you can..." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1684761, text = "Sargeras cannot be denied!" },
            { id = 1684764, text = "The Eridar... Raine..." },
            { id = 1684759, text = "This will be the last death you reject!" },
            { id = 1684758, text = "This will be the last gift you reject!" },
            { id = 1684767, text = "Why is it dark?" },
        } },
    } },
    { who = "Leishen", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 800409, text = "I am Lei Shen, slayer of kings and gods, you have made a grave mistake." },
            { id = 800415, text = "You have sealed your doom." },
            { id = 800421, text = "You have swept the filth from my doorstep. Perhaps you are worthy of my attention." },
            { id = 800425, text = "You! You have earned my ire! I will make an example of you, such that all who look upon my might will tremble and submit!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 800413, text = "My power cannot be contained!" },
            { id = 800401, text = "The unworthy have not yet learned of my power." },
            { id = 800403, text = "War God Al-Chukla, add my strength to your own." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 800419, text = "Mwahaha! These insects do not know their place, Gadazol! If you wish to prove your might on such weaklings, it matters not to me." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 800423, text = "But your trespass ends here! None may enter my forbidden stronghold! I shall rebuild this bridge with your bones for bricks!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 800405, text = "Make a demonstration of these invaders, such that all nations tremble before me." },
            { id = 800407, text = "Shamboom! Secure the inner courtyard. None should look upon my works and live." },
        } },
    } },
    { who = "Leishui", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 631882, text = "STAY AWAY FROM ME!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
