    { who = "Leothraxion", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1411992, text = "NOTHING CAN HIDE FROM THE LIGHT!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
