    { who = "Lespin Silverleaf", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1500460, text = "GAH!" },
            { id = 1500458, text = "HA!" },
            { id = 1500461, text = "UGH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1404476, text = "It does not matter what could happen to his reputation. He has already ruined it. This is why you are still an apprentice." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1404474, text = "I always suspected something was amiss with you." },
            { id = 1404477, text = "My work is second to none." },
            { id = 1404473, text = "my work will shine" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1404475, text = "An amateur merchant embraces excuses. A master embraces solutions." },
            { id = 1404480, text = "Do return soon. Perhaps as a customer." },
            { id = 1404478, text = "Each of my pieces is impeccable, even the ones made by my apprentice." },
        } },
    } },
    { who = "Lethka", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5332766, text = "FRAK will end you." },
            { id = 5332782, text = "Your precious ideals will mean nothing when Farrokh is done with the Wellspring. All will be flames." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5332751, text = "I removed an obstacle." },
            { id = 5332825, text = "I will be the one to smash the barrier to pieces. Then Virnoff will see how wrong she was to leave us." },
            { id = 5332763, text = "I will enjoy burning you to ash, then melting your precious ice incarnates!" },
            { id = 5332810, text = "Virenoth neglected my power, but Varak will not. If I prove myself here, I could become as mighty as the incarnates." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5332813, text = "Cinder Summit will serve our needs. Only I am strong enough to harness the power within that mountain. Not these... servants." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5332816, text = "How dare he? I alone am worthy to receive this power. Ferak chose me!" },
            { id = 5332757, text = "Now, I have a mountain to explode." },
            { id = 5332769, text = "The Cinder Summit's power will crush that barrier!" },
            { id = 5332754, text = "You abandoned us to your regrets. Farrakh continued on the path to victory." },
            { id = 5332760, text = "You threw away power for ideals. I WILL NOT!" },
        } },
    } },
