            { id = 1686174, text = "Fight well, traveler." },
            { id = 1686102, text = "Many gave their lives to hold this ground, honor their sacrifice, and drive these demons back into the abyss!" },
            { id = 1686105, text = "There's nothing more I can do, Commander. They are with the Light now." },
            { id = 1686106, text = "There's nothing more I can do, Commander. They're with the Light now." },
            { id = 1686100, text = "They gave everything to this war. We must honor that sacrifice." },
            { id = 1686172, text = "We shall see the Legion's end." },
        } },
    } },
    { who = "Lightspawn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3489146, text = "Ah, Freedom. You have my gratitude." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3489143, text = "But the Ogres ensnared me. Drained my power." },
            { id = 3489144, text = "Free me so I might recover and pass some of my power to you." },
            { id = 3489142, text = "I attempted to bring an end to these rituals." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3489147, text = "Accept my blessing and end the necromancy that plagues this island." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3489141, text = "Dispel the foul magic that binds me here." },
            { id = 3489145, text = "The spell is weakening. The light returns to me." },
        } },
    } },
    { who = "Lihuvim", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4325278, text = "Clearing the clutter!" },
            { id = 4325279, text = "Dematerialization beams purge all disorder!" },
            { id = 4325281, text = "Deploying Spatial Hindrances!" },
            { id = 4325282, text = "Domination does not relent. Neither can we." },
            { id = 4325277, text = "Measure twice. Cut once." },
            { id = 4325275, text = "Perhaps, if the combatants are SHIFTED!" },
            { id = 4325285, text = "Recording this new information." },
            { id = 4325280, text = "Reducing Safe Pathways!" },
            { id = 4325276, text = "The alignment shall be rearranged." },
            { id = 4325284, text = "There is much to be learnt!" },
            { id = 4325283, text = "These designs must be rigorously tested!" },
        } },
    } },
    { who = "Lili Stormstout", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 635768, text = "HEY!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 635760, text = "Alright, let's go!" },
            { id = 635776, text = "Huh, my Uncle Chen traveled all over the world, on foot, and he's still fat." },
            { id = 635780, text = "Is it just me, or are you being kind of weird and dumb?" },
            { id = 635758, text = "Kay, see you around!" },
            { id = 635762, text = "Wha-?! You gotta go already?" },
            { id = 635772, text = "Whatcha doin'?" },
            { id = 635770, text = "What's up?" },
        } },
    } },
    { who = "Lilian Voss", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
