    { who = "Liu Flameheart", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 617421, text = "LEAVE THIS PLACE!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 617427, text = "AHHH!" },
            { id = 617433, text = "HA!" },
            { id = 617425, text = "HUH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 617475, text = "GAH!" },
            { id = 617461, text = "OOF!" },
            { id = 617457, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 617487, text = "Be aware of your serpent's movements. Focus, then strike as one!" },
            { id = 617419, text = "The heart is mine!" },
            { id = 617409, text = "The heart of the great serpent will not fall into your hands!" },
            { id = 617497, text = "The Serpent Rider's path is drenched in blood and tears. Your journey has just begun." },
            { id = 617485, text = "To be a serpent rider, one must not fear pain." },
            { id = 617495, text = "Train your serpents well. A bond of trust is your strongest weapon." },
            { id = 617493, text = "Weakness will not be tolerated. Only strength prevails." },
            { id = 617491, text = "When you chose this path, you bound your life to that of your serpent. Do not fail them now!" },
            { id = 617489, text = "Yesterday. Today. Tomorrow. You and your serpent act as one." },
        } },
    } },
    { who = "Loathstare", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 554231, text = "The races of the world will perish. It is only a matter of time." },
            { id = 554234, text = "You are mine now." },
            { id = 554235, text = "You are next." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 554232, text = "Close your eyes, sleep." },
            { id = 554229, text = "Soon, the world will tremble." },
            { id = 554228, text = "The end is upon you." },
        } },
    } },
    { who = "Locus Walker", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1679415, text = "Here's a hint. It's an ancient word of power. If I whisper it in your ear, your mind will fall into madness. Still want to play?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1688857, text = "I have something I want to show you. But we mustn't be seen. Follow." },
            { id = 1679406, text = "I represent an alternative." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1679414, text = "But by all means, if you want to see reality itself torn asunder, keep asking about my name." },
            { id = 1679411, text = "Careful. I dabble in powers beyond your comprehension." },
            { id = 1679405, text = "Do go on." },
            { id = 1679410, text = "Fascinating. Simply fascinating." },
            { id = 1679408, text = "Flesh is fickle, power endures." },
            { id = 1679407, text = "It is all about perspective." },
            { id = 1679409, text = "Try not to waste my time." },
            { id = 1679413, text = "Were I to speak it aloud, a thousand void portals would rip open, and some very unpleasant entities would come looking to collect on old depths." },
            { id = 1679412, text = "Yes, I do have a real name. It's none of your business." },
        } },
    } },
    { who = "Loken", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 554249, text = "HWAH!" },
            { id = 554257, text = "UGH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 554267, text = "AHHH!" },
            { id = 554265, text = "OOH!" },
            { id = 554251, text = "UGHHH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 554256, text = "What hope is there for you? None!" },
            { id = 554260, text = "What little time you had, you wasted!" },
        } },
    } },
    { who = "Lor the Mar Theron", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1800199, text = "Lady Liadrin, champion, you are most welcome. As you can see, we have an... unexpected visitor." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1800203, text = "I had hoped your visit was motivated by a love for Silvermoon. Instead, you come at the behest of the Alliance's boy-king. How disappointing." },
            { id = 1800200, text = "I see no need to keep secrets from allies, Illyria. In fact, some new friends of ours are just arriving." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1800204, text = "You doubt my words, yet how can we trust your own? Do you deny that the Lords of the Void whisper to you? Did you not surrender yourself to the shadows on Argus?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1800198, text = "Enough! We need to cleanse this corruption before the Well is lost!" },
            { id = 1800202, text = "Nonsense! Whatever you came to say, you may say in front of our guests." },
            { id = 1800207, text = "Please follow me." },
            { id = 1800201, text = "Please, call me Lor'themar. But where are my manners? Allow me to introduce another guest, Lady Alleria Windrunner, a hero of Silvermoon's past." },
            { id = 1800206, text = "Ramath, kindly open the way for us." },
            { id = 1800208, text = "The Sunwell is secure. Your aid was invaluable, Thalyssra, and yours, champion." },
            { id = 1800197, text = "What is happening?" },
            { id = 1800205, text = "Whatever she has become, Alleria is a daughter of Quel'Thalas. I will not deny her pilgrimage to our most sacred site. First Arcanist, you and your retinue would be welcome to join us." },
        } },
    } },
    { who = "Lorash", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2061974, text = "Damn! This was supposed to be quick and quiet! Focus!" },
            { id = 2061973, text = "Kill this one quickly, before they alert the others." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 2061982, text = "That wasn't a guard, but far be it from me to stop us from murdering the Alliance." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 2061976, text = "Ah, Ah, Ah, no, no, this one belongs to me." },
            { id = 2061983, text = "Hey, careful with the civilians. We may draw the guards' attention." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2061978, text = "No, no, no. The city's in an uproar. I'll get us out of here." },
            { id = 2061977, text = "Nothing quite as satisfying as taking out an alliance commander, and so easily." },
            { id = 2061975, text = "Sloppy, sloppy, sloppy! Make less noise next time!" },
            { id = 2061981, text = "Technically, we don't need to kill the civilians, but I like your style." },
            { id = 2061979, text = "That should do it. How does it feel to single-handedly sack an entire city?" },
            { id = 2061972, text = "Try not to get spotted. We can't draw too much attention." },
            { id = 2061980, text = "You're cold as ice. I like it." },
        } },
    } },
    { who = "Lord Andestrasz", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4679274, text = "Call upon your Drake companion, then drop off the edge while moving forward. You will glide to your destination." },
            { id = 4679273, text = "First, you will learn how to glide with a Drake and move efficiently about the peaks. Come, let us get started with some quick lessons." },
            { id = 4679271, text = "Welcome. I'm glad you are ready to explore our wondrous isles." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4679269, text = "Ah, caught a good wind stream lately." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4679275, text = "As you aim for the ground, you'll pick up speed. Use this to fly faster, then level out to reach your destination." },
            { id = 4679270, text = "Careful, those downdrafts are brutal." },
            { id = 4679264, text = "Fair skies and strong winds." },
            { id = 4679268, text = "How fair the winds today!" },
            { id = 4679265, text = "Keep your feet off the ground!" },
            { id = 4679272, text = "Our drakes are excited to take to the skies of the Dragon Isles once more, and for you to provide an extra set of eyes to help them. This is Dragonriding!" },
            { id = 4679266, text = "See you up there!" },
            { id = 4679267, text = "The sky cools." },
        } },
    } },
    { who = "Lord Brannon Stormsong", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2011628, text = "I am doing what I can." },
            { id = 2011629, text = "I failed my subjects. I lacked authority and they sought direction elsewhere because of it." },
            { id = 2011631, text = "I must prove myself to my uncle." },
            { id = 2011630, text = "I suppose that's it then." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2011627, text = "Help! I'm being attacked!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 2011633, text = "I'm sorry, can you please leave me be?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2011622, text = "A... a cult has taken hold of this town due to my inan- oh... inadequacy!" },
            { id = 2011624, text = "Angle point is under my watch." },
            { id = 2011623, text = "Anglepoint has been saved, but my fear still lingers. Deep Warden, as smart a man as he was, did not hold that kind of power previously." },
            { id = 2011625, text = "Do you believe that the sea creatures have been affected too?" },
            { id = 2011632, text = "Now I must return home. My uncle and his tide sages in Stormsong Valley may have more information about this dark magic." },
        } },
    } },
    { who = "Lord Chamberlain", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3582143, text = "BEHOLD THE MIGHT OF THE VENTHIR!" },
            { id = 3582145, text = "BURN IN ANIMA!" },
            { id = 3582146, text = "THE ANIMA OVERFLOWS" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3772937, text = "HEH!" },
            { id = 3772933, text = "HMMM!" },
            { id = 3772931, text = "HRRR!" },
            { id = 3772935, text = "ROAR!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3502020, text = "Your generosity is as vast as your wisdom, master. Your will be done." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3582147, text = "I have anima to spare!" },
            { id = 3546941, text = "I humbly present the maw walker." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 3582144, text = "You are no match for my power!" },
