        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3772963, text = "AAARGH!" },
            { id = 3772969, text = "GAH UGH!" },
            { id = 3772967, text = "GAH!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3546940, text = "Begging my master's pardon." },
