    { who = "Lord Maxwell Tyrosus", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1243031, text = "Excellent! Meet me at Crassus's Landing when you are ready. I've assembled the Argent Crusade's finest to join us to rescue Highlord Tirion." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1243023, text = "Ready yourselves, men. The Broken Shore awaits. We leave on our champion's command." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1243027, text = "You brave souls have been chosen to strike into the depths of Hell itself to rescue Highlord Tyrion. This is your last chance to turn back." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1241259, text = "We must go to Light's Hope Chapel at once. High Lord Forgering deserves to be put to rest among the ancient heroes of the Light buried there." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1241229, text = "Argent Crusade, charge!" },
            { id = 1241277, text = "Champion, I'll signal for our hippogriff riders to get our fallen Delights hope Chapel you must forge ahead and find the high lord" },
            { id = 1241207, text = "Thank the Light I found you. I must speak with you at once." },
            { id = 1243033, text = "The demons before us are all that stand between us and the Ashbringer. Regardless of the outcome, our families will know that we fought for the freedom and safety of our world." },
            { id = 1241217, text = "The fiends have Tyrion! We have to act quickly!" },
            { id = 1241267, text = "We have to get out of here before more demons come. Quickly, the High Lord is just outside the temple." },
            { id = 1243025, text = "We move on our champion's command." },
            { id = 1243029, text = "You must come quickly. Tyrion called for you by name. I fear he does not have long for this world. Hurry!" },
        } },
    } },
    { who = "Lord Roccor", tier = "character", groups = {
