    { who = "Lord Smolderon", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1444499, text = "I AM FURY INCARNATE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1407188, text = "Approach my throne, and we shall see just how far you will go to save this world." },
            { id = 1406839, text = "If you are unafraid of death, meet me at my throne. You may prove useful after all." },
            { id = 1407257, text = "Your champions crumbled, Pyroth." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1406844, text = "Destroy the impostor, shaman! Bring me his heart!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1406837, text = "Fire Lord, you are nothing but a pile of rocks!" },
            { id = 1406838, text = "Perhaps I underestimated your strength." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407187, text = "The Burning Legion threatens us all, but the power of the Firelands must be earned." },
            { id = 1407256, text = "These mortals do my bidding. A pity you do not share their enthusiasm." },
            { id = 1406853, text = "Tread carefully in my domain, shaman. Even Farseers can burn." },
            { id = 1406840, text = "You may enter, but spare me your pleas for help, shaman. I know of the Earthen Ring's plan to unite the elements." },
        } },
    } },
    { who = "Lord Stormsong", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2010450, text = "I grow tired of this. Your end is now." },
            { id = 2010457, text = "I look forward to drowning you myself!" },
            { id = 2010456, text = "I will tolerate your insolence no longer!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2010455, text = "Oceans surge! Arise, my minions!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2010451, text = "As sure as minions are endless, why resist?" },
            { id = 2010452, text = "Crawling horrors come and feed." },
            { id = 2010449, text = "darkness take you" },
            { id = 2010454, text = "Deep creatures, hear my call." },
            { id = 2010453, text = "Nightmarish beasts, come forth!" },
            { id = 2010458, text = "The tides move against me." },
        } },
    } },
    { who = "Lord Varothen", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 573318, text = "AHHH!" },
