    { who = "Lord Waycrest", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1969165, text = "I don't believe I left them with Lucy's letters, but I suppose it's prudent to be sure." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1969163, text = "Lucy is merely following her heart, Meredith, just as I did when I wed you." },
            { id = 1969166, text = "Oh you found it, thank the tides." },
            { id = 1969168, text = "Oh, and do convey my apologies for the delay." },
            { id = 1969169, text = "Please forgive my tardiness." },
            { id = 1969167, text = "Please inform the happy couple I will be down shortly." },
            { id = 1969170, text = "She will be down shortly. She asked that I begin in her stead." },
            { id = 1969164, text = "While I am thankful for your help, I must ask that you not rummage through my daughter's undergarments." },
        } },
    } },
    { who = "Loren Stormhoof", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1500079, text = "BOO!" },
            { id = 1500083, text = "BOOM!" },
            { id = 1500080, text = "HMM!" },
            { id = 1500076, text = "HMPH!" },
            { id = 1500074, text = "HUH!" },
            { id = 1500078, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1411911, text = "I will find the way." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1445810, text = "As with those that came before me, I pledge my service to you and the Unseen Path." },
        } },
    } },
    { who = "Lorewalker Cho", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 798920, text = "I do not see any rainbows today, do you?" },
            { id = 798914, text = "I will be the Thunder King." },
            { id = 798912, text = "It is thunder that sends animals cowering and fills the hearts of peasants with dread. Let thunder be my herald, so that my power is felt throughout the land.\"" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3184826, text = "Wait, there is one more tome we could search. Bring me a copy of The Origins of the Mogu." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3184813, text = "Ah, champion! Just as new dangers threaten Pandaria, her heroes make a triumphant return." },
            { id = 634560, text = "Hello" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 634554, text = "Farewell." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3184824, text = "Stubborn and prideful, the Baroque used the spirits of the dead to animate the statues littering their ruins and turn them into immortal soldiers." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3184817, text = "After his defeat, the Mogu splintered and began warring for dominance. Many new clans arose from the ashes." },
            { id = 3184816, text = "As you know, the Mogu clans were once again united by the resurrected Fandaking Leshan." },
            { id = 798904, text = "But Lei Shen did not agree." },
            { id = 798908, text = "But thunder, thunder, thunder proclaims the coming of the storm." },
            { id = 798902, text = "His followers fell to their knees before him. We will call you the Lightning King, they said." },
            { id = 634564, text = "Hmm?" },
            { id = 3184820, text = "However, I see nothing pertaining to our mysterious sigil. Perhaps my copy of Power Through Blood holds the answer." },
            { id = 798900, text = "It is said that he tore out the very heart of the Mogu god, and from that hateful act he gained power over wind and storm." },
            { id = 798918, text = "It is said that, after the revolution, the Red Crane of Hope placed the rainbow in the sky, so that Pandaren would know not to fear the storms any longer." },
            { id = 634552, text = "Jade Serpent guide you." },
            { id = 798906, text = "Lightning strikes in an instant and is over in a flash, he said." },
            { id = 3184821, text = "Masters of blood magic, the Dokkani bolster their ranks with powerful war machines fueled by the life essence of those they conquer." },
            { id = 634574, text = "Oh, history will make note of your deeds." },
            { id = 798916, text = "Oh, my friend, that awful sound. For a hundred, hundred generations, the Crash of Thunder filled the hearts of Pandaren with terror." },
            { id = 634570, text = "Oh, now cut that out." },
            { id = 634572, text = "Oh, stop now! Don't poke the bear!" },
            { id = 634562, text = "Pandaria welcomes you." },
            { id = 3184818, text = "Perhaps this sigil belongs to one of them. Let's begin our search with my copy of The Serpent Masters." },
            { id = 798898, text = "The Mogu tell a legend about Leshan, the Thunder King." },
            { id = 3184825, text = "The sigil does not appear here, Hila. Could it be we've not encountered these mogu before?" },
            { id = 3184822, text = "This looks nothing like the sigil though. See if you can find a copy of Wheel of Stone." },
            { id = 3184814, text = "This will surely be a tale to remember, but enough prattling. How can I help?" },
            { id = 798910, text = "Thunder quakes the skies long before the lightning strikes, and thunder echoes in the hills long after lightning's power is spent." },
            { id = 634550, text = "Tread lightly." },
            { id = 3184819, text = "With their command over storm and serpent, many consider the Xantian the dominant clan, though the others surely disagree." },
        } },
    } },
