        { name = "Threats", family = "Menace", lines = {
            { id = 798950, text = "Proudmoore! You will release my people from the Violet Hold, or I will cut you down myself!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 798966, text = "I have selected a landing site for our forces, a small peninsula to our east that is easily defended." },
