    { who = "Lothraxion", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1504235, text = "GO" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1504232, text = "Farewell." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1416677, text = "Allies, do not despair. It is I, Lothraxion, High Commander of the Grand Army of the Light." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1504236, text = "Act swiftly." },
            { id = 1504233, text = "Be strong." },
            { id = 1504237, text = "Death to the Legion!" },
            { id = 1504234, text = "Fight On!" },
            { id = 1416679, text = "Heroes, rally beneath the light! Balnazzar! Prepare to meet your end!" },
            { id = 1416675, text = "Highlord, let us return to your order hall. We have much to discuss." },
            { id = 1416678, text = "On order of High Exarch Turalyon, we came as fast as we could. I am sending reinforcements down to join you." },
            { id = 1416676, text = "Prophet Velen, Warriors of Light, a well-earned victory. I expected nothing less from the heroes of Azeroth." },
            { id = 1417509, text = "The light is everywhere. I welcome it, whether in glory or death." },
        } },
    } },
    { who = "Lothrius Mooncaller", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1405222, text = "I will defend this place to my last." },
            { id = 1405223, text = "My home may be in ruins, but I will remain strong." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1405224, text = "The Moonguard will soon be no more." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1405218, text = "You found them! I will have them properly preserved and sent somewhere safe immediately." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405221, text = "Are you here to help us?" },
            { id = 1405220, text = "Behold the plight of the Moonguard." },
            { id = 1405219, text = "Your timing is impeccable." },
        } },
    } },
    { who = "Lucille Waycrest", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1860900, text = "I can't believe we're here. My father used to tell me stories about this place." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1860907, text = "Wait, what was that?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1860909, text = "I'm sorry, Mainlander. The Coven's magic must be disturbing the spirits of the ancient Drust. We'll have to be careful." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1860898, text = "Bella, I'll need you to follow this one and carry the supplies they find, okay?" },
            { id = 1860905, text = "Drustvar was their ancestral home. It was from here that they launched endless raids into our fledgling hamlets." },
            { id = 1860899, text = "Gya! Ride to Aram's stand, Bella." },
            { id = 1860901, text = "It contains an ancient secret of our house from back when the Waycrests first settled this land." },
            { id = 1860904, text = "Long ago, when Kul Tiras was first settled, our people encountered a savage group of warmongering barbarians. They called themselves the Drust." },
            { id = 1860903, text = "That's it. The way is opening." },
            { id = 1860906, text = "This carried on for countless years, until the ancestors of House Waycrest decided that something had to be done." },
            { id = 1860902, text = "We just need to find the entrance." },
        } },
    } },
    { who = "Luena", tier = "character", groups = {
