    { who = "Lukou", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5556924, text = "I be here, always." },
            { id = 5557057, text = "I be takin' ya to break the effigies." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5556973, text = "Go on now." },
            { id = 5557051, text = "Hold on tight!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 5556918, text = "Greetings, young one." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5557105, text = "Grabbed a feather, didn't we go up?" },
            { id = 5556964, text = "in the morrow." },
            { id = 5556912, text = "Let us make you whole." },
            { id = 5556958, text = "On your way now." },
            { id = 5556894, text = "Some pain be part of healing, like a fever that chases the sickness away." },
            { id = 5557003, text = "We would not have joined the Darkspear if they sacrificed their own." },
        } },
    } },
    { who = "Lulubelle Fizzlebang", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1407411, text = "Let's see what's in the bag, shall we?" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1407413, text = "The darkness gives us strength! Well, at least sometimes it does." },
