    { who = "Lyana Stardust", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1406335, text = "My work is almost complete. I just need a few more moments without interruption." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1406332, text = "Demons will be drawn to the power I'll call upon to enchant your weapons." },
            { id = 1406334, text = "I'll keep doing what I do best, as long as you keep those demons away from me and my enchanting table." },
            { id = 1406337, text = "I've given them the finest enchantment I can offer." },
            { id = 1406333, text = "The materials used are extremely volatile. An interruption of any kind could prove disastrous." },
            { id = 1406336, text = "There. The weapons are finished." },
        } },
    } },
    { who = "Lyandra Sunstrider", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1267599, text = "If you long for my blade so badly, then you shall have it!" },
            { id = 1267589, text = "The blade is mine by the will of the master, and by rights of blood! Oppose me and you will be struck down!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1267583, text = "I too came to Icecrown in search of fellow Malorne. The Lich King gave me the blade. And more. He gave me purpose." },
            { id = 1267597, text = "I will not be defeated! Come, my pet! Sate your hunger with the flesh of the living!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1267591, text = "Foolish mortal! You should have bled when you had the chance!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1267587, text = "you do not realize that you're groping in the darkness fellow Malorne would be wasted in your hands" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1267593, text = "Arise, ghouls! Feast upon this intruder's heart!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1267601, text = "Awaken, Gorewing! Tear my foe asunder!" },
            { id = 1267603, text = "Nathan! How dare you! Have you forgotten who I am?!" },
            { id = 1267585, text = "Only when the blinding pain of life left me did I see the truth. Only then was the majesty of the plan revealed." },
            { id = 1267595, text = "Unacceptable! My minions will rip you apart!" },
            { id = 1267605, text = "You're so c-c-cooled!" },
        } },
    } },
    { who = "Lyanis Moonfall", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1244575, text = "By Elune, clearly Ysera is beyond saving. All we can do is end her suffering." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1369416, text = "Help has arrived at last! Elune be praised!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1257432, text = "By Elune's grace, is everyone alright?" },
            { id = 1244562, text = "Enemy reinforcements headed this way!" },
            { id = 1244567, text = "Incoming! Defend the temple!" },
            { id = 1244583, text = "Oh Elune, grant us your light and strengthen us for what we must do." },
            { id = 1244564, text = "Our enemies are launching a new attack!" },
            { id = 1244581, text = "Shine your light down, Mother Moon, and lend us your strength!" },
            { id = 1244579, text = "Stand in Elune's light, and her blessing will strengthen your attacks!" },
            { id = 1244543, text = "Thank you, champion. Lead on. We must help the other defenders." },
            { id = 1257286, text = "To me, Hero! Elune, protect us!" },
        } },
    } },
    { who = "Lyessa Bloomwatcher", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1384508, text = "I am ready to begin the ritual." },
            { id = 1384518, text = "I can feel the well growing in strength. We must push forward." },
            { id = 1384509, text = "I will prepare the well's waters for the cleansing." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1384520, text = "The ritual is nearly complete! Do not give up hope!" },
            { id = 1384522, text = "Use G'Hanir to call upon the spirits of the forest to destroy this fiend!" },
            { id = 1384510, text = "You must protect me until the ritual is complete, or G'Hanir will be lost." },
            { id = 1384502, text = "You must save our injured. I will prepare the cleansing ritual." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1384494, text = "Preparations are complete. We are ready to begin." },
            { id = 1384501, text = "Skylord, you must inform the Dream Grove. We will ensure no further life is lost this day." },
            { id = 1384519, text = "The power grows with every moment. This day will be ours!" },
            { id = 1384521, text = "We have done it. The Mother Tree is whole once more!" },
        } },
    } },
    { who = "Lyleth Lunastre", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1405226, text = "My lord, you have lost your sense of decorum. It is already decided." },
            { id = 1407656, text = "Our father's memorial is just around the corner. I'm sure you will find Anaris nearby." },
            { id = 1407922, text = "This is not up for debate, Inaris. You are either with us or against us. Choose wisely." },
            { id = 1407645, text = "True. You will have to make an appearance." },
            { id = 1405227, text = "You are not the only one with a nose for politics." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1405228, text = "I humbly accept this appointment. It is an honor beyond words." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1408329, text = "Behold, Suramar, our haven, our sanctuary." },
            { id = 1408331, text = "Elisande and the Legion seek to bring us to heel through fear through hunger" },
            { id = 1407923, text = "Oh, dear child... Do you not realize what he died for?" },
            { id = 1408332, text = "The flame of the Shellderai flickers. We must reignite it." },
        } },
    } },
    { who = "Lyrandor Nightveil", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 6119198, text = "I stand with the Kirin Tor." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6119252, text = "Hands off my Kirin Tor tabard! It's a rare collector's item now... probably." },
            { id = 6119246, text = "Return if you need my aid." },
            { id = 6119254, text = "Thank you. I do not know what would have happened when I ran out of mana." },
            { id = 6119289, text = "When the Kirin Tor calls, I answer." },
        } },
    } },
    { who = "Lysander Starshade", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5244248, text = "I can disrupt this portal, but it will require concentration. Please, defend me while I shut it down." },
            { id = 5244252, text = "I do not need it." },
            { id = 5244238, text = "I thought men were not permitted such." },
            { id = 5244261, text = "I wasn't asking for ... I'll be fine." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5244247, text = "Come, Champion. I think we've cleared this place." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5244249, text = "Another portal. Protect me and I will take care of it." },
            { id = 5244246, text = "Blasted portal cover me and I'll tear it down" },
            { id = 5244233, text = "Everyone, to the portal!" },
            { id = 5244243, text = "Look! The Moonwell!" },
            { id = 5244235, text = "You had every right to be wary, Warden." },
        } },
    } },
    { who = "Lysonia Hand of Doubt", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3534182, text = "WHO DARES INTERRUPT THE CONVERSION OF THIS NON-BELIEVER?!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3595962, text = "Join us and be embraced. Resist and you will be swept aside." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3595958, text = "My fellow Kyrian, hear me now. Too long have we struggled under the tyranny of erasure." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3534186, text = "Foolishly, you rush toward your fate!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3595959, text = "Over and over again, we are told that we must give all we are to serve a greater purpose." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3534190, text = "Forsworn! Take flight! Attack now, while they are wounded!" },
            { id = 3534184, text = "Forsworn, show these intruders the true path!" },
            { id = 3595956, text = "Forsworn, the temple is ours!" },
            { id = 3534188, text = "It is too late! This one has already seen the truth, and awakens with eyes wide open!" },
            { id = 3595960, text = "The Forsworn would have you keep your memories, your attachments." },
            { id = 3595961, text = "We are here to liberate you! To offer another path!" },
            { id = 3595923, text = "We will claim the Temple of Purity in our name, and we will destroy all who stand in our way." },
        } },
    } },
    { who = "Machine Speaker Foreman", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5727315, text = "You have exhausted my patience." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5727318, text = "Disruptions will not be tolerated." },
            { id = 5727327, text = "I'll deal with you myself." },
            { id = 5727323, text = "Our work must continue." },
            { id = 5727334, text = "Watch your step." },
        } },
    } },
    { who = "Machine Speaker Machinist", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5726482, text = "Protect the machines!" },
