    { who = "Machinist Brandt", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1045683, text = "I'LL TAKE YOU OUT WITH ME!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1045681, text = "Don't let this nuisance anywhere near the cannon!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1045682, text = "Well then, I'll just have to end this myself!" },
        } },
    } },
    { who = "Mackay Firebeard", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370364, text = "Bah! I knew your crap bird was too slow!" },
            { id = 1370363, text = "Do it! Bring it down!" },
            { id = 1406856, text = "Ha! I was hoping for a warm welcome, but this isn't what I had in mind." },
        } },
    } },
    { who = "Mad Stitch Surgeon", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3572406, text = "DIE QUICKLY, SO I CAN BEGIN!" },
            { id = 3587196, text = "I WILL DESECT YOU MYSELF!" },
            { id = 3572405, text = "I WILL REND AND REMAKE YOU!" },
            { id = 3572404, text = "MORE PARTS FOR MY PROJECTS!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3572409, text = "Don't waste my flesh!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3572407, text = "Meat and bone, skin and sinew!" },
            { id = 3587195, text = "Wonderful! More test subjects! Unleash the plague borders!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
