    { who = "Magister Hathorel", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2991944, text = "DIE, ALLIANCE FILTH!" },
            { id = 2991967, text = "YOU WILL NOT SUCCEED!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2923942, text = "No, you will watch your friends die, just as I did." },
            { id = 2991943, text = "None of you will escape these halls!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2991940, text = "Guards! Defend our mages!" },
            { id = 2923941, text = "Have you forgotten the Purge of Dalaran, murderer? Today, the Sunravers will be avenged!" },
            { id = 2923940, text = "Indeed she did, traitor. You and Lady Proudmoore." },
            { id = 2921766, text = "Leonie! Get in here and eliminate them!" },
            { id = 2923943, text = "Rangers, kill them all for the Sunreavers!" },
        } },
    } },
    { who = "Magister Umbric", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1800147, text = "It will take some time for us to adjust to our new forms. We look forward to your return, Lady Windrunner. And champion, you have our deepest thanks." },
            { id = 1800145, text = "My arrogance was nearly our undoing. I dabbled with powers far beyond my control. If you will train us, Illyria, we will follow where you lead." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1800143, text = "I feel the power... calling to me... changing me..." },
            { id = 1800140, text = "My people and I heard tales of what transpired on Argus. As you might imagine, we have a keen interest in your interaction with the Dark and Naru." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1800142, text = "Take this cube for instance. It is an ancient device, perhaps even predating life on Azeroth. It seems to have been locked and we cannot yet open it." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1800138, text = "Together, we will prove them wrong." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1800144, text = "Alleria, champion. My people are free, but we have been changed. And the voices..." },
            { id = 1800139, text = "Illyria Windrunner, how did my what an unexpected honor" },
            { id = 1800141, text = "Indeed. Like you, we believe the Void can be used to defend life rather than consume it. We have made great progress, Lady Windrunner, but many mysteries remain." },
            { id = 1800148, text = "Our void experiments are proceeding well. I am certain we are on the cusp of a breakthrough, despite Rammoth's small-minded protests." },
            { id = 1800146, text = "Silvermoon turned its back on us long ago. Today we are reborn and it is fitting that we walk a new path. From this day forth, the Alliance has our loyalty." },
            { id = 1800137, text = "There will be those who doubt you, who question your resolve, your ability to harness powers that have caused the downfall of weaker wills." },
        } },
    } },
    { who = "Magmatalon", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4687059, text = "I WILL BURN YOU TO SINDERS!" },
            { id = 4687053, text = "YOUR DEATH WILL BE AGONY!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4679749, text = "I see you have unearthed the flamestone." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4679750, text = "I can sense its strength." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4687054, text = "Back to the elements!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4679757, text = "Then go, while I turn this wretched titan-stained place into ashes!" },
            { id = 4679747, text = "Your Garves did not join our ranks as expected, Aranag." },
        } },
    } },
    { who = "Magmolatus", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 995109, text = "BOUND TO DEST!" },
            { id = 995105, text = "BURN UNTO NOTHINGNESS!" },
            { id = 995089, text = "I WILL EXPUNGE YOUR EXISTENCE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 995085, text = "You are but a pebble amongst boulders." },
