    { who = "Magnar Icebreaker", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1370073, text = "I have fallen. Who's near? You are a Vanishar?" },
            { id = 1370065, text = "My son died before my very eyes! I failed to protect him! You will not!" },
            { id = 1370062, text = "You are not my son, he is in the Halls of Valor, called by Odin before his time!" },
            { id = 1370072, text = "You will die for saying his name! I shall send you to Helheim myself!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1370075, text = "I see now. My weapons are yours, warrior. May they bring you glory as you strike down Helia's minions." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1370061, text = "Curse her here! Curse her cowardly followers! I'll not rest until she is dead!" },
