    { who = "Marasmius", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3614658, text = "Back again, I see. Such a hard worker." },
            { id = 3614653, text = "Come visit soon, yeah?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3614654, text = "A task completed is its own reward." },
            { id = 3614651, text = "Ha! Ha! Those miscreants got what was coming to them! We make a pretty good team, the three of us!" },
            { id = 3614659, text = "It's always nice to speak with you." },
            { id = 3614655, text = "Keep up the good work, young one." },
            { id = 3614657, text = "Oh, it feels good to... stretch out." },
            { id = 3614652, text = "See you around sometime." },
            { id = 3614661, text = "Tell me when you're ready young one, this is always unsettling for first timers." },
            { id = 3614662, text = "That'll show him! Ha ha!" },
            { id = 3614656, text = "Well, if it isn't my favorite mushroom tender." },
            { id = 3614660, text = "You know what this is? A lack of respect for your elders, that's what!" },
        } },
    } },
    { who = "Margaux", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1405240, text = "DON'T HURT HIM!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1405237, text = "Ahead you will see our distribution facility." },
            { id = 1405231, text = "To my left you will see one of our orchards." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405236, text = "A cask of Arcwine from our vineyard can be safely stored for hundreds of years." },
            { id = 1405235, text = "Each bottle is sealed with magic to prevent any of the Nightwell's essence from fading." },
            { id = 1405238, text = "Here we arranged to send hundreds of barrels and casks of Arcwine out to the city." },
            { id = 1405232, text = "If you're at all familiar with the wine-crafting process, you know that it is necessary to allow the juice to ferment." },
            { id = 1405229, text = "The building we approach now is called the Ageing Chamber." },
            { id = 1405234, text = "The buildings before you house our bottling facilities." },
            { id = 1405239, text = "The Magistrix monitors these activities very- GASP!" },
            { id = 1405233, text = "This one houses a species of tree that produces extra sweet fruit, which you tasted in the infusion." },
            { id = 1405230, text = "We prefer to shorten the process using time magic. Such power is our birthright." },
        } },
    } },
    { who = "Margrave Gharmal", tier = "character", groups = {
