        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3730520, text = "At ease, soldier." },
            { id = 3730521, text = "Begin your report." },
            { id = 3730518, text = "Embrace challenge. Conquer your trials." },
            { id = 3730517, text = "Revel in your victories. Be proud of what you achieve." },
            { id = 3575512, text = "So, this mortal witnessed your treachery." },
