        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1392207, text = "Whoa, whoa, whoa. Is that the new shadow I see walking into my vault? Unfricking believable." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1402003, text = "Aim for their shins, or knees, or whatever you can reach! Just take them out already!" },
            { id = 1401942, text = "East over the water! Looks like the Legion's back for more! Positions! Hurry up!" },
            { id = 1401962, text = "Everybody get ready. We have incoming and they sound testy" },
            { id = 1392206, text = "Oh hey, while you're there, could you let Nikki know she has three days left to pay up? I'm not running a charity over here." },
            { id = 1401944, text = "Oh, this is not good. Legion ship overhead! If you owe back taxes, now's the time to pay up!" },
            { id = 1392204, text = "That'll do juuuuuu" },
            { id = 1401964, text = "This is not a drill. Here they come. First priority, protect my stuff!" },
