    { who = "Marshal Everit Reade", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1861747, text = "I hope you're right, my lady. Form up, men! We ride!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1861745, text = "But my lady, it will be safer if..." },
            { id = 1861739, text = "It is worse than you know, my lady. This coven has spread like wildfire throughout Drustvar." },
            { id = 1861742, text = "They, they have him, my lady. We were working on a way to extract him when we heard word of... this trial." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1861979, text = "Constable Framer! I order you to release the Lady Waycrest into my custody!" },
            { id = 1861730, text = "Look out! Enemies from the woods!" },
            { id = 1861732, text = "The traps aren't slowing them down anymore! More incoming!" },
            { id = 1861981, text = "There is no time to argue! If you refuse to stand aside, we'll take her by force!" },
            { id = 1861740, text = "They've overrun much of the land past the mountains, with only a handful left holding Adam's stand." },
            { id = 1861735, text = "We'll protect the Lady, Mainlander! Take out their leader!" },
            { id = 1861733, text = "What in creation is that?" },
            { id = 1861995, text = "You've bought us some time, Mainlander. Let's just hope that these villagers truly mean no harm to the Lady Waycrest." },
        } },
    } },
    { who = "Marshal Gryan Stoutmantle", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1401956, text = "Ready your blades, allies! The battle begins!" },
            { id = 1402053, text = "Take back what is ours! Show these demons their way back to the Nether!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1402017, text = "Allies of all flags and kingdoms, the time to fight for our lands is now!" },
            { id = 1401950, text = "The sky burns, allies! The Legion comes at us again!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1402049, text = "All forces, spread out! Legion corruption rises in all directions!" },
            { id = 1401954, text = "Close ranks! We make our stand here!" },
            { id = 1401948, text = "Legion ships on the horizon! All forces to Sentinel Hill!" },
            { id = 1402051, text = "Make haste! Spread throughout the lands! Purge this infestation!" },
            { id = 1401952, text = "Prepare for battle. We won't allow the Legion to destroy what we've built here!" },
            { id = 1401958, text = "Steel at the ready! We have incoming!" },
            { id = 1402012, text = "The Doomguards make their descent! Ready at the hill!" },
            { id = 1402009, text = "We must drive them back! Focus on the commanders!" },
        } },
    } },
    { who = "Marshal Mcbride", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4924595, text = "Is that Van Cleave? GUARDS!" },
