    } },
    { who = "Maruuk", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4669274, text = "I WILL HUNT YOU BEYOND DEATH!" },
            { id = 4674668, text = "REND THE EARTH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4669284, text = "You shall pay for this blasphemy with your lives!" },
            { id = 4669281, text = "Your soul will never rest." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4669204, text = "I believed that my legacy was the sum of battles won and lands conquered." },
            { id = 4669206, text = "My legacy is our family still thriving now I can rest" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4674671, text = "Flee before me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4669290, text = "Before I join her, I will bleed you dry." },
            { id = 4669287, text = "Oh, peace at last." },
            { id = 4674674, text = "This existence is agony!" },
            { id = 4669280, text = "This is what has become of our legacy?" },
        } },
    } },
    { who = "Marwyn", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 554988, text = "AHHH!" },
            { id = 554991, text = "RAAAGH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 555001, text = "Choke on your suffering!" },
            { id = 555011, text = "Death is all that you will find here." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 554986, text = "I saw the same look in his eyes when he died. Tyranus could hardly believe it. Ha Ha Ha ha!" },
