    { who = "Master Windstrong", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1399629, text = "Help masters! Demons are ransacking the temple!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1399630, text = "The Jade Serpent fights the invaders inside while we hold the gate for survivors to escape. Several scribes are missing and I fear the worst. Please, help us." },
            { id = 1399631, text = "We're counting on you to rescue our scribes!" },
        } },
    } },
    { who = "Masud the Wise", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4659087, text = "Let's compare notes." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4659088, text = "Are you familiar with Polymorph? You're about to be." },
            { id = 4659084, text = "Can I help you?" },
            { id = 4659085, text = "Fancy meeting you here." },
            { id = 4672717, text = "Glania can help direct you toward the Kirin Tor's efforts in the Azure span. Make sure to tell her Massoud and Pekina sent you." },
            { id = 4672718, text = "Hmm, maybe three or four more? Five adventurers seems like a good number to have for any task." },
            { id = 4659083, text = "I'll be here when you return." },
            { id = 4672716, text = "I'm sure an adventurer will come by. His place should be crawling with him." },
            { id = 4659082, text = "Keep a keen mind and a watchful eye." },
            { id = 4659080, text = "Thank you for your assistance." },
            { id = 4659081, text = "Watch yourself out there." },
            { id = 4659086, text = "What can I do for you?" },
        } },
    } },
    { who = "Matron Mother Malevolence - masculine voice", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1313230, text = "AHHH AHHH!" },
            { id = 1313229, text = "HAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1281950, text = "Ah, there you are. Lord Illidan has placed my shivara at your disposal." },
            { id = 1281944, text = "If you will excuse us, come, my dears, up the volcano to the foothold." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1281954, text = "Don't worry, Mother's here. Oh my, he's a big one." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1281942, text = "Time is of the essence. Come, sisters, our former brethren await our tender mercies." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1281952, text = "A mother's work is never done." },
            { id = 1281948, text = "A small force has infiltrated the Black Temple, but the Sha'tari army is still being repelled." },
            { id = 1281958, text = "I'm needed elsewhere." },
            { id = 1281956, text = "Our assault is underway. I'll join in when you attack the Overseer." },
            { id = 1281946, text = "We are to obtain the Sagarai Keystone with all due haste, and return to aid in the defense." },
            { id = 1281940, text = "We will see it done. I urge you to remember that the Black Temple is under attack." },
        } },
    } },
    { who = "Maut", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
