    { who = "Mawsworn Spiked Caster", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4035421, text = "UNTOLD ANGRISH AWAITS YOU!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4035418, text = "Your screams will echo across the maw!" },
            { id = 4035419, text = "Your screams will echo across the mouth!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4035423, text = "I will bask in your fear!" },
