    { who = "Maximillian of Northshire", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1586232, text = "Do you know who it is you are addressing?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1586233, text = "I am Maximilian of Northshire, damsel rescuer extraordinaire. How dare you." },
            { id = 1586234, text = "I say, are you keen to feel the pointy part of my blade?" },
        } },
        { name = "Farewells", family = "Manners", lines = {
