    { who = "Mayla High Mountain", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1343626, text = "You have done the Highmountain tribes a great service today." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1319701, text = "Shardmasters from Greystone are performing some sort of empowering ritual within the chasm of the Crystal Fisher. This is too close to Thunder Totem for comfort. Can you stop them?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1343624, text = "Dargrul has trapped a great basilisk mother deep within the vault. If we don't put her down now, he will emerge with an army of trained basilisks." },
            { id = 1319703, text = "Thank you, champion. The Greystone Drogbar are getting far too ambitious these days." },
        } },
