    { who = "Medivh", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1536161, text = "HA!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1523333, text = "You have all the power you will ever need, Khadgar. It is your heart, your courage, that makes you this world's guardian. And a better one than I ever was." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1530932, text = "I will open the way. While you battle that fiend, I will sever the tower's connection to Legion worlds. I suggest we be quick about it." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1523385, text = "There is much that lies ahead for all of us. Farewell." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1523389, text = "Enough sentiment. Hear these words before I depart." },
            { id = 1523377, text = "Hmm. I must remember to shut you down from time to time. Overuse might cause you to become…eratic." },
            { id = 1523387, text = "It may be simpler to shut a door than to pass through it, but sometimes a step into the unknown is required to break the bonds of fate." },
            { id = 1530934, text = "I've left so many fragments of myself throughout this tower." },
            { id = 1523375, text = "Now you're ready to oversee the tower's protection in my absence." },
            { id = 1523391, text = "Oh, my path leads elsewhere. Besides, Azeroth has found her guardian in you, young trust." },
            { id = 1523371, text = "Too. Much. Power!" },
        } },
    } },
    { who = "Meerah", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1998819, text = "I don't think those trolls up ahead are friends of yours." },
            { id = 1998827, text = "I doubt she could. Most of your kind can't. Well, not anymore." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1998822, text = "Hold on if you can, it's about to get real bumpy." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1998826, text = "Can you believe this wasteland was once the jewel of the troll empire? A jungle teeming with life. Now, whatever's left is buried beneath the sands." },
            { id = 1998821, text = "Dolly! Dolly, wait! It's not safe down there!" },
            { id = 1998825, text = "Hiro's got no reason to worry. I've had plenty of practice! But you might want to hold on, just in case." },
            { id = 1998830, text = "Kira, I'm so happy you're back. Was it scary out there? How'd you get one of their crow lusks? Did you name it? Can I name it? Is it nice?" },
            { id = 1998828, text = "Nisha will be so happy to see you! She's out of the crater killing Sethrak! Like she always is." },
            { id = 1998823, text = "Oh, it's not, but you don't want to travel through the canyon. It's filled with nightmares." },
            { id = 1998820, text = "Oh, this isn't good. Not at all. Everybody, out of the wagon! Quick!" },
            { id = 1998829, text = "The kits are being held in the crater below. Please be careful!" },
        } },
    } },
