    { who = "Melris Malagan", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1392007, text = "I have seen the beautiful gifts they bring. You do not understand!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1392001, text = "Foolish orc! You will be the first to witness the Legion's arrival into my city!" },
