        { name = "Loyalty", family = "Manners", lines = {
            { id = 1391973, text = "Sister Ebonlock has gathered the skull and blood of the innocents. She awaits your escort." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1392009, text = "Do you not see? Can you not feel their warm embrace?" },
            { id = 1392003, text = "Ered nash bila mornul nakun! Ered nash ban manari!" },
            { id = 1392002, text = "Long have I waited for this day, let us not waste another moment." },
            { id = 1392010, text = "Master! Your servant requires aid!" },
            { id = 1391974, text = "May the Legion guide you, and do not forget to destroy this letter. We must leave nothing to chance." },
