        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 4925886, text = "My legacy lies deep within the Earth. In the darkness, you will find strength." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4925887, text = "Serve my will, and one day the world will tremble before your might." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4925882, text = "Bound by unfaltering unity to fight the wars others could not." },
            { id = 4925881, text = "Deep within the Halls of Averus, I forged you, my ideal soldiers, my Drakthir." },
            { id = 4925880, text = "Hear now the words of the Earth Warder, the voice of your Creator." },
            { id = 4925884, text = "That is your purpose. The destiny that lies before you." },
            { id = 4925885, text = "Your obedience, your loyalty must never falter." },
        } },
    } },
    { who = "Meng the Demented", tier = "character", groups = {
