        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 622338, text = "GAH!" },
            { id = 622328, text = "NOOO!" },
            { id = 622332, text = "RAWR!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 622374, text = "Hah! Enemies! Everywhere! Kill! Kill them all!" },
            { id = 622364, text = "Like rice stalks before the blade, or four before me!" },
            { id = 622372, text = "Muhahaha, slaughter yourselves for my amusement!" },
            { id = 622366, text = "None may stand against the imperial majesty of Ming!" },
            { id = 622368, text = "T-Don't bleed on me! Filthy! Disease!" },
