    { who = "Mennu the Traitorous", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 555235, text = "DON'T MAKE ME KILL YOU!" },
            { id = 555234, text = "YOU BROUGHT THIS ON YOURSELVES!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 555236, text = "It had to be done!" },
            { id = 555233, text = "The work must continue!" },
            { id = 555231, text = "You should not have come!" },
        } },
    } },
    { who = "Mephiles the Loyal", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3743982, text = "Intruders! You will not interfere!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3743985, text = "Curse him, witch! I will never talk!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3744953, text = "Master, our preparations are complete. We await your arrival." },
            { id = 3743984, text = "Slay as many as you wish, I will tell you nothing." },
            { id = 3743983, text = "What? What is the meaning of this? Where are you taking me?" },
        } },
    } },
    { who = "Mephistos", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1322756, text = "FREEDOM IS BUT A HOPELESS DREAM!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1322807, text = "Impressive you have made it this far, demon hunters. Now... I will extinguish your souls like a candle's flame!" },
            { id = 1322758, text = "No! No! You shall never be free!" },
            { id = 1322728, text = "You see, demon hunters, your attempts are futile. Even your master, the great Illidan Stormrage, is now a prisoner of the Legion." },
            { id = 1322755, text = "You will never see the light of this world again!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1322762, text = "Your allies have fallen. My army will crush you before you can see the light of day!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1322760, text = "Ha Ha Ha ha" },
            { id = 1322830, text = "Such arrogance! To think you can stand against the Legion!" },
            { id = 1322761, text = "Your persistence is admirable, but my demons have infiltrated every floor of the vault. Only death awaits you." },
        } },
    } },
    { who = "Mephistoth", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1393475, text = "So, mortal, you have slain one of my generals." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1393476, text = "Savor your victory while you can, Warlock. This war is far from over." },
            { id = 1393477, text = "We will meet again! Ha Ha Ha ha!" },
        } },
    } },
    { who = "Mephistroth", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1580875, text = "You cannot withstand the power of the Legion!" },
            { id = 1384899, text = "Your persistence will be the death of you! Minions attack!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1384905, text = "I grow tired of your interference! Die!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1580873, text = "Run! Hahahaha! Fool! I have led you to the slaughter!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1384895, text = "Come to me, servant of Hellfire, rid me of this uninvited guest!" },
            { id = 1384897, text = "Fire the guns! Cover the path in hellfire! Don't let that warlock through!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1384890, text = "Hahahaha! Foolish warlock! Did you really think I would remain unaware of your infantile plot to steal my treasure? You underestimate the Nathrezim!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1580872, text = "Ah, our guests of honor have finally arrived. I look forward to ripping those horns from your skull, betrayer!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1580874, text = "Beware the shadows!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1384893, text = "As for you, treacherous skull, I'll deal with you later." },
            { id = 1384904, text = "Did you think I would stand idle as you clawed your way through my minions? Listen mortal, as the treasure you fight so hard to obtain is broken to my will!" },
            { id = 1384901, text = "Enjoy your victory while you can, Warlock. Hahahaha! This isn't over between us. It has only begun." },
        } },
    } },
    { who = "Mercilessone", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 555241, text = "AAA!" },
            { id = 555244, text = "AAAHHH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 555246, text = "OH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 555256, text = "Thank you for watching!" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 555247, text = "AHHH!" },
        } },
    } },
    { who = "Meredy Huntswell", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3488764, text = "Haha! Your polymorphed foe will wander around for a bit! Use that to your advantage and fight whoever's left!" },
            { id = 3488759, text = "Your foe will wander around as a sheep, till you attack him, like so!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3488756, text = "I hope me spellbook isn't ruined from sitting at the bottom of the lake. Maybe I should have gone after it myself." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3488762, text = "You got two fools attackin' you now! Cast Polymorph to even the odds!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3488755, text = "An ice moat? Uh, sure. What are you gonna do with it?" },
            { id = 3488760, text = "Cool! C'mere! We're gonna flank our, ah, recruit, and teach him how to use Polymorph!" },
            { id = 3488757, text = "Here's a taste of Polymorph!" },
            { id = 3488758, text = "It's a demonstration! Polymorph can be a huge help in a fight!" },
            { id = 3488763, text = "Very funny, recruit. I think you got the hang of this. Let's go back." },
            { id = 3488761, text = "Why cool? I'd never do such a thing. Promise." },
        } },
    } },
    { who = "Merina", tier = "character", groups = {
        { name = "Mockery", family = "Menace", lines = {
            { id = 1397531, text = "I was told to stand watch, but no one ever came back for me. I wasn't strong enough to defend the site. Or perhaps I was simply here too long. I'm not sure anymore." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1397532, text = "If you want the ritual to work, you need the focus. I tried to keep it from the monsters, but I was too weak." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1397530, text = "Are you here to take me away? Or do you only seek that which was left behind?" },
            { id = 1397533, text = "It lies near my corpse. I... I think it's keeping me here. Please take it far away. Perhaps then I will finally be able to go home." },
        } },
    } },
    { who = "Merithra of the Dream", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2991685, text = "Though we have suffered great losses, the green dragonflight remains steadfast in our duty to Azeroth." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2991683, text = "I do not know if I possess such strength, or if I can fulfill the task that lies ahead of me." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2991687, text = "Is it time to go already?" },
            { id = 2991679, text = "Lifebinder, might I ask you something?" },
            { id = 2991680, text = "Long did my mother lead the green dragonflight as the aspect of the dream." },
            { id = 2991686, text = "May this gift honor the memories of those who came before us." },
            { id = 2991689, text = "May your dreams be peaceful." },
            { id = 2991690, text = "Tell me of your dreams." },
            { id = 2991684, text = "Thank you, Alexstrasza. I will do my best to live up to my mother's legacy." },
            { id = 2991681, text = "Yet she always seemed distant, as if she were in two places at once." },
            { id = 2991682, text = "You knew her before you became Aspects. What was she truly like?" },
        } },
    } },
    { who = "Merithra of the Dream Dragon", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3010010, text = "GAH!" },
            { id = 3010006, text = "HUH AH!" },
            { id = 3010008, text = "UGH!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3010004, text = "Hello champion" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3009998, text = "Is it time to go already?" },
            { id = 3010005, text = "Isn't it past your bedtime?" },
            { id = 3010001, text = "May your dreams be peaceful." },
            { id = 3010000, text = "Rest well." },
            { id = 3010002, text = "Tell me of your dreams." },
            { id = 3010003, text = "What would you ask of me?" },
        } },
    } },
    { who = "Meryl Felstorm", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1382437, text = "I could use a little help here!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1382433, text = "Find a way past his barrier. I'll try to keep him occupied." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1382392, text = "Are you ready?" },
            { id = 1382390, text = "Good, you made it. I'm afraid we have an escaped dreadlord on our hands." },
            { id = 1382432, text = "He's too strong! We need the power of the Forge!" },
            { id = 1382427, text = "It looks like the Dreadlord is one step ahead. Hurry, the passage is this way!" },
            { id = 1382428, text = "It's over, Dreadlord. Your evil reign ends here." },
            { id = 1382436, text = "It's working! Activate the forge!" },
            { id = 1382435, text = "Nice work! Now, destroy the rift siphoning power from the forge!" },
            { id = 1382389, text = "Thank goodness I've reached you. I need your help." },
            { id = 1382391, text = "We don't have much time. The demon will surely have found the forge by now. I will meet you in the Violet Hold." },
            { id = 1382426, text = "We will need its might if we are to defeat the Burning Legion." },
        } },
    } },
    { who = "Mestrah", tier = "character", groups = {
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2400245, text = "Your Horde serves only death." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2400247, text = "Fall before the dragon!" },
            { id = 2400244, text = "Feel the fury of the light!" },
            { id = 2400238, text = "How many fists can you withstand?" },
            { id = 2400243, text = "In the twisting nether, I slew countless demons of the Legion. This motley crew of troll sympathizers poses a little threat." },
            { id = 2400239, text = "No quarter for you!" },
            { id = 2400236, text = "The dragon will bring your doom!" },
            { id = 2400240, text = "The elements will break you!" },
            { id = 2400241, text = "Time to test your mettle!" },
            { id = 2400242, text = "You face a Dragon of the Light!" },
            { id = 2400237, text = "Your defense is feeble!" },
        } },
    } },
    { who = "Mikanikos", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3582213, text = "I built this goliath with a special core. Now with faceless, I can bind my soul to him." },
            { id = 3582217, text = "I feel his power within me! I name him... Bronn." },
            { id = 3582139, text = "I will locate Phaestus. You collect metals. No scratches, no imperfections." },
            { id = 3547136, text = "Magnificent. Bronze strength is my strength. Our strength." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3582121, text = "Come! Who knows how the Forsworn abuse my forge? They must not harm my sacred faceless too!\"" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3582219, text = "Need. More. Anima. Friend! Help me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3547139, text = "Everyone, hop on!" },
            { id = 3582136, text = "Huh! The Forge hands return! Get operations up and running! There's work to do!" },
            { id = 3547138, text = "Not to worry, I know what to do." },
            { id = 3582123, text = "Seeker, I left you in charge. Where are my forge hands?" },
            { id = 3582214, text = "Seeker, keep watch. Hero, apply the reinforced armor." },
        } },
    } },
    { who = "Millhouse Manastorm", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 601517, text = "HA!" },
            { id = 601502, text = "RAWR!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 555331, text = "I didn't even break a sweat on that one!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1408637, text = "That was a bit of a pickle. Thanks, you must be the one I've been hearing so much about lately." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 601514, text = "COUGH!" },
            { id = 601505, text = "D'OH!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1408635, text = "Hey, you! Help a fellow mage out! That demon, Norvir, has the key!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1408646, text = "Did you know the Nightborne Soulstone can be used to control millions of people? I'm sure going to have some fun when I get it!" },
            { id = 1408642, text = "I'm going to find that Soul Stone if it's the last thing I do!" },
            { id = 1408643, text = "Once I get that Soul Stone, nobody will be able to stop me!" },
            { id = 1408639, text = "Uh-oh! It looks like the inner vault has been breached! We'd better see if the Nightborne Soulstone has been taken!" },
            { id = 1408647, text = "Vargoth and his limited intellect will never be able to unlock the Soulstone's full potential. I'm the only one who can really show you what it can do." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 555336, text = "Alright! Who ordered up an extra large can of whoop-ass?" },
            { id = 1408640, text = "Blast! It's gone! That Vargoth is going to be sorry when I catch up with him!" },
            { id = 1408641, text = "He was here very recently. He can't have gotten too far ahead." },
            { id = 1408644, text = "Now that is a fancy weapon. You should let me borrow it sometime." },
            { id = 1408645, text = "Of course, if I had a fancy weapon like yours, I'd be running this place! And much more competently, I might add." },
            { id = 1408638, text = "You and I are gonna make a great team! Let's blow this place up!" },
            { id = 555339, text = "You guys feel free to jump in anytime!" },
        } },
    } },
    { who = "Millificent Manastorm", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1324343, text = "ARE YOU READY TO EXPLODE?!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1503603, text = "HA!" },
            { id = 1503604, text = "PHEW!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1324357, text = "I know it was you, Milhouse!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1324371, text = "Don't millie me, Millhouse Deremus Manastorm! I'm coming for you!" },
            { id = 1324349, text = "Wait! I recognize that voice." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1324353, text = "Oh, finally free from that cursed mage trap! Such a..." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1324339, text = "Here comes the heat!" },
            { id = 1324345, text = "Millhouse! You're next!" },
            { id = 1503605, text = "Thank you for watching!" },
            { id = 1337556, text = "There's no place you can hide from me, Millhouse! NO PLACE!" },
            { id = 1324361, text = "Why you?! No one insults my hair! NO ONE!" },
        } },
    } },
    { who = "Mimiron", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1386106, text = "I suppose there's no time like the present. This will either fix everything or destroy us. I need you to press the big red button labeled do not push this button." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1386103, text = "Activate the stabilization matrix before it tears the whole lab apart!" },
            { id = 1386108, text = "All you need to do is deactivate the two control panels over by the Fusion Press. Bronzebeard and I will man the central console." },
            { id = 1386111, text = "Astounding! Fusion system running at 98.33% efficiency. Repeating, of course." },
            { id = 1386098, text = "Download complete. Splendid work. Positively splendid. Please, join me at the control console." },
            { id = 1386104, text = "Leviathan Unit Stable! Excellent work! Most excellent indeed!" },
            { id = 1386102, text = "Oh dear, now the Storm Leviathan unit is experiencing a target recognition system malfunction." },
            { id = 555345, text = "Oh my! It would seem that we're out of time, my friends!" },
            { id = 1386101, text = "Thorim's throne at the Temple of Storms. I suggest you get moving. We don't have much time." },
            { id = 1386107, text = "Those alarms indicate that we are encountering some minor technical difficulties with the Fusion Press Unit." },
            { id = 1386095, text = "Use my teleportation pad to exit the workshop. We need to get you to the Temple of Storms before that Vrykul arrives!" },
            { id = 1386105, text = "Well, friends, the good news is the download is 89% complete. But we may also be experiencing a minor case of total system failure." },
            { id = 1386099, text = "Yes, yes, I see. Oh, no, no, no, not good, not good at all." },
        } },
    } },
    { who = "Mindflayer Kaahrj", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1332632, text = "I'LL KEEP THIS MASK AWAY AND I'LL KEEP ALL MY FURTS PISSED!" },
            { id = 1332636, text = "SCARED FOR MY GOD LOOK SHUCK I'M LIKE A LANE" },
            { id = 1332635, text = "SHUT THE FUUUUUUU" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1332626, text = "I just sick me of grand, not sin again, again, AGAIN!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1332627, text = "In fact, you could just tie the sack. You're not allowed!" },
            { id = 1332628, text = "The door will reset if you ask for more for more." },
        } },
    } },
    { who = "Minerva Ravensorrow", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1383565, text = "WE'RE ALREADY DEAD, IDIOT!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1369929, text = "What? Don't you have any sense of duty to aid your fellow knights?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1369949, text = "Poor Margrave, the final death claimed you at last." },
            { id = 1369925, text = "We don't have much time. Margrave has taken to the Citadel. The only thing I've seen come out of that place are demons and corpses. We'll need a break in there to get him out." },
            { id = 1369933, text = "You're a cold one, Sliver. Fine, I'll help. But if we have any chance of getting Margrave out alive, we should take it." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1369920, text = "Ahhh! That's much better!" },
            { id = 1369946, text = "More incoming! Intercept them!" },
            { id = 1369910, text = "Spare me your paltry words, Sliver. I've not taken my final breath yet." },
            { id = 1369937, text = "The Legion took my weapons from me, so it's only fitting that I take one of theirs." },
            { id = 1369940, text = "What's the delay? Go already!" },
        } },
    } },
    { who = "Mirabelle", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1993326, text = "GIRLNAMES! LOAD YOUR CANNONS! ADVANCE!" },
            { id = 1971332, text = "WE'VE BEEN COMPROMISED!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1971334, text = "Mind your step, druids! This place is a death trap!" },
            { id = 1971333, text = "Plan B it is then!" },
        } },
    } },
    { who = "Mishka", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 617595, text = "Hello!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 617597, text = "How can I help you?" },
            { id = 617599, text = "Is anyone in need of medical aid?" },
        } },
    } },
    { who = "Mistcaller", tier = "character", groups = {
        { name = "Mockery", family = "Menace", lines = {
            { id = 3522234, text = "No fooling you!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
