            { id = 1406852, text = "Did you really think you could stop me? Foolish children!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1407211, text = "I will take these poor, pathetic creatures under my wing and lead them to the glorious destiny they yearn for!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1406846, text = "Our work is nearly finished. Do not allow these meddling shamans to interfere with the rituals." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407210, text = "But I have heard the prayers of their faithful, crying out for destruction." },
            { id = 1407218, text = "Cower, mortals! Obliteration is upon you!" },
            { id = 1407212, text = "Dark secrets have been revealed to me through the void, ways of subjugating the elements to my will." },
            { id = 1407216, text = "The blood of Syntharia flows through my veins, and a voice whispers to me from the dark beyond!" },
            { id = 1407215, text = "The destruction of Azeroth is at hand. Soon, the very elements that shape this world will cause its demise." },
            { id = 1407217, text = "The Twilight Dragonflight lives, and our destiny is at hand!" },
            { id = 1406863, text = "The Twilight's hammer is all but destroyed. This once great order has been laid low, scattered, and leaderless." },
        } },
    } },
