    { who = "Morketh", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1056313, text = "NOW WE HUNT DOWN VORGORSH" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1056317, text = "Let's kill some ogres!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1056321, text = "Hey! You're the one in charge, right? Tell your dogs to let me out of this cage!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1056314, text = "A fine strike, two remain." },
            { id = 1056316, text = "Blood and Thunder, what a battle!" },
            { id = 1056319, text = "Commander, over here!" },
            { id = 1056311, text = "Commander, when I heard the ogre's death cry, I came as soon as I could. Did everything go well?" },
            { id = 1056320, text = "Damn these ogres and their magic! I can't find a way to bring the barrier down, so we're just going to have to sneak in around it. I'll go first and clear the way. Meet me on the other side." },
            { id = 1056322, text = "Have you even inspected this cage? It's on the verge of falling apart! Let me out, and I'll show you how to make one strong enough to hold a raging cluffed-up ball at it!" },
            { id = 1056318, text = "I'll move forward and scout their gates while you're taking out those catapults! Lok'tar ugar!" },
            { id = 1056312, text = "Now we hunt down Zulmork!" },
            { id = 1056315, text = "Only Koromog remains now!" },
        } },
    } },
    { who = "Moroes", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1518222, text = "STOP TROUBLING THE MASTER'S GUESTS!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1518224, text = "I do so detest party crashers." },
            { id = 1518214, text = "I don't believe the master is expecting you." },
            { id = 1519040, text = "I fear that I am currently... ...indisposed." },
            { id = 1518232, text = "I insist you dress for dinner." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1518226, text = "The Master hasn't been himself for quite some time. Perhaps a feast will brighten his spirit." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1518230, text = "Master, I hope I served you well." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1518220, text = "May I take your jacket?" },
            { id = 1518234, text = "Mind your manners!" },
            { id = 1518216, text = "Perhaps your party would be more comfortable at the children's table." },
            { id = 1518218, text = "Seems I'll be retiring for the evening." },
            { id = 1518228, text = "The guards really must do a better job of keeping out the ruffians!" },
        } },
    } },
