    { who = "Mortanis", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3536144, text = "THE BONES CALL FOR YOU!" },
            { id = 3536138, text = "THE BONES WILL ONLY STRENGTHEN MY VESSEL!" },
            { id = 3536143, text = "THE SKULLS OF THE FALLEN, CRY FOR VENGEANCE!" },
