        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3536137, text = "A willing sacrifice for the House of Rituals!" },
            { id = 3536136, text = "The ritual will not be disrupted! Bones of the Fallen, awaken and greet our visitors!" },
            { id = 3536140, text = "Your disturbance matters not, for the ritual is complete!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3536145, text = "The power of Maldraxxus flows through me! I am the face of death!" },
