    { who = "Mudleader Lorac", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5049784, text = "YOU BROUGHT IN REINFORCEMENTS?! I KNEW YOU WERE GONNA CHEAT SOMEHOW!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 5049781, text = "Did the barrier just fall? You are a failure, Baldani! If you were still alive, I'd kill you myself!" },
            { id = 5049772, text = "I just took out one of you with rocks and dirt! You won't take any more effort!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5049775, text = "I guess your father didn't teach you much about being an Earth Warder!" },
            { id = 5049767, text = "I never disappoint! I have a plan for all contingencies! I can restrain you with my Earth Mastery!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 5049751, text = "Haha! I knew you order-addled fools would come!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5049757, text = "Remember the name Lorak. I ensure these caverns will be your tomb!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5049760, text = "Dragons?! Yes! Killing you two will cement my status as a legend!" },
            { id = 5049787, text = "Fine! FINE! But you'll never defeat me! I have mastered the elements of both Earth and water!" },
            { id = 5049754, text = "Lord Farrakh was unconcerned, but I knew you'd follow! I am a planner! I am prepared!" },
            { id = 5049790, text = "This is the part where you DIE! Attack them, my mud minion!" },
            { id = 5049763, text = "Why won't you die? Killing you should have been easy!" },
        } },
    } },
    { who = "Mudmug", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 635938, text = "Alright then." },
            { id = 635944, text = "Fine day." },
            { id = 635954, text = "I'll put my boot in ya." },
            { id = 635948, text = "Mm-hmm." },
            { id = 635940, text = "See ya!" },
            { id = 635946, text = "Yell-o!" },
            { id = 635936, text = "Yup." },
