    { who = "Muehzala", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3730569, text = "I'VE BEEN BURNING THIS WHOLE WORLD TO ASHES ALL OVER ONE LICKLE WHISPER TO THIS BULLY STROLL" },
            { id = 3730656, text = "THE SHADOWS TAKE YA!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3730570, text = "Oh, you like me whispers, little chieftain? Who's gonna send your soul to the morn itself? But your bond to this world be too hard to break." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3730660, text = "Foolish mortals! Me be the true god of death!" },
            { id = 3730565, text = "Hahahaha, foolish Loa, don't be stopping me, Boa. First, I'll be feasting on your followers. Then you." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3730567, text = "It be too late. Me gave a ancient spirit the chance to be joining me. They made a bad choice. And now, they be trapped in the mall." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3730659, text = "Darkness be mine to command!" },
            { id = 3730566, text = "Ha! Me no bow down to your cheap tricks!" },
            { id = 3730655, text = "So small, so weak!" },
            { id = 3730658, text = "There be no escaping that!" },
            { id = 3730568, text = "You don't be stoppin' to Jira, he'll be workin' his plans for a long time, a looooong time." },
            { id = 3730654, text = "Your life be mine!" },
        } },
    } },
    { who = "Mug", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 6213571, text = "EAT MOLTEN FIST!" },
            { id = 6213553, text = "LET'S FINISH THIS SEA!" },
            { id = 6213562, text = "NOW I'M MAD!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6213570, text = "Feel the burn!" },
            { id = 6213568, text = "Hit him with both barrels!" },
            { id = 6183932, text = "Nobody passes without permission from the boss." },
            { id = 6183936, text = "You got it, Zee!" },
            { id = 6213563, text = "You're headed six feet under!" },
        } },
    } },
    { who = "Muln Earthfury", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1407225, text = "We have put an end to the rituals, but I fear the worst is yet ahead of us." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407227, text = "By the Earth, Mother, it is just as I feared. The Twilight Dragonflight has returned." },
            { id = 1407230, text = "By the Earth, Mother." },
            { id = 1406862, text = "Lead on, Forseer, and I shall follow." },
            { id = 1406857, text = "The Earthen Ring stands with you, Farseer." },
            { id = 1407222, text = "The servant of Farazane is bound by the dark powers of the Void. I hope we are not too late." },
            { id = 1407220, text = "These are troubling words, Farseer." },
            { id = 1407224, text = "This one is almost lost to the corruption. We must hurry." },
            { id = 1407223, text = "Twilight whelps. I thought the Twilight Dragonflight were extinct." },
            { id = 1407221, text = "We must defeat the Twilight's hammer and restore balance to Deepholm." },
            { id = 1407251, text = "We should return to the heart of Azeroth, Farseer. There is still much to be done." },
            { id = 1407226, text = "We should return to Therazane and inform her of what has transpired here." },
        } },
    } },
