        { name = "Conversation", family = "Feelings", lines = {
            { id = 3609544, text = "A blade is a tool. The skill is in the hand that wields it." },
            { id = 3609540, text = "Do let me know if you come across anything... challenging." },
            { id = 3609543, text = "Guard. Turn. Parry. Dodge. Spin. Thrust." },
