            { id = 3609422, text = "Mortal! Over here!" },
            { id = 3609412, text = "Oh, you know me. A different age, a different cage." },
            { id = 3609539, text = "Remember me next time you're in for a fight." },
            { id = 3609542, text = "Revendreth, where no one should know your name." },
            { id = 3609429, text = "We must part ways for now, as I have some vengeance to dispense. I do hope our paths cross again. Try not to die." },
