        { name = "Mockery", family = "Menace", lines = {
            { id = 1405877, text = "I had things well in hand. Those fools were weak. We are better off without them.\"" },
            { id = 2922268, text = "Worthless scum! You are unfit to grovel before my queen!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2958667, text = "Take no prisoners, slay every landwalker you see!" },
