            { id = 2924476, text = "Merely glimpsing my queen's visage would strike you blind." },
            { id = 2924478, text = "Yes, my queen!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2924485, text = "Abyss, claim me." },
            { id = 1405884, text = "Anyway, follow me. There's something over here I need your help with." },
            { id = 1405879, text = "Chergosh and the others didn't make it? How convenient." },
            { id = 2923966, text = "Clean Azshara! More land walkers approach!" },
            { id = 2922264, text = "For Queen Azshara!" },
            { id = 1405883, text = "Found Tyrannus too late, did you? Pity." },
            { id = 1405885, text = "I'll have that book now, and you'll be having a little accident." },
            { id = 2922258, text = "In the depths, everything changes!" },
            { id = 2922267, text = "Is that the best you can do?" },
            { id = 2958668, text = "More troops to the palace gates! Drown the enemy in their blood!" },
            { id = 2922260, text = "Such an easy target!" },
        } },
