        { name = "Conversation", family = "Feelings", lines = {
            { id = 1314252, text = "Fight well, slay many demons, try not to die." },
            { id = 1884158, text = "For Queen Azshara!" },
            { id = 1314258, text = "How can I aid you, little one?" },
