    { who = "Naielle", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1056525, text = "None can hide from the Rangari." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1056517, text = "Go with my blessing, Yiro. Do not forget those less fortunate." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1056523, text = "We are the eyes of the prophet." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1056526, text = "Did you ever get a hoof to the crotch? Want to know what that feels like?" },
            { id = 1056520, text = "Fight on your own terms." },
            { id = 1056519, text = "Know your enemy." },
            { id = 1056521, text = "The drama I shall overcome." },
            { id = 1056522, text = "This is such a puzzling world." },
            { id = 1056518, text = "Travel light and move quickly." },
