    { who = "Ner'zhul", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1041687, text = "You are just in time! Witness the dark majesty of the void!" },
            { id = 1041681, text = "Your soul shall serve me." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1041689, text = "Darkness is my strength! With this power, the Shadow Moon will be conquerors!" },
            { id = 1041683, text = "I am the herald of the end!" },
            { id = 1041688, text = "I will save my clan, even if I must forfeit the souls of my ancestors!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1041679, text = "The darkness, it flows within me. It seeps from every vein. Come, strangers. Gaze into the eyes of the void. Tender your souls to me. Muhahaha!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1041684, text = "A kindling of bone and shadow, army of the dead arise!" },
            { id = 1041680, text = "Peer into the gateway I command. Cross into the realm of the Shadowlands. I shall deliver you to your death.\"" },
            { id = 1041677, text = "The Shadowmoon cannot be defeated! We walk in the realm of death itself!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1041686, text = "Feel the void's cold embrace." },
            { id = 1041685, text = "Into the abyss!" },
            { id = 1041682, text = "You bend to my will." },
        } },
    } },
    { who = "Nethekurse", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 556464, text = "RUN, COWARD! RUUUUUUU UUUUUUU" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 556467, text = "I had more fun torturing the peons!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 556459, text = "Beg for your pitiful life!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 556466, text = "Come on! Show me a real fight!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 556469, text = "I'm already bored!" },
            { id = 556473, text = "Oh, just die!" },
            { id = 556465, text = "Your pain amuses me." },
        } },
    } },
    { who = "Nether Prince Durzaan", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1785288, text = "Even shattered as it is, this place echoes with the whispers of the Great Ones who were slain, and the hatred of he who broke this world." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1785287, text = "My people were reshaped by the void, stripped of the limitations of flesh. We offer you the same gift." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1785292, text = "A minor setback. What is in motion cannot be undone. Surely you see this." },
            { id = 1785291, text = "A pity you remain defiant. The patience of the masters is vast, but not infinite." },
            { id = 1785285, text = "At last, the future I foresaw has come to pass. Thank you for opening the way." },
            { id = 1785294, text = "Do you not see what we offer? The majesty of chaos, the glory of infinite hunger!" },
            { id = 1785286, text = "Names are of little consequence. A more interesting question is... What shall you become?" },
            { id = 1785296, text = "So be it. Your death is regrettable, but necessary." },
            { id = 1785293, text = "The Void will transform you, awaken what you were meant to be." },
            { id = 1785289, text = "We are on the same side windrunner no matter what that traitor has taught you" },
            { id = 1785295, text = "Why do you fight your destiny Windrunner? Join me and rule by my side!" },
            { id = 1785290, text = "Why do you resist? You stand on the threshold of a grand destiny." },
        } },
    } },
    { who = "Nethermancer Sepethrea", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 556497, text = "Don't value your life very much, do you?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 556495, text = "And don't come back!" },
            { id = 556491, text = "In dollar, fin-el, in doll!" },
        } },
    } },
    { who = "Newt", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 1915575, text = "Hey, uh, you've been great and all, but we can handle the rest here." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1915578, text = "And BOOM goes the bad guy!" },
            { id = 1915579, text = "Aww, they blow up so fast, I can't even enjoy it! Well, maybe I can enjoy it a little." },
            { id = 1915580, text = "Eh, tonight you're sleeping with the swamp fishies!" },
            { id = 1915582, text = "Hehe, boss, uh, we got some screws missing in places that the manual clearly says require screws!" },
            { id = 1915583, text = "How many more of these goons we gotta blow up before they get a message?" },
            { id = 1915574, text = "Oh, come on! 80% is plenty! Why push it and risk blowin' the deal?" },
            { id = 1915573, text = "Oh, I thought I was gonna suffocate in there! Thanks, pal!" },
            { id = 1915572, text = "Out of my way! That gold's got my name on it!" },
            { id = 1915577, text = "We got a beard problem here!" },
            { id = 1915581, text = "Well, excuse me, Princess!" },
            { id = 1915576, text = "You can ride my rocket back to your base. It's a one-way trip though, so don't fire it up until you're all set to go." },
        } },
    } },
    { who = "Nexus Prince Bilaal", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1382053, text = "I HAVE BECOME VOID!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1382052, text = "You are too late, Interloopers! Nothing can stop me now!" },
            { id = 1382546, text = "You are too late. Even now the powers within the vault serve to widen the breach into the twisting nether." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1382535, text = "Fools! You may have destroyed the Surge Needles, but you are too late to stop us! The power of Eluneth will rip open the breach!" },
            { id = 1382046, text = "Fools! You may have destroyed the Surge Needles, but you are too late to stop us! The power of Light's wrath will rip open the breach!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1382054, text = "The Ethereum will rise again!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1382065, text = "Another intruder come to claim the treasures of the Nexus Vault!" },
            { id = 1382055, text = "What?! The void cannot be defeated! No!" },
            { id = 1382571, text = "Who dares to... What have we here?" },
            { id = 1382547, text = "With this power, the Ethereum will become unstoppable! We will become void!" },
        } },
    } },
    { who = "Nexus Princess Kyevezza", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5778624, text = "You cannot escape my blade!" },
