        { name = "Loyalty", family = "Manners", lines = {
            { id = 1404052, text = "He and his allies were concocting a plot to poison Elisande. That will teach him to mess with a Moongrow." },
            { id = 1404059, text = "We are the chosen ones." },
            { id = 1784036, text = "We are the defenders of Suramar." },
