        { name = "Conversation", family = "Feelings", lines = {
            { id = 1784035, text = "After 10,000 years of isolation, I was looking forward to some company. But this wasn't what I had in mind." },
            { id = 1784031, text = "Another satisfied customer." },
            { id = 1784034, text = "As the wrath has certainly gone downhill since we've been away, this planet could use a makeover." },
            { id = 1404100, text = "Be gone, fiends!" },
            { id = 1784029, text = "Enjoy your purchase." },
            { id = 1404048, text = "Enough of this! To me, Suezh! Destroy these interlopers!" },
            { id = 1404106, text = "For Sorama! For Elisande!" },
            { id = 1404050, text = "Is that how it is, clever girl?" },
            { id = 1784033, text = "No, I will not blow magic bubbles! Stop asking!" },
            { id = 1404053, text = "Oh, I feel unwell." },
            { id = 1404055, text = "Oh, I must find a physician!" },
            { id = 1404051, text = "So you've taken care of our little pet, have you? No matter. I will show you why I am the Alpha!" },
            { id = 1404105, text = "The Shalturi will rule this world!" },
            { id = 1404102, text = "Their defenses are breached." },
            { id = 1404054, text = "Ugh, what is happening?" },
            { id = 1404058, text = "We cannot be stopped." },
            { id = 1404101, text = "We must hold him here!" },
            { id = 1784028, text = "We only sell the finest quality goods." },
