    { who = "Nightborne commoners - feminine voice", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1404342, text = "I bought this off a scout patrol. He called it a selfie camera. Any idea what it is?" },
            { id = 1404340, text = "I don't understand. This isn't the city. Where" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1404341, text = "Ah! You must be astral! Finally! The first thing I shall do when I get back in the city is drink a cool tall glass of Arcwine." },
            { id = 1404346, text = "Enough! Get out of our city!" },
            { id = 1404348, text = "Hush, they are nearby." },
            { id = 1404345, text = "It will be easier for me to travel on the road." },
            { id = 1404338, text = "More exiles, like me. All I did was punish those servants. You would have done the same!" },
            { id = 1404344, text = "These lamps guided me to this place. I only hope the path on my return is safe." },
            { id = 1404343, text = "Walk in Starlight!" },
            { id = 1404347, text = "We cannot endure your presence any longer." },
            { id = 1404339, text = "Yes, I am ready. Let us make haste. I worry that we will be found by our enemies." },
            { id = 1404349, text = "Your vile magic is an abomination!" },
        } },
    } },
