            { id = 1404144, text = "Hush! They are nearby!" },
            { id = 1404137, text = "Silence! I tire of your prattling! Do not worry. It will all be over soon." },
            { id = 1404136, text = "We are here." },
            { id = 1404145, text = "We cannot endure your presence any longer!" },
