        { name = "Idle", family = "Feelings", lines = {
            { id = 6438888, text = "AAA!" },
            { id = 6438892, text = "HEHEHEH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6180690, text = "And here, I thought I'd have to come huntin' for you! How's Renzec doin'? Oh! Ha! Ha! Ha! Ha!" },
            { id = 6180684, text = "Aw, what's the hurry? Can't you see how much fun I'm having?" },
            { id = 6180162, text = "Cuz Dark Fuse keeps you nobodies in line!" },
            { id = 6438890, text = "Ha Ha Ha ha!" },
            { id = 6180031, text = "Haha! They keep up or they go under." },
            { id = 6180679, text = "Hahahaha! That's right! Run! The streets belong to Dark Fuse! Don't forget it!" },
            { id = 6180165, text = "Have fun! Ha Ha Ha ha!" },
            { id = 6180686, text = "Ooh, I wonder what this one will do!" },
            { id = 6180024, text = "Those spy copters are for your safety, so if we lose any more, I'll murder you all!" },
            { id = 6180685, text = "What are you gonna do about it? We have the black blood! You're outgunned! AHAHAHA!" },
            { id = 6180164, text = "You're the one who gets to stick around and mop up this mess!" },
        } },
    } },
    { who = "Nimue", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5342586, text = "PROTECT THE DREAM!" },
            { id = 5342589, text = "YOU BRING DISORDER!" },
        } },
