    { who = "Oakin Ironbull", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1274600, text = "You have my thanks, champion." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1415271, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1277209, text = "I've got a bad feeling about this." },
            { id = 1277205, text = "Meet me in the cave below, they'll want to see the corpse of the harpy you slew." },
            { id = 1277207, text = "Something about this doesn't seem right." },
            { id = 1277195, text = "We're here to meet with Torok. My companion slew the Witch of the Wood." },
        } },
    } },
    { who = "Observer", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1385175, text = "I see spirits all throughout the ruins of this land, souls ready to be harvested." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1385187, text = "Ah, from this height, I can see everything!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1385207, text = "Look at this city! So much magic to feed upon!" },
            { id = 1385219, text = "There's green everywhere, just not my preferred shade." },
            { id = 1385197, text = "What a drab place. It would look far better covered in fire." },
        } },
    } },
    { who = "Odyn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1275622, text = "Every opponent has a weakness. I will find yours!" },
            { id = 1275618, text = "Let us see if your wits are as sharp as your weapons!" },
            { id = 1275610, text = "My power is beyond anything you have yet faced!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1275602, text = "I feel... invigorated. Care to try again, champions?" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1275576, text = "Do not be ashamed, you fought with courage and honor." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1275620, text = "An agile mind is as deadly as the sharpest blade." },
            { id = 1275612, text = "Be warned champions, I will hold nothing back!" },
            { id = 1275628, text = "Mighty Valarjar, heed my summons!" },
            { id = 1275608, text = "Most impressive. I never thought I would meet anyone who could match the Valarjar's strength. And yet here you stand." },
            { id = 1275604, text = "There is no shame in defeat, so long as one fights with valor." },
            { id = 1275606, text = "There is one final trial that awaits. Me. Should you triumph, I will carve your names in these sacred halls myself and grant you a reward worthy of your valor." },
            { id = 1275614, text = "Yield now, or I will call upon my true power!" },
        } },
    } },
