        { name = "Conversation", family = "Feelings", lines = {
            { id = 3434338, text = "All. Over. Now." },
            { id = 3434330, text = "Boss, say you too late!" },
            { id = 3434334, text = "Bossy smash! Me smash!" },
            { id = 925066, text = "Ha Ha Ha ha!" },
