    { who = "Ohn Seshteng", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4678313, text = "Come, help me place these totems for the ritual." },
            { id = 4675193, text = "Go with Onara's blessing." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4675198, text = "May Onara's breath lift your spirit." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4675194, text = "Do your best." },
            { id = 4678319, text = "Feathers of the waterfowl, creatures of sky and river." },
            { id = 4678322, text = "Lifeblood of a beast, ready for runes in her elegant script." },
            { id = 4675195, text = "Off to your next adventure?" },
            { id = 4675199, text = "Oh Nora, give me strength." },
            { id = 4678316, text = "Reads of the river, here to whistle her song." },
            { id = 4678331, text = "The wind is your song, Mother Eagle. Show me!" },
            { id = 4675197, text = "What news do you bring, outsider?" },
            { id = 4675196, text = "Who has the wind brought today?" },
        } },
    } },
    { who = "Okir", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4677825, text = "I can spare no hunters for the konamatra now." },
            { id = 4661274, text = "My voice is dedicated to my Khan." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4661276, text = "Direct your attention to my con." },
            { id = 4661272, text = "May your hunt be successful!" },
            { id = 4661277, text = "Please do not perceive me." },
            { id = 4661275, text = "Sansa Khan welcomes you to our fire." },
            { id = 4677675, text = "Shikar! Follow the thunder of your Khan's attack!" },
            { id = 4677657, text = "The proto-dragon Grannith was nearly in our grasp when Balakar's warriors ambushed us." },
            { id = 4661271, text = "Watch the sky." },
            { id = 4677678, text = "We must retake our weapons of war and drive the Nokud back." },
            { id = 4677660, text = "When Grannith's blood soaks the ground, our purposes can align." },
        } },
    } },
    { who = "Okri Putterwrench", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2011168, text = "I only require a few more minutes, Rosalind. With the help of the Enhanced Harpoons, you shall triumph over your quarry!" },
            { id = 2011169, text = "Inform me when you are prepared to go! Time is fleeting and the monster shall not hesitate!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2011167, text = "I await your return with great anticipation!" },
            { id = 2011166, text = "My plumarious feathers! You scared me!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2011165, text = "Brother Tharold, Lord Stormsong, you've arrived at a most fortuitous time. We require your aid." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2011170, text = "May the tides bring us into proximity again!" },
            { id = 2011171, text = "Need a specific gizmo? A gadget? Perhaps a doodad!" },
            { id = 2011172, text = "Please return posthaste!" },
            { id = 2011173, text = "The outriggers are prepared for anything!" },
            { id = 2011174, text = "The terror of the sea, swayed by Deep Warden's dark master! Perhaps too large a monster even for the outriggers!" },
            { id = 2011175, text = "Well, I sure hope so! Because there's something else coming this way!" },
        } },
    } },
    { who = "Ol Waxbeard", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5769470, text = "FOR CANDLE TING!" },
            { id = 5769476, text = "LET'S GO, WICK!" },
            { id = 5769477, text = "MOVE! MOVE, WICK!" },
            { id = 5769475, text = "MY MANCOT, NOW!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 5769467, text = "Move, weaklings! Here we come!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5769479, text = "Better watch out!" },
            { id = 5769469, text = "Fight Wipespeared! Fight Weak! Stupid!" },
            { id = 5769478, text = "Here it comes!" },
            { id = 5769474, text = "Now dodge my cart!" },
            { id = 5769473, text = "Whitelings, help Blackbeard!" },
            { id = 5769472, text = "You dead! Hahahaha!" },
        } },
    } },
    { who = "Olaf", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4661556, text = "Leave this to me!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 4770628, text = "GAH!" },
            { id = 4770610, text = "OH!" },
            { id = 4770626, text = "UGH!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4661561, text = "Hey, what now? All I see are books." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 4661565, text = "Yeah! We're calling dibs on this room! Safe travels all!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4661813, text = "Eat my shield!" },
            { id = 4661549, text = "Have we found any riches? We've been digging down here so long, I can't even think straight!" },
            { id = 4661558, text = "I'll stow my head!" },
            { id = 4661551, text = "Nice work! That frog has been a real pest." },
            { id = 4661817, text = "Time to move this thingy!" },
            { id = 4661826, text = "You know, I think that tussle actually helped clear my head!" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 4770426, text = "GRR!" },
            { id = 4770424, text = "GRRR!" },
            { id = 4770428, text = "HMM!" },
        } },
    } },
    { who = "Olbarig", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5708672, text = "Fly high, strike true." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5724875, text = "Something like that. But you weren't afraid of the truth, Luftsele. And that's why you deserve this." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5724877, text = "At some point he changed, more like one of those shaman, like Thrall." },
            { id = 5724878, text = "But I realized it didn't matter, the way he called them." },
            { id = 5708670, text = "Honor the titans, but don't wait up for them." },
            { id = 5708673, text = "May the path you forge be your own." },
            { id = 5708674, text = "State your business." },
            { id = 5724880, text = "Sure, he went through many recharges, but he knew what the titans had done to the rooks was wrong." },
            { id = 5708675, text = "Ugh, conversation initiated." },
            { id = 5724879, text = "We fought about it, that's why I finally left. He wouldn't admit it." },
            { id = 5708676, text = "What do you want?" },
            { id = 5708677, text = "You annoy me more than Balgrim ever did." },
        } },
    } },
    { who = "Oldgods", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1033774, text = "Our herald Akomai arises from the depths. You have earned the honor of being the first he devours." },
            { id = 1033773, text = "You are unworthy of being devoured by Akomai. Instead, our sacrifices shall tear the flesh from your bones." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1033772, text = "Savor this victory, mortal. Now that you've heard our whispers, it is only a matter of time until you belong to us." },
        } },
    } },
    { who = "Olmyr the Enlightened", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
