    { who = "Orcs", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3677938, text = "I thought death was the end of existence. Here, it seems. Death is a power that offers new beginnings." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3636450, text = "And I will reassure that justicar, she has our full support. Our reinforcements will be arriving shortly." },
            { id = 3636452, text = "And make sure you bring Lieutenant Althera up to speed before you return. She will be awaiting your initial reports at the crossroads." },
            { id = 3587149, text = "Blood and thunder, soldiers! We've been trying to push our way past the storm!" },
            { id = 4323305, text = "We trusted you! You betrayed us all!" },
