    { who = "Orcs - masculine voice", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1123762, text = "CRUSH THAT WICK!" },
            { id = 899563, text = "FOR HELL'S SCREAM!" },
            { id = 1052823, text = "FOR THE FROSTWOLVES!" },
            { id = 899561, text = "FOR THE TRUE HORDE!" },
            { id = 902723, text = "GET BACK IN LINE!" },
            { id = 1123763, text = "NOW YOU DIE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 902731, text = "Very well. If you won't talk, you won't need your head anymore." },
            { id = 1123764, text = "You cannot stop us!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 899559, text = "I am Dragon Maw! I am the blood of the dragon and the fist of the horde!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1033661, text = "Help me!" },
            { id = 1052822, text = "Run with the pack!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1033660, text = "We must leave this place!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 998339, text = "Ah, you wade to a river of souls, stranger. It is mass to turn back." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 998343, text = "This was once a place of peace, a place for eternal rest." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 998341, text = "An eternity in darkness cannot escape." },
            { id = 902171, text = "Deal with the devil's awe first, then we'll lock the rest up." },
            { id = 902729, text = "Do you see this burning candle? You haven't till it burns out to tell us about the Pandaren artifacts. Ugh... Start talking!" },
            { id = 1052824, text = "Fight as one." },
            { id = 902727, text = "Have anything to say for yourself, pandaren!" },
            { id = 902725, text = "If you move, I will spill your entrails all over the floor!" },
            { id = 902167, text = "It's busting out of the cage! I'm the shock collar! Get that thing under control!" },
            { id = 902169, text = "Shock it until it can't move anymore! It's causing a riot in here!" },
            { id = 1052825, text = "SPEAK" },
            { id = 1033659, text = "This is madness!" },
            { id = 902717, text = "We still have forces in that tower!" },
            { id = 1052826, text = "What is it?" },
            { id = 899555, text = "You dare try to take my tower? Hahahaha!" },
        } },
    } },
