    { who = "Orik Trueheart", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1390338, text = "I found a Vrykul saga describing a powerful shield tear-crafted for his Vrykul champion to carry into battle." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1388472, text = "Farewell to ye." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1390337, text = "Since the defeat of the Lich King, I've spent my time around Ulduar learning about Tyr. He was the only titan keeper who fought Loken during his betrayal." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1390340, text = "Aye, that's my hope. With your help, we have a chance of finding this artifact." },
            { id = 1388474, text = "How do you do it?" },
            { id = 1390341, text = "Just mount this wee birdie here and follow me to Stormheim!" },
            { id = 1388471, text = "See ya around!" },
            { id = 1390343, text = "The tower in the middle of Doloran has a portal to Wyrmrest Temple. Should get you most of the way there. Tahu, thanks again for helping us paladins." },
            { id = 1390342, text = "You made it! This land haunts me still. So much pain and death. Well, let's get on with it." },
        } },
    } },
    { who = "Ornekka", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1057532, text = "And I see you out there, Ashad. No use hiding from me, darling. Come here. Come here!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1057538, text = "Take care." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1057541, text = "Greetings" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1057536, text = "Farewell!" },
            { id = 1057537, text = "Safe travels!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1057535, text = "But my old bones would only slow you down. I'll be fine here." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1057540, text = "Are you lost?" },
            { id = 1057539, text = "Be careful out there!" },
            { id = 1057542, text = "Can I help you?" },
            { id = 1057534, text = "Oh, how sweet of you, Rashad. I never knew you cared." },
            { id = 1057531, text = "Yes, yes, I understand. I will tell you the way." },
            { id = 1057533, text = "You too, Percy! That's it! Give old Ornica some sugar!" },
        } },
    } },
    { who = "Ortell", tier = "character", groups = {
