        { name = "Boasts", family = "Menace", lines = {
            { id = 5722391, text = "I shall watch for you." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5722374, text = "Do not fear the dark." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5722366, text = "Let nature take its course." },
            { id = 5722382, text = "Perhaps we'll meet again." },
            { id = 5722416, text = "So, your path leads you here." },
            { id = 5722400, text = "Speak to me." },
            { id = 5722432, text = "The roots brought us both here." },
            { id = 5722350, text = "The world watch over you." },
            { id = 5722340, text = "Wild guide you all." },
