    { who = "Osseus", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1589631, text = "FEED ME WITH YOUR SCREAMS!" },
            { id = 1589632, text = "YOUR SUFFERING WILL BE LEGEND" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1589630, text = "I will cut you to the core!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1589626, text = "Admit that I am right. Break the body, and the spirit follows." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1589629, text = "Agony impales you!" },
            { id = 1589637, text = "Ha ha, too much to endure!" },
            { id = 1589635, text = "Heh! Another broken body!" },
            { id = 1589633, text = "How much can you withstand?" },
            { id = 1589628, text = "Pain, pain beyond measure!" },
            { id = 1589634, text = "This will hurt! I promise!" },
            { id = 1589627, text = "Yes! Let them come! Their bodies will fuel the flames of their burning world!" },
        } },
    } },
    { who = "Othaar", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1033790, text = "I agree. Stand down, Exarch. Enough damage has been done." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1033791, text = "Ah, it's you. Trust me, friend. I will handle this. You may go." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1033783, text = "We will rise again." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1033788, text = "Exalt Nihil, weren't you overheard arguing with Hetaru earlier?" },
            { id = 1033784, text = "Never forget." },
            { id = 1033793, text = "Oh! Damn him! I thought I'd gotten rid of Maladaar when I gave him up to the Iron Horde!" },
            { id = 1033787, text = "Our power is supreme." },
            { id = 1033782, text = "Someday, we will recreate the glory of Argus." },
            { id = 1033785, text = "The people speak through me." },
            { id = 1033786, text = "What brings you to the X-Arcs?" },
            { id = 1033792, text = "What is that? Is that Maladar's work? No, no. You don't need to do that! He is not to be trusted!" },
            { id = 1033789, text = "You seem to know an awful lot about the tools of our enemy." },
        } },
    } },
    { who = "Otis", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 1858657, text = "Ah, you did it! I knew me pooch would help out! Man's best friend, that one." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1858659, text = "A pleasure doing business with you. Now if you don't mind, I'll take me leave before my absence is noticed." },
            { id = 1858653, text = "Ahoy! You lot got the look of proper cutthroats, not like the usual scum that passes for pirates round here." },
            { id = 1858658, text = "As promised, here's some official Cutwater Corsair Regalia. Now you look like respectable criminals." },
            { id = 1858655, text = "But first, I got a problem. This here lock ain't cooperatin' with my attempts to pick it! That mangy dog's got the key, but he's a slippery one." },
            { id = 1858654, text = "If you're itching to make some mayhem, you'll need a meeting with the Council of Captains! I can help with that." },
            { id = 1858656, text = "So? You scratch my back, I return the favor. Got me?" },
        } },
    } },
    { who = "Outlaw Pirate Boss", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1989673, text = "You will regret seeing this." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1989671, text = "Don't worry, I'll get rid of this pest." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1989669, text = "Always a pleasure doing business with you, m'lady." },
            { id = 1989672, text = "Lady Waycrest is a powerful enemy." },
            { id = 1989668, text = "Nothing personal, kid." },
            { id = 1989670, text = "Seems we have a visitor." },
        } },
    } },
    { who = "Outlaw Pirate Generic", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2018372, text = "STAND AND DELIVER!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1983832, text = "Come at me, you briny hogs! I'll fly your hides as we do colors!" },
            { id = 1999469, text = "Steady as she goes, helmsman." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1999468, text = "Clients want to stop right now. We're shoving off" },
            { id = 1999470, text = "Helmsman, steer us away!" },
            { id = 2018371, text = "I'll cut you from stem to stern!" },
            { id = 1999471, text = "No, you idiot! The other away!" },
        } },
    } },
    { who = "Overlord Geyarah", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1993366, text = "With every victory, you will show the people of Azeroth that we are masters of war.\"" },
            { id = 1993368, text = "You have fought countless battles across the face of Azeroth. You have shown both our allies and enemies what it means to be Mag'har." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1993360, text = "We are the last survivors of a proud tribe, the uncorrupted, the unbroken, the Mag'har!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1993359, text = "Mere words to others, but everything to us." },
            { id = 1993367, text = "No matter where your journey takes you, never forget that the Heart of Draenor beats within you. Lok'tar ogar!" },
            { id = 1993365, text = "Now, the Horde needs our strength against the Alliance, and we have answered their call." },
            { id = 1993364, text = "Our people remained united under the leadership of Grommash Hellscream. One tribe, the Mag'har." },
            { id = 1993369, text = "Return to Orgrimmar, that I may recognize your dedication to our people." },
            { id = 1993358, text = "Strength and honor, blood and thunder!" },
            { id = 1993361, text = "War grips this land. Good! We will revel in the carnage! And claim victory!" },
            { id = 1993363, text = "Years ago, the heroes of this world journeyed to Draenor and fought beside us against the Burning Legion." },
        } },
    } },
    { who = "Overseer Brutarg", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1314800, text = "BOOM!" },
            { id = 1314805, text = "BRRR!" },
