        { name = "Conversation", family = "Feelings", lines = {
            { id = 6180419, text = "So we can tell Gallywix." },
            { id = 6180441, text = "The warehouse. The hostages. He already knows." },
            { id = 6216395, text = "This shall fix the dark, huh?" },
            { id = 6180390, text = "We need way more black blood than this! If we was paying you, this would be coming out of your checks!" },
        } },
