    { who = "Overseer Ingra", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1524162, text = "BEHOLD THE INFINITE LEGION!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1524088, text = "More souls to fuel the portal!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1524138, text = "No! The portal!" },
