    { who = "Paku", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1994039, text = "You are both alive! Good! Just as I said." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1994041, text = "Ah, another answers the call of the skies!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1994042, text = "For the first time, they will feel the wind beneath their wings! The joy of flight! They" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1994036, text = "For now, we are going to teach it an object lesson." },
            { id = 1994034, text = "Rastakhan! The snakes of Vol'dun siege your western border! Do something about it!" },
            { id = 1994037, text = "Small thing, if you want to return to the nest, you had best start running." },
            { id = 1994032, text = "Something drives the Sethra to attack. They are swarming like never before." },
            { id = 1994033, text = "Well, that is inconvenient." },
            { id = 1994043, text = "Well, that sometimes happens too." },
            { id = 1994038, text = "What did you expect? It just hatched. It must feed. Go, that's the kraal for some meat." },
            { id = 1994040, text = "Why are you still using your legs?" },
            { id = 1994035, text = "Your little one has no faith in its wings. You must continue to show it the joy of the skies!" },
        } },
    } },
