            { id = 632608, text = "Family, friends, food, these are what matter most." },
            { id = 632516, text = "Have you seen the sights of Pandaria?" },
            { id = 641888, text = "Hm?" },
            { id = 632512, text = "Is there not something more productive you could do with your hands?" },
            { id = 632963, text = "It is called... Touch me again and I will kick your face!" },
            { id = 641994, text = "It is said, wise men do not poke bare." },
            { id = 641978, text = "Jade Serpents guide you." },
            { id = 642074, text = "Keep your eyes and heart open." },
            { id = 632610, text = "May you find mastery in your passions." },
