            { id = 641884, text = "Slow down." },
            { id = 632606, text = "Slow down. Life is to be savoured." },
            { id = 632959, text = "So, you like to play games?" },
            { id = 632506, text = "Tell me of your travels." },
            { id = 641988, text = "Tell me of your troubles." },
            { id = 642076, text = "The world is your teacher." },
            { id = 641976, text = "There is no hurry." },
            { id = 632496, text = "Travel safe." },
            { id = 642092, text = "We never treated our elders such when I was a cub." },
            { id = 641886, text = "What do you need?" },
