    { who = "Patch", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1997774, text = "CURVE BALL! CURVE BALL!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1997766, text = "50,000 gold pieces to the first one who gets to that deployment point!" },
            { id = 1997764, text = "Alright team, let's move!" },
            { id = 1997770, text = "Giant! Incoming! Hey! That's the guy that wrecked our ship! Time for some payback!" },
            { id = 1997768, text = "Great to see you all made it back in one piece. Thanks to... Hey, there's the guy of the hour!" },
            { id = 1997771, text = "I've got juuust a thing to do with them! Let them have it!" },
            { id = 1997767, text = "There's a hidden spot over on the other side of these ruins that would make a perfect base of operations. Tell the team to rendezvous there." },
            { id = 1820035, text = "We need to check the accuracy of the gun before we can do anything else, so why not get rid of a few of those naga at the same time?" },
            { id = 1997765, text = "We're set up and ready to go. Just hop on in." },
            { id = 1997773, text = "Whoa! You got their attention now! BIG HEART INCOMING!" },
            { id = 1997769, text = "Whoa, watch out! They've got cannons firing in opposition! Take them out with some cluster shots!" },
            { id = 1997772, text = "You heard the princess, let her rip!" },
        } },
    } },
