    { who = "Pathfinder Jeb", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4643077, text = "Don't panic. We've prepared for this." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4643076, text = "Expedition to the Dragon Isles? Sounds fun, but they've got plenty of soaring peaks to climb. Wrap it up trainees, we're moving out!" },
            { id = 4667634, text = "I'll see you before you see me." },
            { id = 4643082, text = "Like I always say, you've gotta be prepared for anything." },
            { id = 4643050, text = "Mountains to climb!" },
            { id = 4667633, text = "Mountains to climb, vistas to see." },
            { id = 4643078, text = "Phew. Unexpected. But nothing we can't handle." },
            { id = 4643079, text = "See? Thorough preparation makes quick work of any problem." },
            { id = 4643080, text = "Thanks for the help. Next time this happens, I'll be ready to handle it." },
            { id = 4643083, text = "We'd best keep moving." },
            { id = 4643081, text = "Yip should have packed spare supplies." },
            { id = 4643023, text = "You'll get lots of pictures in the Dragon Oils, Wulford. Imagine all the ancient wonders we'll be discovering." },
        } },
    } },
