    { who = "Perisimona", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 5062350, text = "Hey, my spore paws! What about the machines outside? The ones that make that terrible buzzing sound!" },
            { id = 5062355, text = "Hey, you! Hey, Drax here!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5062349, text = "Anything for my sweet-smelling snaily-kins! I mean, to Baros! Oh, follow me! I'll show you where I last saw him!" },
            { id = 5062356, text = "If you go down the road, you'll find all sorts of good salvage! Shiny stuff! Mechanical stuff!" },
            { id = 5062615, text = "I'll miss your scent!" },
            { id = 5062357, text = "Not your people? You're not Sundered Flame?" },
            { id = 5062358, text = "Oh no! They're plundering our secret stash! Me and Snallykins come out here for trinkets to sell! Ugh! That makes me mad!" },
            { id = 5062370, text = "Snailikinz, oh, you're all right. I thought I'd never smell your scent again." },
            { id = 5062359, text = "They don't want to share the vault treasures with us, but I can take you there. It's just down the road." },
            { id = 5062430, text = "Try again? You want to do this again? Oh, I will never understand your kind, but you do get up to some interesting things." },
            { id = 5062451, text = "You know, Emberthal, I didn't like your scent at first. But now, it's definitely growing on me." },
            { id = 5062371, text = "Your soldiers kidnapped my juberus and his client and took them to their camp!" },
        } },
    } },
