    { who = "Polemarch Adrestes", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3589044, text = "I am glad you arrived safely." },
            { id = 3582424, text = "I shall inform the Archon, rest until we decide our next steps." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3582411, text = "Take the time you need, Mechanicos. But do work with haste. There is much to be done." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3587789, text = "It is not our duty to ensure that souls are reaching their proper realms, it is our duty to bear them through the veil." },
            { id = 3589047, text = "The Maw Walker has proven that they are an ally, not only to Bastion, but to all the Shadowlands." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3589046, text = "Brothers and sisters, hear me. On this day, we have come together for a momentous occasion." },
            { id = 3589045, text = "In this moment we shall follow the path together. Come." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3582425, text = "On this day, we take a major step toward repairing the Way of the Kyrian." },
            { id = 3522421, text = "Pelagos is an Ardenweald, requesting an audience with the Queen. Meet him there." },
            { id = 3582122, text = "Retrieving Faestus is of utmost importance. Go with haste." },
            { id = 3587790, text = "The Archon, along with the rest of the Eternal Ones, is working to solve the problem. We must support her by fulfilling our duty, no matter what." },
            { id = 3587824, text = "The final trial before Ascension is perilous. As Pelagos is not ready, I insist that you join Kleia in this final step." },
        } },
