    { who = "Primus", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3738265, text = "I am the Primus. Your presence within my sanctum means a darkness has fallen upon Maldraxxus and all the realms of death." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3738261, text = "Enemies arise from without and within." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3738266, text = "Ages ago, the eternal ones punished our brother Zovaal for his treachery. He was bound within the inescapable maw to be forevermore its jailer." },
            { id = 3738260, text = "Duty is a mental worn by all who serve." },
            { id = 3738267, text = "Now I fear that Zovaal did not act alone. I suspect he had ancient allies and will seek to win others to his cause." },
            { id = 3738258, text = "Unto you, I bestow this power...defender of Maldraxxus!\"" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3738262, text = "Focus. Strategy. Relentlessness." },
            { id = 3738259, text = "Might without control is wasted." },
            { id = 3737459, text = "The foes of the worthy shall be vanquished!" },
            { id = 3738263, text = "Victory will be claimed, not by a single house, but through the strength of our covenant.\"" },
            { id = 3738257, text = "Within you lies the courage, might, and guile to conquer your rivals.\"" },
        } },
    } },
