            { id = 2931335, text = "I'm detecting a power node within that Trogden!" },
            { id = 2931319, text = "It seems to be moving toward Bondo's yard. You should keep your distance." },
            { id = 2931321, text = "Its flight path will take it over the heaps. I suggest avoiding that area." },
            { id = 2931305, text = "Now is our chance to disable it and acquire the access code." },
            { id = 2931322, text = "Proceed with caution! Mechagon's war machine appears to be changing course." },
            { id = 2931323, text = "Remain alert! The flying menace has altered its trajectory!" },
