    { who = "Prince Galen Trollbane", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1444599, text = "Next time you will kneel before me." },
        } },
        { name = "Mockery", family = "Menace", lines = {
