        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1416913, text = "Drive the Witherbark tribe from my kingdom, and I will grant you access to the tomb of my father." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1444597, text = "Are you here to pay tribute?" },
            { id = 1416861, text = "Guards! Seize them!" },
            { id = 1444601, text = "Hurry back, or I will unleash the hounds." },
            { id = 1416859, text = "I'm the prince! How dare you!" },
            { id = 1416909, text = "It seems your Deathlord has finally arrived." },
            { id = 1444595, text = "Out with it. I have little time." },
