    { who = "Princess Talanji", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1934882, text = "You are telling me that you got Bwonsamdi's aid and killed Hireek?" },
            { id = 1869416, text = "You have my tanks. Now the souls of the dead may travel in peace." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1869415, text = "This monster was once a guardian of the faithful. Now it feeds upon the souls of the dead. Destroy it!" },
            { id = 1934881, text = "We are not going to play this game, Bwonsamdi. You want a lower spirit? Hireek has already been killed. You go get that spirit." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1934883, text = "Amazing! But we have work to do. This leaves two Loa. We must join the Tortollans on their pilgrimage to see Torga, the Turtle Loa." },
            { id = 1934879, text = "By the Loa, no! Now we see the true power of the blood trolls. Oh father, why did you ignore them for so long?" },
            { id = 1934885, text = "Look! Blood trolls! They must be preparing to attack my city!" },
            { id = 1934878, text = "Prepare yourself! We have no idea what may be ahead." },
            { id = 1869413, text = "The very land has produced a horror! Quickly, strike it down before it can crawl its way to Zuldazar!" },
            { id = 1934884, text = "We seem to be in the clear now. We will need to move first once we land at Zul'jin Ruins." },
            { id = 1869414, text = "Well done. We cannot allow such abominations to run rampant through our lands." },
        } },
    } },
    { who = "Princess Tess Greymane", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1388567, text = "Stay alert out there!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1388565, text = "Look to the shadows." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1388571, text = "How can I help?" },
            { id = 1389352, text = "I'll have my people talk to your people. Sound good?" },
            { id = 1389354, text = "Oh, you're one of those rogues." },
            { id = 1391966, text = "Sorry boys. Looks like we're going with my plan after all. Let's talk details." },
            { id = 1388568, text = "Speak your mind." },
            { id = 1388564, text = "The job's not done yet." },
            { id = 1388569, text = "There's a potion for everything." },
            { id = 1389353, text = "Uh-huh, hmm, yup, totally paying attention." },
        } },
    } },
    { who = "Prioress Murrpray", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5769535, text = "BURN BY SACRED FLAME!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5769538, text = "My faith! My flame!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5769537, text = "Brothers and sisters, hark into the flame!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5839848, text = "Are these still strikes, lackeys? Guards, guards!" },
            { id = 5769536, text = "By Beisley Purified!" },
            { id = 5769539, text = "By the Emperor's will, shall glory return to Hallowfall." },
            { id = 5769534, text = "Flames take you!" },
            { id = 5769533, text = "Sacred Flame, grant me strength!" },
            { id = 5769540, text = "The Empire will see you burn!" },
            { id = 5769529, text = "The Sacred Flame will cleanse your transgressions!" },
            { id = 5769531, text = "Ye of little faith!" },
        } },
    } },
    { who = "Priscilla Ashvane", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1963607, text = "Suffer no insolence from the soot-smeared rabble. Make examples, if you must! All that matters is that our clients get their supplies on time." },
            { id = 1963606, text = "The chemists are producing excellent powder. You will keep them supplied with refined Azerite, or I'll find someone who can." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1963605, text = "I don't care how you do it, I want those forges running day and night." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1963642, text = "Ha! Enjoy your hollow victory, fools! Without the Kaldiran fleet, you have no hope of defeating me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1963643, text = "Allow me to demonstrate." },
            { id = 1963608, text = "And ban this note after reading it, you buffoon!" },
            { id = 1864156, text = "Corgus, explain to me why you haven't flooded the lower levels and drowned these squabbling rats!" },
            { id = 1963602, text = "Faithful employees, effective immediately, all shifts are doubled. We do not ask this of you lightly. Your hard work ensures the safety of Kul Tiras in these uncertain times." },
            { id = 1963604, text = "Kindly direct inquiries to Mr. Farthing or Mr. Williams." },
            { id = 1963603, text = "Regarding increased company presence on site, rest assured, they are here for your safety." },
            { id = 1963644, text = "Their gate has fallen, breach the city, and slay all who oppose me!" },
            { id = 1864157, text = "You'd better be right, or your replacement's first duty will be to watch you drown with the rest of this scum!" },
        } },
    } },
    { who = "Professor Ichistrasz", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4689614, text = "You are lucky we both know how to heal!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4689627, text = "I do not doubt your capabilities, but just in case..." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4689618, text = "Indeed. Come with us. It should only take a moment to set up for a new lesson." },
            { id = 4689537, text = "Let me show you the power of life magic!" },
            { id = 4689579, text = "Life magic can only do so much, you know." },
            { id = 4689534, text = "Looks like you could use my help." },
            { id = 4689624, text = "Me? There is too much nature! What are you doing?" },
            { id = 4689619, text = "Well, it seems like things are in further disrepair than we anticipated." },
            { id = 4689576, text = "What an overgrown statement." },
        } },
    } },
    { who = "Professor Maxdormu", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4673146, text = "YOU OBVIOUSLY HAVE NOT STUDIED THE MATERIAL! DETENTION!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4673148, text = "Ah, here we are! Ahem. Long ago, members of the Blue Dragonflight accidentally overloaded an arcane elemental and created a powerful construct named Veximus that quickly started to wreak havoc." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4673143, text = "Ahem, Veximus did not absorb any arcane orbs!" },
            { id = 4673144, text = "Are you trying to rewrite history? No orbs!" },
            { id = 4673154, text = "Did you not take the prerequisite? Well, try again." },
            { id = 4673153, text = "No, no, no! That is not what happened at all!" },
            { id = 4673150, text = "Since you did so well on your lesson, feel free to take something from the Good Students Reward Chest!" },
            { id = 4673147, text = "Since you keep disrupting my lesson, detention for everyone!" },
            { id = 4673151, text = "That is not what it says in the book!" },
            { id = 4673145, text = "The dragons absorbed the orbs, not Veximus!" },
            { id = 4673149, text = "Though Veximus tried its best to defeat the dragons, it was ultimately destroyed. Well done!" },
            { id = 4673152, text = "You should study harder!" },
        } },
    } },
    { who = "Professor Mystakria", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4673534, text = "Oh my, I am sure you will bounce right back!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4673539, text = "I have just the thing, give me a moment." },
            { id = 4673540, text = "I will put this potion where you can see it!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4673538, text = "Hold on a little longer. I have something for you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4673532, text = "New students! How wonderful! It has been quite some time since the Academy has been open." },
            { id = 4673529, text = "Perfect. We are just about... Wait, Ichistras. There is too much life magic. What are you doing?" },
            { id = 4673536, text = "Please, help us new students!" },
            { id = 4673530, text = "Please, if you could, clear them out while we realign the life magics of this place." },
            { id = 4673535, text = "Thank you so much for your help, though this all could have been avoided by someone not trying too hard." },
            { id = 4673531, text = "These Lashers must have grown wild while we were away." },
            { id = 4673533, text = "We...believe in you. Try again." },
            { id = 4673537, text = "What is that thing? This is your fault!" },
        } },
    } },
    { who = "Professor Putricide", tier = "character", groups = {
