    { who = "Prophet Skitra", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3185045, text = "SO EASILY CONFUSED" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3185043, text = "Your minds shall rot!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3185040, text = "I could break you now, but I shall toy with you a little longer." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3185041, text = "Are you certain any of this is real?" },
            { id = 3185048, text = "Embrace the madness!" },
            { id = 3185050, text = "How did you know?" },
            { id = 3185042, text = "Reality and illusion meld into one." },
            { id = 3185046, text = "Your eyes betray you!" },
            { id = 3185039, text = "Your minds cannot endure forever!" },
            { id = 3185049, text = "Your minds smell so delicious!" },
        } },
    } },
    { who = "Prophet Velen", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1411471, text = "I see a path that leads to our victory. You are there, walking with the Light, guiding us all.\"" },
            { id = 1411468, text = "Our order will fall at his hands. Everyone within will perish." },
            { id = 1390879, text = "Over the long years of the Draenei's flight from the Burning Legion, the Naaru helped us, sometimes at the cost of their very lives. We would have perished without their aid.\"" },
            { id = 1411469, text = "This will be our fate. We are doomed to die at the hands of the dreadlord Balnazzar!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1411467, text = "I see a great darkness looming over Netherlight Temple. The shadow of the Burning Legion, ready to strike!\"" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1411473, text = "An old enemy becomes an ally." },
            { id = 1390880, text = "At last we found a way to repay their kindness. We came upon a terrible sight, a naaru that had turned to the void. There had to be a way to save it.\"" },
            { id = 1411472, text = "It's becoming clear." },
            { id = 1390878, text = "The mages have established a portal for us to use. If you would follow me, I would speak of the Naaru and the Draenei." },
            { id = 1411470, text = "This will be our fate... unless..." },
            { id = 1390881, text = "We built a prison to contain and study the fallen creature, a place to commune with the naaru and ponder the nature of the Twisting Nether. It is here that I would take you.\"" },
            { id = 1390884, text = "Well done indeed!" },
        } },
    } },
    { who = "Protector Kah Rev", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4080848, text = "FOCUS ON THE TARGET!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4080131, text = "I have trained my entire existence for this moment, for this battle. I will follow your lead, Maw Walker." },
            { id = 4080851, text = "I stand with you." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4080853, text = "Protect the secrets, always." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4080854, text = "Well met, Maw Walker." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4080856, text = "How can I serve?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4080850, text = "Injured? The prophecies never mention that!" },
            { id = 4080852, text = "Purpose guide us" },
            { id = 4080130, text = "Reinforcements! Just in time. We are about to push toward the vault." },
            { id = 4080855, text = "Tell me your secrets." },
            { id = 4080849, text = "The prophecies of your might were true, Maw Walker!" },
        } },
    } },
    { who = "Protectors", tier = "creature", groups = {
