        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4317425, text = "My spear will find your heart!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4317423, text = "Acyrion's resolve is unbreakable!" },
            { id = 4317429, text = "Ah! I've failed! Vakirian!" },
            { id = 4317421, text = "Kyrian, protect me!" },
            { id = 4317424, text = "Nothing is sharper than a Kyrian blade!" },
