    { who = "Prototype of Renewal", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4317511, text = "BEASTS OF THE WORLD, CHARGE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4317515, text = "Your corpse shall feed my children." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4317520, text = "All things end." },
            { id = 4317518, text = "But... my aunt... has... ended..." },
            { id = 4317510, text = "Nature cannot be conquered." },
            { id = 4317519, text = "The forest must endure." },
            { id = 4317516, text = "The hunt begins!" },
            { id = 4317517, text = "The wilds have no mercy." },
            { id = 4317509, text = "Their strength harvested." },
            { id = 4317512, text = "There is no shelter from nature's wrath." },
            { id = 4317514, text = "When my seeds wither, so shall you." },
        } },
    } },
    { who = "Prototype of War", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4317472, text = "FOCUS. STRATEGY. VIOLENCE." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4317469, text = "I will carve my runes into your soul." },
            { id = 4317474, text = "My war has ended." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4317466, text = "Death's reach is inescapable." },
            { id = 4317467, text = "Flesh exists to rot." },
            { id = 4317468, text = "Let the necrosis spread." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4317465, text = "No realm exists without death." },
            { id = 4317473, text = "Shameful, shameful defeat." },
            { id = 4317470, text = "Some scars never fade." },
            { id = 4317464, text = "The pattern must be restored." },
            { id = 4317471, text = "Weakness must be purged." },
        } },
    } },
    { who = "Prustaga", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1386049, text = "The heart of this weapon will infuse me with the might of the titans! The vrykul shall bow before me, their new god queen!" },
            { id = 1386066, text = "You will not stand in my way!" },
            { id = 1386048, text = "You've played your part. Now I shall play mine!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1386019, text = "I care nothing for friendship, soft earthen. So long as this one helps us enter the tomb, I will tolerate the intrusion." },
            { id = 1386028, text = "I will dispel the runes! Protect me!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1386063, text = "You cannot stop me fools! I just need more power!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1386024, text = "Enough chatter! Move!" },
            { id = 1386044, text = "Hmm, Titan Strike is close." },
            { id = 1386031, text = "They grow in strength. Be ready." },
            { id = 1386035, text = "They're coming to life!" },
            { id = 1386040, text = "Where is Titanstrike, little tinkerer?" },
            { id = 1386068, text = "Your kind has long forced my people into servitude. No longer! Now we've fought our own destiny!" },
        } },
    } },
    { who = "Pygmy", tier = "character", groups = {
