    { who = "Pyroth", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1407253, text = "Charghor, my champion. You will pay, mortal." },
            { id = 1407186, text = "Soon, Lord Smolderon, you will kneel before the true Fire Lord!" },
            { id = 1407254, text = "You dare oppose the son of Ryolith? You will be destroyed!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407252, text = "Are you so weak, Lord Smodron, that you require the help of mortals?" },
            { id = 1407255, text = "Slain by a mortal, it cannot be!" },
            { id = 1406850, text = "You approach your demise, shaman! Turn back, while you still live!" },
        } },
    } },
    { who = "Qadarin", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3516986, text = "I wish you the best, my friend." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3516985, text = "Protect that which you hold dear." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3516988, text = "Hail, Hero of Azeroth!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3527653, text = "He invoked the dark power of Elune, and together we repelled the invaders." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3527656, text = "But our Gambit failed. We both lost our lives, and he has blamed himself ever since." },
            { id = 3527655, text = "Desperate to save him, we attempted to lessen his burden by sharing Elune's power between us." },
            { id = 3527652, text = "Fearnax knew the risks, but we had no choice." },
            { id = 3527651, text = "Please forgive my husband. Thernax became the Night Warrior to save our world, but he paid a dear price in the end." },
            { id = 3516984, text = "Regret nothing done out of love." },
            { id = 3516989, text = "The wield owes you a great debt." },
            { id = 3527654, text = "Though we had saved our world, the power of the Night Warrior began to destroy him." },
            { id = 3516987, text = "You seek knowledge of the Night Warrior?" },
        } },
    } },
    { who = "Qiang the Merciless", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 622390, text = "SOLDIERS! CRUSH THEIR FLAKE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 622378, text = "I will crush you, in body and spirit!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 622384, text = "My tactics are unbeatable." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 622392, text = "Taking attack! March into battle!" },
            { id = 622388, text = "The Emperor rules all!" },
        } },
    } },
    { who = "Qonzu", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5331357, text = "What have we here? A mortal whose mere presence changes the realm? You are very interesting indeed." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5329010, text = "Wait until you see what happens next!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 5329008, text = "Goodbye, and hello as always." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5329017, text = "Oh, that? Just an old pellet of mine. Those bones are from the last mortal who pestered me." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5329016, text = "All things must change, your behaviour most of all." },
            { id = 5329013, text = "Are you supposed to be here?" },
            { id = 5329009, text = "Getting lost is the best way to find things." },
            { id = 5331360, text = "Now, why would I want to stop the dream from changing? I think I will wait and see what happens. Try not to die, mortal." },
            { id = 5329014, text = "Oh, is this your dream, or mine?" },
            { id = 5329015, text = "Things are not what they seem." },
            { id = 5329012, text = "What a fascinating creature!" },
            { id = 5329011, text = "You've been frightfully predictable." },
        } },
    } },
    { who = "Queen Ansurek", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5778781, text = "MY STRENGTH IS YOURS!" },
            { id = 5778783, text = "POLE OF DARKNESS!" },
            { id = 5778780, text = "THE LOYAL RISE!" },
            { id = 5778779, text = "THEY... ARE FOOL FOR MY TRANSFORMATION!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 5778784, text = "You are not warriors, you are lambs to the slaughter!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5778575, text = "I tire of this game! End this now!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5778572, text = "Stop playing with your food and finish them all, Gracks!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5778777, text = "How have my soldiers failed?" },
            { id = 5778778, text = "This entire generation of Nerubians is tainted and worthy of ascension!" },
        } },
    } },
    { who = "Queen Azshara", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2025240, text = "HAAAGH!" },
            { id = 2025241, text = "HRRR!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2002977, text = "It would seem you have guests, Lord Stormsong." },
