        { name = "Mockery", family = "Menace", lines = {
            { id = 2002980, text = "Drown these insects, my children. Show yourselves worthy of my pride." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2002979, text = "Enjoy this victory. It will be your last." },
            { id = 2002981, text = "How tenacious. Feel honor in your accomplishment of living long enough to face my pride." },
            { id = 2002978, text = "You dare to interfere in my affairs. What makes you think you can oppose my will?" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
