        } },
    } },
    { who = "Queen Mia Greymane", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2108604, text = "Make them pay for this, champion." },
            { id = 2108608, text = "The guilty will pay for their crimes." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2108606, text = "My home calls to me." },
