        { name = "Conversation", family = "Feelings", lines = {
            { id = 2108591, text = "Astari, hurry! Evacuate the city before it burns!" },
            { id = 2108590, text = "Astari, there is no time to lose. We must evacuate this city before it burns to ash!" },
            { id = 2108602, text = "Save all you can!" },
            { id = 2108603, text = "So much innocent blood." },
            { id = 2108605, text = "Thank you for your service." },
            { id = 2108593, text = "They will not go." },
            { id = 2108609, text = "Time is short." },
        } },
    } },
    { who = "Queen Neferess", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5859124, text = "My people shrouded in pain." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 5859126, text = "No more darkness, pain, no more!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 5854735, text = "I, abomination, hurts, leave me, Nya." },
