    { who = "Queen Sguard Zirix", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5779299, text = "TO GROUND MY SHOULDERS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 5783507, text = "I will crush you, hahaha! I will crush all of you! NERUBIANS! RISE!" },
            { id = 5782642, text = "Stubborn Earthen, you will not impede my ascension!" },
            { id = 5783504, text = "The core way is severed. You will never reach the Harbinger." },
            { id = 5782485, text = "You are but fodder for my ascension. Die, in Anserac's name!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5782491, text = "Swarms of us to hit! Rise and devour them!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5782424, text = "Drag them screaming into the depths!" },
            { id = 5782427, text = "The Queen rewards her chosen soldiers! Destroy them!" },
            { id = 5769185, text = "We must ensure the Galway is never repaired!" },
        } },
