        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3434352, text = "We serve the Jail Lord!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1989253, text = "Alert the crew!" },
            { id = 3434354, text = "Death to the outsiders!" },
            { id = 1989252, text = "Guards! To me!" },
            { id = 1989286, text = "Now retreat! Now surrender!" },
            { id = 1989284, text = "Our boars will feed on you!" },
