            { id = 3434355, text = "Our thorns will strangle you!" },
            { id = 3434351, text = "The Geolord demands your demise!" },
            { id = 1989287, text = "The thorns will grow strong with your blood!" },
            { id = 1989279, text = "We claim this land!" },
            { id = 1989280, text = "We climb this land!" },
            { id = 3434353, text = "Witness our power!" },
            { id = 3386491, text = "You. Cannot. Stop us." },
