    { who = "Ra Den", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3235495, text = "GRRR!" },
            { id = 3235502, text = "NO!" },
            { id = 3235503, text = "ROAR!" },
            { id = 3235497, text = "RRR!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3164886, text = "Incredible. The level of expertise that would require. You are most impressive." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3184869, text = "I will take us to the Chamber of Heart. This may prove... disorienting." },
            { id = 3164888, text = "I would appreciate the opportunity to converse with you further on the matter." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3184865, text = "Hmm... Perhaps I should observe this myself." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3235515, text = "BRAWWW!" },
            { id = 3235519, text = "OOF!" },
            { id = 3235520, text = "RAWR!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3184863, text = "An intriguing discovery, Speaker, if the Mogu have learned how to focus the Forge's energies." },
            { id = 3184866, text = "Long has it been since I last saw the Forge of Origination." },
            { id = 3164884, text = "Mother, you reconfigured the engine of Nalak'sha to power the Forge of Origination." },
            { id = 3194145, text = "N'Zoth opened my eyes to his great truth. He freed me from the narrow confines of the Titan's Path." },
            { id = 3184871, text = "Odd that I was unaware of its existence." },
            { id = 3164890, text = "Oh, yes, of course." },
            { id = 3184867, text = "Storm Speaker, I leave the Rajani in defense of the engine." },
            { id = 3184870, text = "Such a magnificent facility. It looks to be of Arcadis' make." },
        } },
    } },
    { who = "Rabaan", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5708649, text = "I will return to honing my art." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5782168, text = "Affirmative. Our two companies are the fiercest in Kazalgar. They cheer for you, my friend." },
            { id = 5782043, text = "And now we begin our play to honor the Thraegar. Heroes lost to time, but not forgotten." },
            { id = 5782019, text = "And so, the Thraegar's adventure ended before they reached the bottom of the Coreway." },
            { id = 5782022, text = "But with this play, we honor the memory of the Thraegar and the core they heed." },
            { id = 5708650, text = "Conversation gladly terminated." },
            { id = 5708645, text = "Conversation reluctantly initiated." },
            { id = 5708648, text = "Do come back for the show." },
            { id = 5708647, text = "Here for an inscription of my name." },
            { id = 5708646, text = "I'm very busy. Can this wait?" },
            { id = 5782183, text = "The Earthen of Kaz-Al-Gah never wandered far from home. Except for one. The Wanderer!" },
            { id = 5708643, text = "To be, or not to be. That is the question. Oh, write that down. I'd like that." },
        } },
    } },
    { who = "Rabbits", tier = "creature", ctype = "Critter", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 5563377, text = "HAHAHAHA!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5563343, text = "Thank you for watching!" },
        } },
    } },
    { who = "Rabinesaturna", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 558755, text = "The memories in this locket swirl in anguish, such pain and suffering. Let us see what it wants to show us." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 558754, text = "I will attend to the Archdruid. Malfurion and Madoclaw have requested your presence immediately." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 558751, text = "It is. The Great War of Silithus raged over a thousand years ago. Valstan tried to save his people but was captured and killed." },
            { id = 558753, text = "Oh, this is terrible. Why would Lyara cling to this memory? Valstan must have been an important part of her life." },
            { id = 558752, text = "What? What has happened?" },
            { id = 558756, text = "Who is this? That looks like Valstan, Fandral Staghelm's only son. What is he doing? Is this a memory of the Qiraji war?" },
        } },
    } },
    { who = "Raccoon", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6220743, text = "Thank you for watching." },
        } },
    } },
