    { who = "Radovan", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 6025300, text = "Have a fuller stable than your friends list? Then you won't want to miss Mount Mania!" },
            { id = 6025292, text = "If you've got a passion for fashion, then you won't want to miss the Fashion Frenzy!" },
            { id = 6025299, text = "Ma, you are easily entertained." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6025301, text = "Behold one and all a contest like no other, and saddle on up if that is your druther. Come join a parade of fur, hooves, and wings. Report to Mount Mania and see all of these things." },
            { id = 6025294, text = "Calling all fashionistas to strut their stuff in the fashion frenzy!" },
            { id = 6025298, text = "Do you require guidance?" },
            { id = 6025293, text = "For those with a passion for silk, leather, and steel, the frenzy of fashion is all too real. Be seen by the masses. Be their envy, their desire. Become the example to which all lovers aspire." },
            { id = 6025297, text = "How may I be of service?" },
            { id = 6025289, text = "Hurry hurry, don't be late, there's much to do and celebrate!" },
            { id = 6025295, text = "Let the celebration take you." },
            { id = 6025291, text = "memories, pleasantries, comedy, and drama! Stay for the show! Come pet-a-lama! Er, alpaca." },
            { id = 6025296, text = "When in doubt, dance." },
        } },
    } },
    { who = "Radulf Leder", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2737994, text = "I can smell the Horde stench from here! We will purge them like the filth they are!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2740574, text = "Go forth with the light." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2737992, text = "It is an honor to fight beside you heroes. Together, we will drive the Horde out of Arathi Basin." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2737996, text = "Arathi Basin and its resources are crucial to the Alliance's war efforts. Secure this land in the name of Stromgarde!" },
            { id = 2739824, text = "Arathi Basin is lost. We must regroup and defend the rest of our land." },
            { id = 2739826, text = "Arathi Basin is ours, champions. The League of Arathor thanks you." },
            { id = 2737993, text = "Champions, the League of Arathor is fortunate to have you. This battle should be swift and decisive." },
            { id = 2740576, text = "Stromgarde will be restored." },
            { id = 2740575, text = "The League of Arathor will prevail." },
            { id = 2737995, text = "Victory for the Alliance!" },
            { id = 2739825, text = "We are pushing them back! Show these defilers no mercy!" },
            { id = 2740577, text = "We must secure the Highlands." },
        } },
    } },
    { who = "Raen Dawncavalyr", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5725424, text = "I'm not an ingot. You can't hammer me into shape." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5725178, text = "I support our army with the finest blades." },
            { id = 5724588, text = "The shadows don't stand a chance against my blades." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 5727572, text = "But what if I figured out the weight balancing? You said that was what you didn't like about the first few I made." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5727568, text = "Farron! I was inspired last Belladar's shadow. I designed a new arm prosthetic. I think you'll wear this one." },
            { id = 5724550, text = "The Sacred Flame tempers not just our souls, but my steel." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5725066, text = "A dangerous world calls for inspired solutions." },
            { id = 5724569, text = "Imperial steel conquered a continent." },
            { id = 5727570, text = "It's my pleasure to make a new arm you would use, Farron. You told me about the discomfort and how it impacted your mobility, so I was thinking..." },
            { id = 5727577, text = "Oh yeah? Hmm... That's a tough one. Let me sketch out some ideas and get some measurements. I think that'll be an interesting project." },
            { id = 5725085, text = "Well-crafted equipment is essential." },
        } },
    } },
    { who = "Raest Magespear", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1592954, text = "Destroy me? No brother, your blade will become my instrument!" },
            { id = 1592956, text = "Useless! Stand aside while I do what you cannot, brother!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1592951, text = "I hope you enjoy my creation, brother! It saddens me that it ends this way." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1592949, text = "You are too late, foolish brother! The twisting never awaits me, and with it, unlimited power! All of Azeroth will kneel upon my return!" },
            { id = 1592950, text = "Your tiny mind cannot comprehend the forces that will soon be at my command. Perhaps I should give you a taste." },
            { id = 1592953, text = "You're a fool to follow me, brother. The Twisting Nether feeds my strength! I have become more powerful than you could ever imagine!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1592955, text = "Kill this interloper, brother!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1592957, text = "Once again, I must clean up your mess, brother!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1592952, text = "Hah! I'm… defeated? That's… impossible!" },
        } },
    } },
    { who = "Rage of Azshara", tier = "character", groups = {
