    { who = "Ragnaros", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 558810, text = "BE CONSUMED BY FLAME!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 558794, text = "I will see you all burn!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 558787, text = "Be gone from my realm, insects!" },
            { id = 558769, text = "Deathwing has prepared me to face the vassal of Terikosa. Your fool's journey ends here." },
            { id = 558806, text = "Mortal Insects! You dare trespass into my domain? Your arrogance will be purged in living flame!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 558788, text = "The Realm of Fire will consume you!" },
            { id = 558797, text = "This is my realm!" },
        } },
    } },
    { who = "Ragnvald Drakeborn", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1411091, text = "My blade thirsts for demon's blood!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1370170, text = "Ha! With all of us together, we may yet be victorious. Either way, I'll not go down easily. Let us be about it then!" },
            { id = 1370157, text = "Ulrich! My battle brother! I will avenge you!" },
            { id = 1370161, text = "Watch over me from above, my brothers, and save me a seat in the hall!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370162, text = "A brute has joined the battle, little hero! Come and meet your fate before your place is taken!" },
            { id = 1370168, text = "At last! Haha! This is the glorious death Harvey promised me!" },
            { id = 1370176, text = "Fight on, hero. For me, the halls await." },
            { id = 1370153, text = "Shug off your wounds, warriors! And not the battle awaits!" },
            { id = 1370156, text = "That old seer is mad, but rarely wrong. Come, friend. More demons approach. Prove your valor." },
            { id = 1411092, text = "Time for battle for Odin!" },
            { id = 1370165, text = "What was that?" },
        } },
    } },
    { who = "Rajani Mogu", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3150229, text = "COWER BEFORE THE STORM!" },
            { id = 3150224, text = "IN RADEN'S NAME!" },
            { id = 3150233, text = "THOROGONIC! LIVE! ON! GRAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3150228, text = "You will be purged from Azeroth!" },
