        { name = "Conversation", family = "Feelings", lines = {
            { id = 3150227, text = "Death to N'Zoth!" },
            { id = 3150235, text = "I... can hear... the storm!" },
            { id = 3150234, text = "The vaults... will not... fall." },
            { id = 3150226, text = "We will defend the Vale!" },
            { id = 3150230, text = "Witness the might of the Rajani!" },
            { id = 3150225, text = "You dare defy the titans!" },
