    { who = "Raksi", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1056571, text = "So, this is what they were after. Thank you for clearing the way." },
            { id = 1056572, text = "That's quite enough of this illusion, I think." },
            { id = 1056570, text = "You're going after it? Suit yourself, I'm getting out of here!" },
        } },
    } },
    { who = "Ralia Dreamchaser", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3488719, text = "I found an ancient druidic stone nearby. Let us approach it and commune with the wilds." },
            { id = 3488724, text = "I will return to Captain Garak. Perhaps you can follow in your new animal form." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3488720, text = "Spirits of nature, we beseech you, bestow your gifts upon this druid." },
            { id = 3488721, text = "The spirits answer." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3488727, text = "Elune! Please shield us from harm!" },
            { id = 3488725, text = "Is someone there? Help! Elune, guide them to me!" },
            { id = 3488722, text = "Listen to their whispers. Learn the lessons that they impart." },
            { id = 3488726, text = "You saved my life. Allow me to return the favor. Hop on." },
            { id = 3488723, text = "Your connection to nature has grown stronger. Use it to protect the wilds and keep the balance." },
        } },
    } },
    { who = "Ramkahen Tolvir", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3150061, text = "DEATH TO THE OLD GODS!" },
            { id = 3150067, text = "DO NOT GIVE IN!" },
            { id = 3150063, text = "I DIE FOR RAMKHAGEN!" },
            { id = 3150064, text = "MAKERS, WATCH OVER ME!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3150066, text = "I return to the Earth." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3150057, text = "Be gone from all doom!" },
            { id = 3150058, text = "By the king's decree!" },
            { id = 3150062, text = "In the name of the Titans!" },
            { id = 3150060, text = "N'Zoth will not prevail!" },
            { id = 3150065, text = "The forge must not fall." },
            { id = 3150059, text = "We must defend the forge!" },
        } },
    } },
    { who = "Rana", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4280050, text = "I am already home, and now my home is in danger. I must protect it." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4280026, text = "Continue your rest, Sacred One." },
            { id = 4279934, text = "Indeed, but those who do the disturbing must also do the undisturbing." },
            { id = 4280023, text = "Oh no! That Vombata has been hurt! Help me come it down!" },
            { id = 4280005, text = "safe, I have faith in a more workers' ability to protect us." },
            { id = 4280053, text = "The lock is broken. They must already be inside." },
            { id = 4279999, text = "There is treachery, certainly, but there is also awe, sanctity, and, eventually, enlightenment." },
            { id = 4280029, text = "There, there, sweet thing." },
            { id = 4279890, text = "This place of wonder? This place of beauty?" },
            { id = 4279828, text = "We exist in perfect communion with destiny, Adelie. I am exactly where I should be. Also, it is just Rana now." },
            { id = 4280014, text = "Were you afraid of that cute little thing?" },
            { id = 4280041, text = "What? No. They want to enter this lumbering bolt!" },
        } },
    } },
    { who = "Ranah Saberclaw", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2397831, text = "CAN'T YOU SEE, I'M TRYING TO MEDITATE!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2432336, text = "FUUU!" },
            { id = 2432334, text = "YEAH!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 2397838, text = "Oops. Well, that wasn't very tranquil of me." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2397836, text = "How am I supposed to meditate with the Alliance here? I guess we'll just have to kill them." },
            { id = 2397835, text = "Maintain balance. I meditated earlier, so now it's time for violence. To balance things out." },
            { id = 2397834, text = "Ugh, stop dying!" },
        } },
    } },
    { who = "Rangarijonaa", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1058023, text = "I could do this blindfolded." },
            { id = 1058021, text = "My eye is on you, Commander." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1058019, text = "Continue practicing, Commander." },
            { id = 1058018, text = "Start running. I will even give you a head start." },
            { id = 1058022, text = "We may need more to hunt after this." },
            { id = 1058020, text = "You're becoming quite the survivor." },
        } },
    } },
    { who = "Ranger Orestes", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1378220, text = "This stinks of a trap. You can't rely on the word of a demon." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1382941, text = "I should be going with you. If this is a trap, you need my bow covering your backs." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1388696, text = "Let's get this war won." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1382709, text = "Good luck, friends. Save... Hilaria." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1382582, text = "Admit it, Vereesa. This mission is personal." },
            { id = 1382654, text = "Beware the Houndmistress." },
            { id = 1370864, text = "Never was very good at filing orders. See you on the other side!" },
            { id = 1382707, text = "No, but didn't make it to the cathedral. Wounds bad. It's so cold." },
            { id = 1382705, text = "Turns out rushing through that portal not my best idea" },
        } },
    } },
    { who = "Rannan Korren", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5091508, text = "Stop and drop everything. Let's get out of here. We'll pick up our work later. Thanks for your help adventurers. Take this" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 5049048, text = "Ah, fine day for some tinkering, don't you think?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5049051, text = "Alright, see you later!" },
            { id = 5049054, text = "But, I have so much science to tell you about!" },
            { id = 5091528, text = "Greta, our Nifin scouts report a Titan containment force coming straight for you! Hurry! You're running out of time!" },
            { id = 5049045, text = "Hm? Oh! Yes! Heh, hello! Hello." },
            { id = 5049042, text = "Oh, um, didn't see you standing there." },
            { id = 5091505, text = "The Sundered Flame are coming! Quick! Let's clear out the Jarrod in ruins to the west and help Thalen Darkanvel with his investigation!" },
            { id = 5091392, text = "The Sundered Flame, again? Ugh. Don't they know we're doing important, science-y stuff? Deal with their patrols so we can keep working." },
            { id = 5091514, text = "What? Oh no no no no! Adventurers! The Sundered Flame are back! Quick! Get back to the platform!" },
            { id = 5091525, text = "Whoa! Whatever you did really riled up the native wildlife! Get back to the hub, fast!" },
        } },
    } },
    { who = "Rashanan", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5754561, text = "GORGE ON YOUR EYES!" },
            { id = 5754569, text = "NOWHERE TO RUN!" },
            { id = 5754560, text = "YOUR FLESH MELTS!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5754563, text = "My spawn must feed!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5754564, text = "Act and Devour!" },
        } },
    } },
    { who = "Rathan", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3752062, text = "I look forward to working with you." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3752066, text = "Ah, the Maw Walker has arrived. We will soon reclaim your body, Emani." },
            { id = 3752060, text = "Greetings, my friend." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3752057, text = "Know the soul, not the construct." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3752059, text = "All efforts are enough reward." },
            { id = 3752067, text = "Consult the schematics before we proceed. Amenie's construct is of complex design." },
            { id = 3752063, text = "Garmal is no friend of ours. If you would have us, we would join your cause." },
            { id = 3752068, text = "Good. Now activate the vat of acerbic bile and connect it to the construct." },
            { id = 3752058, text = "Strength in numbers, small walker." },
            { id = 3752064, text = "Thank you, Maw Walker. With you by our side, we are sure to prevail. Do you not agree, Amani?" },
            { id = 3752061, text = "There is much to be done." },
        } },
    } },
    { who = "Raul the Tenacious", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2103377, text = "GRRRAH!" },
            { id = 2103373, text = "YEAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1984525, text = "I wouldn't have to do this if we just stop fighting." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1984522, text = "Ah, finally! Time for a nap." },
            { id = 1984521, text = "Ah, nap time!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1984527, text = "Oh, I guess I played too hard." },
            { id = 1984520, text = "So, just run for it, horties! We won't chase ya!" },
            { id = 1984524, text = "Someone's gotta lick your wounds!" },
            { id = 1984526, text = "We're already here, but it's the perfect time of day for a nap!" },
        } },
    } },
    { who = "Ravandwyr", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1408624, text = "I will see you back in the Hall of the Guardian. Isara, you are welcome to join us there." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1408625, text = "I think that cough is getting worse." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1408622, text = "Well, that was uncomfortable. You came just in time." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1416836, text = "Great! I will serve you and our order most faithfully!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1408620, text = "Even experienced mages have an alarming tendency to disappear here, and we could really use you in the Tyris Guard." },
            { id = 1408626, text = "Hmm, perhaps you should get some rest, Meryl." },
            { id = 1411908, text = "I'm up to the task!" },
            { id = 1408618, text = "Isara, be on your guard while inside the Empyrean Enclave." },
            { id = 1408629, text = "Khadgar, thank you for coming so quickly. He is declining rapidly." },
            { id = 1408621, text = "Look, my favorite conjurer has arrived!" },
            { id = 1408628, text = "Meryl, please get some rest. Conjurer, I hope to see you in Azsuna shortly." },
            { id = 1408627, text = "You don't sound so good." },
        } },
    } },
    { who = "Ravnyr", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3544538, text = "DEATH! MORE DEATH!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3489168, text = "Foolish ogre! You have given me nowhere near enough power!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 3489169, text = "Pathetic mortals! Your deaths will nourish me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3489170, text = "No! I will not go back!" },
        } },
    } },
    { who = "Rax Sixtrigger", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1418144, text = "Don't worry, these ain't stolen, they just haven't been paid for yet." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1418149, text = "Hey, no refunds. Got it?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1418139, text = "Bury me with my money." },
            { id = 1418143, text = "Check out this one, handmade in Kazan, hand stolen in Gadgetzan." },
            { id = 1418146, text = "Just don't ask where these came from." },
            { id = 1418150, text = "Of course it's authentic!" },
            { id = 1418148, text = "Pleasure doin' business with ya!" },
            { id = 1418142, text = "Too late! Too late will be the cry when Six Triggers bargains pass you by!" },
            { id = 1418140, text = "Ugh, system overload?! What does that mean?! W-W-W-W" },
            { id = 1418141, text = "You again? Snaggle! Take them out!" },
            { id = 1418147, text = "You got the gold, I got the goods." },
            { id = 1418145, text = "You here shoppin' or shopliftin'?" },
        } },
    } },
    { who = "Razak Ironsides", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1984469, text = "FIRE IN THE HOLE!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1984471, text = "Hoards here, so listen up. Do your jobs out there, and I'll shoot you myself. Farm ranks!" },
            { id = 1984467, text = "Look alive! We've got company!" },
            { id = 1984474, text = "Meccano Strider down! Need evac! ASAP!" },
            { id = 1984476, text = "Never bring a knife to a mech fight!" },
            { id = 1984468, text = "Now don't you... let me down!" },
            { id = 1984472, text = "The only good bug is a dead bug, and you horde look a lot like bugs." },
            { id = 1984475, text = "They've taken out my mechano-strider! Fall back!" },
            { id = 1983974, text = "Violence has resolved more conflicts than anything else in history. Let's add another to the list." },
        } },
    } },
    { who = "Razuvious", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 558987, text = "STAND AND FIGHT!" },
            { id = 558994, text = "YOU SHOULD HAVE STAYED HOME!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 558992, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 558988, text = "Ha ha! I'm just getting warmed up!" },
            { id = 558993, text = "Show me what you've got!" },
        } },
    } },
    { who = "Regald Hornfyre", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5727108, text = "Well, that's what they said. One of the big ones from the heart of Siegeholder. I'm as flummoxed as you are." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5723661, text = "Beware the shadows." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5723662, text = "for the Empire." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5723663, text = "Belladar, shift in your favor." },
            { id = 5723666, text = "General, the Nerubians. They've opened a new front and lights writ out." },
            { id = 5727114, text = "I... can't answer that for you." },
            { id = 5723665, text = "Sacred Flame, guide your way, friend." },
            { id = 5727112, text = "This had nothing to do with you. They've attacked before, they'll attack again. That's how it's always gone." },
        } },
    } },
    { who = "Rehgar Earthfury", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1370365, text = "Haha! You are a champion in the making!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1370512, text = "I will grant you a lightning shield, but don't let him get too close!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1370366, text = "Help the others!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370501, text = "Ancestors, watch over you!" },
            { id = 1370490, text = "Storm, earth and fire, heed my call!" },
            { id = 1370507, text = "The elements walk in harmony with this one. I've not seen a better shaman since I fought alongside Thrall himself." },
            { id = 1370494, text = "The Legion is attacking!" },
            { id = 1370367, text = "This thing has said useless for 10,000 years!" },
            { id = 1370511, text = "This vrykul is all talk, use his strength against him!" },
            { id = 1370515, text = "You've almost got this, champion!" },
        } },
    } },
    { who = "Reldorn", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3580081, text = "I do not like the look of this place. Stay close." },
            { id = 3580088, text = "I must return to my post for now. Good hunting." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3580077, text = "Let's get moving. This way." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3580106, text = "Welcome back. Did you find what you need?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3580078, text = "These creatures are not of Ardenweald. They invade our groves and consume the anima like locusts." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3580076, text = "Beware Huntress, this road is no longer safe." },
            { id = 3580075, text = "Beware Huntsman, this road is no longer safe." },
            { id = 3580107, text = "I've prepared the perfect glamour to help you get by undetected. Just stand still for a moment." },
            { id = 3580079, text = "Look! Those rifts must be how they enter the forest! Close them, quickly!" },
            { id = 3580087, text = "Sir, it is an honor to meet you... and to be saved by you." },
            { id = 3580080, text = "That should keep them at bay for now. Let us continue our search." },
        } },
    } },
    { who = "Rellnightwind", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 617669, text = "Back to your duties." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 617671, text = "Goodbye." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 617679, text = "At ease, soldier." },
            { id = 617673, text = "I'm counting on you." },
            { id = 617675, text = "Keep your mind on the mission." },
            { id = 617677, text = "reporting in" },
        } },
    } },
    { who = "Remnant of Nerzhul", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4077448, text = "DON'T ESCAPE THE CHAINER!" },
            { id = 4077440, text = "ETERNITY DEVOURES ALL!" },
            { id = 4077439, text = "FAILURE, BRENDING MY SOUL!" },
            { id = 4077447, text = "GO INTO THE ABYSSSSSS" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4077444, text = "Your hands will serve him." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4077442, text = "My prison, now yours." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4077441, text = "A taste... of FREEDOM!" },
            { id = 4077445, text = "At last! Reprieve!" },
            { id = 4077446, text = "Know the weight of my crown." },
            { id = 4077450, text = "Worlds never heal!" },
        } },
    } },
    { who = "Remornia", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3656903, text = "I'LL PAINT THESE HALLS WITH YOUR SCREAMS! AHAHAHA!" },
            { id = 3656904, text = "NOTHING LEFT BUT BLOODY BITS!" },
            { id = 3656900, text = "YES! YES! I'LL HACK THEM TO PIECES!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3656946, text = "I have a better idea, master. Let me carve them up instead." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 3656927, text = "Yes, master! Now we will both revel in their torment!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3656934, text = "Death! Glorious Death!" },
            { id = 3656907, text = "I'll carve them into itty-bitty pieces!" },
            { id = 3656910, text = "Oh, I'll splatter them across your walls!" },
            { id = 3656938, text = "Ooooh! I made that bonus break!" },
            { id = 3656902, text = "Their agony will echo across the realms of death!" },
        } },
    } },
    { who = "Renataki", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 559018, text = "LEARN YOUR PLACE!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 559003, text = "AHHH AHHH!" },
            { id = 559011, text = "AHHH!" },
            { id = 559008, text = "HA!" },
            { id = 559010, text = "HAAA!" },
            { id = 559024, text = "YEAH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 559000, text = "GAH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 559004, text = "A swift slice to the throat, and this one falls like any other!" },
            { id = 559009, text = "Aha! I shall add a new blade to my collection today!" },
            { id = 559013, text = "Ha Ha Ha ha!" },
        } },
    } },
    { who = "Rendle", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3609368, text = "As a newly arrived soul, you should know this is a place of torment and penance." },
            { id = 3609370, text = "Each of these sinstones represents a soul who has come to this place and cleansed themselves of their sins. Eventually moving on from here, or accepting the role of Aventhea." },
            { id = 3609371, text = "Final judgment comes from the master. It is he who commands this place. It is he who embraces souls to become Venthyr, the tormentors and eaters of sin." },
            { id = 3609356, text = "Is... is that a new soul? Ha! I ain't seen one of them in a while!" },
            { id = 3609359, text = "Welcome, damned soul, to Revendreth. Your last hope at redemption. Right this way, and we'll get you sorted." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3609369, text = "Not to fear though, for as you can see by these many sin stones, the road to redemption is possible." },
            { id = 3501896, text = "Oh, Chamberlain! There's a commotion up ahead. Looks like a fight!" },
            { id = 3609374, text = "or are simply just a bunch of bad apples." },
            { id = 3609378, text = "Quick! Make yourself presentable! Lord Chamberlain is here!" },
            { id = 3609358, text = "That is because they're still alive, I think. Don't be insensitive." },
            { id = 3609372, text = "There are always those few who are unwilling to work for redemption." },
        } },
    } },
    { who = "Renzik the Shiv", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2000005, text = "I got the intel. We just gotta make it outta here with it." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2118766, text = "A couple of dashes of my secret ingredient, and voila! The modifications are complete." },
            { id = 2118765, text = "A little gunpowder, some fuses, and copper chips." },
            { id = 2118768, text = "Ahh, makes a goblin proud, you know?" },
            { id = 2118764, text = "I'll add in a bit of this, smash it in real good, heh!" },
            { id = 2118763, text = "Lemme just... Hold on a second, will ya?" },
            { id = 2118762, text = "Oooh, you got me some Azerite? That's the good stuff!" },
            { id = 2118767, text = "This thing is the bomb! Now seriously, it could blow the top hat off of Gallywix's Pleasure Palace!" },
            { id = 2118761, text = "You want explosions? Buddy, you got it. Hop into one of these beauties and take it for a spin." },
        } },
    } },
    { who = "Reshad", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1056967, text = "I will see you again." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1056968, text = "Ah, farewell for now." },
            { id = 1056972, text = "Ah, hello!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
