        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1369791, text = "It seems the spirits are indeed drawn to this place. Let us hope they are friendly." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1369788, text = "Aroden was the first of the Dark Riders, and I believe he leads them now." },
            { id = 1369764, text = "Enough! Stay your weapon!" },
            { id = 1369789, text = "If my convictions are correct, the key to finding the Dark Riders, as well as the artifacts they still covet, can be found there." },
            { id = 1369793, text = "It seems you've been followed. Dark Riders!" },
            { id = 1369790, text = "The Catacombs' entrance is just down this path. Make haste!" },
            { id = 1369787, text = "The Dark Riders were not always like this. They were once a group of traveling merchants." },
            { id = 1369765, text = "The riders will be upon us soon enough, and nothing is gained if we both die here." },
            { id = 1369768, text = "What? Have you not come to finish what the Dark Riders started?" },
        } },
    } },
