        { name = "Conversation", family = "Feelings", lines = {
            { id = 5708455, text = "Every Stormrook has its own personality." },
            { id = 5708457, text = "Have need of a Stormrook?" },
            { id = 5708454, text = "Nothing like the wind in your crags." },
            { id = 5708458, text = "Returning to task." },
            { id = 5708456, text = "The Titans drive my directive." },
            { id = 5708459, text = "Trust in the edicts." },
        } },
    } },
    { who = "Rosaline Madison", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2011208, text = "My scouts report that the corruption hasn't spread beyond the harbour yet. We're culling any monsters that stray too far out." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2011201, text = "Get ready outriggers, these creatures are unlike anything we've faced before." },
            { id = 2011207, text = "Let's go Okri, the outriggers are waiting." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2011200, text = "And down she goes! A fight for the ages, Altriggers!" },
            { id = 2011203, text = "I've got a weapon and I'm not afraid to use it." },
            { id = 2011204, text = "I've got monsters to kill." },
            { id = 2011205, text = "I've never seen a monster I couldn't take down." },
            { id = 2011206, text = "Let me know when you're ready to play with the big kids." },
            { id = 2011209, text = "Nicely done, my friend. You're welcome to join us for a hunt any time. For now, take a Griffon down to Anglepoint. We'll clean up here." },
            { id = 2011210, text = "Oi! Ferald! Enough dallying! We need your blessing to go out for our hunt!" },
            { id = 2011211, text = "Oi! You're either talking or helping. Let's take the hunt to the water." },
            { id = 2011202, text = "Ugh, I'm sick of your face." },
        } },
    } },
    { who = "Rotface", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 559438, text = "AHHH!" },
            { id = 559433, text = "HAAA!" },
            { id = 559440, text = "HAHA!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 559436, text = "My brokes did it!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 559443, text = "GRR!" },
            { id = 559442, text = "OW!" },
            { id = 559437, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 559434, text = "How did he make toys out of you?" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 559462, text = "WEEE!" },
        } },
    } },
    { who = "Rothadrin Darkgrove", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1241853, text = "Hahahaha! You cannot hope to stop me!" },
            { id = 1241867, text = "How do you think you will fare against the might of Xavius?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1241857, text = "I grow tired of you." },
            { id = 1241847, text = "I live to serve, Xavius." },
            { id = 1241851, text = "I will spread the nightmare to every mountain and valley." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1243225, text = "Rise! Grow! Take this forest!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1241865, text = "My power will destroy this pathetic land!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1241855, text = "Cut me down, and I will grow anew." },
            { id = 1241849, text = "Nothing can withstand the might of Xavius." },
            { id = 1241869, text = "The nightmare will consume all of you!" },
            { id = 1241717, text = "Xavius is the master of this forest now. To enter is to succumb to the nightmare." },
        } },
    } },
    { who = "Rothoof Defiler", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1505049, text = "AHHH!" },
            { id = 1505050, text = "HA!" },
            { id = 1505048, text = "YEAH!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1418273, text = "Foolish mortals. Soon, this place will belong to the master!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1505057, text = "UGH!" },
            { id = 1505056, text = "YES!" },
        } },
    } },
    { who = "Rottgut", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1411957, text = "RAWR! DUDE! HEH HEH HEH HEH!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1489620, text = "HMPH!" },
            { id = 1489618, text = "YAY!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1444645, text = "Hmm... Not good." },
            { id = 1411958, text = "Oh, right good!" },
        } },
    } },
    { who = "Rotun", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 899733, text = "Hmm, you have run out of time. Shall we try again?" },
            { id = 899735, text = "Welcome to the Proving Grounds. Your first trial will now begin. Defeat each wave of illusions before time runs out." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 899727, text = "Ah, the illusionary banana tosser. It will rapidly toss bananas toward you. Move to avoid them. Prevent it from running away from you, if you can." },
            { id = 899715, text = "Greetings!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 899723, text = "A master of defence, the Illusionary Guardian deflects all attacks from the front. Stay behind it." },
            { id = 899717, text = "An illusionary Banshee. Kill it. Quickly. Before it explodes." },
            { id = 899731, text = "Illusionary varmints come in packs and are harmless. Use attacks that affect multiple opponents to kill them quickly." },
            { id = 899721, text = "Oh, the illusionary Shah! Save your strongest attacks for when its barrier falls, leaving it exposed." },
            { id = 899729, text = "The Illusionary Amber Weaver conjures globs of amber that float toward you and explode on any contact. Lead the amber globs into other illusions." },
            { id = 899725, text = "The Illusionary Mystic will heal any ally that is significantly wounded. Interrupt its healing spells." },
            { id = 899719, text = "This illusionary slayer will test your ability to damage your opponent. Do not worry, it cannot harm you." },
            { id = 899737, text = "This trial will test how far your skill can take you. It will never end. It only gets more challenging." },
        } },
    } },
    { who = "Rulkan", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1033718, text = "I pleaded with him to stop, but he would not turn back." },
            { id = 1033715, text = "My husband Ner'zhul chose to save our people. He joined the Iron Horde, but they asked of him a heavy price." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1033723, text = "Go." },
            { id = 1033712, text = "Stay your weapons! This must be the messenger the Draenei prophet promised." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1033713, text = "Welcome to my fire traveler. I know much of Ner'zhul. And yet, these days, I know him not at all." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1033721, text = "The Shadowmoon Fortress is sealed to outsiders, but this keystone will allow entry. Good luck, hero!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1033722, text = "Ancestors, forgive us." },
            { id = 1033719, text = "By breaking this stone, he foreswore all loyalty to our ancestors." },
            { id = 1033717, text = "So Ner'zhul turned to the silent void. He broke the ancient laws and drew upon the Dark Star." },
            { id = 1033714, text = "When the Iron Horde came, they gave our clan a choice, join them or die." },
            { id = 1033720, text = "You must do what I cannot. Stop Ner'zhul. End his madness before it is too late." },
        } },
    } },
    { who = "Runas the Shamed", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1243245, text = "I hope you can see beyond my tattered robes and desperate behavior. I am not a monster." },
            { id = 1243233, text = "I only want to help, good dragon." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1243243, text = "Don't you know who I am?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1243249, text = "I'll drink the mana from your broken bones!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1243227, text = "Bunch of manor addicts, that lot. Not me, though! My discipline is iron!" },
            { id = 1243239, text = "Feeding on such raw energy, it clouds my judgement!" },
            { id = 1243231, text = "I... I... I..." },
            { id = 1243235, text = "So sorry, my friends. I just couldn't help myself." },
            { id = 1243229, text = "The Tideskone. Such power." },
            { id = 1243247, text = "Watch, I shall prove it to you. I am not just a man of adult freak like the rest of those wretches." },
            { id = 1243241, text = "We will feast on the dragons instead!" },
            { id = 1243237, text = "What in blazes are you doing?!" },
        } },
    } },
    { who = "Rune Scribe Lusaris", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2030301, text = "HA!" },
            { id = 2030299, text = "NYAA!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1985517, text = "The Alliance are here. Channel your energies. We will make no mistakes." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1985512, text = "Strike them down. Follow my lead." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1985513, text = "Do as we planned. Engage!" },
            { id = 1985518, text = "Focus now. Worthy enemies are near. And the Alliance as well." },
            { id = 1985520, text = "Hmph. An inevitable fate." },
            { id = 1985519, text = "It is time. Remember your training, and show these Alliance Kurz what it means to be Highborne." },
            { id = 1985522, text = "Now, eliminate this one!" },
            { id = 1985515, text = "Quickly now! Retreat!" },
        } },
    } },
    { who = "Runecarver", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3601242, text = "The past is a shattered mirror." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3601252, text = "I recall so little." },
            { id = 3601249, text = "I will aid you as I can." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3601243, text = "Do not lose yourself to despair." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 3601248, text = "Go carefully into the darkness." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3601247, text = "Safeguard your soul, mortal." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3601253, text = "Fate has brought our paths together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3601245, text = "Beware the Jailer's Eye." },
            { id = 3601244, text = "We walk among the fragments of memory." },
            { id = 3601250, text = "What have you found?" },
            { id = 3601246, text = "Within these halls lie horrors beyond imagining." },
        } },
    } },
    { who = "Runemaster Molgeim", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 559474, text = "GAH!" },
            { id = 559469, text = "HIYAH!" },
            { id = 559481, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 559480, text = "The world suffers yet another insignificant loss!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 559472, text = "NOOO!" },
            { id = 559467, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 559479, text = "Death is the price of your arrogance!" },
            { id = 559484, text = "Face the lightning surge!" },
            { id = 559473, text = "Nothing short of total decimation will suffice!" },
            { id = 559477, text = "This meeting of the Assembly of Iron is adjourned!" },
        } },
    } },
    { who = "Runeseer Faljar", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1244215, text = "ENOUGH OF THIS!" },
            { id = 1418157, text = "I SPIT ON YOUR ANCIENT RIGHT, SHIELD MADEN!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1244201, text = "Give in, Ashildir. If your spirit will not bend, then it will be broken." },
            { id = 1244225, text = "I can. You have sealed your fate, Shieldmaiden. You and this... outsider." },
            { id = 1244221, text = "The God-King will not need your judgment if you are no longer among the honored dead." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1418156, text = "I would see you banished before I allow you to grant judgement to an outsider!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1244209, text = "You were a fool to meddle! My armies are eternal!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1451973, text = "HMPH!" },
            { id = 1451972, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1244227, text = "Enjoy your eternity of damnation! HELLHEIM AWAITS!" },
            { id = 1244219, text = "You should have yielded a shield there." },
            { id = 1244205, text = "You think to stop me, I am the master of the vengeful dead!" },
        } },
    } },
    { who = "Rury", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3557364, text = "What an odd creature you are." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3557362, text = "I suppose I can come with you. You clearly need all the help you can get." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3557351, text = "Oh, off with you now." },
            { id = 3557350, text = "Time for a nap." },
            { id = 3557352, text = "What is it now?" },
        } },
    } },
    { who = "Ruska Rocktooth Azerothian Archives", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5226535, text = "Don't tease an orc with a shovel!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5226524, text = "The archives find, catalog, and preserve artifacts." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5478427, text = "Excellent finds, but there's way more to be studied here." },
            { id = 5226520, text = "If you don't mind getting your hands dirty, we'll get along fine." },
            { id = 5226504, text = "I'll make sure you get credited in my thesis." },
            { id = 5478431, text = "Nothing to do but keep digging!" },
            { id = 5226500, text = "Send some people my way! We could always use a few more hands!" },
            { id = 5226516, text = "So much of the past still needs digging up." },
            { id = 5226512, text = "Tell me if you find anything!" },
            { id = 5226528, text = "The best part of my job is getting what we find back to its proper home." },
            { id = 5226508, text = "There's always a place for you on the dig." },
            { id = 5226532, text = "Where do we dig you up?" },
        } },
    } },
    { who = "Ruven", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1502929, text = "AH!" },
            { id = 1502933, text = "AHHH DUH!" },
            { id = 1502930, text = "HA!" },
            { id = 1502931, text = "MMM!" },
            { id = 1502932, text = "NNN!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1411431, text = "You will not be missed. Take comfort in that." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1405296, text = "I will not be defeated by the likes of you!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1502934, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405293, text = "A challenger! Don't make me laugh." },
            { id = 1405295, text = "Kneel before the might of the shoulder-eye!" },
            { id = 1405294, text = "The Legion brings us power unending!" },
        } },
    } },
    { who = "Rygelon", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4326066, text = "You are known to me, champions of Azeroth." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4329409, text = "My kind has re-originated countless worlds, but this flawed cosmos is beyond repair. It must be broken and remade." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 4326068, text = "For reality to endure, it must be remade. But you are nothing more than aberrations to be discarded." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4329414, text = "Corruption will be eliminated." },
            { id = 4329408, text = "Cosmic collapse is inevitable." },
            { id = 4329410, text = "Evolution itself, I see now, is a failed concept. One that breeds only chaos." },
            { id = 4329416, text = "Existence will be reordered." },
            { id = 4329411, text = "Order demands the eradication of life. Submit, mortals, to the harmony of death." },
            { id = 4329406, text = "Reality is folding upon realities." },
            { id = 4329413, text = "Through death will come order." },
            { id = 4329415, text = "Witness the fury of the cosmos." },
            { id = 4326067, text = "Your deeds have unbalanced the harmony of the cosmos." },
        } },
    } },
    { who = "Rymek", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4678411, text = "HOLD THEM BACK! THIS POWER IS ALMOST MINE!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4678222, text = "I have learned much here today, but what do I see there over the water?" },
            { id = 4678192, text = "I look forward to seeing the wonders of these groves." },
            { id = 4678226, text = "I understand that you lost a child, yet you press on with your duties. I find that commendable." },
            { id = 4678204, text = "I would be delighted." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4678219, text = "But the dreamer is dead, my friend. How do you plan to bring her back?" },
            { id = 4678229, text = "How can I help, my friend?" },
            { id = 4678235, text = "It has been most rewarding, and Lord Somnicus has graciously offered to let me see the dream portal for myself." },
            { id = 4678198, text = "It must be difficult at times to continue your work without your aspect." },
            { id = 4678216, text = "Tell me more." },
            { id = 4678195, text = "What realm does the green dragonflight protect, nature?" },
            { id = 4678213, text = "Your tears absorb your flight's power." },
        } },
    } },
    { who = "Saara", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1390897, text = "Thank you for free. I know you have a great need, and I will help you however I can." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1503994, text = "I will help you." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1503992, text = "Goodbye." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1503995, text = "Can the Gnarled Aid You?" },
            { id = 1503996, text = "Careful! I can be shot!" },
            { id = 1503993, text = "In the light we are reborn." },
            { id = 1503991, text = "Light reveal your power." },
            { id = 1503997, text = "Please don't smudge me." },
            { id = 1390887, text = "The altar is complete, Bittu." },
            { id = 1390896, text = "The hunger, the rage, they are gone. The light has welcomed me home." },
            { id = 1503990, text = "Walk in light." },
            { id = 1503998, text = "Would you like to see the temple, say, from the outside?" },
        } },
    } },
    { who = "Sabellian", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4640295, text = "And you are?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4640302, text = "I did not inherit my father's madness. His temper, on the other hand." },
            { id = 4640294, text = "I have been too long away." },
            { id = 4640326, text = "My return was absolutely crucial." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4640299, text = "Come now, speak." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4640298, text = "Can I trust you?" },
            { id = 4640303, text = "Hmph. Mortals. Mortals never change." },
            { id = 4640301, text = "Is this what heroes do on Azeroth these days, how droll." },
            { id = 4640300, text = "Our numbers may be few, but we still outnumber you." },
            { id = 4640297, text = "Tell me of Azeroth." },
            { id = 4640293, text = "You seem... familiar." },
            { id = 4640296, text = "You stand before the rightful heir." },
        } },
    } },
    { who = "Saboteur Kiptilak", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 631888, text = "I BROUGHT ENOUGH BOMBS FOR ALL OF YOU!" },
            { id = 631898, text = "YOU BLEW IT!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 631896, text = "I'm the Bonner Man! Take it!" },
        } },
    } },
    { who = "Sadana Bloodfury", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1041345, text = "ANOTHER SPIRIT FOR THE ARMY!" },
            { id = 1041346, text = "EMBRACE THE ETERNAL DARKNESS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1041349, text = "Your souls will belong to me!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1041342, text = "Ancestors of the Shadowmoon, shine in the darkness! Lend me your strength!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1041350, text = "Restless spirits, heed my command!" },
            { id = 1041344, text = "Rivers of the damned, rise! Rise in the name of darkness! Rise in the name of Ner'zhul! The Shadowmoon beckons!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1041348, text = "Mmm. Mmm, yes! The perfect sacrifice!" },
        } },
    } },
    { who = "Saelorn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1327268, text = "Your screams are funny! Make me laugh!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1327256, text = "I hope the next one doesn't break so quickly!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1327260, text = "Don't look behind you!" },
