        { name = "Conversation", family = "Feelings", lines = {
            { id = 1327262, text = "And along came a spider!" },
            { id = 1327254, text = "Aww, I hate it when my toys stop screaming!" },
            { id = 1327266, text = "Aww, I have tried to teach them to kill you slowly, but they just won't listen!" },
            { id = 1327272, text = "If you scream loud enough, maybe I will let you die." },
            { id = 1327250, text = "This is why I can't have nice things!" },
            { id = 1327258, text = "What? Why would you do this?" },
            { id = 1327270, text = "Which do you like more? Screaming or crying? I like to hear you do both!" },
            { id = 1327252, text = "Why do they break so easy?" },
        } },
    } },
    { who = "Saezurah", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4287074, text = "You are where you were meant to be." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4287076, text = "All creation has a purpose." },
            { id = 4287068, text = "As one song ends, another begins." },
            { id = 4287071, text = "Discord must be quieted." },
            { id = 4287078, text = "Let our voices bring harmony." },
            { id = 4287067, text = "Let the ciphers guide you." },
            { id = 4287073, text = "Marvel at their design" },
            { id = 4287070, text = "May our silence be brief." },
            { id = 4287075, text = "May the song flow through you." },
            { id = 4287077, text = "The flow brings unity." },
            { id = 4287072, text = "The song rises within you." },
            { id = 4287069, text = "Wisdom of the first ones hate you." },
        } },
    } },
    { who = "Sal Atwater", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2616797, text = "I can mind the house, dear. Go on, have an adventure!" },
            { id = 2616900, text = "I hear the mainland's nice this time of year." },
            { id = 2616778, text = "I think this lumber is haunted." },
