        { name = "Conversation", family = "Feelings", lines = {
            { id = 2616774, text = "Be gentle with our new friends, sweet pea." },
            { id = 2616902, text = "I'll be around if you need me." },
            { id = 2616772, text = "Me? Hot Tides? No. That's my wife. She's inside." },
            { id = 2616773, text = "Out back, dearest!" },
            { id = 2616779, text = "She's just a tad shy, ma'am. Play her no mind. Oh, would you like some warm milk while you wait?" },
            { id = 2616777, text = "Well, they were quite helpful, actually. Erm, dearest." },
            { id = 2616903, text = "What can I do for you, friend?" },
        } },
    } },
    { who = "Salandria", tier = "character", groups = {
