        { name = "Conversation", family = "Feelings", lines = {
            { id = 4423411, text = "Al diala shalah" },
            { id = 4423415, text = "Are you ready? Let's go!" },
            { id = 4423414, text = "Bala dash mela noray" },
            { id = 4484712, text = "Even more scourge than anticipated, but we managed to get close enough to look inside." },
            { id = 4423412, text = "I'll see you again soon, right?" },
            { id = 4423416, text = "It's so good to see you again!" },
            { id = 4484713, text = "That Samlian Aethas mentioned had some sort of crystal array, he kept appearing within it, almost as if summoned." },
            { id = 4484658, text = "Then I should prove myself, right? You said it yourself. We'll hold the line and keep Quel'Thalas safe. I intend to do just that." },
            { id = 4484656, text = "Ugh, finally! It feels as if I've been in training for ages! Send me to Tranquilian!" },
            { id = 4423418, text = "Watch it, or I'll tell the orphanage about the school of hard knocks!" },
        } },
