        { name = "Loyalty", family = "Manners", lines = {
            { id = 2018949, text = "We're in this together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2022834, text = "Beneath the tides, waiting, calling." },
            { id = 2022837, text = "For Addington! For Stormsong Valley!" },
            { id = 2018946, text = "Home is where the valley is." },
            { id = 2022835, text = "I'm so cold. Will the voices stop soon?" },
            { id = 2018945, text = "I've got your back if you've got mine." },
            { id = 2018943, text = "Oh, thank the tithes, not everyone has lost their damn mind! Half the house has gone mad!" },
            { id = 2018948, text = "There's nothing a hard day's work can't fix." },
            { id = 2018942, text = "You don't have to tell me twice." },
