    { who = "Sanath Lim Yo", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1585953, text = "Enough! Stay your weapon!" },
            { id = 1585954, text = "It seems the Grimoire took my mind, just as it has eroded Xylem's, and now he has escaped with the Iris!" },
            { id = 1585955, text = "You must follow him through his portal. Go! Before it's too late!" },
