        { name = "Conversation", family = "Feelings", lines = {
            { id = 2962023, text = "ABC, always be creating." },
            { id = 2962019, text = "Be good, do good." },
            { id = 2960150, text = "It's for the, uh, radiation poisoning, right, sweetie?" },
            { id = 2962022, text = "Lovely to see you!" },
            { id = 2961845, text = "Of course we'll join your cause, Prince Erasmin! That's why we're here!" },
            { id = 2962017, text = "Oh, you just gave me an idea!" },
            { id = 2961846, text = "Tinkmaster over Spark. Krizek and I want to thank you for the opportunity to accompany you to Mechagon." },
            { id = 2962020, text = "Try to stay out of trouble!" },
            { id = 2962021, text = "Wanna help me test something?" },
            { id = 2961843, text = "Your people have been through so much, Prince Erasmund. We are mo" },
