    { who = "Saprish", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1686224, text = "STRIKE HARD AND FAST!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1686223, text = "I shall always be one step ahead!" },
