        { name = "Conversation", family = "Feelings", lines = {
            { id = 1686221, text = "A simple tactical error." },
            { id = 1686222, text = "I. Did. Not. Foresee. This." },
            { id = 1686230, text = "It seems this nuisance requires a more personal touch. I shall handle you myself." },
            { id = 1686225, text = "More fodder for my beauties!" },
            { id = 1686219, text = "Our efforts will not be interrupted!" },
            { id = 1686226, text = "So easily outclassed." },
            { id = 1686229, text = "We are being overrun! Get in there and deal with this incursion!" },
            { id = 1686228, text = "We will not be pushed out! Bring in more forces from the Void to deal with these intruders!" },
        } },
    } },
    { who = "Sarah Howell", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
