    { who = "Sassy Hardwrench", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3087722, text = "Come on! We got money to make!" },
            { id = 3087721, text = "Let's get back to work!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3087723, text = "Always got more to do." },
            { id = 3089706, text = "Boss! We got trouble!" },
            { id = 3089703, text = "Got a ride to Krampopolis waitin' for ya on the dock." },
            { id = 3087720, text = "Great to see ya!" },
            { id = 3087718, text = "I'm all ears, boss!" },
            { id = 3089704, text = "Oh, and Gallowix bought out the whole town, so, uh, try not to get on his bad side." },
            { id = 3089705, text = "She'll round up the bias and not set up the auction! We're gonna be rich!" },
            { id = 3087719, text = "Something on your mind." },
            { id = 3089702, text = "Well, well, look who it is!" },
            { id = 3087724, text = "You need anything, you come to me." },
        } },
    } },
    { who = "Sataiel", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1447459, text = "All who have tried to tame Ulthalesh have been consumed! You will fare no better!" },
            { id = 1383455, text = "Do not fret! Through all the less, you will be so much more in death than you were in life!" },
            { id = 1447463, text = "Impossible! You will be consumed!" },
            { id = 1383454, text = "Such poor souls! You don't even belong here, but you will forever be bound to this place!" },
            { id = 1447461, text = "You will join the harvested!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1447458, text = "Fool! You would think to succeed where even I, Chosen of Sargeras, had failed?" },
            { id = 1383458, text = "How quaint! Do you really think your holy light can protect you from the Legion's onslaught?" },
            { id = 1383456, text = "You were fools to think such a pitiful force could oppose an agent of Sargeras!" },
            { id = 1383457, text = "Your worthless lives will pave the way for the Legion!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1447462, text = "Oh, flesh feasts!" },
            { id = 1447460, text = "Ulthalesh will devour you!" },
            { id = 1383459, text = "Where is your light to protect you now?" },
        } },
    } },
    { who = "Satyr casters", tier = "creature", ctype = "Demon", groups = {
