    { who = "Scalecommander Azurathel", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4643230, text = "My head... Alright, we need to get our bearings." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4643291, text = "By wing or by talon, we will see it done." },
            { id = 4643234, text = "Can you bring down this barrier?" },
            { id = 4643058, text = "Focus. Obsidian Warders, stay alert on approach." },
            { id = 4643231, text = "Gear up, evoker. Then we rendezvous with the Earth Warder." },
            { id = 4643237, text = "Have you found the Earth water?" },
            { id = 4643289, text = "Only fragments. A battle against a great foe. We claimed victory, I think. Though I fear we... paid a terrible price for it." },
            { id = 4643308, text = "That dragon is going to collapse our only way out!" },
            { id = 4643025, text = "We Drakthir would rather fly home than ride a wooden vessel as it drifts upon the waves. But I pledge to accompany your expedition, so... waves it is." },
            { id = 4643309, text = "We were trained to defend dragons, not to fight them. This feels wrong." },
        } },
    } },
    { who = "Scalecommander Cindrethresh Dragon", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4643239, text = "But there isn't." },
            { id = 4643370, text = "Cut the chatter, Kodethi. Hostiles could be lurking. Evoker, time to get those skills sharpened." },
            { id = 4643027, text = "Finally! I could have flown there and back again by now!" },
            { id = 4643063, text = "Focus! Keep your eyes on the sky. You never know when danger might swoop in." },
            { id = 4643236, text = "Just the reinforcements I needed!" },
            { id = 4643238, text = "No, he is not in this chamber." },
            { id = 4643311, text = "So today, we fight for each other. For all Drakthir!" },
            { id = 4643310, text = "The Pisigos has left us no choice, Sury. He means to destroy us." },
            { id = 4643290, text = "We will find answers. But first, we need to get our people out of here." },
            { id = 4643243, text = "Well, this should be fun!" },
            { id = 4643288, text = "What do you remember, Zuri? Before the stasis." },
        } },
    } },
    { who = "Scalecommander Cindrethresh Visage", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4661218, text = "You have your orders." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4672914, text = "I hear some dragons even choose to look like gnomes, whatever that is." },
            { id = 4661224, text = "I woke up today and chose violence. How about you?" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4661219, text = "Let's get back to training!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4672916, text = "All I know is that I like what I see, in myself and in you." },
            { id = 4661220, text = "Anything for an ally." },
            { id = 4661221, text = "Here to spa?" },
            { id = 4672912, text = "Hmph, I guess the old dragon was right after all." },
            { id = 4661223, text = "I'm ready. What do you need?" },
            { id = 4672911, text = "It does, doesn't it? Vissian said to look inside and let the magic within express how I wanted to be seen." },
            { id = 4672909, text = "Suri! I wondered if I'd recognize you in your visage, but somehow I just knew it was you." },
            { id = 4661222, text = "You call that a uniform?" },
        } },
    } },
    { who = "Scalecommander Sarkareth", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4636201, text = "I have no time for pleasantries." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4636199, text = "Get to the point." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4636191, text = "off with you." },
            { id = 4636194, text = "That will be all." },
            { id = 4636197, text = "We are done here." },
            { id = 4636200, text = "What do you want of me?" },
        } },
    } },
    { who = "Scalecommander Viridia", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4659417, text = "I hope for your quick return." },
            { id = 4643435, text = "My people need time to recover before we can rendezvous with the others. And the Draconid, well, they are not known for their swiftness." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 4643429, text = "Shh, shh, shh. I know. You are as brave and foolish as ever." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4643673, text = "All Werns, prepare to evacuate. The Aspect will provide cover." },
            { id = 4643684, text = "Fair skies and strong winds, Syndra." },
            { id = 4643683, text = "I'm sorry, dear friend. My wan will remain in the Dragon Isles. If fate is kind, we will not be parted long." },
            { id = 4643431, text = "Nonsense. I am perfectly fine. Just hurry back with those toxin glands, evoker." },
            { id = 4643434, text = "Please Evoker, save all of my people that you can, and honor the memories of the fallen." },
            { id = 4643433, text = "There is strength in mercy, Syndra." },
            { id = 4643437, text = "They are soldiers just like us. Do not judge them too harshly for following orders." },
            { id = 4643427, text = "Uh-uh-uh. Easy there, Syndra. Easy." },
        } },
    } },
    { who = "Scarlet Commander Forsythe", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5226992, text = "MONSTERS! DIE IN THE LIGHT!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5226989, text = "I will purge the world of you!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 5226990, text = "Is that all there is?" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 5226995, text = "Ready yourselves. This is the hour where you will be tested. Only you stand between the darkness of death and the light of the living." },
            { id = 5226997, text = "Too long have those monsters polluted the hallowed lands of our people. No more. Today we will reclaim what is ours and purge the stain of the unliving from the world." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5226991, text = "Do you not see that the world will be better off without the Forsaken in it?" },
            { id = 5226988, text = "Lillian Vos. Your father would despise you for what you've become." },
            { id = 5226996, text = "Soldiers of the Scarlet Crusade, we stand at the threshold of a new Lordaeron, poised to liberate it from the cold grasp of the undead." },
        } },
    } },
    { who = "Scarlet Footsoldier", tier = "character", groups = {
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5227003, text = "At your side, my lady!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5227004, text = "FLEA to hunt another day!" },
            { id = 5227009, text = "I, uh... Yes, sir. Here's your boat, sir. Please, stop looking at me like that, sir." },
            { id = 5226999, text = "Keep your wits sharp! The undead draw near." },
            { id = 5227008, text = "Of course. Ride away, Lieutenant. Have a good ride over." },
            { id = 5227007, text = "Of course. Right away, Lieutenant. Have a good ride over." },
            { id = 5227001, text = "Shed your fears and open yourself to avenging light!" },
            { id = 5227006, text = "That uniform looks a bit big for you." },
        } },
    } },
    { who = "Scholar Roh Suir", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4087522, text = "Follow the purpose. Always." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4087529, text = "Welcome to the Archive. What remains of it?" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4087530, text = "Wisdom and knowledge must be preserved." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4087528, text = "A true scholar studies all." },
            { id = 4087527, text = "I... we... have a solemn responsibility." },
            { id = 4087526, text = "May you return with knowledge." },
            { id = 4087525, text = "Memories are fleeting. The Archive is eternal." },
            { id = 4087523, text = "Restore the Archive. Fulfill the Purpose." },
            { id = 4087524, text = "Seek out knowledge wherever you go." },
            { id = 4087533, text = "The Archivist must be rescued. All of our fates depend on it." },
            { id = 4087531, text = "Trust in the purpose." },
            { id = 4087532, text = "You... are not one of them. Please, I need assistance." },
        } },
    } },
    { who = "Scourgelord Tyrannus", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 559677, text = "GAAAH!" },
            { id = 559681, text = "HA!" },
            { id = 559685, text = "HUH!" },
            { id = 559674, text = "HYAH!" },
            { id = 559680, text = "NYAH!" },
            { id = 559696, text = "RAAAGH!" },
            { id = 559679, text = "RAWR!" },
            { id = 559676, text = "WAH!" },
            { id = 559669, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 559695, text = "Such a shameful display. You are better off dead." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 559700, text = "I shall not fail the Lich King! Come and meet your end!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 559663, text = "AHHH!" },
            { id = 559672, text = "ARGH!" },
            { id = 559694, text = "BOOM!" },
            { id = 559660, text = "GAH!" },
            { id = 559688, text = "OW!" },
            { id = 559662, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 559667, text = "Impossible! Rhyme Fang! Warn!" },
            { id = 559661, text = "Perhaps you should have stayed in the mountains!" },
            { id = 559698, text = "Thank you for watching!" },
        } },
    } },
    { who = "Scout Tomul", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4636073, text = "Ah, the hunt is upon us. This target will test your mettle, Two-Foot. Are you prepared?" },
            { id = 4636074, text = "Come out and hunt if you are up to the challenge. This quarry is strong and relentless." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4636077, text = "Find and kill the beast that roams this area. It cannot be left to harm others." },
            { id = 4636076, text = "Find the beast that roams these lands and kill it. We will make good use of the resources it provides." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4636079, text = "This giant is a plague upon the land. Bring it down!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4636075, text = "A wild creature stalks this land. Come, join the hunt. Prove your skill." },
            { id = 4636081, text = "The end of the hunt draws near. Sound the haunt and form the other hunters." },
            { id = 4636078, text = "This elementals magic is wild and dangerous. Destroy it so that it does no harm to others." },
            { id = 4636080, text = "We near the end of our hunt? Signal the other hunters by blowing the horn!" },
            { id = 4636082, text = "We're drawing close to the end of our hunt! Blow the horn to signal the other hunters!" },
            { id = 4636083, text = "You did better than I expected. My scouts will search for new hunting grounds while these lands replenish." },
            { id = 4636084, text = "Your skills impress me, Two-Foot. We must let this land be replenished. My scouts will seek new hunting grounds and new challenges." },
        } },
    } },
    { who = "Scrollsage Nola", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2005934, text = "Help! These little ones have taken our scrolls and turned themselves into beasts. We have dispelling scrolls, but you will need to get close enough to use them. Watch out!" },
            { id = 2005935, text = "You have my thanks. Children these days have no respect for their elders or their belongings. Now back in my day..." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2005937, text = "There's something strange going on nearby, be a dear and check it out, it could lead to something interesting." },
            { id = 2005938, text = "This will make a great story to tell the others. Here's something for your efforts. Keep it up." },
        } },
    } },
    { who = "Sea Priest Council - feminine voice", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2007902, text = "HAHA!" },
            { id = 2007899, text = "HUAGH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1957476, text = "None shall stand against the storm!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1957471, text = "Once our ritual is complete, the Kul Tiran fleet will belong to Queen Azshara!" },
            { id = 1957474, text = "The winds will blast the flesh from your bones!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1957480, text = "Together, my love, we are a force of nature!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1957479, text = "Cleansed by the storm!" },
            { id = 1957475, text = "The breeze is ever at our backs!" },
            { id = 1957477, text = "The clouds break." },
            { id = 1957472, text = "Wins! Protect me!" },
        } },
    } },
    { who = "Sea Priest Council - masculine voice", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1957503, text = "I'LL BREAK YOU TO SPRINTERS!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2020883, text = "HEY GAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1957505, text = "Welcome, Brother Pike! You have arrived just in time to witness our victory!" },
            { id = 1957506, text = "Welcome, intruders! You have arrived just in time to witness true power." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1957507, text = "My hull is impenetrable!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1957512, text = "Enjoy your watery grave!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1957508, text = "I'll cast you to the depths for that!" },
            { id = 1929215, text = "No power can break our bond." },
            { id = 1957510, text = "Return me to the sea." },
            { id = 1957509, text = "The tide shall take you!" },
            { id = 1957511, text = "You should have stayed ashore!" },
        } },
    } },
    { who = "Secutor Mevix", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3692175, text = "MALTRAXIS HONORS YOU" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3692176, text = "My blades are at your command." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3692172, text = "Do not forsake your allies." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3692179, text = "But sir, that will result in a massive number of casualties." },
            { id = 3692181, text = "I'll set the charge!" },
            { id = 3692182, text = "Keep them off me mortal!" },
            { id = 3692171, text = "Our might is without equal." },
            { id = 3692173, text = "Show no weakness, offer no mercy." },
            { id = 3692177, text = "Something to report?" },
            { id = 3692174, text = "We follow the will of the Primus." },
            { id = 3692180, text = "We'll blast them to pieces!" },
        } },
    } },
    { who = "Seeker of Wisdom", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1406139, text = "Oh no... RAVEN DWEAR!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1406136, text = "I don't see anything unusual about this brazier. It looks to be in pretty good shape for something so ancient." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1406138, text = "Your friend is right. We should work together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1406134, text = "Death by sword or death by spells, it's all the same to me." },
            { id = 1406140, text = "I'll do that. See you soon." },
            { id = 1406142, text = "Lovely view up here. Hmm. Now that book warrants a closer look." },
            { id = 1406141, text = "Ravntweer, you should not have gone off alone." },
            { id = 1406137, text = "There's a Fel rune locking that door. The Empyrean society should not be using such magic." },
            { id = 1406143, text = "There's nothing exotic about fel magic." },
        } },
    } },
    { who = "Seerhao", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 852131, text = "Do not fear the heights as I did when I was young. Fear can drive us to terrible deeds. Ah, but I see that like me, you have learned the lessons of courage." },
            { id = 852123, text = "My, you are strong. When I was young, I might have doubted that we could do this. But now, I have no doubts at all." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 852143, text = "I conquered my doubts, my fears, my anger. I buried all of it within the land." },
            { id = 852137, text = "I was going to teach you a lesson, but instead, it is you who have taught me. You see, when I was young… When I was young… When I was young…" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 852133, text = "Ah, here we are. Oh, oh, these old bones are tired. More than you can imagine." },
            { id = 852125, text = "Such wind, such cold. Once it would have filled these old bones with despair, but on this day I am filled with hope." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 852145, text = "But, I held on to one vice, the one Sha I never conquered. Pride." },
            { id = 852127, text = "Hehehe, do not get angry with the elements, violence is their nature. I conquered my own anger long, long ago." },
            { id = 852129, text = "Such a patient one. When I was young, I would have hated this task. Nowadays, I am filled with love." },
            { id = 852141, text = "The realm you see all around you was mine to command." },
            { id = 852135, text = "You surprised me. I expected a hero such as yourself to bark at the task of carrying an old man up a mountain. Most are too proud." },
        } },
    } },
    { who = "Sendrax", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4680079, text = "I will protect them." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4672594, text = "So you two were adversaries before leading this expedition together?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4672592, text = "But I am honored to be the one to welcome you to the Dragon Isles!" },
            { id = 4672850, text = "But, I suppose this is a type of emergency." },
            { id = 4672862, text = "Major Domo, the new arrivals were wondering where you were, and I thought..." },
            { id = 4672858, text = "Oh, yes! In times of trouble, there is no one Queen Alexstrasza trusts more!" },
            { id = 4672593, text = "On my first real assignment, no less! What good fortune!" },
            { id = 4672851, text = "There! Major Domo Solistra will arrive soon!" },
            { id = 4680080, text = "This is my calling." },
            { id = 4672849, text = "We were trained to only use these signal flares if the situation is dire." },
            { id = 4672591, text = "Yes, I had expected Major Domo, Solistra, and Arathian to be here by now." },
            { id = 4672884, text = "Yes, Major Jomo!" },
        } },
    } },
    { who = "Senegos", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1243289, text = "I'm afraid it will be of no use to you in its current shattered state." },
            { id = 1243285, text = "Oh, you are a kind small thing." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4703929, text = "I can use my frost breath more than three times a day, you know." },
            { id = 1243307, text = "My starlight is in danger! Protect her!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1243303, text = "Don't be so eager to mourn, Starlight. Give me this one last adventure." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1243287, text = "Ah, the Tidestone of Galganeth." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4703919, text = "The Dragonflights will rise again." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1243301, text = "Steragosa, do me one last favor. Your younger brothers and sisters need your help." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1243305, text = "Another nightfallen attack. Bring my child to me, young one." },
            { id = 4703917, text = "Do what you must to save the world, hero." },
            { id = 1243299, text = "Farondis, old friend. Is that you?" },
            { id = 4703928, text = "Have you no respect for your elders?" },
            { id = 1243291, text = "Let the useful one approach, I am not as dead as I look." },
            { id = 4703918, text = "May the wisdom of the Titans guide you." },
            { id = 4703927, text = "Must you act like a child?" },
            { id = 1243297, text = "See you soon, Starlight." },
        } },
    } },
    { who = "Sentinel Talondras", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4661881, text = "I WILL PURGE YOU FROM EXISTENCE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4661880, text = "Halt! You will go no further!" },
            { id = 4661879, text = "Stop where you are!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4661888, text = "I will protect the Keeper's secrets for all of time!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4661886, text = "An unworthy foe." },
            { id = 4661883, text = "Halt! The unworthy will not enter this hallowed place." },
            { id = 4661885, text = "His memories are not for you!" },
            { id = 4661884, text = "Keeper Tear's secrets will be protected!" },
            { id = 4661882, text = "Let the unworthy be purged!" },
            { id = 4661878, text = "Must regain strength!" },
            { id = 4661887, text = "Such weak flesh!" },
        } },
    } },
    { who = "Sentry Pierce", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1406315, text = "Admiral, Commander! Have you seen it?" },
            { id = 1466011, text = "Look for yourself!" },
            { id = 1406316, text = "Look to the sky! It's happening above the lodge!" },
            { id = 1406318, text = "The emergency signal flares, they're being fired above the lodge!" },
        } },
    } },
    { who = "Ser Geant Bainbridge", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1857660, text = "PREPARE TO DIE!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1857659, text = "I will cut you down!" },
            { id = 1857661, text = "None can withstand the tide!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1857666, text = "The sea will claim your bones!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1857665, text = "You don't deserve victory." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1857658, text = "Artillery! Clear this scum from my battlefield!" },
            { id = 1857657, text = "Cannons! Fire on my position!" },
            { id = 1857668, text = "Ha! About what I expected from the Horde!" },
            { id = 1857664, text = "Your end is here, horde scum!" },
        } },
    } },
    { who = "Ser Geant Calvin", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1992348, text = "I just want to wish you good luck, we're all counting on you." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1992358, text = "Let's get out of here." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1992355, text = "Keep to the right, I think I saw a way out." },
            { id = 1992350, text = "We're out. I'll make my way back to Roz with the report. You've saved the town, hero!" },
            { id = 1992356, text = "You actually did it! Quickly, over here!" },
        } },
    } },
    { who = "Ser Geant Dalton", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1391557, text = "I bear an important message from D'nath Trollbane." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1391556, text = "Commander, I have a message for you." },
            { id = 1391559, text = "Excellent, Commander. Danith awaits you on Crassus' landing." },
            { id = 1391558, text = "If you please, this is an important matter that requires your attention." },
        } },
    } },
    { who = "Ser Geantgorrok", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 636142, text = "BLOOD AND THUNDER!" },
            { id = 636136, text = "FOR THE HORDE!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 636152, text = "Do I have Alliance in my fangs?" },
            { id = 636134, text = "Lok'tar, friend." },
            { id = 636132, text = "Our enemies must fall." },
            { id = 636144, text = "This land is ours. It just doesn't know it yet." },
            { id = 636146, text = "What news, friend?" },
        } },
    } },
    { who = "Ser Rik", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1998918, text = "Ah, I can feel my strength returning. It appears the Antivenom is working." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1998922, text = "Are you here to help?" },
            { id = 1998928, text = "He leads them in their fight, searching for the remaining keys that will allow him to break the barrier around Atul'Aman, and use what's within to conquer all of Zuldazar." },
            { id = 1998924, text = "Korthak brought this war upon us." },
            { id = 1998926, text = "Long ago, we lived as one, as our Loa would have wanted." },
            { id = 1998925, text = "Our temple is the last bastion against the faithless." },
            { id = 1998921, text = "Sethralis will save us." },
            { id = 1998927, text = "Since Korthak's betrayal, the faithless have brought war upon these lands." },
            { id = 1998919, text = "The faithless will not take our temple." },
            { id = 1998920, text = "We do what we must." },
            { id = 1998923, text = "We must remain strong." },
            { id = 1998929, text = "We will do whatever it takes to stop him." },
        } },
    } },
    { who = "Setesh", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 560000, text = "EMBRACE THE END" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 560001, text = "HUH ROAR!" },
            { id = 559977, text = "RAWR!" },
            { id = 559986, text = "ROAR!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 559981, text = "AHHH!" },
            { id = 559979, text = "ARRR!" },
            { id = 559990, text = "AWWW!" },
            { id = 559982, text = "OOF!" },
            { id = 559980, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 560003, text = "Do you understand now?" },
        } },
    } },
    { who = "Sethrak - feminine voice", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2006869, text = "YOU CANNOT STOP THE FAITLESS EMPIRE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2006870, text = "You cannot stop the storm!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2006867, text = "I know you're there. Your scent tickles my tongue." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2006868, text = "May the desert take your soul!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2006866, text = "Dig, seek, find! The final key must be here!" },
            { id = 2006861, text = "Hmm, you'll fetch a high price." },
            { id = 2006864, text = "Korthak will reward us if we find the key first!" },
            { id = 2006863, text = "The key is ours. The other keepers failed in their task. For Korthik, I will not." },
            { id = 2006871, text = "The sun sets on the Zandalari Empire! The faithless will claim what is left!" },
            { id = 2006872, text = "There will be others." },
            { id = 2006865, text = "Those blasted Zandalari are closing in! We must find it before they do!" },
        } },
    } },
    { who = "Sethrak - masculine voice", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1997934, text = "EYES WILL NOT BE BROKEN" },
            { id = 1997930, text = "YOU CANNOT STOP THE SENSE!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1997928, text = "I will strip the flesh from your bones!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1997932, text = "Come, Vultures. You've waited for this feast." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1997927, text = "You fight well for a pathetic land dweller, but this ends now!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1997935, text = "The ritual is not yet complete! The clogs must be subdued!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1997933, text = "Another Pterodactyl, too weak for the faithless!" },
            { id = 1997931, text = "I'll string you up by your feet and let the vultures eat you alive." },
            { id = 1997936, text = "No, the frogs must not be freed!" },
            { id = 1997938, text = "Seth Rallis, I'd forgotten your voice." },
            { id = 1997929, text = "The temple must fall. We will slaughter any who stand in our way." },
            { id = 1997937, text = "We are not bound to the lower! Our strength is our own!" },
        } },
    } },
    { who = "Sethrak casters", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1971384, text = "FOR THE EMPEROR!" },
            { id = 1971382, text = "YOU WILL SHATTER LIKE GLASS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1971388, text = "Like sand, you will be scattered and forgotten!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
