    { who = "Shadowlord Slaghammer", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1391114, text = "The Shadow Deacon's already below starting his ritual. To get there, we'll need to do a bit of work. If you have any questions, let me know. But we'd best hurry." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1391113, text = "My recede ye'd be comin'. I'm Slaghammer, payin' my family's debt by hangin' out with these buggers. Heh heh heh, lemme take down this barrier." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1496805, text = "HUH!" },
            { id = 1496804, text = "UGH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1391115, text = "His boogers are suppressing Tyr's wards, so the Daekon can do his work below. We need to take him down. Start by dispelling the wards on the ritualists." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1391116, text = "A trap! Huh! Destroy that creature before it kills us!" },
            { id = 1391111, text = "Excellent. I was expecting him, but I don't think you were." },
            { id = 1391117, text = "Here we go. The path to the prison should be op- Well, if it ain't me old friend, we'd be doin' the world a favor ridin' it o' this, buddy!" },
            { id = 1391134, text = "Keep an eye on that blade though, no tellin' was somethin' that old be capable of." },
            { id = 1391118, text = "More of the Deacon's mind games. We could master spell him, or just fight through, but it wouldn't have got too close." },
            { id = 1391121, text = "This isn't any good. I can hear more coming from above. I'll handle them. Ye take care of the Deacon!" },
            { id = 1391133, text = "You did it! The cultists have run off! Ha! Ha Ha Ha ha! You should get back to foul. I'll use this twilight portal stone for you." },
        } },
    } },
    { who = "Shadowy Figure", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 1545086, text = "Hey, whoa there!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1545102, text = "Hmph. I got nothing." },
            { id = 1545094, text = "It's tough to savor a juicy slab of boar meat when you've got a bloody lip, know what I mean?" },
            { id = 1545092, text = "Me? I'm not much of a fighter." },
            { id = 1545104, text = "Oh well, be seeing ya!" },
            { id = 1545090, text = "Ruined a perfectly good nap." },
            { id = 1545096, text = "So listen up. While you deal with this little mess I may or may not have caused, I'm going to make a dramatic exit." },
            { id = 1545100, text = "Uh, this is harder than it looks. Have you ever tried to come up with a sweet catchphrase right on the spot?" },
            { id = 1545098, text = "Uh, wait. I should say something cool and memorable before I go." },
            { id = 1545088, text = "You really shouldn't sneak up on people like that." },
        } },
    } },
    { who = "Shadowy Figure Be - masculine voice", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2923200, text = "But she's always giving me orders and sending me on stupid missions. What about me? What about what I want to do?" },
            { id = 2923199, text = "Oh great, the hero is here. Ugh, this assignment is going to take forever." },
            { id = 2923202, text = "What a waste of time this has been." },
            { id = 2923201, text = "You're worse than she is. Why do I even talk to you?" },
        } },
    } },
    { who = "Shadowy Figure Gnome - feminine voice", tier = "character", groups = {
        { name = "Farewells", family = "Manners", lines = {
            { id = 2923190, text = "Yeah! That's more like it! Time to leave this dump." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2923188, text = "All you do is whine! If you don't put a lid on it, I'll put a lid on you! Now brace yourself! It's time for stage two!" },
            { id = 2923189, text = "Because I'm a genius? Oh, this piece of junk is taking too long. What if I remove the regulators and crank it to the max?" },
            { id = 2923187, text = "Shut up! She trusted us to complete this task, and this time we will, with the power of science!" },
        } },
    } },
    { who = "Shadowy Figure Ne - masculine voice", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2416347, text = "We have been watching you, hero. You haven't the faintest idea what you are up against." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2416349, text = "I have just deactivated all safety protocols from this unit and took something special for us to keep." },
            { id = 2416351, text = "I would wish you luck, but my words would be wasted. Super teleport, activate!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
