    { who = "Shaohao", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 896380, text = "Ah, you have raised your pets well and beaten some of Pandaria's most seasoned and charismatic trainers. But the trial is not over. Oh, no." },
            { id = 896376, text = "In this trial you will not be allowed to heal your pets. One of the marks of a great leader is the ability to lead many subjects from many backgrounds united under one banner." },
            { id = 896378, text = "Today, you will face many trainers who have honed their skills and proven themselves. Will your pets tell the same story about you? We shall see. Good luck!" },
            { id = 896398, text = "You have walked the Trial of Hope and learned of the path of the Red Crane. May it guide your footsteps through time." },
            { id = 896396, text = "You have walked the trial of strength and learned of the path of the White Tiger. May you remember this lesson always." },
            { id = 896394, text = "You have walked the Trial of Wisdom and learned of the path of the Jade Serpent. May you learn from this lesson as I did." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 896388, text = "When my journey began, I was reckless in my strength. The White Tiger taught me control. My hatred, anger, and violence were vanquished." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 896386, text = "Long ago, the Jade Serpent instructed me to purify my spirit and become one with the land. My doubts were vanquished." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 896392, text = "In the face of great fear, the Black Ox taught me fortitude. Through terror and darkness, it persevered. The fear was vanquished." },
            { id = 896390, text = "The Red Crane saw hope in me and instructed me to look inward. Despite my visage of despair, I found this hope. The despair was vanquished." },
        } },
    } },
    { who = "Sharkbait", tier = "character", groups = {
