    { who = "Sigryn", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1595380, text = "I will be your instrument. Tell me what I must do.\"" },
            { id = 1595384, text = "I will continue to cry, Thor. See you there." },
            { id = 1595381, text = "I will ride ahead to Hostford. I would be honored if you would join me there." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1595383, text = "Cease your prattling, runes here!" },
            { id = 1595385, text = "Jarl Velbrand, as the blood of Skovald and at the behest of Eyir, I claim the throne of the Tideskul." },
            { id = 1595389, text = "Oh no, Torvald! You've succumbed to the fel! But how?" },
            { id = 1595382, text = "Runsir Foljar! I am Sigrun, Blood of Skovald. In the name of the Valkira, I challenge you for the rule of the Tideskorn." },
            { id = 1595378, text = "This outsider says I am to unite the Tideskorn." },
            { id = 1595388, text = "Torvald, it is you! I didn't want to leave you, but I wasn't strong enough! How did you survive the assassins?" },
            { id = 1595379, text = "Very well. If I truly am so important to the Tideskorn, then I cannot turn my back on this task." },
            { id = 1595387, text = "We should waste no time. Direct!" },
            { id = 1595386, text = "Will you yield?" },
        } },
    } },
