        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370564, text = "Glory will be mine in the halls of valor!" },
            { id = 1373784, text = "Out with it!" },
            { id = 1370566, text = "Stand and fight!" },
            { id = 1370565, text = "The Northwinds obey my command!" },
            { id = 1370562, text = "This isn't over, shaman. Someday we will meet on a true field of battle." },
            { id = 1370568, text = "Who challenges me? The weapons of this storm belong to my clan by rights!" },
        } },
    } },
    { who = "Sika", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3588205, text = "Bye! Come back soon!" },
            { id = 3547150, text = "Centurions will overwhelm us!" },
            { id = 3588191, text = "Have it! Yes!" },
