    { who = "Sikari", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 899895, text = "A new enemy, illusionary flame callers. They cast fireballs and spew lava. Use the lava to your advantage, it will burn the other illusions." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 899905, text = "I am down. Maybe I should bring more healing herbs for next time." },
            { id = 899903, text = "I cannot heal to that much damage. Did you forget to equip your heaviest armor?" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 899901, text = "Illusionary foragers are attacking, do not let their cute faces fool you. They can work together to cause terrible devastation." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 899887, text = "Help! Get these things off of me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 899897, text = "Beware, illusionary wind guards can use their wings to knock you back. When they do, they will lightly switch to attacking me instead." },
            { id = 899899, text = "Illusionary ambushes. Get their attention quick, and get them away from me, so they cannot hit me with their devastating bananas." },
            { id = 899891, text = "Illusionary rippers approaching. They should pose little challenge. They are but mindless grunts." },
            { id = 899909, text = "Once again, you must defend me. Rodan, give us a challenge this time." },
            { id = 899893, text = "Prepare your defenses. That is an illusionary conqueror. When they become enraged, they gain great strength, and nothing can stop them." },
            { id = 899889, text = "What are you standing in? Get out of the fire!" },
        } },
    } },
    { who = "Sikran", tier = "character", groups = {
