    { who = "Silgryn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1408341, text = "Do you think you will have enough?" },
            { id = 1407927, text = "I will find Lyleth. You stay out of trouble." },
