        { name = "Boasts", family = "Menace", lines = {
            { id = 4659904, text = "I appreciate your aid." },
            { id = 4611120, text = "I see, and the rest of our flight, where are they?" },
            { id = 4611118, text = "I sense an aspect." },
            { id = 4611113, text = "I was expecting Malygos. Where is he? And who are you?" },
