        { name = "Loyalty", family = "Manners", lines = {
            { id = 4611125, text = "Child of my flight, shall we work together to make that hope a reality?" },
            { id = 4611115, text = "Sindragosa? In a way... A simulacrum created by her in order to preserve her memories and knowledge." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
