            { id = 3756535, text = "HA!" },
            { id = 3756539, text = "HMPH!" },
            { id = 3756537, text = "HYAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3502018, text = "For this task, I lend you Prince Renethal's Medallion, as well as the might of our dear friend, the Maw Walker." },
            { id = 3546937, text = "My children, I know the suffering you have endured." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3546939, text = "I fear further sacrifices must be made if Revendreth is to survive this crisis." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3502019, text = "Bring the accuser to me, and her medallion shall be yours. The Prince's is already promised to another faithful ally." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3756585, text = "AAARGH!" },
            { id = 3756581, text = "D'OH!" },
            { id = 3756595, text = "OOF!" },
            { id = 3756591, text = "UGH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3546942, text = "Ah, the mortal who escaped the inescapable prison. A living soul restoring hope to the realms eternal." },
            { id = 3546943, text = "Maw Walker, I am aware of your urgent request for anima. Under normal circumstances, I would of course oblige." },
