        { name = "Conversation", family = "Feelings", lines = {
            { id = 3502017, text = "Lord Chamberlain, I hereby charge you with bringing an end to this failed rebellion." },
            { id = 3546944, text = "Sadly, you arrive in the midst of a violent rebellion. Our resources are stretched perilously thin." },
            { id = 3546945, text = "This drought has left my people desperate." },
