    { who = "Sironas", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5557686, text = "Meddling Drannai, Krocool, Minari, no matter, you will all fall!" },
            { id = 5557685, text = "You are too late! My corruption has spread too deeply!" },
            { id = 5557681, text = "You will never cleanse this aisle!" },
            { id = 5557288, text = "You will not ruin my plans again, Draenei. My magic has claimed this land, and will soon claim every last soul in your wrecked city." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 5557684, text = "Yes! Come to me, you fools! COME! TO YOUR DEATH!" },
