    { who = "Sister Etna Blayze", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5839846, text = "YOU WON'T PEEL OFF ANYMORE! YOU MUST DEFEAT DALECRY NOW!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5839855, text = "No! Such heresy! They defile the Sacred Flame by animating the dead! They are no better than the Kobis!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5839861, text = "All who take comfort in the light of the sacred flame, thank you." },
            { id = 5839839, text = "But of late, the devotees have become secretive, hostile." },
            { id = 5839847, text = "Dalecry was an Arathi hero. How could the Priory force him to turn against Hallifall?" },
            { id = 5839841, text = "Each of his lieutenants bolsters his tactics. Draw them away and defeat them." },
            { id = 5839860, text = "It is done. These zealots no longer steer our faith towards destruction." },
            { id = 5839853, text = "Merpray has warped the Priory from a place of contemplation to an uprising. Why?" },
            { id = 5839854, text = "She has always preached of the strength of the Emperor's will, but to turn against us is madness." },
            { id = 5839837, text = "The expedition built the Priory as a place to contemplate the mysteries of Belladar." },
            { id = 5839840, text = "The god sought to kill you. Captain Dale Cry is protecting something." },
        } },
    } },
    { who = "Sister Malady", tier = "character", groups = {
