        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1324313, text = "Cut them down and heave their souls into the tides!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1324304, text = "All hands on deck!" },
            { id = 1324311, text = "Intruders on the Naglfar! Give no quarter to these scallywags!" },
            { id = 1324302, text = "No prey, no pay! Now secure the Naglfar!" },
            { id = 1324310, text = "No quarter to these scallywags! Helya doesn't abide, intruders!" },
            { id = 1324309, text = "Nothing sweeter than to die at sea!" },
