    } },
    { who = "Skull of the Manari", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1385157, text = "And what did you have in mind for that?" },
            { id = 1384891, text = "There you are, mortal. I sense you are near. Move quickly and head down the path." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1384903, text = "Freedom! The feeling is sweet, but Mephistroth's magic has diminished my power. Let's depart this place before the Dreadlord is able to return!" },
            { id = 1384894, text = "The master is gone, and his minions gorge upon my power! Come, repay this degradation! Introduce them to unfathomable levels of pain!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1384902, text = "Curse you! I will not give in!" },
            { id = 1384886, text = "Fine then, come to Fell Soul Hold if you truly believe you can free me. But if you're not up for the challenge, you'll be joining me in eternal torment." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1384908, text = "Now what? Ah, one day I will free myself of your control, and... Wait... You're not my master." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1385155, text = "Already planning to run away?" },
            { id = 1385156, text = "Always have an escape planned. A lesson I learned the hard way." },
            { id = 1384898, text = "Do you hear me, mortal? Mephistroth imprisoned me at the far side of the valley. Hurry! I sense he is preparing for something... significant." },
            { id = 1384896, text = "Good! Now, before the master returns, slay my captors and free me!" },
        } },
    } },
    { who = "Sky Admiral Rogers", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1239049, text = "I can't believe you tucked me into this! Can you even control this thing?!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1239145, text = "Bring us in!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1239149, text = "A boarding party on the deck!" },
            { id = 1239147, text = "Enemy flyers incoming! All guns! Fire at will!" },
            { id = 1239139, text = "Griffin Riders, first wing, prepare to descend. Second wing, hold position." },
            { id = 1239051, text = "Heads up! Very big dragon incoming!" },
            { id = 1243504, text = "Hero! Get those chemical flares away from the ammo!" },
            { id = 1243506, text = "Legionnaires, move out! Storm those ships and find Sylvanas!" },
            { id = 1239141, text = "Main cannons, prepare for a second volley as we breach the cloud line!" },
            { id = 1239143, text = "Man the deck guns! All hands, prepare for contact with the enemy!" },
            { id = 1239053, text = "Put that vile thing out of its misery already." },
        } },
    } },
    { who = "Sky Captain Elaena Lancekat", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 6124707, text = "My troops can defend this camp against Naga, but we require your help securing the island. Lend a hand if you would be so kind." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 6124734, text = "Reliable as always. The Empire appreciates Stalwart allies. Our forces on high remain vigilant." },
            { id = 6124735, text = "We will not tolerate a threat to our airship on this island, no matter where it may hide. Allies of the Arathi, prepare for battle!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6124731, text = "Look lively! I want that cave entrance cleared! Run out the guns! Commence bombardment!" },
            { id = 6124733, text = "Our troops will strike at this draconic horror within its lair. A barrage of cannon fire will reveal its presence. Prepare yourselves." },
            { id = 6124736, text = "Well done! An exemplary display! The cave is open! Troops, deploy!" },
            { id = 6124710, text = "We've seized the upper hand. It won't be long before these sea snakes slither back from whence they came." },
        } },
    } },
