        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4066330, text = "Your skins are lacking." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4066333, text = "I have no time for amateurs." },
            { id = 4066324, text = "My cartel bears my shame!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4066315, text = "A tidal wave begins as a ripple!" },
            { id = 4066309, text = "Be where your opponent is not!" },
            { id = 4066321, text = "Die, foes of Cartelso!" },
            { id = 4066318, text = "Every circle has its center." },
            { id = 4066327, text = "Such flawed technique." },
            { id = 4066306, text = "To remain still is to invite defeat!" },
            { id = 4066303, text = "When outnumbered, divide your enemies!" },
        } },
    } },
    { who = "Sol", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
