    { who = "Soldiers", tier = "creature", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1054589, text = "Take cover within the shield!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1054588, text = "Commander! Reinforcements from the arcane sanctum have arrived." },
            { id = 1054587, text = "If that beast crosses through, the unchecked growth will choke the whole of Azeroth. Hurry!" },
            { id = 1054585, text = "Watch out! Wolf Riders!" },
            { id = 1054586, text = "You! Maybe there is still time. The portal atop this outpost is a direct link to our world, to Stormwind, the Genosaur." },
        } },
    } },
    { who = "Soleah", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4070668, text = "Oh, you have a talent for acquiring intriguing artifacts. This was found among the ruins of the Black Empire, yes?" },
            { id = 4070667, text = "See how your wisdom fares against the might of the titans." },
            { id = 4070665, text = "Suffering and power. I must now travel beyond Tazavish, but your journey ends here." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4070664, text = "Aldaleel, is there no sanctuary from your filth?" },
            { id = 4070669, text = "Apologies, Captain. Please direct your grievances towards my associates." },
            { id = 4070666, text = "Haha! Power eludes your grasp, Aldalil! A tenet of your cartel!" },
            { id = 4070670, text = "Must you hound my every step?" },
            { id = 4070674, text = "Oh, the stars are mine!" },
            { id = 4070671, text = "Only the withered and dead belong in museums, like your cartel." },
            { id = 4070663, text = "So as me see to his payment." },
            { id = 4070673, text = "Their realms... I can feel them all!" },
            { id = 4070672, text = "Your cartel has dissolved into dust. I choose to lead mine to glory." },
        } },
    } },
    { who = "Sologroark", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1124282, text = "I'LL KEEP WATCH! GET MY BLUEPRINTS!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1124278, text = "Let's get this over with. Gul'dan has turned these docks into a recruiting ground." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1124279, text = "Blackhand ordered construction of a gigantic cannon. Then I built a monstrous warship to carry it. Bigger isn't always better. Our strategy fell apart in the waters around Shattrath." },
            { id = 1124287, text = "Ha! There's none better!" },
            { id = 1124284, text = "Here, this is a perfect natural harbor." },
            { id = 1124285, text = "I'll whip these laborers into shape, and have this harbor ready in no time!" },
            { id = 1124289, text = "I'm the best there is." },
            { id = 1124288, text = "Tell me more." },
            { id = 1124281, text = "This is why you should cover your buildings in spikes!" },
            { id = 1124280, text = "We normally use these grapples to tug ships into port." },
            { id = 1124283, text = "You wanna get past Gul'dan's navy, I can get you through." },
            { id = 1124286, text = "You've found him! If you wish me dead, put a hammer in my hands, and let's make a fight of it!" },
        } },
    } },
    { who = "Solsten", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1275931, text = "THE STORM GATHERS! STRIKE NOW ASIA!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1275917, text = "You're solid as ritual with your presence, mortals!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1275920, text = "Herrscher! The fury of the storm is yours to command!" },
            { id = 1275894, text = "Spoken like a true vulture!" },
            { id = 1275941, text = "The storm gathers within you, Herrscher!" },
        } },
    } },
    { who = "Somnikus", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4676859, text = "I know whelps more respectful than you." },
            { id = 4676869, text = "My son. He was very brave and would have wanted me to continue. And so I shall." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 4676888, text = "Then I should be the one to go. I will tally, Serra. Perhaps I'll join my son in the realms of death." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4676882, text = "He... tricked me... and... and I let him in." },
            { id = 4676848, text = "Just let me sleep." },
            { id = 4676866, text = "No, that can only be done from within the Emerald Dream." },
            { id = 4676842, text = "Why am I awake?" },
            { id = 4676854, text = "Wilds keep you." },
            { id = 4676885, text = "You mean the theory Garith has had? Could we do it? Could we bring Isara back so she could vanquish them all?" },
        } },
    } },
    { who = "Sooli", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 902153, text = "Ah, illusionary tunnelers. Speedy and I have faced these foes before. Mmm. Beware. They may burrow into the ground and then suddenly pop up under a new target and chop! Hahahaha!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 902159, text = "Haha! Wonderful job, everyone! Friend, see Rotan about beginning the next trial." },
            { id = 902149, text = "Huh? Ooh! Ooh!" },
            { id = 902147, text = "Oh, dear... Speedy! Help!" },
            { id = 902155, text = "Please, take care of Speedy." },
            { id = 902151, text = "Speedy and I are at your service." },
            { id = 902157, text = "There is no end in sight to these illusions, but we shall hold out as long as we can." },
        } },
    } },
    { who = "Soridormi", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4690780, text = "I will be here." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4690782, text = "If you want something done, I am the one to see." },
            { id = 4690778, text = "May time be kind to you." },
            { id = 4690779, text = "Ponder what we discussed." },
            { id = 4671342, text = "The beast ahead will threaten all who enter Thaldrazas. If not stopped, aid us in this fight." },
            { id = 4690777, text = "The sands flow eternal." },
            { id = 4690776, text = "There is much to do." },
            { id = 4671343, text = "This ended just as I saw it would. We are in your debt, adventurer." },
            { id = 4690783, text = "Time flows through me." },
            { id = 4690774, text = "Time is of the essence." },
            { id = 4690775, text = "Time reveals all." },
        } },
    } },
    { who = "Sorka", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 997044, text = "I think I see the problem." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 997050, text = "Don't worry, I'm coming. This looks fun." },
            { id = 997046, text = "Let's see how well you've trained our soldiers, Garon!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 997048, text = "Ha! What brutality! What bloodshed! Beautiful!" },
            { id = 997052, text = "I'm going to enjoy this." },
            { id = 997058, text = "I'm just too good." },
            { id = 997054, text = "It feels... so..." },
            { id = 997056, text = "Oh look, I broke it." },
        } },
    } },
    { who = "Sotanathor", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1692723, text = "Come small ones, die by my hand!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 1697051, text = "AH!" },
            { id = 1697052, text = "BLEH!" },
            { id = 1697048, text = "GRRR!" },
            { id = 1697050, text = "NO!" },
            { id = 1697055, text = "RRR!" },
            { id = 1697054, text = "UGH!" },
            { id = 1697053, text = "YEAH!" },
        } },
    } },
    { who = "Soul Queen Dejahna", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1592432, text = "FEED ENGINE! FEED!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1592434, text = "I claim you for the master!" },
            { id = 1592435, text = "I should have been stronger. Tell Tyrande, I am sorry." },
            { id = 1592436, text = "I tried to resist them, but failed. At least now, I am free." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1592430, text = "Do not resist the master's will!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1592427, text = "Ah, the ties that bind!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1592431, text = "Elune holds no power here. This tomb belongs to the Legion." },
            { id = 1592438, text = "Let this temple become your tomb!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1592428, text = "As I serve, so shall you!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1592429, text = "Can you feel the clutch of DOOM?" },
            { id = 1592433, text = "Hear the screams of the forlorn!" },
            { id = 1592437, text = "Let their agony wash over you!" },
        } },
    } },
    { who = "Soul Shackled", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3463015, text = "end this suffering" },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 3463004, text = "Tormented no longer." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3463011, text = "Finally, it ends." },
            { id = 3463013, text = "It never ends. It never ends!" },
            { id = 3463009, text = "It... is finally over..." },
            { id = 3463005, text = "They're all mentioned. No longer." },
        } },
    } },
    { who = "Soulguide Daelia", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3589071, text = "You shall. This ancient device shall allow your souls to connect. Simply reach out to one another." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3591801, text = "Go in service." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3589074, text = "It is done. May the power within your souls serve you well." },
            { id = 3591803, text = "Together we rise." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3591802, text = "Together we are strong." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3591800, text = "Archon watch over you" },
            { id = 3589067, text = "Aspirant Kleia, thank you for joining us on this sacred occasion to witness the bonding of this outsider with Aspirant Pelagos." },
            { id = 3589073, text = "Now, simply place your hand upon the device to further augment your bond." },
            { id = 3591805, text = "What troubles you?" },
            { id = 3591804, text = "You seek guidance?" },
        } },
    } },
    { who = "Soulrender Dormazain", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4077004, text = "MOSS ONE! FEED UP ON THAT PAIN!" },
            { id = 4077001, text = "MUTILATION IS MY SPECIALTY" },
            { id = 4077000, text = "YOU WILL SUFFER!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4076997, text = "You are mine to slaughter!" },
            { id = 4075679, text = "You will submit." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 4076998, text = "Witness a masterpiece of torment!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4077006, text = "Unleash every burden, every regret that infuses your soul, Hellscream." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4077002, text = "Mars One, demonstrate the power of agony!" },
            { id = 4076995, text = "The smell of seared flesh is intoxicating." },
            { id = 4077005, text = "Your agony belongs to me." },
            { id = 4076994, text = "Your rage is exquisite, Hellscream. It alone could power us so far just for eons!" },
        } },
    } },
    { who = "Speaker Brinthe", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5704246, text = "Return if you have more queries." },
            { id = 5704256, text = "You have my focus." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5704259, text = "I attend to the archive." },
            { id = 5704257, text = "I speak for the machines." },
            { id = 5704251, text = "I will ensure your name is in the archive." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5704248, text = "Back to work." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5704252, text = "May the deeps continue to ring." },
            { id = 5704253, text = "May your cogs hold true." },
        } },
    } },
    { who = "Speaker Koldiss", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5728089, text = "Let's get this done right." },
            { id = 5728085, text = "Stay safe out there." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5728083, text = "Enough is enough." },
            { id = 5728092, text = "Hope you brought tools." },
            { id = 5728080, text = "I'll fix you!" },
            { id = 5728086, text = "Keep the gears turning." },
            { id = 5728087, text = "Maintenance today, or repairs tomorrow." },
            { id = 5728090, text = "Measure twice, cut once." },
            { id = 5728084, text = "This is gonna get messy." },
            { id = 5728082, text = "Time for you to break down!" },
            { id = 5728091, text = "Time to fix things." },
        } },
    } },
    { who = "Speaker Kuldas", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5777759, text = "GET THEM OFF ME!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5777756, text = "I'm getting lit up!" },
            { id = 5777760, text = "It's getting too hot. We're getting out of here." },
            { id = 5872025, text = "Mind your tone, Foreman." },
            { id = 5855039, text = "No one's going anywhere. The bulwark of authorization is on complete lockdown." },
            { id = 5855041, text = "Shutting down that golem will shut down the whole purge program." },
            { id = 5777757, text = "They're... on me!" },
            { id = 5777758, text = "Ugh, not feeling too hot." },
            { id = 5777754, text = "Watch my back while I commune with the machine." },
            { id = 5855040, text = "Well, look at you. I've seen this room shut down a thousandfold, but never like that." },
        } },
    } },
    { who = "Specter of Helya", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1370037, text = "I grow weary of your presence! Tell Odin that this changes nothing! He will suffer my wrath for ages to come!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1370036, text = "Vapefus, you weak fool! Your torment will be unending!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370032, text = "So this is the champion of Odin! Let them die by Odin's own blades! I bless these weapons with the fury of Helheim! Go Vigfus! Slay the champion and earn my favor for all eternity!" },
        } },
    } },
    { who = "Spellblade Aluriel", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1349116, text = "YOU SHOULD HAVE THOUGHT BETTER OF CHALLENGING ME!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1349108, text = "I let you strike first, and that's the best you can do?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1349109, text = "A gallant attempt, but a vain one." },
            { id = 1349106, text = "Entire armies have fallen by my sword. What chance could you possibly have against me?" },
            { id = 1349117, text = "Such a shame. I had hoped for a proper challenge." },
            { id = 1349110, text = "Unworthy! A waste of my time!" },
            { id = 1349107, text = "Well done. I trained those guards myself. They are not easily bested. I suppose you merit the honor of facing me. Strike at your leisure. As a courtesy, I grant you the first blow." },
            { id = 1349111, text = "Where's the fun in so easy a kill?" },
        } },
    } },
    { who = "Spirit of Torga", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1923362, text = "I am here. What is it you seek?" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1923364, text = "Destroy the camps surrounding my corpse to weaken Xiong'o." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1923365, text = "May fortune favour you mortals, and thank you." },
            { id = 1923363, text = "Princess Talanji, the Blood Trolls power jungle with my remains." },
        } },
    } },
    { who = "Spirit of Ursoc", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1384635, text = "Vile beasts of the nightmare, you will never take my claws!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1384637, text = "I thank you, druids. These abominations of nightmare are relentless. They will stop at nothing to snatch the claws from my lair." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1384643, text = "Protect our Healers and Casters, Guardian. We must not let our allies fall." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1384641, text = "These foes are weak, but fight in numbers. In life, I paid the price for underestimating my enemy. Never again." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1384646, text = "Control the enemies. You can determine where they fall." },
            { id = 1384642, text = "Creatures of the wild, heed my call. Come to our aid!" },
            { id = 1384644, text = "Keep it up, Defenders! We will never yield to these invaders!" },
            { id = 1384648, text = "The heart of the bear never falters! Hold the line, hero!" },
            { id = 1384645, text = "Their blood will burn the very ground where they fall. Don't let them touch our defenders!" },
            { id = 1384647, text = "We were! The Nightmare's corruption has spread to the trees!" },
            { id = 1384640, text = "Worthy you may be, but if you would wield my claws to defend this world, you must make haste to retrieve them. Even now, I sense more of the enemy approaching." },
        } },
    } },
    { who = "Spirits", tier = "creature", ctype = "Undead", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 626259, text = "AHHH!" },
            { id = 626237, text = "NO!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 626283, text = "Ow, Ow, Ow, ow" },
        } },
    } },
    { who = "Spiritwalker Ebonhorn", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1274558, text = "Let me know when you are ready to continue, champion." },
            { id = 1274568, text = "Our people need a leader like home, one with the strength and courage to face any obstacle, qualities you have proven to possess." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1274861, text = "I will await you in a lot on the Southwestern Bluff. I advise against delay." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1274550, text = "Welcome, my friends, to the Vault of Neltharion, or as the world came to know him, Deathwing." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1274606, text = "A champion arrives in our most dire hour. Welcome." },
            { id = 1277296, text = "For generations, the Tauren of this mountain fought. Countless lives, even entire tribes, were lost." },
            { id = 1274540, text = "For home, the War of the Ancients did not end at the Well of Eternity. With the Legion defeated, he focused on the monster that got away." },
            { id = 1274556, text = "Is it wise to wait in a field of ettins?" },
            { id = 1274552, text = "No rush, champion. We are just in the middle of a field of ettins. I am sure nothing bad could possibly happen." },
            { id = 1277298, text = "Once, upon returning from such a battle, Holm Highmountain found his people slaughtered by a previously unknown foe." },
            { id = 1274554, text = "We should really keep moving." },
        } },
    } },
    { who = "Spiritwalker Quura", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2021825, text = "HAAH!" },
            { id = 2021826, text = "HUAGH!" },
            { id = 2021828, text = "HYAAAGH!" },
            { id = 2021827, text = "VAAAGH!" },
            { id = 2021823, text = "YEAH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1985545, text = "I... was... right..." },
            { id = 1985549, text = "I've heard bad things about the Alliance. Let's stay away from them." },
            { id = 1985547, text = "Let me get that!" },
            { id = 1985544, text = "Oh no, they're here!" },
            { id = 1985548, text = "This will help!" },
        } },
    } },
    { who = "Spiritwalker Ussoh", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2921732, text = "I saw a vision of Bane. He was imprisoned. Suffering. Surrounded by enemies." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 2911951, text = "Greetings young one." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2921733, text = "A figure emerged from the shadows, angry, vengeful, the Warchief." },
            { id = 2911820, text = "Focus on the smoke as it swirls around you. Let it fill you and lighten your spirit." },
            { id = 2911949, text = "Honor the spirits." },
            { id = 2921735, text = "The spirits whisper that this vision will come to pass before the next sunrise." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2911948, text = "Ancestors guide you." },
            { id = 2911821, text = "Breathe in and out." },
            { id = 2911898, text = "Isahi, Akule. We must make haste to Thunder Bluff. Our champion will aid Bloodhoof Village." },
            { id = 2911819, text = "Light the incense, then center yourself and slow your breathing." },
            { id = 2921734, text = "She spoke but a word, and Bane's life flickered out." },
        } },
    } },
    { who = "Sporebatrock", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5012376, text = "Thank you for watching!" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 5012380, text = "AHHH!" },
            { id = 5012378, text = "PFFTTT!" },
        } },
    } },
    { who = "Spriggan Caster", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3459944, text = "GET OUT OF HERE!" },
            { id = 3459943, text = "GET OUTTA HERE!" },
            { id = 3459952, text = "WHY ARE YOU BOTHERING ME?!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3459946, text = "Good! Now leave!" },
            { id = 3459954, text = "Make it quick!" },
            { id = 3459950, text = "Yeah? What do you want?" },
        } },
    } },
    { who = "Spriggan Melee", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3459803, text = "GET OUT OF HERE!" },
            { id = 3459811, text = "WHY ARE YOU BOTHERING ME?!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
