    { who = "Sprinkle Noggenfogger", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 6180544, text = "HEY! HEY! HELP ME! PLEASE!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 6179544, text = "Until next time!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6180755, text = "Heave! Back up and pull it down!" },
            { id = 6179538, text = "I'm happily married!" },
            { id = 6179590, text = "See you real soon!" },
            { id = 6180545, text = "What happened? What were all those bandage monsters? Where's Marin?" },
