        { name = "Conversation", family = "Feelings", lines = {
            { id = 610395, text = "Ha Ha Ha ha" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 610365, text = "AAA!" },
            { id = 610367, text = "HAAA!" },
        } },
    } },
    { who = "Sprucecrown", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5328598, text = "Clarel, my dearest friend, you have helped me to tend this most sacred grove for as long as I can remember." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5328603, text = "I was asked by Merithra to care for this massive sapling. After it blooms, I can stretch into a moist hollow and truly relax." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5328616, text = "Come with me. We will encourage the plants to thrive around Aamir Drusil." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 5328599, text = "Our ritual will not be stopped. Life may be fragile, but it is resilient." },
            { id = 5328602, text = "The thorns have been pulled out, and now a dream-sattling grows. Let us continue the ritual." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5328615, text = "A mere dracil thrives under our attention. Bless you for your help, young ones." },
            { id = 5328607, text = "A perfect day to help the forest grow around a meadrasil, don't you think?" },
            { id = 5328609, text = "Hmm. New life comes from old. Find some mulch for a dream sapling." },
            { id = 5328618, text = "Once, I fell asleep in the nesting grounds of a flutter of fairy dragons. They nested upon me for a season and coated my leaves with dust." },
            { id = 5328612, text = "Pick a dream fruit, young ones." },
            { id = 5328611, text = "The magic within the Dreamfruit will fill you with power and seeds." },
            { id = 5328610, text = "This magical dream fruit will help you with my tasks. Take a bite and drink deep of the juice." },
        } },
    } },
    { who = "Squallshaper Auran", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
