    { who = "Stabby Lottie", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1980783, text = "HIYAH!" },
            { id = 1980785, text = "YEAH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1959969, text = "Captain! The doohick has detected enemies nearby! Time to break out my good knives!" },
            { id = 1959968, text = "Fix the fires! Fix the explosions! Pfft! Slave drivers!" },
            { id = 1959965, text = "Gonna stab ya!" },
