    } },
    { who = "Stage Manager Huberta", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5858999, text = "I don't remember them attending rehearsal. Show them out." },
            { id = 5858994, text = "I think they want a spotlight. Make it clear they are not getting one." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5859000, text = "Down in front. Do something about those pebble brains." },
            { id = 5858997, text = "Give our actors a hand. They need all the support we can give." },
            { id = 5859002, text = "Imagine how these props will look with just a bit more polish." },
            { id = 5858998, text = "It isn't a show without the cast and the crew. Help them out." },
            { id = 5858993, text = "Soon they'll outnumber our audience. Give them a graceful exit. Quickly." },
            { id = 5858990, text = "the market draws a crowd on its own. If we assist them, their customers might stay for the show." },
            { id = 5858995, text = "This has gone on long enough. Get them to be quiet." },
            { id = 5858996, text = "We cannot let our audience be louder than the show!" },
            { id = 5858992, text = "We need a pair of deft hands for this task." },
            { id = 5859001, text = "We've been rehearsing for just this moment. Time to seize it." },
        } },
    } },
    { who = "Star Augur Etraeus", tier = "character", groups = {
        { name = "Victory", family = "Fighting", lines = {
            { id = 1349190, text = "Held to the majesty of the stars, you are nothing less than nothing." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1349187, text = "As the stars wax, so your lives wane!" },
            { id = 1349189, text = "Could we hope to resist? Can you?" },
            { id = 1349182, text = "If only you knew what lay beyond." },
            { id = 1349192, text = "Is that not enough? Must I show you the true horror of our reality?" },
            { id = 1349186, text = "No mortal may abrogate the precepts of fate!" },
            { id = 1349184, text = "See for yourself the cruel frozen void that lies beyond the margin of Azeroth's skies!" },
            { id = 1349183, text = "Such insolence. Very well. I shall show you!" },
            { id = 1349188, text = "The Burning Legion, slayers of whole worlds!" },
            { id = 1349185, text = "The stars align! Fear their portents!" },
            { id = 1349193, text = "Very well. Witness what I have seen and tremble!" },
            { id = 1349191, text = "What meagre petulance. I expected more from you." },
        } },
    } },
    { who = "Steelbreaker", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 560909, text = "SO FRAGILE AND WEAK!" },
            { id = 560902, text = "THIS MEETING OF THE ASSEMBLY OF IRON IS ADJOURNED!" },
            { id = 560920, text = "YOU WILL NOT DEFEAT THE ASSEMBLY OF IRON SO EASILY, INVADERS!" },
