        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 560913, text = "AHHH!" },
            { id = 560908, text = "OOF!" },
            { id = 560911, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 560919, text = "Flesh! Ha ha! Such a hindrance!" },
        } },
    } },
    { who = "Stellagosa", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1243343, text = "I overestimated my strength. All of the dragons, even the aspects themselves, have been greatly weakened since the fall of Deathwing." },
            { id = 1243325, text = "I see enemies coming in from the lagoon." },
            { id = 1243337, text = "My grandfather is the last among us that clings to any magical power. Do you really want him to expend it all on this Tidestone?" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1243323, text = "Get up, brother. Wake up!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1243339, text = "Your allies may stay here in the Repose while you help the whelplings." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1270830, text = "I'm glad you're here. I can tell you'll help." },
            { id = 1243333, text = "No, not you too!" },
            { id = 1243329, text = "Rest now, Grandfather. You must save your energy." },
            { id = 1243331, text = "They're attacking! We need reinforcements in the northeast!" },
            { id = 1243341, text = "You, Runus, what are you doing here?" },
        } },
    } },
    { who = "Steria Duskgrove", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 6119185, text = "I am here to help." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 6119293, text = "You're why people like animals better." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6119218, text = "Let me know if I can help." },
            { id = 6119241, text = "Peace be with you." },
            { id = 6119261, text = "The Kirin Tor need my aid." },
            { id = 6119271, text = "Till the next time we meet!" },
        } },
    } },
    { who = "Steve", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1365863, text = "FEED MY HUNGER, RICH!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1365861, text = "Pathetic! You're putting me to sleep! Here, let me return the favor." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1365875, text = "Ah, but I suppose we will reward our allies soon enough. Until then, I'll amuse myself by cleaning up their mess." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1365859, text = "Fester and die!" },
            { id = 1365882, text = "Ha Ha Ha ha! Another twig for the kindling!" },
            { id = 1365871, text = "Incompetent mortal filth! These nightborne can't even defend their own palace from invasion, if it were up to me!" },
            { id = 1365879, text = "Never trust a mortal to do a demon's work!" },
            { id = 1365873, text = "Show these pretenders how to fight!" },
            { id = 1365867, text = "The light has abandoned you." },
            { id = 1365869, text = "Underlings! Get in here!" },
            { id = 1365865, text = "Witness your end." },
            { id = 1365877, text = "You think getting past a few power-addled elves means you can stand against the true son of the Legion?" },
        } },
    } },
    { who = "Steward", tier = "character", groups = {
