        { name = "Conversation", family = "Feelings", lines = {
            { id = 6183982, text = "AIN'T SEEN NOTHIN' YET! Hehehehe" },
            { id = 6183978, text = "Bag up this trash!" },
            { id = 6183904, text = "Gallywix couldn't whoop you little hooligans? Ha ha! I'll show him how he did it in my day." },
