    { who = "Stone Fiend Ser Vant", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3461320, text = "I can't believe it! I lost!" },
            { id = 3461315, text = "I don't get them." },
            { id = 3461322, text = "I got him! I got him!" },
            { id = 3461318, text = "I regret nothing! Wait, no, everything!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3461321, text = "Don't tell my boss about this!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3461323, text = "Everybody stay back! I can take them!" },
            { id = 3461316, text = "If you rebuild me, make my arms huge!" },
            { id = 3461324, text = "I'm really quite busy!" },
            { id = 3461313, text = "Master? Is that you?" },
            { id = 3461317, text = "No, not my wings!" },
            { id = 3461314, text = "What fleshy thing creeps close?" },
            { id = 3461319, text = "Yeah, well, maybe... I wanted this!" },
