    } },
    { who = "Stoneblood Harpy B", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1377630, text = "BEHOLD MY CURSE!" },
            { id = 1377626, text = "FLEA THE FLESH AND SCATTER THE BONES!" },
            { id = 1377633, text = "RIP THE FLESH FROM ITS BONES!" },
            { id = 1377631, text = "THIS LAND IS Ours!" },
            { id = 1377624, text = "WE WILL NOT BE STOPPED!" },
            { id = 1377627, text = "YOU CANNOT ESCAPE THE CURSE!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1377629, text = "Ahh! Curse you!" },
            { id = 1377625, text = "Flesh and bone to earth and stone!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1377632, text = "Ha! I'll tear you apart!" },
            { id = 1377623, text = "The Witch Mother commands it!" },
        } },
    } },
    { who = "Stoneborn Assassin", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3461941, text = "First you die, then you suffer!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3461931, text = "A... good... fight..." },
            { id = 3461939, text = "Meet death with dignity!" },
            { id = 3461935, text = "So, my watch... ends!" },
            { id = 3461938, text = "Such is your end!" },
            { id = 3461934, text = "To stone, I return!" },
            { id = 3461940, text = "Your time has come!" },
        } },
    } },
    { who = "Stoneborn Destroyer", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3461774, text = "I have wares of war for trade." },
            { id = 3461769, text = "I was carved ages before your kind learned to speak." },
            { id = 3461776, text = "My honor for Revendreth." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3461772, text = "Flotsam of the Battlefield!" },
            { id = 3461771, text = "I've scrounged a few wares for sale." },
            { id = 3461768, text = "Know that your continued behavior is nothing new or original, and you should feel bad about yourself for trying!" },
            { id = 3461775, text = "Need something destroyed?" },
            { id = 3461773, text = "What are your requirements?" },
            { id = 3461778, text = "What news do you herald?" },
            { id = 3461770, text = "When you die, make sure it is on your feet, weapon in hand, smile on your face, and among the corpses of your enemies." },
        } },
    } },
    { who = "Stoneborn Guard", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3461513, text = "A WARRIOR'S... END... Go!" },
            { id = 3461508, text = "ALL IS DUST!" },
            { id = 3461516, text = "ALL MIRRORS MUST BE SHATTERED!" },
            { id = 3461512, text = "WELL. THOUGHT. IRRELLLLLLL" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3461510, text = "I am free, El." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3461518, text = "Misguided fool! You are but a tool of greater powers!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3461514, text = "For the honor... of Revendreth..." },
            { id = 3461515, text = "For the Master." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3461517, text = "Ignorance cannot excuse your allegiance!" },
            { id = 3461509, text = "In defeat, we still... Fly..." },
            { id = 3461511, text = "To stone I return." },
        } },
    } },
    { who = "Stoneborn Quest Boss", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3593519, text = "I will tear your flesh from your bones!" },
            { id = 3593516, text = "My eyes may close, but more take my place." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3593518, text = "AHHH! You... ...possess more strength... ...than... ...I imagined." },
            { id = 3607817, text = "The master awaits the accuser and the maw walker." },
            { id = 3593517, text = "You dare step foot in Revendreth?" },
            { id = 3593515, text = "You reek of Kyrian filth!" },
        } },
    } },
    { who = "Stonehead", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3533625, text = "Bring Snap next time!" },
            { id = 3533624, text = "Don't be bad, bud." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3533621, text = "Fine! Me not lonely!" },
            { id = 3533623, text = "I... am... my... best bud." },
            { id = 3533629, text = "Looking for me?" },
            { id = 3533631, text = "Ooh, paper got fancy stamp. In big words." },
            { id = 3533622, text = "Rock's been busy today." },
            { id = 3533627, text = "You good bud, or bad bud?" },
            { id = 3533630, text = "You not bad, bud. You good, bud." },
        } },
    } },
    { who = "Stormcaller Brundir", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 561077, text = "GAH!" },
            { id = 561081, text = "RRR!" },
            { id = 561075, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 561087, text = "Whether the world's greatest gnats, or the world's greatest heroes, you are still only mortal." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 561094, text = "HA!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 561076, text = "AAARGH!" },
            { id = 561073, text = "AHEM!" },
            { id = 561078, text = "GAAAH!" },
            { id = 561074, text = "HYAH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 561080, text = "This meeting of the Assembly of Iron is adjourned!" },
        } },
    } },
    { who = "Stormcaller Mylra", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370446, text = "Here! That demon must have crawled this way! There's fell blood splattered on the stones!" },
            { id = 1370447, text = "Imps! Get Zoom as they summonin' these little buggers!" },
            { id = 1370337, text = "It's a massacre out there! All around the world, our forces fall back!" },
            { id = 1370432, text = "Keep your eyes on Thrall! He's wounded! He's likely to kill himself down here! And I don't want to be the one who has to tell his wife!" },
            { id = 1370445, text = "Look! There he is!" },
            { id = 1370336, text = "Over here, shaman! We've no time to lose!" },
            { id = 1370444, text = "That damn hammer fell somewhere below! Hold on! This part always gives me tummy to wobblies!" },
            { id = 1370339, text = "The greatest shaman in the world, Orgarro Imbello. What's left of him, that is." },
            { id = 1370369, text = "The Highlands are completely overrun! The clan is scattered!" },
            { id = 1370370, text = "They followed us here!" },
            { id = 1370338, text = "Unless we find a way to turn this around, Azeroth will fall!" },
        } },
    } },
    { who = "Stormguard Gorren", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5769614, text = "MY FELLER, YOU RUIN!" },
            { id = 5769609, text = "YOU NEVER DESERVE TO BE STORMWORD!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5769610, text = "I command this rookery, by right!" },
            { id = 5769612, text = "Know my might!" },
            { id = 5769611, text = "My strength prevails!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 5769613, text = "Crushed by my power!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5769616, text = "Feel my blessing!" },
            { id = 5769615, text = "Share in my gift!" },
            { id = 5769619, text = "The invaders are vanquished my duty done" },
            { id = 5769618, text = "The might of my hammer!" },
            { id = 5769607, text = "The title, the glory! It should have been mine, Belkrim!" },
            { id = 5769617, text = "Your death is my directive!" },
        } },
    } },
    { who = "Stormrider Adalar", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5705324, text = "Fly high, strike true!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5859367, text = "Back to it, then. Whatever it is." },
            { id = 5705321, text = "Back to work then. Or not." },
            { id = 5859365, text = "Come back later and bring me a Cinder Brew?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5705325, text = "Hm? Yes? I'm a little busy." },
            { id = 5859366, text = "May your path be forthright." },
            { id = 5859369, text = "Other than enjoying the finer things, I've not found my path." },
            { id = 5705328, text = "The only thing I don't like are these static-filled feathers everywhere on my clothes!" },
            { id = 5705327, text = "We fly to protect Dornagal." },
            { id = 5859368, text = "Work cycle enthusiastically paused." },
        } },
    } },
    { who = "Stormrider Gurnot", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5705372, text = "Fly high, strike true." },
            { id = 5859385, text = "My directive is to protect the Unbound." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5706795, text = "Back to flying!" },
            { id = 5859386, text = "Find your path, whatever it is." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5705373, text = "Are you in need of a Stormrider's aid?" },
            { id = 5705370, text = "Eyes on the skies!" },
            { id = 5859383, text = "Have you ever felt your path led to something greater?" },
            { id = 5705375, text = "I'm not a dwarf in disguise, I promise ye!" },
