    { who = "Stormrider Vokmar", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5858472, text = "Thank the titans you are here. The storm perch has been breached and the storm riders, corrupted." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5706772, text = "Fly high, strike true." },
            { id = 5858470, text = "I do not like that it feels darker and colder as we go down. But there are more survivors to rescue." },
            { id = 5706777, text = "I protect, I attack, and then I need ore snacks." },
