            { id = 5858404, text = "Finally, I thought I'd have to fight Goron on my own." },
            { id = 5858473, text = "Hurry! If we free these Stormrooks, we can fly there and try to end this madness." },
            { id = 5706776, text = "The Storm Rider's directive is to protect." },
            { id = 5858471, text = "What is that orb? It's radiating dark energy, and it's affecting the storm rocks." },
