    { who = "Stormspeaker Qian", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3176208, text = "As you have seen, the mantid have begun to swarm." },
            { id = 3184832, text = "Halt, outsider! Your kind are not welcome here." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3176209, text = "I did not realize they had grown so bold as to invade Mogoshan vaults." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3176211, text = "The rise of their new Empress must have spurred them to action." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3149991, text = "An empowered mounted swarm under N'Zoth's control would be a deadly threat. We must keep them in check." },
            { id = 3184868, text = "As you command, Highkeeper." },
            { id = 3176212, text = "Meanwhile, our scouts report that a massive Mogu army is assembling in the north, in numbers not seen since the days of Lei Shen." },
            { id = 3195817, text = "Safeguard the Veil." },
            { id = 3195818, text = "The other clans must see reason." },
            { id = 3184834, text = "The Speaker, what is the meaning of this?" },
            { id = 3176210, text = "This is far too early for another cycle to begin." },
            { id = 3176213, text = "With the attention of the Golden Lotus Divided, the Mogu clearly see an opportunity to conquer the Vale and subjugate everyone within." },
        } },
    } },
    { who = "Stormward Baelgrim", tier = "character", groups = {
