    { who = "Sulthis", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2019868, text = "I can only hope I've hidden my key well enough so that you are the only one to find it." },
            { id = 2000363, text = "Together, with Vorrik and Korthak, we sealed the tomb with the hopes that no one would ever wake the giant buried within. We will not be doomed to repeat the mistakes our neighbors made so long ago." },
            { id = 2000366, text = "Vorik, if you are receiving this message, then I fear I was too late. Korthik has betrayed our people and plans to break the barrier we placed on the tomb long ago." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2000365, text = "I shall inform Vorik of my concerns, but first, I must safeguard my key. I have a feeling something bad will happen. Very soon." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2000362, text = "The city has fallen. Nothing was left in the wake of the battle between Sethralis and Mithraks. Our Loa gave her life to keep us safe, and we will not let that sacrifice be in vain." },
        } },
    } },
    { who = "Summoned Voidwalker", tier = "character", groups = {
