    { who = "Sunbringer Firasi", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1984533, text = "BE HEALED BY THE LIGHT!" },
            { id = 1984532, text = "I'VE GOT YOU!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1984536, text = "Ah, the Alliance, and I was having such a good day. Care to improve it by leaving now?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1984534, text = "Alliance, the Light has granted us this island. Leave before blood is shed. This is your final warning." },
            { id = 1984528, text = "Into the fray!" },
            { id = 1984531, text = "Light bless you." },
            { id = 1984529, text = "The enemy is upon us!" },
            { id = 1984530, text = "The light will guide me back." },
            { id = 1984535, text = "This island is ours, Alliance. Violence will not be necessary if you abandon it." },
            { id = 1984537, text = "You fought well. I fought better." },
        } },
    } },
    { who = "Sundered Pillager", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4955709, text = "For Sakuret! For the sanded flame!" },
            { id = 4955712, text = "Our crush is the strongest!" },
            { id = 4955717, text = "These ruins are ours. This island is ours!" },
