    { who = "Suntender Heart", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 900009, text = "HA UGH!" },
            { id = 900005, text = "HAAAH!" },
            { id = 900003, text = "HUH GAAAHHH!" },
            { id = 900007, text = "HUUU!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 899997, text = "You will suffer from our failure!" },
