    { who = "Supervisor Radlock", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5835581, text = "I ain't payin' you to stand around. Check out that disturbance or you're fired!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 5835584, text = "Hey, what's going on in here?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5835546, text = "Is everybody on a break or something? Drop those mugs and go see what's going on!" },
            { id = 5835587, text = "Looks like you should have brought some bigger friends." },
            { id = 5840410, text = "Pack it up, team! I know when we're beaten." },
            { id = 5835578, text = "What was that? You with the... What is that on your face? Oh, get out of my sight and do your job!" },
            { id = 5835542, text = "You and you! Get out there and stop them!" },
        } },
    } },
    { who = "Surgeon Stitchflesh", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3533111, text = "I will fix your flaws!" },
            { id = 3533109, text = "My constructs can handle you on their own!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3533116, text = "Another exquisite creation!" },
            { id = 3533112, text = "Away! These are my creations!" },
            { id = 3533114, text = "I'll have you in STITCHES!" },
            { id = 3533113, text = "Imbecile! I'm the one who made you!" },
            { id = 3533108, text = "Just a moment longer. It seems that the parts for my new creation have arrived at last!" },
            { id = 3533115, text = "Oh, I'm awfully proud of this one!" },
            { id = 3533110, text = "Your flesh holds such potential!" },
        } },
    } },
    { who = "Surigosa", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5015177, text = "I want to know why you are doing this. Why would you try to recreate something so horrid?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5023776, text = "I can help you look after the Nexus if you want to start to come here." },
            { id = 5015162, text = "I see your intuition was correct, Azoragos. Here comes Kalecgos' mortal now." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5015174, text = "Kalecgos... Oh, bless it all!" },
            { id = 5015168, text = "No, Kalecgos. The mortal must go alone." },
            { id = 5015169, text = "Our presence will merely exacerbate the situation. She will feel more threatened. We are breaking the cycle, yes?" },
            { id = 5023672, text = "Perhaps all of this chaos was their only way of getting our attention. Wildly lashing out, hoping someone would hear them." },
            { id = 5015167, text = "Quiet your steps, mortal. Lest you spook their leader." },
            { id = 5015165, text = "You lead our flight, Kalecgos. We will do things your way. Let us hope your peaceable solution does not end buried under the corpses of dragons." },
        } },
    } },
    { who = "Suura Swiftarrow", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2739846, text = "Well fought, champions! You have struck fear into the hearts of the Horde!" },
