            { id = 1244139, text = "No matter. Soon you will witness the birth of a new age." },
            { id = 2002781, text = "Oh, I know you won't." },
            { id = 897348, text = "Oh, you're still here? I had kind of hoped you had perished. You would make a very attractive corpse." },
            { id = 2002770, text = "Or perhaps, you will have a chance to say hello to your son." },
            { id = 1801007, text = "Serve me well, and you will be rewarded." },
            { id = 4081163, text = "Suffer my wrath!" },
            { id = 4080416, text = "Surrender your sigil, or the wildseeds will perish." },
            { id = 2062637, text = "Take their hope and you will claim victory for the Horde!" },
