            { id = 897342, text = "She's attacking the towers again!" },
            { id = 5225424, text = "Shurele-Oram, my friend." },
            { id = 2002766, text = "So good of you to finally show up, High Overlord." },
            { id = 2429532, text = "so he can slaughter them in their sleep." },
            { id = 2108688, text = "Soldiers, no! Do not rush the-" },
            { id = 1801001, text = "State your business to your Warchief." },
            { id = 3698368, text = "Such a narrow vision. You disappoint me." },
            { id = 561222, text = "Taranis had a son named Arthas." },
            { id = 2736330, text = "Thank you for your honesty." },
            { id = 4327514, text = "That is yet to come." },
            { id = 2002720, text = "That night elf commander is testing my patience. Break her!" },
            { id = 2108674, text = "That ship must have come from Darnassus, which means..." },
            { id = 2002738, text = "That should quell their appetites. For a while, at least." },
            { id = 1243488, text = "The Alliance will be upon us soon, and we have nowhere to run." },
            { id = 4093251, text = "The archer does not mourn the loss of their arrows, high lord." },
            { id = 4075661, text = "The battle is almost upon us." },
            { id = 4322888, text = "The cycle must be broken." },
            { id = 4324001, text = "The jailer did not control me." },
            { id = 4324764, text = "The jailer is using Anduin to bolster his ranks!" },
            { id = 1801000, text = "The lifeblood of Azeroth belongs to the Horde." },
            { id = 4081168, text = "The Maw devours everything!" },
            { id = 4081169, text = "The Maw will claim you!" },
            { id = 4081161, text = "The past shackles you!" },
            { id = 4322891, text = "The true battle lies ahead." },
            { id = 1248735, text = "There are so many of them!" },
            { id = 2429533, text = "There can only be victory or death for us, Spain." },
            { id = 2736333, text = "There is no place for weakness in our ranks." },
            { id = 2108686, text = "There will be nowhere to run when next we meet, Malfurion." },
            { id = 3084079, text = "They will learn the truth along with all the rest." },
            { id = 4080418, text = "This ends now." },
            { id = 2002752, text = "This is no time for sentiment, High Overlord!" },
            { id = 573172, text = "This isn't how it's supposed to end." },
            { id = 4080414, text = "To the skies, strike at the heart!" },
            { id = 561226, text = "To those who would question our place in this world!" },
            { id = 2108669, text = "To Zorumgar! Quickly!" },
            { id = 4081774, text = "Vengeance is mine!" },
            { id = 561263, text = "Very well, Warchief. I have solved the plight of the Forsaken." },
            { id = 4081777, text = "Very well. Death it is!" },
            { id = 1248709, text = "Vol'jin! Pull him back! Keep your lines steady! We have to hold!" },
            { id = 2002753, text = "War demands that we take a more direct approach." },
            { id = 561229, text = "Warchief! So glad you could make it!" },
            { id = 2108696, text = "We advance as the fires continue to burn." },
            { id = 4322895, text = "We live in prisms of our own making." },
            { id = 2108682, text = "We must stay the course for now." },
            { id = 2120267, text = "We pass through the wall on my command!" },
            { id = 561258, text = "We watched as our homes were razed to the ground." },
            { id = 1800996, text = "We will bring the Alliance to its knees." },
            { id = 1800999, text = "We will claim what is ours." },
            { id = 2108663, text = "We will squeeze Malfurion from both sides." },
            { id = 1248866, text = "We'll never bow to you!" },
            { id = 1248672, text = "We'll take the ridge and cover your flank." },
            { id = 4080410, text = "Well?" },
            { id = 2002765, text = "We're almost there! Make haste, heroes!" },
            { id = 1244135, text = "What have we here? Another one of Greymane's mercenaries?" },
            { id = 1782211, text = "What have you to say, Chieftain?" },
            { id = 1993353, text = "What say you, champion? Are you prepared to pursue a new ally?" },
            { id = 2108702, text = "When I sent you on this mission, I did not foresee this outcome." },
            { id = 2108693, text = "Where did you fly away to, little bird?" },
            { id = 561269, text = "Where is that ogre-headed buffoon?" },
            { id = 4496030, text = "Why are you here, Andwan?" },
            { id = 2108681, text = "Wildbend River is locked in a stalemate, and Malfurion knows it." },
            { id = 2575609, text = "Yes, it is beyond time we did." },
            { id = 897346, text = "You do realize we are directly below it, right?" },
            { id = 4496034, text = "You fear you might not be who you thought you were." },
            { id = 2429536, text = "You should be grateful." },
            { id = 2068242, text = "You were the right arrow for the shot, champion." },
            { id = 4081138, text = "Your lives end here!" },
            { id = 3587735, text = "Your skills come highly recommended. I will make use of them." },
            { id = 2736329, text = "Zelling." },
            { id = 4081165, text = "Zovaal will not be denied!" },
        } },
    } },
    { who = "Sylvar Artisan", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3446622, text = "as the Queen wills it." },
            { id = 3446618, text = "Is it time to go already?" },
            { id = 3446612, text = "Now where did I put that?" },
            { id = 3446616, text = "The queen watches over us." },
        } },
    } },
    { who = "Sylvar Caretaker", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3430050, text = "May your spirit know peace." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3430046, text = "All things in balance." },
        } },
    } },
    { who = "Sylverin", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1405298, text = "Pardon me, do you have a death wish?" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1405299, text = "I strongly advise against that." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1405300, text = "Don't be daft! Move away from there!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405308, text = "It was my pleasure." },
            { id = 1405302, text = "Oof! Get away from there!" },
            { id = 1405306, text = "Relax, have a beverage." },
            { id = 1405301, text = "What inspired such idiocy? Nightwell energy is intensely volatile in this state!" },
            { id = 1405307, text = "You need only alert me to your needs." },
        } },
    } },
    { who = "Syrana Starweaver", tier = "character", groups = {
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1405313, text = "The Moon God will soon be no more." },
            { id = 1405556, text = "The Moonguard are no more. There is no saving our beloved stronghold." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1416007, text = "Alune Aurine Tourelle" },
            { id = 1405558, text = "For Nightborne deceived us. The Moon God will soon be lost forever." },
            { id = 1405314, text = "It is my duty to guard this keep to the end." },
            { id = 1405320, text = "Lothrius's magic called to me. He must still be alive. Quickly, you can help us rejoin the others." },
            { id = 1405312, text = "Our demise came without warning." },
            { id = 1405316, text = "We are beaten. Only memory remains." },
            { id = 1405318, text = "We will move when the way is clear. Your bravery is worth more than you know, friend." },
        } },
    } },
    { who = "Tacha", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4643060, text = "I can't wait to climb them!" },
            { id = 4661194, text = "I suggest we keep moving." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4625926, text = "Don't forget to look behind the waterfalls!" },
            { id = 4625925, text = "Let's meet up later, okay?" },
            { id = 4625929, text = "Wait till you hear what I found!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4625927, text = "Hey, uh, where've you been?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4625928, text = "Climbed any mountains lately?" },
            { id = 4625924, text = "Keep your eyes peeled and your ears perked up." },
            { id = 4625923, text = "Let me know if you find anything neat!" },
            { id = 4625930, text = "What are you up to today?" },
            { id = 4625931, text = "You wanna explore my claws close up?" },
            { id = 4643029, text = "You'll get plenty of pictures in the Dragon Isles! So many new species to document!" },
        } },
    } },
    { who = "Taelia", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1864201, text = "Well done! Looks like you have things under control." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1864196, text = "Stay low. They haven't spotted us yet." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1864197, text = "According to our intelligence, the keys that access the Azerite caches and the hostage wing are kept by the Overseer, around his neck." },
            { id = 1864203, text = "It seems Lady Ashvane will have an opening for a new Overseer after all." },
            { id = 1864204, text = "Now that we have the prison under our control and the keys in our possession, we can begin securing the Azerite and releasing the hostages." },
            { id = 1864199, text = "That creature must be why the Overseer didn't have many patrols on this side of the island. Good job defeating it." },
            { id = 1864200, text = "Ugh! You had to crawl through this stuff to escape! Try to stay downwind from me!" },
            { id = 1864202, text = "We'll finish securing the lower levels while you make your way to the Overseer." },
            { id = 1864198, text = "We'll secure the perimeter guards while you make your way to the sewer grate. It should still provide a way into the prison." },
            { id = 1864205, text = "You do good work, for an escaped fugitive." },
        } },
    } },
    { who = "Taelia Fordragon", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3718396, text = "I could make out the Lord Admiral's voice, and what must have been Thrall's as well. Their cries. They chilled me to the bone." },
            { id = 3706271, text = "I haven't asked a single thing of you since I was the little girl. The little girl you sent away." },
            { id = 3706270, text = "I journeyed all the way to the realms of death to meet the father I thought was lost to me. Volvar Fordragon, one of Azeroth's bravest heroes." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3616956, text = "All this time you knew my father was alive but you didn't tell me!" },
            { id = 3724343, text = "Anduin's still captive there. Has something happened to him, father?" },
            { id = 3706272, text = "But I'm asking you this, tell us if they are still alive." },
            { id = 3615880, text = "Did you say Bolvar? Bolvar Fordragon? That's my father, is he alive?" },
            { id = 3724344, text = "Father, resist him! Do not let him win!" },
            { id = 3706268, text = "Please father, we need to know if our friends can still be saved." },
            { id = 3615874, text = "Right now, I don't give a damn about justice. I just want to find where she's taken our friends. King Greymane, what's the plan?" },
            { id = 3616961, text = "We? Anduin knew too, didn't he? The king told me story after story about my father as if he were some long dead hero of the past. But the whole time, Anduin hid the truth." },
            { id = 3616963, text = "Well, you were wrong. Now I know my father is alive, free from that damned helm, and no matter what it takes, I will go to his side." },
        } },
    } },
    { who = "Taelloch Foreman", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5786167, text = "Don't... Speaker... Ringing... Don't... Let... Them... Destroy..." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5786164, text = "Can you hear it? The ringing. The ringing. It returns. The music is eternal." },
            { id = 5786162, text = "Change is coming, workers. Hoards of Skardin stir within the Hall of Awakening." },
            { id = 5786163, text = "Taaloc could be next. Barricade your doors, but be not afraid. We will press on." },
            { id = 5786165, text = "The itching... I can taste the sounds. Revelation awaits." },
            { id = 5786161, text = "The outcome was not what I expected. I have been altered, perhaps even chosen." },
            { id = 5786166, text = "The ringing, the ringing, will lock away deepest cavern for darkest memory." },
            { id = 5786159, text = "Workers of Taeloc, as your foreman, I have met with the High Speaker in secret." },
        } },
    } },
    { who = "Taerar", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1489549, text = "GAH!" },
            { id = 1489551, text = "GRRR!" },
            { id = 1489550, text = "RAWR!" },
            { id = 1489553, text = "ROAR!" },
            { id = 1489554, text = "UGH!" },
            { id = 1489552, text = "YEAH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1349965, text = "Children of Madness, I release you upon this world!" },
            { id = 1349976, text = "Peace is but a fleeting dream. Let the nightmare reign!" },
        } },
    } },
    { who = "Tahu Sagewind", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1390347, text = "I will begin the ritual. Focus your will upon the spirit while our friend keeps us safe." },
            { id = 1390345, text = "We have found you, and you have found the grave." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1388490, text = "I bid you welcome." },
            { id = 1390339, text = "I have some ability to speak with the long departed. We may be able to question the hero in this saga directly." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1390355, text = "Return to your rest and be disgraced no more." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1390357, text = "It was my honor to serve. I must go to Netherlight Temple and inform the Conclave of our success." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1388486, text = "Another time, then." },
            { id = 1388487, text = "We will meet again." },
            { id = 1390344, text = "You asked the Sunwalkers for aid, and I've come. May my presence bring success to your quest, Auric." },
        } },
    } },
    { who = "Tak Tak", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1383870, text = "I put you down here! Tack-Tack do what he do best! Nothing!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1383871, text = "Back to Turtle! This place too wet anyways." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1373724, text = "How's it jukin'?" },
            { id = 1383869, text = "Oh, you too late. Them Wobgobblers done took this place!" },
            { id = 1383867, text = "Okey-doke. Back to Pandaria. This place smells like turtle anyways." },
            { id = 1383868, text = "Pandaria lookin' real bad. Ain't seen this much gerb jobbing since that big orc guy duked up the veil." },
            { id = 1373725, text = "Pull me finger. Okay, no, wait. Uh, no, pull this one. Uh, okay, wait, wait. Uh, no, come back later. We try again." },
            { id = 1373720, text = "We done? Okey-doke." },
            { id = 1373723, text = "What you need!" },
            { id = 1373722, text = "Where we going?" },
        } },
    } },
    { who = "Tal Galan", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4080050, text = "Record keepers, return to the respite. You will be safe there." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4069945, text = "I admit there are so many theories to explore, so many discoveries to be made. No! I will not think of it! Begone, Broker! I need nothing from you!" },
            { id = 4080044, text = "I have assembled the message, starting it now." },
            { id = 4080084, text = "I understand, Bonesmith. Once the vault is opened, you can be on your way." },
            { id = 4080032, text = "I will meet you and our friend up ahead, Maw Walker. Purpose guide us." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 4080054, text = "If he confronted the Jailer, there may be nothing left of your master." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4069939, text = "Friend? The elusive Anari has no friends." },
            { id = 4069943, text = "One day, perhaps, if the purpose wills it." },
            { id = 4080052, text = "So it would seem, if we can locate more records, perhaps the answers will be found within them." },
            { id = 4080049, text = "That is all we have. If we can find additional records, I should be able to reconstruct more of the Primus's message." },
            { id = 4069941, text = "You more than most from what I hear. In fact, I imagine this conversation is merely a pretext for you to inquire what I know of Xerath Mortis." },
        } },
    } },
    { who = "Tal Inara Voice of the Arbiter", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3587826, text = "The anima drought has afflicted more than just bastion aspirant. As the Jailer's power grows, all the Shadowlands suffers." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3611403, text = "I will consider your words." },
            { id = 3555163, text = "I will see it done, eternal ones. With her voice have I spoken." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3555164, text = "Come, mortal. The hour of decision is at hand." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3611076, text = "Since that day, no soul has been judged. Instead, all are lost to the horrors of the Maw." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3555149, text = "As the Arbiter's voice, I heed the call of the Eternal Ones. How may I serve?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3587827, text = "A great darkness fell upon our blessed arbiter, plunging her into an unending slumber." },
            { id = 3611397, text = "All will be judged fairly." },
            { id = 3611394, text = "Blessed be her voice." },
            { id = 3611400, text = "One day, she will awaken." },
            { id = 3611388, text = "With her voice have I spoken." },
            { id = 3611391, text = "Your path is chosen." },
        } },
    } },
    { who = "Taldaram", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 561367, text = "AHHH!" },
            { id = 561364, text = "OH!" },
            { id = 561362, text = "UGH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 561365, text = "beg for mercy" },
            { id = 561379, text = "Ha, Ha, Ha, ha!" },
        } },
    } },
    { who = "Taldath the Destroyer", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1401300, text = "FOOL! YOU DARE FACE ME ALONE?!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1501376, text = "HA!" },
            { id = 1501375, text = "HMPH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1401305, text = "Varagus will hunt down every one of your disgusting ilk! Pity you won't be around to witness it!" },
            { id = 1401307, text = "Vermin! My lord wields power beyond your comprehension! He will end you!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1401310, text = "Your efforts mean nothing! Soon all of Suramar will bow to my master's will!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1401309, text = "The Twinblades will be your end." },
            { id = 1401298, text = "You would stand before me after so many of your kin have fallen! Release me now! And I may yet spare you." },
        } },
    } },
    { who = "Talgath", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1689142, text = "Let the hunt be finished! You are mine, prophet!" },
            { id = 1689138, text = "Your screams will echo through Antorus if they escape." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1689147, text = "I only hoped they would give you a reason to stay. How cold of you, leaving without your mate and child." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1392316, text = "Destroy them! Your blades thirst!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1689141, text = "A welcome change of pace, to be certain." },
            { id = 1689140, text = "How unlike you, villain, to stand your ground." },
            { id = 1689139, text = "Make way! I will deal with this myself!" },
            { id = 1689144, text = "Oh, how Kil'jaeden mourned for you. Do you know how deeply your departure wounded him?" },
            { id = 1689137, text = "Steal the pacifist, I see! Face me!" },
            { id = 1689143, text = "We will finish this another time!" },
            { id = 1689145, text = "You did not lose him, you gave it up! All of it! Your people, your planet, even your family!" },
        } },
    } },
    { who = "Tally Zapnabber", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1984483, text = "I got one! I got one!" },
            { id = 1984480, text = "I was right, you guys!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2015420, text = "Authentication code is one-niner-niner. Instrument alignment is outside acceptable parameters. Believe that. I can make this work. Sit tight. Over." },
            { id = 2015421, text = "Execute to follow. See that big red button? Yeah. Get clear of the area and do press the big red button. Execute when ready. Over." },
            { id = 1984478, text = "I'm not not not sure we should be doing this" },
            { id = 1984484, text = "Oh, Oh, Oh, high priority target!" },
            { id = 2015418, text = "Radio check. This is Alpha One. Address group Alpha Squadron. Do you read me? Over." },
            { id = 2015419, text = "Roger, yes, calibration complete. All of you must orient the instruments in very specific locations. Contact me when they're in place. Over." },
            { id = 1984482, text = "The Horde are here?! Are you guys sure about this? I mean, I have delicate instruments and they're expensive!" },
            { id = 1993329, text = "Um, ladies and gentlemen, rev those engines! Attack!" },
        } },
    } },
    { who = "Taloc the Corrupted", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1990735, text = "Additional fuel for rot." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1990731, text = "Activating Cudgel Retrieval." },
            { id = 1990728, text = "Fluid evacuation in progress. Entering stand-by." },
            { id = 1990734, text = "Fuel levels de-depleted. SHUTTING DOWN!" },
            { id = 1990733, text = "Hosts detected. Infection commencing." },
            { id = 1990730, text = "Initiating blood dispersal of target host." },
            { id = 1990732, text = "Initiating Plasma Collection" },
            { id = 1990729, text = "Levels at maximum. Resume collection." },
            { id = 1990736, text = "New candidate for corruption." },
            { id = 1990726, text = "Specimen Targeted for Destruction" },
            { id = 1990737, text = "Subjects primed for contamination." },
        } },
    } },
    { who = "Talon Damos", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4901583, text = "I would just as soon never set foot in a crash again." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4925748, text = "Ah, there is beauty in these ruins." },
            { id = 4925746, text = "Welcome to the squad. I'm Talon Deimos. I'm glad you're on our side." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4925745, text = "Emberthal and I fought together in the early days, though my memories are a bit hazy. Ten thousand years in stasis does that, I guess." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4901586, text = "Embeth all awaits you inside." },
            { id = 4901580, text = "Good, you're here." },
            { id = 4925747, text = "I'll meet you at the Reach. Best not to keep Scale Commander Emberthaw waiting, if you catch my drift." },
            { id = 4925749, text = "Maybe our past is worth saving." },
            { id = 4901589, text = "Oh, and, uh, thank you for aiding us." },
            { id = 4925750, text = "You should talk to Emberthol inside. I'll stay out here. This place makes me feel... claustrophobic. I'm sure you understand." },
        } },
    } },
    { who = "Talonkingikiss", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 561404, text = "YOU DIE! REK! STAY AWAY FROM TRINKETS!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 561402, text = "I just cut you, pretty! Rrroww! Slice you! Yesssssss" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 561400, text = "OOOHHH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 561399, text = "No escape for you." },
            { id = 561405, text = "You make war on IKISS?" },
        } },
    } },
    { who = "Talonstalker Kavia", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4679631, text = "I heard rumors you were here." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4667530, text = "Come then. Let us speak." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4679632, text = "Careful. I detect that some of the coal has been altered by Jaradin magic." },
            { id = 4671382, text = "He does what needs to be done. Honor and glory didn't help defeat the Shah or rid the world of mad dragons. Wrathion did." },
            { id = 4667526, text = "If you see anything strange, let me know." },
            { id = 4679630, text = "It is best you see the size of their defensive force for yourself." },
            { id = 4667529, text = "I've been keeping an eye out." },
            { id = 4671379, text = "I've never been one for taking prisoners, but new times call for new ways." },
            { id = 4667525, text = "Keep your secrets to yourself." },
            { id = 4667527, text = "The Black Talon are always loyal." },
            { id = 4667531, text = "This isn't the best way to make your mark on the world." },
        } },
    } },
    { who = "Talthis Tyrs Guard Exemplar of Order", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5226561, text = "A world without the Titan's influence. One pales at the thought." },
            { id = 5226424, text = "Be careful, Valinay! Help a champion!" },
            { id = 5226546, text = "Fortier in all things." },
            { id = 5226256, text = "It's luring you away from the beacon, away from us! Resist it, Valinay, for light's sake!" },
            { id = 5226556, text = "Study, practice, discipline. One must always strive to improve oneself." },
            { id = 5226541, text = "The Titans will guide you." },
            { id = 5226246, text = "Travard! Champion! Valene has fallen prey to a faceless one! I can't get through to her!" },
            { id = 5226550, text = "Walk always in the light." },
            { id = 5226313, text = "We have this in hand, Velenae. We will rally back at Tearhold." },
        } },
    } },
    { who = "Tandred Proudmoore", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 2124661, text = "HYAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2031479, text = "I will honor my father's legacy." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2031480, text = "We stand strong together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2031483, text = "Do the seas call to you as they call to me?" },
            { id = 2031482, text = "May the seas guide you home." },
            { id = 2031485, text = "That bloke in the red shirt over there told me I wasn't canon. Well, obviously! I'm a mariner, not a canon!" },
            { id = 2031484, text = "We will set things right." },
            { id = 2031481, text = "What do you ask of House Proudmoore?" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 2124659, text = "AHHH!" },
            { id = 2124658, text = "HEY!" },
            { id = 2124656, text = "HMM!" },
            { id = 2124660, text = "HWAH!" },
        } },
    } },
    { who = "Taoshi", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 644295, text = "HA!" },
            { id = 644307, text = "HEH!" },
            { id = 644303, text = "UGH!" },
            { id = 644305, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 800037, text = "Hero, it will be up to you to defeat the Storm Lord Nalak. You will have to marshal a small army." },
            { id = 800029, text = "My lord, you are gravely wounded!" },
            { id = 637421, text = "You are welcome among the Shadowpan." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 637431, text = "I would recommend against such actions." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 637425, text = "Ready for some action?" },
            { id = 637379, text = "Stay light on your feet." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 644333, text = "AHHH UGH..." },
            { id = 644337, text = "AHHH!" },
            { id = 644335, text = "OOOHHH!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 637423, text = "Good to see you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 637381, text = "Be wary beyond the wall." },
            { id = 800039, text = "But after what I have seen today, I have faith in you." },
            { id = 800041, text = "It has been a great honor to fight by your side. Thank you." },
            { id = 637435, text = "Keep it up. They'll never find your body." },
            { id = 637383, text = "Keep your eyes keen, adventurer." },
            { id = 800027, text = "Lord Zu, the Alliance, the Horde, all chaos is about to erupt out here!" },
            { id = 800049, text = "The Mogu forge weapons of both blood and steel. Their blades feast on death." },
            { id = 800045, text = "This way, the doors can only be opened from within." },
            { id = 800047, text = "We can slip through here quietly, or fight our way through. It is your decision." },
            { id = 800033, text = "We must get you back to the monastery." },
            { id = 800043, text = "Well now, you sure know how to arrive in style." },
            { id = 800035, text = "Yalia, take Lord Zu to safety." },
            { id = 637433, text = "You overestimate my patience." },
        } },
    } },
    { who = "Taran Zhu", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 623186, text = "AHHH!" },
            { id = 623184, text = "HUAAAGH!" },
            { id = 623182, text = "MMM!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1383886, text = "If your Legion wants Pandaria, you will have to get through us!" },
            { id = 1383888, text = "It is done! You have done a great service for Pandaria this day!" },
            { id = 1383889, text = "There it is. The staff of our last emperor. You have proven yourself worthy to wield it, friend of the Shadowpan." },
            { id = 623342, text = "You are wasting everyone's time!" },
            { id = 623340, text = "You are wasting my time." },
            { id = 1383885, text = "You will find no easy target here, demon!" },
            { id = 800163, text = "You will kneel when you beg for my mercy, monster!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1383866, text = "I will need your healing powers, champion! I cannot face this demon alone!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 800177, text = "Face me, Shambu! Or is the court of the Thunder King a den of cowards?" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 800169, text = "Champion with me we must press forward while your comrades cover the rear" },
            { id = 1383864, text = "Come, that monster has already spread his corruption to the waters above. We must act quickly." },
            { id = 623268, text = "Hold fast against the shadow." },
            { id = 800181, text = "Stay close to Yalia's healing, champion!" },
            { id = 800185, text = "Stay near Yalia so that she may heal you." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 623220, text = "GAH!" },
            { id = 623222, text = "UGH!" },
            { id = 623212, text = "YAAH!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 623264, text = "Do not succumb to the darkness." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1383890, text = "Ah, ten thousand years ago, Emperor Shaohao used that very staff to cloak our land in a veil of mists, hiding us from the Burning Legion." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1383887, text = "Begone, beast. Your shameful crusade ends here." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 623324, text = "How can the Shadowpan serve?" },
            { id = 623322, text = "The Shadowpan welcomes you." },
            { id = 1383865, text = "We must work together. Champion, we will follow your lead. How do you wish to deploy the Shadowpan?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1383861, text = "Bless the Crane, I heal her!" },
            { id = 800183, text = "Dance around Shanbu's attacks. We are faster. We are smarter." },
            { id = 623338, text = "Enough! We have work to do." },
            { id = 623326, text = "Hmm, we are outnumbered, but not outwitted." },
            { id = 800179, text = "Keep moving! Avoid the Storm Lord's lightning!" },
            { id = 623266, text = "Remain centered, my friend." },
            { id = 800171, text = "Shambu! Again you try to create a god? When will you learn?" },
            { id = 1383863, text = "Thank you, hero. The sacred waters have already been corrupted. If you help me rescue the others, we may be able to reclaim this place." },
            { id = 1383862, text = "The Legion knows the importance of this sacred place. I personally led the patrol here, but we were ambushed and overcome." },
            { id = 800165, text = "Those statues wield the power of the First Emperor! Destroy them!" },
            { id = 800167, text = "Toshi! Get those doors open!" },
            { id = 800175, text = "Yolia! We need more healing! Toshi! Cover the rear!" },
            { id = 800173, text = "Zandalari reinforcements are coming!" },
        } },
    } },
    { who = "Tarecgosa", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 561428, text = "YOU SHALL NOT HAVE HIM!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 561429, text = "I am with you always." },
            { id = 561431, text = "My thoughts are with you, mortal." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 561433, text = "Ah, I cannot hold on much longer." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 561438, text = "Assist me! There are too many!" },
            { id = 561437, text = "Careful! Avoid his breath at all costs!" },
            { id = 561434, text = "Fight hard, immortal! We mustn't fail!" },
            { id = 561426, text = "Fight on, hope shines through even the most utter darkness." },
            { id = 561435, text = "Never give up." },
            { id = 561436, text = "Quickly! Onto my back! We must escape this place!" },
            { id = 561432, text = "Security here is much stronger than I recall. What is Erigos protecting?" },
            { id = 561430, text = "Watch out! More sentries!" },
        } },
    } },
    { who = "Tasha Riley", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3154030, text = "I see you finally decided to visit our base of operations. Unfortunately, you're far too late." },
            { id = 3154031, text = "My elite team has collected everything we need to construct a weapon beyond imagination." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3154032, text = "Horu! Greet our guest." },
            { id = 3154042, text = "Horu! Open the rest of the cages! Everyone else, team meeting!" },
            { id = 3154035, text = "It's no surprise you won. We all know Horu would lose a fight against a strong breeze. Perhaps this will occupy you." },
            { id = 3154039, text = "It's plebeian, you... Gah! Never mind. Just handle them!" },
            { id = 3154043, text = "Okay, everyone remember the new plan? Auron, you're up." },
            { id = 3154037, text = "That's oddly specific." },
            { id = 3154040, text = "Theron, what happened to one hundred percent?" },
            { id = 3154036, text = "You entertain me. Theron, what are the odds that this hero succeeds?" },
        } },
    } },
