    { who = "Telzo Sparkspanner", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2913742, text = "Imagine no longer, Simpleton. I am more than willing to tell you how you and your little crew will meet your demise." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2921643, text = "I keep this simple for you, simpletons. Smash the small ones, and then smash everything they own!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 2913741, text = "I don't hear any more noise! I do hope that means you smashed the intruder, you foolish brute!" },
            { id = 2913744, text = "Recognition! And what did we get? A fool of a gnome sweeping in and reaping the rewards of all our work." },
            { id = 2913746, text = "You fools! The Titan Defenses are already under my control! The loss of my mech means nothing! You will- REEPLE!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2913745, text = "All those who followed Mecha-Talk must pay! With my army of troggs, I will decimate all of Nomanity!" },
            { id = 2921482, text = "Be mindful of your conduct!" },
            { id = 2921640, text = "Behold! True Gnomish ingenuity!" },
            { id = 2913743, text = "Did you really think that I, the great thermoplag second in command, would die in a scheme I helped engineer?" },
            { id = 2921483, text = "I'm acting in self-defense!" },
            { id = 2921484, text = "This'll leave you ecstatic!" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 3014006, text = "HA!" },
        } },
    } },
    { who = "Temel", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3607769, text = "Let's get this over with, master!" },
            { id = 3608047, text = "Your secret's safe with me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3607781, text = "Dredgers. Always making messes." },
            { id = 3608045, text = "If you hear something, let me know." },
            { id = 3608044, text = "I'm going to find your sinstone one of these days." },
            { id = 3607779, text = "Lazy caretakers! That monument is practically falling over!" },
            { id = 3608046, text = "Remember, you did not hear that from me." },
            { id = 3608048, text = "See you around, Maw Walker!" },
            { id = 3607772, text = "so I can betray my friend with it. Gee, thanks." },
            { id = 3607780, text = "What curious candles!" },
            { id = 3607786, text = "With pleasure, master!" },
            { id = 3607768, text = "Yeah! I'm not going anywhere with you!" },
        } },
    } },
