    { who = "Terrorguard", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1385177, text = "This place is nothing but a shadow of itself. We will crush it last, so that its inhabitants may despair at the destruction of their world." },
