    { who = "Tezan", tier = "character", groups = {
        { name = "Greetings", family = "Manners", lines = {
            { id = 3623573, text = "Welcome to Ardent." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3623572, text = "The spirits are watching." },
            { id = 3623577, text = "You want my anima? Why can't the ancient Tyranid do it?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3623580, text = "Are you sure it's safe? There are still a lot of masked Feyreid." },
            { id = 3623582, text = "I've heard that Derowyn and Corrin were great at pranks. Is that true?" },
            { id = 3623576, text = "Thanks. I'll run ahead. I'm guessing you could use some help." },
            { id = 3623579, text = "There. Let's finish this." },
            { id = 3623575, text = "These be the meanest they I've ever met!" },
            { id = 3623574, text = "We give what we can." },
            { id = 3623581, text = "Well, I better stay with you. For protection." },
            { id = 3623578, text = "Well, okay. But I better get some back later." },
        } },
    } },
    { who = "Thaed Pyremaker", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 6359885, text = "Let their arrogance fuel your spirit, their fear guide your blade! We will stand victorious!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 6359888, text = "The cowardly crawlers are retreating! Rally to me, and we will finish this fight!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 6359883, text = "Hold the line! Keep your strikes decisive and your aim true! May the flame guide you!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 6359886, text = "We are the flames' radiance, defenders of Maraldor, and today we hold!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6359889, text = "Is that the best warrior they can offer? Get in there and show them the strength of the flame!" },
            { id = 6359882, text = "No warrior ever won a battle by dying! The flame still requires your strength!" },
            { id = 6359881, text = "On your feet, soldier! The flames' radiance burns ever brighter!" },
            { id = 6359879, text = "The Sacred Flame blesses us with victory, but stay vigilant. The enemy will return to throw themselves upon our blades once more." },
            { id = 6359877, text = "Victory for the flames' radiance! Take a moment for celebration, but stay on your guard. They'll return soon enough." },
            { id = 6359884, text = "We face the last gasp of a dying empire. Do not relent until the battle is won!" },
            { id = 6359880, text = "We shall not fall, nor shall we give in! Keep fighting, soldier!" },
            { id = 6359887, text = "We've got them on the run! To me! Let us give them a reason to keep running!" },
        } },
    } },
    { who = "Thaelin Darkanvil", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2000273, text = "Heh heh! A fine job teaching these goblins what happens when you meddle with the dark iron dwarves!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2000278, text = "A venture company shaman has command of Elementals rippling with Azerai. Thieving good-for-nothing gobbas donna deserve such power. Crusher!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2000276, text = "Break their machines! Destroy their tools! Crush every tiny green gober that gets in your way!" },
            { id = 2019337, text = "Have a good one!" },
            { id = 2000277, text = "Iron foe is finally within our grasp. Make sure you teach these goblins what happens when you steal from the dark iron." },
            { id = 2019338, text = "Keep those irons in the fire!" },
            { id = 2019339, text = "May your flame burn bright!" },
            { id = 2000279, text = "Of all the things, feeding the lifeblood of the planet to an ogre, thinking it'll give him a brain. I mean, it couldn't, could it? Best smash him before we find out, eh?" },
            { id = 2000274, text = "Of course, goblins have those tiny brains, so you'll probably have to bash a few hundred more for the lesson sinks in." },
            { id = 2000280, text = "The Venture Company's Chief Weapons Researcher is here. We've been trying to pin him down for ages. Go! Give him a beating for me." },
            { id = 2000275, text = "These Goblins are corrupting Azerite on a massive scale! We cannot let this stand!" },
        } },
    } },
    { who = "Thalkiel", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1418234, text = "ANOTHER WEAKLING FALLS!" },
            { id = 1418238, text = "DIDN'T EVEN TRY!" },
            { id = 1418240, text = "FALL BEFORE YOUR MASTERS!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1418232, text = "The soul of that one would be useful!" },
            { id = 1416629, text = "You know, I've been rather missing having some skin on my bones. Maybe there's something we can do about that." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1416631, text = "No! Lower cast won't do it all!" },
            { id = 1444699, text = "No, no, no. Wrong skin color entirely. That won't do." },
            { id = 1416633, text = "Not bad, not bad. Green eyes, though. Mine were gray." },
            { id = 1444702, text = "Ugh, that head reminds me of an uppity apprentice I had. Get rid of it." },
        } },
    } },
    { who = "Thalnos Soulrender", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 621169, text = "WE HUNGER FOR VENGEANCE!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 621177, text = "More, more souls!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 621181, text = "Claim a body and wreak terrible vengeance!" },
            { id = 621179, text = "Seek out a vessel, and return!" },
        } },
    } },
    { who = "Thalrenus Rivertree", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1416010, text = "ILLUN FALLAH SHALLAH" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1405327, text = "I will remain if you should have need of me again." },
            { id = 1405321, text = "I will take this opportunity to lay traps for the intruders. I am certain we will meet again." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1405566, text = "Here we go." },
            { id = 1405325, text = "Our vigil has ended, but I remain." },
            { id = 1405328, text = "Thank you for that welcome distraction." },
            { id = 1405563, text = "They will be upon us shortly. I can teleport us somewhere safe." },
            { id = 1405562, text = "We meet again. Lothrius and Sirana have just informed me of your deeds." },
            { id = 1405323, text = "We stand watch over Suramar." },
            { id = 1405322, text = "What do you require of the guard?" },
        } },
    } },
    { who = "Thane Wildsky", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1372720, text = "AH!" },
