    { who = "Thanekorthazz", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 561834, text = "NEXT TIME, BRING MORE FRIENDS!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 561832, text = "Come on and fight ye way and nitty!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 561836, text = "I'm gonna enjoy killing these slack-jawed daffodils!" },
            { id = 561831, text = "I've heard about enough of your snooveling! Shut your fly trap before I shut it for you!" },
            { id = 561837, text = "To arms here, house-to-boats, we've got company!" },
        } },
    } },
    { who = "Thanikos Hand of Courage", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3575465, text = "NO! NO! NOOOOOO" },
            { id = 3575464, text = "WHAT ARE YOU DOING TO ME?!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3618048, text = "I am glad to see I am not yet alone. The Maldraxxi attacked without warning!" },
            { id = 3618057, text = "I have shewed off a portion of their anima, and will heal your wounds if you approach it." },
            { id = 3575461, text = "My Paragon, you do not stand alone!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3618058, text = "anima powers all things in bastion even the mighty colossi this will help it retain its charge" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3575462, text = "For the Archon! For Bastion!" },
            { id = 3618049, text = "You betray your ancient oath to Maldraxxus, Lich! Justice will be done!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3618054, text = "Keep your wits about you. Our enemy has no honor." },
            { id = 3618059, text = "Now Thor is truly powerful if his magic penetrated this plating. He will not go down easily." },
            { id = 3618052, text = "Sacrilege! Mortal, push forward and secure the temple!" },
        } },
    } },
    { who = "Thaon Moonclaw", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
