            { id = 1241883, text = "THE NIGHTMARE WILL CONSUME US ALL!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1243353, text = "You will not escape me this time! BETRAYER!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1241589, text = "I will protect Val'sharah with my life!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1241587, text = "Find me when Cograxus has been slain. I sense an even darker presence here." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1241585, text = "Pathetic creature this curse has made me stronger than the ancients" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1241885, text = "All that remains, agony, madness!" },
            { id = 1241581, text = "The nightmare will consume you!" },
        } },
    } },
    { who = "Tharazun", tier = "character", groups = {
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 561841, text = "AHHH!" },
            { id = 561842, text = "GRRR!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 561864, text = "Roar! Roar! Roar!" },
            { id = 561848, text = "Thank you for watching!" },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 561849, text = "ROAR!" },
        } },
    } },
    { who = "Thassarian", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1411947, text = "SURRENDER TO THE EVAN BLADE!" },
            { id = 1411946, text = "THE TIDES OF BATTLE TURN HERE!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 561886, text = "HA!" },
            { id = 561890, text = "HUUU!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1416857, text = "Indeed you shall, General. Indeed you shall." },
            { id = 1416856, text = "Long enough, my friend. The Burning Legion has returned, and you have been called to the battle." },
            { id = 561896, text = "Suffer well." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1416862, text = "My patience has worn thin as well. Let's find the prince and be done with this." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 561895, text = "AHHH!" },
            { id = 561887, text = "UGH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1416852, text = "Nazgrim, your Deathlord calls! Feel the icy grip of your master, and rise once more!" },
            { id = 1416871, text = "We are the Ebon Blade, knights of undeath who protect this world." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1416853, text = "It is time, my lord. Do what must be done." },
            { id = 1416869, text = "We took his life, my lord. The prince left us little choice." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 561898, text = "Another time." },
            { id = 1416870, text = "Death and ruin. Time has not been kind to this place." },
            { id = 561913, text = "Hmm." },
            { id = 561889, text = "Tomorrow is another day." },
            { id = 1416872, text = "We do what the living cannot." },
            { id = 561908, text = "What?" },
            { id = 561892, text = "You need something." },
            { id = 1411945, text = "Your weakness is our strength!" },
        } },
    } },
    { who = "Thastalah Dryad", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1247035, text = "You have my gratitude traveler." },
            { id = 1247047, text = "You... you have saved me!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1247041, text = "I felt myself slipping away!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1247029, text = "Bless you, stranger." },
            { id = 1247023, text = "Oh, to breathe again!" },
        } },
    } },
    { who = "The Accuser", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3754839, text = "HA!" },
            { id = 3754829, text = "HIYAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3582202, text = "You have my gratitude. We may lack the strength to hold these halls, but the Lord Chamberlain no longer defiles them." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3572384, text = "More of those fools seek to hinder us. Do not allow them to interfere." },
            { id = 3582201, text = "Your shield is naught but cowardice. Mortals, strike down the Lord Chamberlain, and any who defend him." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 3754891, text = "AH!" },
            { id = 3754885, text = "AHHH!" },
            { id = 3754893, text = "OH!" },
            { id = 3754895, text = "UGH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3583977, text = "Sinstone golems are meant to be destroyed, yet he infuses them with anima. End this sacrilege!" },
            { id = 3547084, text = "You deprive your own people of anima and inflict a drought upon all of the Shadowlands!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3583976, text = "The Halls of Atonement once served a sacred purpose. The Lord Chamberlain sullies them to suit his vanity." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3572382, text = "Additional guards are en route. Ensure that their deaths are swift." },
            { id = 3572383, text = "Another interruption from the castle guard. Dispose of them." },
            { id = 3583978, text = "Only one golem remains to bar our path. Reduce it to rubble." },
            { id = 3583975, text = "You make a mockery of Revendreth's hallowed purpose. I will not abide it." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 3754817, text = "HEH!" },
            { id = 3754821, text = "RRR!" },
        } },
    } },
    { who = "The Arbiter", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4322863, text = "I am honored to serve." },
            { id = 4322865, text = "I will judge souls with compassion." },
            { id = 4322666, text = "My path has become clear. I must take my place in Oribos." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4322679, text = "Go in service, friends. Oribos, and all the Shadowlands, are counting on you." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 4322668, text = "Farewell, my friends." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 4322675, text = "Now I can direct the flow of souls to the afterlives they justly deserve." },
            { id = 4322677, text = "Yet much remains to be done. To restore balance to the Shadowlands, I fear more must be asked of you." },
            { id = 4322676, text = "Yet one goal remains before us. To truly restore balance to the Shadowlands, the Jailer must be defeated." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4322672, text = "And tell Adrestes I am sorry I could not become an acolyte." },
            { id = 4322674, text = "Maw Walker, my friend, without you, I may never have found my path." },
            { id = 4322864, text = "This is my calling." },
            { id = 4322665, text = "Yes, Cleia. I am whom I have always been, and yet so much more." },
        } },
    } },
    { who = "The Ashbringer", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1392767, text = "Give me the strength to shatter these bonds." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1392757, text = "Find the strength within." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1392760, text = "Ashes to ashes." },
            { id = 1392756, text = "Courage is your greatest weapon." },
            { id = 1392765, text = "Hope never dies." },
            { id = 1392761, text = "In the light, we are one." },
            { id = 1392766, text = "Light, grant me one final blessing." },
            { id = 1392758, text = "Put your faith in the light." },
            { id = 1392764, text = "We stand united." },
        } },
    } },
    { who = "The Black Bride", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2738024, text = "Sharpen your blades and poison your daggers! We will lay waste to these Alliance Pests!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2740550, text = "I want to see the Alliance rot!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2738026, text = "For the defilers! For the Horde!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2738022, text = "Arathi Basin. This land used to belong to Stromgarde. After today, it will belong to the Horde!" },
            { id = 2739842, text = "Enough! All forces retreat! The Warchief will not be pleased with this." },
            { id = 2739844, text = "Excellent! A Rothy Basin and all of its resources belong to us now!" },
            { id = 2740553, text = "Make ready for the carnage!" },
            { id = 2738023, text = "Prepare for battle, champions! The Alliance will not give up this ground without a fight!" },
            { id = 2738025, text = "Taking control of the resources in Arathi will sever the Alliance's supply lines. Seize them by any means necessary." },
            { id = 2739843, text = "This land is nearly ours! Do not relent, champions!" },
            { id = 2740551, text = "We will slay them all!" },
            { id = 2740552, text = "What do you offer the Defilers?" },
        } },
    } },
    { who = "The Count Ess", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3547106, text = "You will enjoy my hospitality, so long as you remain receptive to what I have to say." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3592463, text = "I am grateful we have this chance at civilized discourse, since stealing from an aristocrat could find you making atonement... or worse." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3547104, text = "Come, let us find a more comfortable place to chat." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 3592461, text = "Perhaps you misunderstood. That was a command, not an offer. Now sit." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3566654, text = "But I must agree with the others. You lack... ...leverage." },
            { id = 3592464, text = "But please, eat. Let us not speak of such heinous crimes." },
            { id = 3547103, text = "I've been expecting you." },
            { id = 3547105, text = "No need to be on edge. As you can see, my guards have been instructed to treat you as a guest." },
            { id = 3592460, text = "Please, take a seat." },
            { id = 3566653, text = "Why Renethal, if only you had shown such passion ages ago. I find it positively enthralling." },
            { id = 3592462, text = "You came here with the intent of stealing my medallion. No need to deny it. I am just stating the known facts." },
        } },
    } },
    { who = "The Curator", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1524968, text = "AH!" },
            { id = 1524967, text = "GAH!" },
            { id = 1524966, text = "HA!" },
            { id = 1524965, text = "HMPH!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1513825, text = "Welcome to the... TERMINATE INTRUDERS!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1523383, text = "Defense protocols activated." },
            { id = 1513822, text = "Deterrent protocols successful." },
            { id = 1513821, text = "Genitorial units, begin menagerie decontamination." },
            { id = 1513824, text = "System failure imminent." },
        } },
    } },
    { who = "The Curator Venthyr", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3593572, text = "Follow me downstairs. Your friends are waiting." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3593513, text = "I did some digging myself. It seems the Countess keeps her sinstone locked away in a crypt. The keys spread amongst nobility as a sign of favor." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3593586, text = "With these shards and some of my own anima, I will piece this mirror back together." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3593414, text = "A brilliant artifact in the art of repentance!" },
            { id = 3593588, text = "Be careful, Pelagos. We'll be right behind you. Everybody remember to apply the powder to protect yourself." },
            { id = 3593590, text = "If I did not know any better, I would think you're a venthyr of some renown!" },
            { id = 3593415, text = "I'm afraid its fate, as well as its creators, is lost to me. I know someone who could help, but not willingly." },
            { id = 3593581, text = "Is it my mind that is more touched or yours? Use the death lotus powder to protect yourself!" },
            { id = 3593404, text = "It has been quite some time since I've seen a kyrian. Perhaps you'll lend me a feather for my studies. Maybe a dozen!" },
            { id = 3593571, text = "Kleia made quick work of the Vensir in our path. She is truly a sight to behold." },
            { id = 3593510, text = "The Countess surely knows poor Alwyn's fate. If we can find her sinstone, it will be the leverage we need for her to assist in your search." },
            { id = 3593412, text = "The Seal of Contrition. Created by a noble by the name of Alwyn, I believe?" },
        } },
    } },
    { who = "The Desolate Host", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1592385, text = "THE DARKNESS SHALL CLAIM YOU" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1592389, text = "You are fuel for the engine." },
            { id = 1592390, text = "Your souls are but fodder." },
            { id = 1592386, text = "Your souls will know despair." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1592388, text = "We will reap your souls." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1592396, text = "Our work must continue." },
            { id = 1592394, text = "Such... Bitter... Harvest..." },
            { id = 1592395, text = "The engine falters." },
            { id = 1592391, text = "Who dies with you?" },
            { id = 1592393, text = "Witness our victory!" },
            { id = 1592392, text = "Your struggle has been for naught." },
        } },
    } },
    { who = "The Fearstalker", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3610751, text = "Next time, I will find you." },
            { id = 3610753, text = "Watch your back, or someone else will." },
            { id = 3610754, text = "You cannot hide from me." },
            { id = 3610757, text = "You have many things to fear, little one." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3610749, text = "I shall give you a head start." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3610748, text = "Run while you can." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3610758, text = "Fear itself is enough." },
            { id = 3610755, text = "Have you ever been truly humbled?" },
            { id = 3610752, text = "Oh, I would run too, if I were you." },
            { id = 3610759, text = "You only made one weakness, to be vulnerable." },
            { id = 3610750, text = "You reek of sin, you would be easy to track." },
            { id = 3610756, text = "Your fear betrays you." },
        } },
    } },
    { who = "The Headless Horseman", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5227902, text = "My family is whole again, as is my soul. I cannot thank you enough, champions." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5227903, text = "Come forth, my minions! Unleash your breath! Choke them with the stench of death! Ha Ha Ha ha" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 5227901, text = "It is done the Headless Horseman is no more" },
        } },
    } },
    { who = "The Jailer", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4326148, text = "Every soul has its place, and your souls will know only Oblivion." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4325054, text = "Annihilate those who oppose me and sunder your final tether to mortality." },
            { id = 4325052, text = "It is done. The final chamber of the Sepulchre opens before me." },
            { id = 4326158, text = "Oblivion is the only release." },
            { id = 4324390, text = "Open the way." },
            { id = 4324393, text = "The Sepulchre's secrets will be mine." },
            { id = 4326157, text = "Their flawed design will be eradicated." },
            { id = 4326159, text = "There is no escape." },
            { id = 4326146, text = "This is your end." },
            { id = 4325053, text = "You were forged into a weapon, to succeed where all others had failed. Now, one final purpose remains." },
            { id = 4326145, text = "Your failure was inevitable." },
        } },
    } },
    { who = "The Lich King", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 554001, text = "COLD IS LOST" },
            { id = 554101, text = "CREAMBLE! AND KNOW YOUR DOOM!" },
            { id = 554068, text = "THE END HAS COME" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 554114, text = "I will not make the same mistake again, Sylvanas. This time there will be no escape. You will all serve me in death." },
            { id = 2408319, text = "Vol'jin, your soul has walked on the other side and returned. You have been altered more than you know." },
            { id = 1242139, text = "Where the weak showed mercy, you did not hesitate to strike. Where the unworthy were vanquished, you have conquered." },
            { id = 2408320, text = "You are neither undead nor damned. You do not belong here. Leave this place at once." },
            { id = 3256074, text = "You are prepared for the war to come." },
            { id = 1242161, text = "You have done well. Ascend to my throne and receive your charge." },
            { id = 554166, text = "Your allies have arrived, Jaina. Just as you promised. You will all become powerful agents of the Scourge." },
            { id = 554123, text = "Your will is not your own." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1242135, text = "I now mark you with my sigil. Let all recognize you as the enforcer of my will." },
            { id = 1242116, text = "I sense powerful spirits remain within the Blades. Enter into the spiritual realm within, and purge them of all that resist your domination." },
            { id = 1242128, text = "Now, ensure that not a single demon escapes my wrath. Crush all who stand in your way." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 554164, text = "Fools of Stormwind, hear me, naive children of the Alliance!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3256073, text = "Do not be merciful." },
            { id = 554088, text = "Go forth and defile these lands." },
            { id = 1416929, text = "Go now, and do what must be done." },
            { id = 2408321, text = "Leave now, or stay forever. The choice is yours." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 554137, text = "NO!" },
            { id = 554058, text = "WHOA!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1242181, text = "Balecon's soul was cursed to relive a moment of his death for eternity and will see you as his enemy. Destroy him." },
            { id = 1242167, text = "Even when consumed by Frostmourne, the soul of Magroth refused to give up the light. Show him the error of his ways." },
            { id = 1242121, text = "It is done. From the shards of Frostmourne, the twin blades are born. Soon, they shall feed upon the souls of my enemies." },
            { id = 1242171, text = "Once hailed by Arthas as a brother, Gavinrat too was ultimately fed to Frostmourne. Grant him a final death." },
            { id = 1242169, text = "The soul of Halak was tortured within Frostmourne till he cursed the Light. Now that he has forsaken it, slay him." },
            { id = 3149392, text = "This is the hour of your dark rebirth. Death's power grows. Rise and become my champion." },
            { id = 554067, text = "Very well. Warriors of the Frozen Wastes, rise up. I command you to fight, kill, and die for your master. Let none survive." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 554079, text = "For the Lich King's gaze is fixed upon you!" },
            { id = 2408318, text = "The Banshee Queen's schemes threaten the balance. I had no hand in them." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 554099, text = "All life must end." },
            { id = 1595657, text = "And hold tight to your reins." },
            { id = 1242133, text = "As we speak, the Ebon Blade is en route to the Broken Isles to hunt for the dreadlords." },
            { id = 554181, text = "Bow to your master." },
            { id = 3149391, text = "But your duty to Azeroth is not yet complete. More is demanded of you. A price the living cannot pay." },
            { id = 554089, text = "Conquer in my name." },
            { id = 554046, text = "Cough... Cough... Cough..." },
            { id = 1242175, text = "Destiny calls to you." },
            { id = 554093, text = "Face now, your tragic end." },
            { id = 3149390, text = "In life, you were a hero to your people. For their sake, you made the ultimate sacrifice." },
            { id = 1595647, text = "Look ahead. Do you see it?" },
            { id = 553986, text = "Pops of Orgrimmar, hear me! Brash upstarts of the Horde!" },
            { id = 553997, text = "Slay all who oppose us." },
            { id = 554073, text = "Speak." },
            { id = 1416918, text = "The time of the second horseman has come, Deathlord." },
            { id = 3256076, text = "There is much to be done." },
            { id = 554009, text = "Tremble, and know your doom!" },
        } },
    } },
    { who = "The Monkey King", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1399700, text = "Get moving, Wicket! Let the trial begin! Makin' sweet hosin' slurp is the way you can win." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1399701, text = "Good goin', Wicket! You know how to picket!" },
            { id = 1399703, text = "Looking good, you. Smelling good, too." },
            { id = 1399707, text = "No, no, and no! That's not how it go! It's like we could be TRYING to lose this here show!" },
            { id = 1399706, text = "No, No, No, don't be spooked, or that brew will be grooked." },
            { id = 1399699, text = "That's one, and that's two. Ah yes, that is three. Now we find out if right wicked be." },
            { id = 1399698, text = "There be one more test, for I tell you my tale. Meet at Jade Serpent's temple, for the mixins go stale." },
            { id = 1399705, text = "Time for the wicked to add the next mixin'. Tossin' a banana, that be the right fixin'." },
            { id = 1399708, text = "Too bad that the wicked got it all wrong, this duke of a brew make me sing a sad song." },
            { id = 1399709, text = "What you do, Wicket? Pour that down the drain. Guess now we will have to start over again." },
            { id = 1399704, text = "Yep, that's the ticket. Keep it up, clever wicket!" },
            { id = 1399702, text = "Yup, yup, that's the way! Hop, hop, save the day!" },
        } },
    } },
    { who = "The Primus", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4293097, text = "GO THROUGH THE GATEWAY, NOW!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4323847, text = "Domination is akin to communication. A language, if you will." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4323777, text = "Together we shall manifest the final sigil!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4254126, text = "Behold, the Crown of Wills!" },
            { id = 4323853, text = "If we can disrupt that interference long enough, we may find a way to thwart it." },
            { id = 4323807, text = "If we use the Helm of Domination, we may be able to discover the source of their resistance." },
            { id = 4254123, text = "imbued with the strength of those who defied domination." },
            { id = 4323850, text = "One so powerful that it interferes with the creature's very understanding of itself. This is why it is almost impossible to resist." },
            { id = 4254129, text = "That which sought to bind us will be made anew!" },
            { id = 4323785, text = "The way is open." },
            { id = 4323775, text = "With the Maw Walker's aid, the covenants have been renewed. Yet one sigil is still required to pursue Zovaal, the Arbiters." },
            { id = 4323803, text = "Zovaal needed to dominate the Atoma to enter the Sepulchre, yet they did not succumb immediately." },
        } },
    } },
    { who = "The Stonewright", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3603518, text = "Choose your next words very carefully." },
            { id = 3566651, text = "I will not subject my stoneborn children to further suffering!" },
            { id = 3566650, text = "None of your grand words matter. You cannot defeat both the jailer and the master." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3603514, text = "I am not overly fond of heroes." },
            { id = 3603517, text = "I have seen your name on many newly carved sinstones." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 3603513, text = "Very well. I shall see what Renethal has to say. If nothing else, perhaps I might end this pointless struggle that has my children fighting each other." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3603516, text = "Leave this place before it claims you." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3603512, text = "So Draven, you continue to serve Prince Renethal, despite his many failures." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3603521, text = "Beware niceties in this realm. None of us are sent here by accident." },
            { id = 3603520, text = "In the end, the more is inevitable for us all." },
            { id = 3603519, text = "One does not resist the master's will." },
            { id = 3603515, text = "This is no place for the living." },
        } },
    } },
    { who = "The Tithelord", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3618512, text = "I am pleased that we see eye to eye." },
            { id = 3618506, text = "My carriage is upstairs. We will finish this discussion on the way." },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 3618501, text = "No more excuses. The master will have his tithe of anima, or I will see to it that everyone in this miserable hamlet are exiled to the Ember Ward." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3618509, text = "We may even be able to increase the rate that we are supplying her with anima." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3618511, text = "Everything will proceed unless she fails to uphold her side." },
            { id = 3618503, text = "Hah! I've heard enough! This... usurper demands our medallions, but offers nothing. Ugh!" },
            { id = 3618507, text = "Now that we are away from itching ears." },
            { id = 3618510, text = "Of course it would. Inform your lady I am still in charge." },
            { id = 3618505, text = "Tell Lady Wixerer that I am still in charge, and..." },
            { id = 3618504, text = "The master's removal changes nothing." },
            { id = 3618508, text = "You can reassure Lady Wixura that our plan remains intact." },
            { id = 3618502, text = "You mean YOU could seize control? These are merely the ravings of a selfish prince, desperate to reclaim his former glory." },
        } },
    } },
    { who = "The Underpin Lonzy Grindgear", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 6244330, text = "I got a deed for these Delves signed by Gallywix. Wait, does that say Gallywax? Ah, you know what? It don't matter!" },
            { id = 6244317, text = "I roll with an iron fist!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6244323, text = "Ain't that a kick in the head?" },
            { id = 6244324, text = "All kneel before the under-in!" },
            { id = 6244320, text = "I'll flatten you for what you've done!" },
            { id = 6244328, text = "I'm the underpin of these parts, your small potatoes!" },
            { id = 6244329, text = "Oh, you'll be hearing from my attorney!" },
            { id = 6244321, text = "People always messing around on my perfectly legal deeded land!" },
            { id = 6244325, text = "Surprise! Now get out!" },
            { id = 6244322, text = "That'll teach you for trespassing!" },
            { id = 6244326, text = "Who are you? What are you doing on my property?" },
            { id = 6244327, text = "You don't look so tough from where I'm sittin'!" },
        } },
    } },
    { who = "Themaker", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 561927, text = "My work must not be interrupted!" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 561930, text = "Perhaps I can find a use for you." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 561925, text = "Let's see what I can make of you!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 561926, text = "Anger, hate, these are tools I can use." },
            { id = 561929, text = "It is pointless to resist!" },
        } },
    } },
    { who = "Thenios Paragon of Wisdom", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3613697, text = "I am ready to aid you." },
            { id = 3596813, text = "I cannot hold them for much longer. Get to the gateway." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3613695, text = "Come forth and be heard." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3613693, text = "A road of sorrows is paved with attachments." },
            { id = 3613691, text = "Continue your journey." },
            { id = 3613698, text = "Do you seek wisdom?" },
            { id = 3613694, text = "Duty is its own kind of wisdom." },
            { id = 3613696, text = "How can I guide you?" },
            { id = 3596742, text = "If we are to assault loyalty, we must strike now. Her power still grows." },
            { id = 3613692, text = "Learn from the past, but do not linger in it." },
            { id = 3596739, text = "Uther is missing, and Lysonia has turned to the Maw itself." },
        } },
    } },
    { who = "Theotar", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3609671, text = "Oh, you... you are walking away. Yes, I too am content ending this conversation as well. Of course." },
            { id = 3593744, text = "Olwen! You have visitors, my friend." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 3609670, text = "A most gracious farewell to you, as well." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3609672, text = "A life-changing conversation. I shall remember it always." },
            { id = 3609673, text = "Care for a quick stroll?" },
            { id = 3609669, text = "If you discover a mighty foe, DEFEAT IT!" },
            { id = 3609668, text = "If you discover my parasol, protect it!" },
            { id = 3609666, text = "If you discover my shirt, bury it!" },
            { id = 3609667, text = "If you discover my teapot, drink it!" },
            { id = 3609674, text = "Insanity is no excuse for bad manners." },
            { id = 3593745, text = "Shortly after Alwyn fell mad to the light, the seal was stolen by a disposed duke who aimed to harness its power for himself." },
            { id = 3593746, text = "We have recently tracked him down, and we're discussing next steps. Your timing is serendipitous, as always." },
        } },
    } },
    { who = "Therazane", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 561990, text = "GRRR!" },
            { id = 561992, text = "HUAH!" },
            { id = 561985, text = "HUH!" },
            { id = 562010, text = "HUUU!" },
            { id = 562027, text = "HUUUH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1407244, text = "Go! Destroy the Twilight's hammer and you shall win my favor!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1407242, text = "I will not fight the Burning Legion while the Twilight's hammer lays siege to Deepholm!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1407248, text = "Protect the earth and ring, Avalancheion! Pave the ground with the corpses of the Burning Legion!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 561979, text = "GAH!" },
            { id = 561994, text = "OH!" },
            { id = 561981, text = "UGH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 561993, text = "His spirit is strong for a creature of mortal flesh. He fascinates me, and I am loath to give him up." },
            { id = 561999, text = "Yes, mortals. Your thrall is here. He has fused with the stone of this place, heart and soul." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1407247, text = "As a symbol of our alliance, I will bestow upon you one of my greatest warriors!" },
            { id = 562029, text = "He may not wish to leave, regardless of whose heart beckons him home." },
            { id = 562026, text = "Still, I can hear the cry of a distant heart echoing through the labyrinth between worlds. It's the cry of a lover's heart I hear, and great Therazane has not forgotten what it was to love." },
            { id = 1407245, text = "The Earthen Ring has done a great service to Deepholm. We will return the favor." },
            { id = 1407246, text = "The stone mother always pays her debts!" },
            { id = 562001, text = "You may seek him with my blessing." },
            { id = 562004, text = "Your world shaman stands in the basalt groves below. But take heed, he has become one with these unending halls of stone." },
        } },
    } },
    { who = "Therin Skysong", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3189354, text = "I have also calculated that I have a 100% chance to destroy this feeble-minded plebeian." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3154003, text = "Wait, is THAT what we decided to call ourselves?" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 3153991, text = "Ah, the hero has arrived. I warned you that I'd predicted your next four moves. We've all been waiting for you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3153998, text = "63.8% to be exact." },
            { id = 3153999, text = "A most improbable development." },
            { id = 3153995, text = "Exactly one in four thousand nine hundred and eighty six." },
            { id = 3189586, text = "Like I said, I've predicted their next four moves. This is all part of my plan." },
        } },
    } },
    { who = "Therum Deepforge", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3177150, text = "HERE COMES THE BOOM!" },
            { id = 3177146, text = "YOU'VE MADE A GRAVE MISTAKE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3177149, text = "You won't dodge this one!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3177147, text = "Mephistoise has burnt out." },
            { id = 3177151, text = "So, you like to play with explosives, do you? Then let's play!" },
        } },
    } },
    { who = "Thiernax", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3527658, text = "My apology, Shandris. It is not easy for me to speak of the Night Warrior." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3516970, text = "The forest sings your praises." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3516968, text = "Elune's wrath is not to be invoked lightly." },
            { id = 3527650, text = "for your sake as well as hers." },
            { id = 3516971, text = "Is there something you wish to ask?" },
            { id = 3527665, text = "Kadarin, I cannot lose him again." },
            { id = 3527663, text = "Kadarin, no! What have you done to him?" },
            { id = 3527659, text = "More Spriggans were being ambushed." },
            { id = 3516967, text = "Nothing is more important than those we love" },
            { id = 3527649, text = "Then her fate is sealed. My condolences, but you must let her go." },
            { id = 3516966, text = "We all do what we must." },
        } },
    } },
    { who = "Thisalee Crow", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1582091, text = "I need to fall back! Keep going!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1582088, text = "Let's do some damage!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1581270, text = "A fine hunt! Good work out there, Archdruid." },
            { id = 1582090, text = "Check out these claws!" },
            { id = 1582093, text = "Gah! That hurts!" },
            { id = 1581269, text = "Goldrinn has his prey cornered, but we should lend a hand. And by hand, I mean talon, claw, or other stabby thing." },
            { id = 1581241, text = "Goldrinn needs our help! A demon decided to cheat the hunt by bringing in backup. Let's give him a taste of his own medicine." },
            { id = 1582094, text = "Heh, there's more where that came from!" },
            { id = 1582092, text = "I... Gotta take a breather." },
            { id = 1582089, text = "I'm feeling stabby!" },
            { id = 1582087, text = "Let me at him!" },
            { id = 1581242, text = "Thanks for the help! Those demons are like gnats compared to Goldrinn, but with so many of them, who knows what could have happened?" },
        } },
    } },
    { who = "Thoktar", tier = "character", groups = {
        { name = "Mockery", family = "Menace", lines = {
            { id = 1056676, text = "No, I hope these weaklings die better than they smell!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1056681, text = "Crushmall gonna win this by a landslide! Mwahahaha! Ahaha!" },
            { id = 1056671, text = "Ha! Looks like getting split in half made that grub twice as ugly!" },
            { id = 1056678, text = "How tiny mens beat mighty Volgore!" },
            { id = 1056674, text = "Korg has to be one scary orc. When he starts choppin', not even his own limbs are safe. Mwahahaha!" },
            { id = 1056672, text = "Ouch! Even I felt that hit in my boulders!" },
            { id = 1056680, text = "There is respect and our heritage won't get him invited to next year's games." },
            { id = 1056670, text = "These pukes are better at dying than fighting!" },
            { id = 1056675, text = "They gonna look like puddles after this fight!" },
            { id = 1056679, text = "Uh, didn't we win Battle over the Spires?" },
        } },
    } },
    { who = "Thomas Zelling", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2431683, text = "Enjoy what you have!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2431691, text = "I do, more than anything." },
            { id = 2431685, text = "I will help the Horde as they helped me." },
            { id = 2431686, text = "My family will be safe no matter what." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2431682, text = "Do not take this life for granted." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2431689, text = "Everyone wants me to control the storms, change the current, but no one ever asks just to sit down and have a nice chat." },
            { id = 2431681, text = "Never forget what is precious to you." },
            { id = 2431692, text = "Oh, that's... that's good. But how? We spent everything we had before my death. I-I mean, my transformation." },
            { id = 2431690, text = "Rexar, wait, is there any news from my family? How are they doing?" },
            { id = 2431688, text = "This is not how I imagined life after death would be." },
            { id = 2431684, text = "This place is my only home." },
            { id = 2431687, text = "You do know I was a Tide Sage, right? Come on, lightning, control the sea? Hmm... Just checking." },
        } },
    } },
    { who = "Thoradin", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1370187, text = "Even in death the monster is restless its corruption has spread throughout the tomb You will have to fight your way through" },
            { id = 1370183, text = "My thanks. Though we have never met before, I sense great courage in your heart. Yes, you are the hero I need." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1370182, text = "I will tell you nothing. What lies beneath will be the end of you." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1370189, text = "As I feared, one of the monster's minions has returned. Its presence is corrupting the wards of the tomb and blocking the path. You must destroy the tendrils to draw it out." },
            { id = 1370184, text = "Long ago, my yearning for knowledge led me here, to a tomb that lies beneath the lake. Within its cold stone walls, I found something long buried. A terrible darkness. An ancient evil." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1370193, text = "Behold, the sight of my final battle! And there lies my foe. Even now, Zakaj struggles for consciousness. You must hurry!" },
            { id = 1370191, text = "There it is atop the crypt prepare yourself" },
            { id = 1370192, text = "These monsters play tricks upon the mind! Beware their illusions!" },
            { id = 1370190, text = "Those tendrils are using dark magic to become immune to attack Interrupt their casting so you can strike" },
            { id = 1370188, text = "When I saw this antechamber, I knew we had found something... momentous. Here was a door so oddly familiar, like a long-forgotten memory. We broke the first seal." },
        } },
    } },
    { who = "Thoras Trollbane", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1444613, text = "My heart still beats with the drums of war." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1444605, text = "This war will not be won with words." },
            { id = 1444615, text = "Victory without sacrifice is only an illusion." },
            { id = 1444607, text = "We alone stand vigil in the night." },
            { id = 1444611, text = "We do what the living cannot." },
        } },
    } },
    { who = "Thorim", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 562082, text = "NOOO!" },
            { id = 562085, text = "UGH!" },
            { id = 562078, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1386087, text = "Ah, and you are joined by one of the mortals who freed us from the grip of the old god. We must hold a feast to celebrate!" },
            { id = 1386078, text = "I know your heart aches at Hati's loss, Hunter, just as mine does. You have a kinship with the spirits of wild creatures greater than any I have seen before." },
            { id = 562105, text = "I will crush you!" },
            { id = 1386067, text = "You are not worthy to wield the fury of the storms, Vrykul!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 562098, text = "I have no time for games." },
            { id = 562099, text = "My patience has reached its limit!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 562086, text = "AHA!" },
            { id = 562090, text = "GYAAAH!" },
            { id = 562083, text = "HEHE!" },
            { id = 562075, text = "HMPH!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1386086, text = "Ah, Bronzebeard! Back again, I see! Hottie has missed you, as has Skoll! Skoll? Ugh! Where has that warg run off to?" },
            { id = 562076, text = "Hail, tiny creature!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1386083, text = "Hati's noble spirit is forevermore bound to the weapon. He will be a loyal companion to you in the dark times ahead." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1386089, text = "That we shall slay the enemy together! Come Vrykul! Face the fury of the storms!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 562115, text = "All who are is lost, my beloved Slane. What is left for me here?" },
            { id = 562106, text = "Beware, the Pantheons return!" },
            { id = 1386081, text = "By Odin's beard! You did it!" },
            { id = 562077, text = "Can't you at least put up a fight?" },
            { id = 562114, text = "Complacence heralds your doom, adventurer." },
            { id = 1386082, text = "From this day forth, I charge you to wield Titan's Strike against the enemies of creation who would destroy this world." },
            { id = 562081, text = "Irritating little gnat!" },
            { id = 1386091, text = "Is that the best these folks can manage? I could do this all day!" },
            { id = 1386064, text = "It is time we finish this! Hotty, kill!" },
            { id = 562089, text = "Let not the message be lost upon you." },
            { id = 562092, text = "What brings you to the Temple of Storms?" },
            { id = 1386079, text = "What your science cannot achieve, this master of beasts can do by instinct alone." },
        } },
    } },
    { who = "Thorngrin the Tender", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 562130, text = "What aggravation is this? You will die!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 562133, text = "I hate to say I told you so." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 562132, text = "You seek a prize, eh? How about death?" },
        } },
    } },
    { who = "Thornguard Burton", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 3014060, text = "HA!" },
            { id = 3014059, text = "RAWR!" },
            { id = 3014054, text = "UGH!" },
            { id = 3014057, text = "YEAH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2908420, text = "Balance in all things." },
            { id = 2908423, text = "Death is the natural end to life's journey. Let us help the Horde be on their way." },
            { id = 2908421, text = "Good day to you!" },
            { id = 2908424, text = "Return to the Earth." },
            { id = 2908419, text = "Time to remove these weeds!" },
            { id = 2908422, text = "We must restore balance. If that means killing the Horde, then so be it." },
        } },
    } },
    { who = "Thornspeaker Tavery", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2908462, text = "DO STOP BLEEDING WON'T YA?" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 2908459, text = "Ah, the Horde. I was just thinking of how much I would love a good hunt. Release the hounds!" },
        } },
