            { id = 1993477, text = "Unit Haswell Online, Goal, Corruption Containment" },
            { id = 1993483, text = "Very well. You asked for it. Commencing re-origination of entire universe." },
        } },
    } },
    { who = "Titan Watcher Koranos", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4662103, text = "FOR THE GOOD OF DRAGONKIND" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4662124, text = "I feel the waking of the isles." },
            { id = 4662123, text = "I have seen much, I know more." },
            { id = 4662122, text = "I keep the faith." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4662125, text = "Order must be served." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4662126, text = "Aspects be blessed." },
            { id = 4662104, text = "Blessings of the Aspects" },
            { id = 4662101, text = "Stand strong in your convictions." },
            { id = 4662105, text = "Titans watch over you." },
            { id = 4662102, text = "Trust in the ways of order." },
            { id = 4662106, text = "We all have a duty." },
            { id = 4662107, text = "We will return these isles to their glory." },
