    { who = "Toddy Whiskers", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4625142, text = "I can't wait to see what you discover!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4625147, text = "Go first, but I've got a story after!" },
            { id = 4625143, text = "Let's get moving! Plenty to be done!" },
            { id = 4625149, text = "Let's see what you've got!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4643022, text = "Ah, the rugged dragon scale. All aboard for adventure, my friends." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4625145, text = "Adventure calls, and we will answer!" },
            { id = 4643049, text = "Lookit there, Wildfeather! A whole new land to explore!" },
            { id = 4659598, text = "Rathian said he would meet us at the Embassy atop the hill." },
            { id = 4625144, text = "See you at the next adventure!" },
            { id = 4625150, text = "Watch it, or I'll let my Griffin take a wee plop in your head." },
            { id = 4625148, text = "Well, look what the wind blew in!" },
            { id = 4625146, text = "What adventure brings you here? Can I join?" },
        } },
    } },
    { who = "Toe Knee", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1513392, text = "I felt, I knew something never before was going to happen. Had to happen. But this is so much more." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1513409, text = "Go on, scram!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1513404, text = "I'm just gonna... play it cool." },
            { id = 1513405, text = "It's you and me against the world, baby!" },
            { id = 1513403, text = "Now that's what I call a hotfoot!" },
            { id = 1513390, text = "Or that we've met before?" },
            { id = 1513406, text = "So you wanna rumble, do ya?" },
            { id = 1513402, text = "Wanna go for a spin?" },
            { id = 1513394, text = "Why it's so much to believe you're not making a joke." },
            { id = 1513388, text = "You're not thinking I'm someone else." },
        } },
    } },
    { who = "Toki", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2006265, text = "I have scars older than your language!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 2006262, text = "Good luck, try not to die!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2006261, text = "Always watch your back, or get a shell." },
            { id = 2006264, text = "Never accept gifts from the Black Empire!" },
            { id = 2006263, text = "Perhaps we shall meet again on the field of battle, side by side, back to back, outnumbered, out-armored, outclassed." },
            { id = 2006266, text = "You look like you've seen some action. We should swap war stories." },
        } },
    } },
    { who = "Tolvir", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3195702, text = "When you are the king of cats, the whole desert is your litter box." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 562562, text = "AAA!" },
            { id = 562576, text = "ROAR!" },
        } },
    } },
    { who = "Tong", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 900073, text = "So it is with your alliance and your horde. They are not strong despite one another. They are strong BECAUSE of one another." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 900069, text = "When the last emperor hid our land from the rest of the world, he also preserved the homeland of our ancient enemy, the mantid. Why did he do this?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 900065, text = "Always you speak, never do you listen. You ignore the lessons of Pandaria." },
            { id = 900077, text = "He destroyed my inn. He left no tip. He is not nice." },
            { id = 900071, text = "He did so to keep the land whole. Living with the mantid for ten thousand years has made us both strong." },
            { id = 900063, text = "Talk, talk, talk!" },
            { id = 900075, text = "You mistake your greatest strength for weakness. Do you see this?" },
            { id = 900067, text = "You see, there is balance in all things. Wisdom etched in our very fur. Black and white, darkness and light." },
        } },
    } },
    { who = "Tormented Theramore Victim", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4076754, text = "ANSWER FOR ALL YOU HAVE DONE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 4076738, text = "I grew up suffering. I had no one else!" },
            { id = 4076752, text = "Suffer as I have!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4076740, text = "I... yes, I was!" },
            { id = 4076739, text = "Maybe... I just... AHHHHHH" },
            { id = 4076737, text = "She was my world, and she was slain in front of me!" },
        } },
    } },
    { who = "Torok Bloodtotem", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1277338, text = "Don't let them cross that bridge or I'll have your hides!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1277203, text = "A cheap trick calling for reinforcements. You're unworthy of this mountain!" },
            { id = 1277328, text = "Does such weakness pass as strength where you come from?" },
            { id = 1277201, text = "Ha Ha Ha ha!" },
            { id = 1277585, text = "Ha! Highmountain cannot even defend its own chieftain, and you would have us join with them? The Bloodtotem honor strength, not victims." },
            { id = 1277340, text = "He went easy on you, outsider. Come speak." },
            { id = 1277239, text = "Navarrogg's toy won't do him any good against me!" },
            { id = 1277336, text = "No outsider will wield the hammer of Kasgaroth! Flay them alive!" },
            { id = 1277330, text = "Oh, pity. That wretched shardling isn't moving. Its death was neither quick nor painless, I assure you." },
            { id = 1277334, text = "Tear them limb from limb, spread their blood on the fields!" },
            { id = 1277332, text = "We are Bloodtotem! Would you let the weak overcome us?" },
            { id = 1277197, text = "You... defeated... a few of our weakest fighters. Heh Heh Heh heh... no matter. When the fel blood courses fully through our veins, even that precious artifact of yours won't do us harm!" },
        } },
    } },
    { who = "Tortollan - feminine voice", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
