            { id = 2108950, text = "MOO!" },
            { id = 2108939, text = "OW!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1979412, text = "It is about the journey, not the destination." },
            { id = 1979409, text = "Knowledge is power, except stupid knowledge. Avoid that if you can." },
            { id = 1979410, text = "Knowledge is the best currency, but I do take gold in interesting trade-ins." },
            { id = 1979408, text = "leaving so soon, but I was just starting a great story." },
            { id = 1979407, text = "Oh, my back is killing me." },
            { id = 2108949, text = "Ow, Ow, Ow, ow!" },
            { id = 1979416, text = "You think you're so powerful and wise. I've got aches in my undercarriage older than your entire civilization." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
