            { id = 2107234, text = "UGH!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1998111, text = "Ah, what do you know. Stay here if you want. We're going ahead. I know every inch of this area." },
            { id = 1998117, text = "Greetings, sir and or ma'am." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1998110, text = "Bah! You're not the boss of anyone. We need to teach those butchers a lesson!" },
            { id = 1998115, text = "Fine, leave! I was done talking to you anyway." },
            { id = 1998116, text = "have anything ancient to trade needs to be at least two centuries old." },
            { id = 1998113, text = "If you find anything exotic, bring it to me!" },
            { id = 1998119, text = "I've seen things that would scare you shell-less!" },
            { id = 1998109, text = "Kisha! Lask! We're gonna take care of these pests chopping up Tralga!" },
            { id = 1998114, text = "Not everything in the ocean is as good-looking or nice-mannered as I am." },
            { id = 1998118, text = "Step closer and don't mumble." },
