    { who = "Tortollan children - masculine voice", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1979443, text = "I like to roll!" },
            { id = 1979446, text = "My mom says we're amphibious. A-afuvelous. Uh-oh. Uh... Amphibious! Oh! Whew! Finally got it!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1979440, text = "How do you carry stuff without a show?" },
            { id = 1979442, text = "Pretty soon, I'll be as old as you!" },
            { id = 1979445, text = "Tortle tortle tortle, I'm rolling everywhere. Tortle tortle tortle, my feetsie's in the air." },
            { id = 1979447, text = "Water is so cool. I like water. Do you like water? What's your favorite thing about water? Mine is how wet it is. Water is so cool. Am I right?" },
            { id = 1979444, text = "When I grow up, I'm gonna read all the things!" },
        } },
    } },
    { who = "Tortured Amalgamation", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3672056, text = "Pain! Suffering! No hope!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3672061, text = "Abandoned by Elune Priestess lies." },
            { id = 3672062, text = "Avenge children soon. Avenge us." },
            { id = 3672058, text = "Burn with us! Burn!" },
            { id = 3672057, text = "C-C-C-Failed us, Tyrande, the flames, Teldrassil, Sylvanas!" },
            { id = 3672059, text = "No peace in death! Fire!" },
            { id = 3672060, text = "The Banshee has won! All life consumed!" },
        } },
    } },
    { who = "Torturer Relyn", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 1601127, text = "AH!" },
            { id = 1601124, text = "ARGH!" },
            { id = 1601129, text = "HA!" },
            { id = 1601128, text = "HMPH!" },
            { id = 1601126, text = "OOF!" },
            { id = 1601132, text = "RRRAH!" },
            { id = 1601125, text = "YEAH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1594913, text = "Laxera does not take kindly to those who meddle in her business!" },
            { id = 1594911, text = "You will not stop us!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1594912, text = "How pathetic. Siren has taken to compelling outsiders to do her bidding." },
        } },
    } },
    { who = "Torvald", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1592681, text = "Maybe then, you will see." },
            { id = 1592676, text = "Poor sister, if you will not join me, then you are my enemy!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1592677, text = "Give in, sister! Only through the fell could you hope to defeat me!" },
            { id = 1592672, text = "Sister, it's been a long time since you left me for dead." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1592673, text = "How? I embrace the gift that father left us. The one you and mother so vehemently denied." },
            { id = 1592674, text = "It seems you don't remember our father feeding us the fel. The sickness he caused in you must have clouded your mind." },
            { id = 1592678, text = "No! It's not possible!" },
            { id = 1592680, text = "Perhaps you should ask them who sent the assassins for us that night." },
            { id = 1592675, text = "Something in our blood made us resist its influence, but it remains within. All you need to do is give in." },
            { id = 1592679, text = "You... You think your master so superior to mine?" },
        } },
    } },
    { who = "Tpaartos", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1782020, text = "FACE THE FISTS OF TEPARTOS!" },
            { id = 1782019, text = "FOR THE LIGHT!" },
            { id = 1782024, text = "TIME TO FIGHT!" },
            { id = 1782021, text = "YOU CANNOT STOP TIPARTOS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1782022, text = "You cannot be real!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1782023, text = "Tepartos must see this through!" },
            { id = 1782014, text = "Tepartos realizes this now." },
            { id = 1782025, text = "The only way is forward." },
            { id = 1782018, text = "We have to fight!" },
        } },
    } },
    { who = "Trade Prince Gallywix", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1417385, text = "On your toes, people! You have a sacred duty to protect the investments of your trade prince!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1417550, text = "Bring this one down quick! He's wreaking havoc on property values!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1417540, text = "Here they come! Time to prove your worth!" },
            { id = 1417538, text = "Hope you heroes brought enough ammunition!" },
            { id = 1417548, text = "Is it just me, or are they getting angrier and, uh, redder?" },
            { id = 1417387, text = "Not again! These demons have no respect for private property! Let's teach them a lesson!" },
            { id = 1417542, text = "Oh, I don't like the sound of that! Stand tall! Even if you're short!" },
            { id = 1417552, text = "Show him there's only room for one boss in Azshara, me!" },
            { id = 1417546, text = "They're pouring it on! Show them we're no slouches!" },
            { id = 1417544, text = "This bunch looks... bigger! But that's no excuse to slack off!" },
            { id = 1417633, text = "This team is trying to muscle in on my territory! Put a stop to it!" },
            { id = 1417383, text = "We got company! Keep track of everything the demons break! I'm sending them a bill!" },
        } },
    } },
    { who = "Travard", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 5126914, text = "HA!" },
            { id = 5126912, text = "HAH!" },
            { id = 5126910, text = "HYA!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1390749, text = "I will complete the ritual to release the hammer and collapse the tomb, but we must be quick. I can sense evil emanating from the tomb." },
            { id = 1390728, text = "My brothers spoke of a dragon called Lanagosa at Wyrmrest Temple. Seek her out while I prepare a strike force for the tomb." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 5127032, text = "GAH!" },
            { id = 5127030, text = "OOF!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 1390748, text = "Ah, there you are. The area was secured at great cost. This cannot continue. We must retrieve the silver hand and destroy the entrance to the tomb." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1388587, text = "Until we meet again." },
        } },
        { name = "Idle", family = "Feelings", lines = {
            { id = 5126954, text = "AHHH!" },
            { id = 5126950, text = "UGH!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1390730, text = "Ephrena, find your brother and rally at the tomb." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1388585, text = "May Tyr guide you." },
            { id = 1390382, text = "Something is wrong! One of the other sparks isn't here!" },
            { id = 1390729, text = "You can make your way there through the portal to Dalaran Crater. I will meet you there with additional forces." },
        } },
        { name = "Noticing you", family = "Orders and warnings", lines = {
            { id = 5126878, text = "HAAARGH!" },
            { id = 5126880, text = "HUH!" },
            { id = 5126876, text = "HUUU!" },
        } },
    } },
    { who = "Tredova", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3592267, text = "Your flesh will nourish my offspring." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3555353, text = "I feast, you die!" },
            { id = 3555351, text = "I have no interest in your anima." },
            { id = 3592266, text = "My progeny shall sate their hunger!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3555354, text = "Go away! Must eat!" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 3555352, text = "Begone! Sustenance awaits me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3555350, text = "Consume, devour, feast!" },
            { id = 3555356, text = "Let me get back to my meal!" },
            { id = 3555371, text = "Such exquisite knowledge!" },
            { id = 3555355, text = "You should have stayed away." },
        } },
    } },
    { who = "Tribemother Torra", tier = "character", groups = {
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1373697, text = "We journey together with the spirits." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1373699, text = "How can I help?" },
            { id = 1370343, text = "Over here, shaman. Take up my spear. The winds will guide your strike." },
            { id = 1373696, text = "The Earthen Ring will persevere." },
            { id = 1373698, text = "The Elements Call" },
            { id = 1370380, text = "The Legion destroys us in the open fields, even Thunder Bluff isn't safe from the infernals." },
            { id = 1370379, text = "What kind of shaman can't light a fire?" },
