    } },
    { who = "Tricktotem", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4663678, text = "MATE THIEVES! KILL THEM! RUIN THEM! DESTROY THEM!" },
            { id = 4663533, text = "NO! RIP OUT THE BONES!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
