    } },
    { who = "Trilliax", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1348506, text = "HOLD STILL, MASTER, FOR INCINERATION!" },
            { id = 1348502, text = "YOU DARE LEAVE CRUMS ON MY FLOOR? DIE!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1348508, text = "stop screaming makes it hard to stab you" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1348496, text = "Did you receive satisfactory service?" },
            { id = 1348504, text = "Filthy. Filthy. FILTHY!" },
            { id = 1348500, text = "Have a bite, master! I know it's your favorite!" },
