    { who = "Tubbins", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3526937, text = "My noggin hurts!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3526946, text = "Four parts, right, rooks?" },
            { id = 3526936, text = "I'm busy too!" },
            { id = 3526940, text = "I'm the pretty one!" },
            { id = 3526942, text = "Tea makes the bad light go away." },
            { id = 3526944, text = "Think hard, Tobbins! Recipe was..." },
            { id = 3526945, text = "Three parts smelly stuff!" },
            { id = 3526938, text = "Tobin's knows best!" },
            { id = 3526939, text = "Tubbins and Gobbins can fix!" },
            { id = 3526943, text = "You rest. Tuppence make tea." },
        } },
    } },
    { who = "Tuberros", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5064188, text = "Be safe now!" },
            { id = 5064197, text = "Grub Nectar! I knew I smelled your scent." },
            { id = 5062639, text = "I-I mean my... Never mind. Just follow me!" },
            { id = 5064212, text = "Mmm, yes, especially stinky, and sticky too, mmm." },
            { id = 5064194, text = "Oh, good going friend. Maybe I should think about getting my own drug bar assistant. Those guys are strong." },
            { id = 5064203, text = "Oh, Hermit Yaring could use a hand tending his fields. Why don't you and that Drogbar guy help him out?" },
            { id = 5064209, text = "Oh, look how shiny those snail shells are. If you could convince a few to look for new lodging, they'd make a perfect gift for Parisa Mona." },
            { id = 5064215, text = "Oh, nice smellin' ya!" },
            { id = 5064206, text = "Oh? Oh, heya boss!" },
            { id = 5062644, text = "We need to get out of here. I can smell my grub nectar nearby." },
            { id = 5064200, text = "Whoa! Happy synth trails!" },
        } },
    } },
    { who = "Tugar Bloodtotem", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1586600, text = "TOO LATE FOOLS! I ALREADY HAVE WHAT I NEED TO DESTROY THUNDER TOTEM!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1586603, text = "A pity you won't be around to see it. DIE!" },
            { id = 1586606, text = "Your efforts are futile. Follow me and see why." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1586601, text = "I found the beast able to survive the fel infusion." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1586604, text = "Fool! You only located me because I wanted to be found! Now I shall have vengeance on Thunder Totem and you!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1586607, text = "Behold my greatest creation! With a Legion's power behind me, Thunder Totem will be destroyed!" },
            { id = 1586608, text = "This changes nothing. The Legion will prevail." },
            { id = 1586602, text = "With an army of these creatures boring into the rock, I will bury Thunder Totem!" },
            { id = 1586605, text = "You merely delay the inevitable. My fell beasts are even stronger now!" },
        } },
    } },
    { who = "Tunk", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3489162, text = "ME GONNA SMASH! YOU NO STOP RITUAL!" },
            { id = 3544532, text = "NOT SO TOUGH NOW!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3544531, text = "Here you go, Splat!" },
            { id = 3489163, text = "Me never see Gorgoth win." },
        } },
    } },
    { who = "Turi Flickerflame", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 5015180, text = "I just... I just miss them so much!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5015176, text = "Come to laugh at me then? Or maybe just to crush me underfoot?" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 6119180, text = "Hey, haven't I been through enough? Sheesh, some people." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5015170, text = "For the sake of those we lost, I won't let you stop me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6119149, text = "Be seeing ya!" },
            { id = 5015171, text = "Master Ronan? Kindi? Forgive me!" },
            { id = 5015172, text = "No! I can't fail! Not when everyone is counting on me!" },
            { id = 5015178, text = "What choice did we have? We had to protect ourselves! I-I couldn't do a thing to stop the first mana bomb, and because of that Ronin and Kindi and everyone is gone!" },
            { id = 5015179, text = "You were supposed to protect us! You were supposed to keep things like this from happening! But you didn't! And now, our home is gone! We can't ever get it back!" },
        } },
    } },
    { who = "Tussle Tonks Announcer", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2925346, text = "MAXIMUM THRUST! MAXIMUM CARNAGE!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2925339, text = "Let's get mobilized for mayhem!" },
            { id = 2925341, text = "Wait, what's this? Some surface dwellers have unwittingly stumbled into the arena!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2925342, text = "A word of caution to anyone sitting in the Splash Zone! Watch out for blood!" },
            { id = 2925345, text = "Better watch your step!" },
            { id = 2925336, text = "Now this is a statistical anomaly, our visitors are still alive!" },
            { id = 2925347, text = "Oh, a brutal hit from the piston hammer! A real fan favorite." },
            { id = 2925343, text = "Spinning up! Here come the buzzsaws!" },
            { id = 2925338, text = "The Platinum Pummeler! And no mercy for you!" },
            { id = 2925348, text = "This fight is about to heat up!" },
            { id = 2925337, text = "Time to introduce them to the legends of the Tussle Talks Arena!" },
            { id = 2925340, text = "What a matchup we've got tonight, folks! Sparks are gonna fly!" },
        } },
    } },
    { who = "Twilight Deacon Farthing", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1391126, text = "THE DARKNESS CONSUMES ALL!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1391125, text = "See how I bend your mind to my will!" },
            { id = 1391124, text = "You cannot trust your own mind!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1391122, text = "Defend me, Blade! You said this would work!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1391129, text = "Give me another chance! No! NOOOOOO" },
            { id = 1391120, text = "Our old leaders chose to work with pawns. I choose the real power!" },
            { id = 1391127, text = "This... this shouldn't be happening! WHY AREN'T YOU PROTECTING ME?!" },
            { id = 1391119, text = "Yes. The blade is right. I am unstoppable. Once Sakaj lives again, I will hold dominion over this world!" },
            { id = 1391123, text = "You think to stop me. With this weapon, I can do anything. ANYTHING!" },
        } },
    } },
    { who = "Tyr the Infinite Keeper", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5194301, text = "DIVIDED! YOU FOOL!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 5194329, text = "You cannot change what is." },
            { id = 5194327, text = "You cannot stop what is infinite!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5194309, text = "My blows are infinite!" },
            { id = 5194311, text = "My strike is true" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5194305, text = "Alihilation is inevitable!" },
            { id = 5194347, text = "But your path ends here." },
            { id = 5194345, text = "For too long I was bound by the shackles of the titans. Now my mind is open to infinite possibilities." },
            { id = 5194319, text = "Your greatest fears realized." },
        } },
    } },
    { who = "Tyrande Whisperwind", tier = "character", groups = {
