        { name = "Dark magic", family = "Fighting", lines = {
            { id = 573182, text = "Let the peaceful light of Elune soothe your souls in this dark time." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 897378, text = "At them my sisters, for Calimdor!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1342773, text = "Ashallah, to me!" },
            { id = 1342779, text = "Elothir? By Elune, not you too. Have you seen my husband?" },
            { id = 573202, text = "Elune guide you through the night." },
            { id = 573204, text = "Eyes of night, pierce this darkness!" },
            { id = 1342783, text = "Feathers and blood. It is still wet. There may still be time." },
            { id = 1342763, text = "His location is still unclear, but he lives." },
            { id = 1342767, text = "Malfurion! He is in pain! Keep fighting, my love!" },
            { id = 1342775, text = "Meet me back at the refuge and we will continue our search." },
            { id = 573206, text = "Spear of Elune, drive back the night!" },
            { id = 1342765, text = "Such malevolent laughter. Xavius, you cruel creature! I am coming for you!" },
            { id = 1342781, text = "The corruption is thick here. What is that across the bridge? Be on guard." },
            { id = 1342761, text = "We must go deeper into the nightmare. Wherever he is, peril is already upon him." },
        } },
    } },
    { who = "Ularogg Cragshaper", tier = "character", groups = {
