            { id = 2126754, text = "Gorak Tool! It cannot be!" },
            { id = 2126760, text = "He is vulnerable within his own realm, and he will go to great lengths to prevent you from entering it." },
            { id = 2126757, text = "It would appear I was mistaken. Thros has come to us." },
            { id = 2130993, text = "Maintain the balance." },
            { id = 2126753, text = "Some pathways are best left closed, lest those on the other side set foot upon them." },
            { id = 2126758, text = "This changes things." },
            { id = 2126755, text = "Thorn Speakers, to arms!" },
            { id = 2126756, text = "Who are you to judge who's worthy? Your twisted ways have disgraced our kind, tool!" },
