    { who = "Urquan", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1058876, text = "You will find the sleepers there to the southwest, across the dunes." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1058874, text = "Champion of the Frostwolf Clan, if they are friends of yours, then they are welcome here." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1058873, text = "No creature should be subjected to what they're doing down there." },
            { id = 1058872, text = "Please be swift and merciful. The Mother of Wolves is the true victim here." },
            { id = 1058875, text = "That cave is inside the Groom Spire. Those are the ruins of Atagar to the west." },
        } },
    } },
    { who = "Ursoc", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1349074, text = "I'LL RIP THE CLAWS FROM YOUR LIFELESS HANDS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1349080, text = "You are free of this place! How I envy you!" },
            { id = 1349086, text = "You have released me from the Nightmare. The claws have served you well." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1349088, text = "I will flatten you like saplings!" },
            { id = 1349078, text = "My sacred gift, from the Watchers. Yes... Yes, Nightmare Lord. Yes! The fury of the claws must be mine once more!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1349076, text = "You should have fled. Now, I'll feed your bones to the Stormcrows!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1349072, text = "Ah, the Nightmare consumes me, compels me, to serve, to kill!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1349082, text = "By the will of the Nightmare Lord!" },
            { id = 1349090, text = "Stamp and trample, cross and crumple!" },
            { id = 1349092, text = "The nightmare grows, the nightmare devours!" },
            { id = 1349084, text = "The nightmare's veil is lifted. I return at last to the long slumber." },
        } },
    } },
    { who = "Ursol", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1384478, text = "The final trial will not be easy, druid. Speak with me when you are ready." },
            { id = 1384477, text = "You have failed, just as I did, yet we can learn from this and change your destiny. Speak with me again." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1384479, text = "Ah, very good, champion. The spirit of the bear truly dwells within you." },
            { id = 1384470, text = "Before you awaits your next trial, defeat the spirits and prove you possess the courage of the bear." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1384474, text = "Once, during the chaos of an ancient battle, my brother and I became separated. I failed to be at his side when he needed me most." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1384475, text = "For this trial, you must prove that you can protect those who entrust you with their lives. Show me that you can succeed where I once failed." },
            { id = 1384471, text = "Magnificent! Your courage is undeniable. A final trial awaits you." },
            { id = 1384472, text = "Tell me, is there anyone willing to fight at your side, druid?" },
            { id = 1384466, text = "The first trial will test your might against the strongest of my followers. Show me that you possess the strength of the bear." },
            { id = 1384476, text = "This one will be your charge. Guard her, or she will quickly be overwhelmed." },
            { id = 1384463, text = "What brings a follower of Cenarius to my lair?" },
            { id = 1384469, text = "You've proven your strength, but do you possess the courage to face overwhelming odds? Tell me if you wish to test yourself." },
        } },
    } },
    { who = "Usha Eyegouge", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2414900, text = "I saw what you did out there. Reminds me of my days in Alterac. My long, long days in Alterac." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 2414899, text = "Those Alliance cowards are fleeing like frightened Tolbook! Pathetic! LAPTAR!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2414901, text = "Ah! I love watching Alliance Pops run away with their tails between their legs!" },
            { id = 2414902, text = "At least I've got one competent soldier! Those grunts could learn a thing or two from you!" },
            { id = 2414898, text = "Boar's dung! A critical supply shipment was ambushed nearby! Get back those goods! No!" },
            { id = 2414903, text = "Every soldier we save is one less rock-scald grunt I have to train back in Orgrimmar! I owe you a drink." },
            { id = 2414897, text = "Listen up, peons! No one rests until our warriors are rescued! We do not abandon our own!" },
            { id = 2414894, text = "Our grunts have somehow managed to pin down an entire Alliance platoon! Help them finish the job!" },
            { id = 2414892, text = "The Alliance is digging in its heels! Everyone forward! No restorations until they're driven out!" },
            { id = 2414895, text = "The plan here is simple. You see the Alliance, you kill the Alliance! I don't care how you do it!" },
            { id = 2414896, text = "These gutless Alliance runts refuse to engage us in open combat! Use the Crawler Mines to break their defenses!" },
            { id = 2414893, text = "Those Alliance vermin are crawling all over the Azerite here! What are you waiting for?! CRUSH THEM!" },
        } },
    } },
    { who = "Uther", tier = "character", groups = {
