    { who = "Valunei Tyrs Guard Exemplar of Compassion", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5226269, text = "Eriska? No! I... I... must end you, sister!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5211562, text = "I am always here if you need me." },
            { id = 5226557, text = "I have found my purpose, to serve others by following Tyr." },
            { id = 5226551, text = "I hope I have helped you." },
            { id = 5226252, text = "My Commander, you once saved my life. Let me save yours. Come with me." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 5226562, text = "Everyone deserves compassion. Everyone." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5226421, text = "A faceless one! You preyed on my compassion for my friend!" },
            { id = 5226394, text = "how did i fall for that creature's lies i need time i'm going back champion" },
            { id = 5226542, text = "May Tyr take your hand." },
            { id = 5226262, text = "Resist? This is my commander. She will prove it. Eriska, tell them what you would say to me when you would catch me daydreaming." },
        } },
    } },
    { who = "Valzuun", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1392449, text = "Excellent. You will find Akari in the Ledger Domain Lounge." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1392453, text = "Ah, you made it. Well done." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1392452, text = "It is done. The way to Shadow Gore Citadel is open." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1392451, text = "Ere dakkur shudas al zul, kodai!" },
            { id = 1388592, text = "Make it so." },
            { id = 1392450, text = "Thank you for seeing the reason." },
            { id = 1388593, text = "We shall see." },
            { id = 1388596, text = "What is it?" },
        } },
    } },
    { who = "Vandel", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1594917, text = "Corvass, slayer! All was quiet until recently. Suddenly Legion portals appeared and we were fighting for our lives. Most of our scouts are missing." },
            { id = 1594919, text = "Huh. She made a few snide comments regarding our vigilance, and then left on her own. I haven't seen her since." },
            { id = 1594918, text = "We are under attack and taking heavy losses. Legion portals are opening up everywhere. We need reinforcements." },
        } },
    } },
    { who = "Vandellor", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4484743, text = "I do not recall. To better focus upon the service I perform, I let go of my mortal memories." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4484744, text = "Even so, it was a pleasure to meet you young one, may your weapons serve you well." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4484738, text = "Often what looks like a shortcut only leads to grief. Stay true to your path." },
            { id = 4484741, text = "Strange, speaking with you, it is as if a long-forgotten memory flickers in my mind." },
        } },
    } },
    { who = "Vanessa Vancleef", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 563374, text = "HA!" },
            { id = 563379, text = "HEY!" },
            { id = 563395, text = "HI!" },
            { id = 563371, text = "HYAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1388619, text = "I have a knack for making people disappear." },
            { id = 1388620, text = "I thought you were above this." },
            { id = 1388611, text = "I will have my revenge someday." },
            { id = 563412, text = "I will not share my father's fate! Your tale ends here." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 563368, text = "Fools! Haha! This entire ship is rigged with explosives! Enjoy your fiery deaths!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1388617, text = "Don't push me." },
            { id = 1388614, text = "Let's talk more action." },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 563381, text = "AH!" },
            { id = 563401, text = "AHHH AHHH!" },
            { id = 563370, text = "GAH!" },
            { id = 563373, text = "UGH!" },
        } },
        { name = "Laughter", family = "Fun", lines = {
            { id = 563385, text = "HAHAHAHA!" },
            { id = 563393, text = "HEHEHEHE!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1388618, text = "Care to split a drink? It's not poisoned. Promise." },
            { id = 563398, text = "Did you really think I would come to this fight alone?" },
            { id = 563418, text = "Ha! The first of many!" },
            { id = 563423, text = "Ha! You didn't honestly think I would only plant one set of explosives, did you?" },
            { id = 1388612, text = "Nothing will stand in my way." },
            { id = 1388613, text = "What can I do for you?" },
            { id = 1388616, text = "Words are petty." },
        } },
    } },
    { who = "Vanthir", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1407676, text = "DUSK LILY POTS! Oh, I see." },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1408350, text = "There you are. Thank you for your patience." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1408352, text = "I will try to have more tomorrow. This is all I can offer for now." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1408346, text = "A sip is all I can offer for now." },
            { id = 1408349, text = "But slowly now, we do not want to waste a drop." },
            { id = 1408348, text = "Drink it slowly, make it last." },
            { id = 1408354, text = "Enough for those most in need. The rest... Ah, welcome, welcome!" },
            { id = 1408351, text = "It is not much, but please take it." },
            { id = 1407677, text = "Please excuse me. I must address this immediately." },
            { id = 1408353, text = "This should be enough for your children." },
            { id = 1408347, text = "This should ease the pain for a little while." },
            { id = 1408355, text = "Your arrival is timely. Welcome to my tavern." },
        } },
    } },
    { who = "Varedis Felsoul", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1241287, text = "BEHOLD THE INFINITE POWER OF THE TWIN BLADES!" },
            { id = 1345802, text = "I AM A GOD! KNEEL BEFORE ME!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1241251, text = "I am through with this charade! Your soul will feed the Twinblades!" },
            { id = 1241285, text = "I was Illidari once, left for dead at the Black Temple. Now you will witness the might of my new master!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1401293, text = "I have no need for mortal armaments!" },
            { id = 1241209, text = "My master has granted me many gifts. Witness the power of the deceiver!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1241211, text = "Pity your allies had to die. Don't worry, I'll put their souls to good use." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1345803, text = "Mmm, gladly, my master!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1241253, text = "Behold the might of the deceiver! Behold the glory of the demon within!" },
            { id = 1241289, text = "It's been years. You should know better than to stand against me!" },
            { id = 1241231, text = "Join me! Unleash your true power! Do not let the weak hold you back!" },
            { id = 1241241, text = "So, Illidari, you seek my head that you might take the Twinblades as your own? Allow me to introduce you to their power, personally." },
        } },
    } },
    { who = "Vareesa Windrunner", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4322334, text = "You are right, Lady Sun. Our family has endured so much darkness. We must find a way to cling to hope." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4322330, text = "I only wish we'd had more time." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 4322328, text = "For so long, there had been little more than hatred and malice in our sisters' eyes. To at last see a glimmer of the Sylvanas we knew." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4322352, text = "And now, after so long, there is much we need to say to one another." },
            { id = 4322332, text = "It will never be like it was before. The pain she inflicted upon the Kaldorei... ...have on the world. How could she ever answer for it?" },
        } },
    } },
    { who = "Varian Wrynn", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 563481, text = "HA!" },
            { id = 563482, text = "HMMM!" },
            { id = 563496, text = "YEAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 563551, text = "My open hand will reward my friends, but let my enemies beware." },
