        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 563498, text = "AH!" },
            { id = 563523, text = "AHHH!" },
            { id = 563524, text = "HUH!" },
            { id = 563511, text = "UGH!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 563501, text = "The Alliance will forge a new destiny for Azeroth." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 563514, text = "Hmph. If only I were still in the Crimson Ring." },
            { id = 563479, text = "I'm of two minds about all this." },
            { id = 563494, text = "Never again will our kingdom be deceived." },
            { id = 563519, text = "Our struggles are far from over." },
            { id = 563486, text = "Stormwind is reborn." },
            { id = 563492, text = "The line of Stormwind's kings has been restored." },
            { id = 563484, text = "You want to compare scars?" },
        } },
    } },
    { who = "Varigg", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1963054, text = "NOW I BEAT THE FISHFOOD!" },
            { id = 1963056, text = "WHAT ARE YOU LOOKING AT?!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1963058, text = "Mmm, not your usual rabble on this here island. Seems this detour might be worthwhile after all." },
            { id = 1963059, text = "Now you're fish bait!" },
            { id = 1963051, text = "Turn them into chum!" },
            { id = 1963061, text = "Well, you're a feisty one!" },
            { id = 1963053, text = "Wigglin' worms for me hook!" },
        } },
    } },
    { who = "Varimathras", tier = "character", groups = {
