        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1686457, text = "Ah, the agony of shadows!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1686462, text = "Away!" },
            { id = 1686474, text = "Behold the might of the Nathrezim!" },
            { id = 1686465, text = "Behold! Pain given form!" },
            { id = 1686153, text = "Better that you died here, where she cannot claim you." },
            { id = 1686154, text = "Death claims us all." },
            { id = 563601, text = "How will this benefit me?" },
            { id = 563560, text = "I'm always on the winning side." },
            { id = 1686459, text = "Ugh, damn it, above witches!" },
            { id = 563562, text = "Vanquish the weak!" },
            { id = 563576, text = "You think you can match the might of a dreadlord?" },
        } },
    } },
    { who = "Varok Saurfang", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4953584, text = "You will find your path in due time, and it will lead you to greatness." },
            { id = 4953568, text = "Your offering is worthy my friend. You have earned our blessing." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4953590, text = "Go now with honor, always." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 4953577, text = "Ah, and you, Duroc, son of Thrall." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3049337, text = "If I wanted to harm him, I'd have done it in the stockades." },
            { id = 4953574, text = "If you would, tell Eitrigg he was right, and Thrall, tell him I am heartened to have dragged him out of seclusion.\"" },
            { id = 3049431, text = "In the end, death claims us all. Ytrid told me those were among the last words Sylvanas spoke to Vol'jin." },
            { id = 4953571, text = "May your actions continue to lead the Orcs to honor and glory." },
        } },
    } },
    { who = "Vassandra Stormclaw", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3077060, text = "I will find a cure." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3076180, text = "I call upon the rage of the great wolf!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3076175, text = "Goldrinn's curse is dangerous, Princess Greymane. I have spent much time and effort in search of a way to cure it." },
            { id = 3076179, text = "Let us begin. But be warned, the spirits that accompany Goldrinn may not take kindly to our intrusion." },
            { id = 3076178, text = "The Warken Curse affects some worse than others. Goldrinn's rage is not easily subdued." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3076176, text = "But if words alone will not suffice, then I believe I know another path to wisdom." },
            { id = 3077059, text = "Elune be with you." },
            { id = 3076181, text = "Goldrin, awaken from your slumber!" },
            { id = 3076190, text = "Hurry! After her! She is losing control!" },
            { id = 3077061, text = "Nature will provide." },
            { id = 3076177, text = "Princess, I have something to ask of you as well." },
            { id = 3076189, text = "This vision of Gilneas was created to match Princess Greymane's dreams. Within it may lurk nightmares of her own making." },
        } },
    } },
    { who = "Vault Observation Executor Vox", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5048755, text = "Coordinates confirmed. Initiating transport." },
            { id = 5049766, text = "Quarant identified. Welcome, Scale Commander Emberthal." },
            { id = 5049778, text = "Querent unknown. Access denied." },
            { id = 5049796, text = "Vault Observation Executor, Fox, is online. Submit query." },
        } },
    } },
    { who = "Vazruden the Herald", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 563635, text = "Your days are done!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 563634, text = "You are nothing! I answer a higher call!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 563638, text = "Is there no one left to test me?" },
            { id = 563639, text = "It is over! Finished!" },
            { id = 563633, text = "The Dark Lord laughs at you!" },
            { id = 563636, text = "Your time is running out!" },
        } },
    } },
    { who = "Velhar", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1124376, text = "You are getting so very frail and weak." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1124379, text = "Know your place, weakling!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1124381, text = "Does it hurt being so powerless?" },
            { id = 1124375, text = "Enforcer! Enact my will!" },
            { id = 1124377, text = "Enough! This is where you die!" },
            { id = 1124373, text = "Harbinger, restore my wounds!" },
            { id = 1124378, text = "Not. Even. Worthy." },
            { id = 1124380, text = "Oh, is that one finished?" },
            { id = 1124370, text = "The Eredar are no strangers to war. Are you so eager to meet your end?" },
            { id = 1124374, text = "The Sovereign watches over me!" },
            { id = 1124382, text = "Your attempts, meaningless!" },
            { id = 1124383, text = "Your existence without purpose." },
        } },
    } },
    { who = "Venari", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3538772, text = "I trust you are not followed." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3538775, text = "I have limitless time. You do not." },
            { id = 3538769, text = "I will detain you no longer." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3538765, text = "Do not draw the jailer's eye." },
            { id = 3538773, text = "Find anything of interest, mewalker." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3538776, text = "All mysteries will be revealed." },
            { id = 3538768, text = "Discover more secrets. Then we can talk." },
            { id = 3538774, text = "Do you feel the more tearing at your mind?" },
            { id = 3538771, text = "Procure something of value." },
            { id = 3538767, text = "Return only if you must." },
            { id = 3538766, text = "Trust not what you see in the more." },
            { id = 3538770, text = "Would that be all, maw-walker?" },
        } },
    } },
    { who = "Venoxis", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 563695, text = "HIYAH!" },
            { id = 563675, text = "HMM!" },
            { id = 563689, text = "ROAR!" },
            { id = 563682, text = "YEAH!" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 563678, text = "AHHH!" },
            { id = 563674, text = "GAAHHH!" },
            { id = 563681, text = "GAH!" },
            { id = 563680, text = "NOOO!" },
