            { id = 563677, text = "SHHH!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 563715, text = "The mortal coil unwinds." },
            { id = 563718, text = "Yeah, you've come to stop us! We will protect hacker to the death!" },
            { id = 563706, text = "Your sacrifice pleases him." },
