    { who = "Venrik", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 1983801, text = "I thought you were dead! Oh, don't tell me you're actually working for those bootlickers!" },
            { id = 1983800, text = "I told you, iron-tied punkster! Wait a minute... Flynn?" },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 2015321, text = "Until next time!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1999016, text = "Ahhh, that hits the spot!" },
            { id = 2015325, text = "Grog or Rael? Or both?" },
            { id = 1999014, text = "I'm sorry, I tried to help him, but I'm no fighter." },
            { id = 2061353, text = "Say Flynn, whatever happened to that woman you were always talking about?" },
            { id = 1999015, text = "There you go. Now, a toast to better days." },
            { id = 2015322, text = "Watch yourself out there!" },
            { id = 2015323, text = "What can I do you for?" },
            { id = 2015324, text = "Will it be?" },
        } },
    } },
    { who = "Venthyr Aristocrat", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3446191, text = "Hmm, I would wager you are hiding many dark secrets." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3446193, text = "It has been so long since I laid hands on a living mortal. Are you in a rush?" },
            { id = 3446199, text = "Oh look, the food can speak." },
            { id = 3446189, text = "Oh, something new." },
        } },
    } },
    { who = "Venthyr commoners", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3462455, text = "Indulge these wares. What is one more sin?" },
            { id = 3462457, text = "Revendreth can be very dangerous. Want to buy something that makes it less so?" },
            { id = 3462461, text = "The Master is watching. Always watching." },
            { id = 3462453, text = "What do you desire?" },
            { id = 3462463, text = "You make me miss my mortal body." },
            { id = 3462459, text = "You need what I have to sell you." },
        } },
    } },
    { who = "Venthyr Council Dredger Waiter", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
