    { who = "Venthyr Council Noble - feminine voice", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 3553695, text = "I shall have your essence!" },
            { id = 3553686, text = "I wield forces beyond imagining!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3553687, text = "Dear guests and vile intruders, take your places for the dance macabre!" },
            { id = 3553689, text = "Enough! Your duration, thicken me!" },
            { id = 3553696, text = "March for destruction!" },
            { id = 3553693, text = "Servants! Deal with these intruders!" },
            { id = 3553685, text = "Witness true power!" },
            { id = 3553694, text = "You were just a vessel to be drained!" },
        } },
    } },
    { who = "Venthyr Council Noble - masculine voice", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3553751, text = "EVERYONE FIND YOUR PARTNERS! OR DIE!" },
            { id = 3553749, text = "YOU ARE SLOW ON YOUR FEET!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3553744, text = "Mmm, your steps were simply delicious! Pity you have to die now..." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3553750, text = "I can dance circles around you!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 3553752, text = "Come, friends! Dance until you bleed!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3553753, text = "Everyone to the dance floor!" },
            { id = 3553742, text = "Everyone, take your positions! It is time for... The dance! MACABRA!" },
            { id = 3553748, text = "Our final song has begun! Everyone, dance until you die!" },
        } },
    } },
    { who = "Venthyr Council Warrior - masculine voice", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3553813, text = "FALL TO MY BLADE!" },
            { id = 3553812, text = "PREPARE YOURSELF FOR DEFEAT!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3553805, text = "Stop this nonsense! You have disgraced this gathering long enough!" },
            { id = 3553809, text = "You cannot escape my steel!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3553811, text = "My defense is unbreakable!" },
            { id = 3553810, text = "My technique is impervious!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3553803, text = "Attention! Set formation for the dance macabre!" },
            { id = 3553814, text = "Guards! Dispatch these intruders immediately!" },
        } },
    } },
    { who = "Venthyr Houndmaster", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 3608207, text = "BRUSH US! NO!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 3608210, text = "Your deaths will not be as quick!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 3608205, text = "None can track my steps." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3608202, text = "Barghast, rend their souls!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3608200, text = "Acutus! Here! Now!" },
            { id = 3608201, text = "Margo to me" },
            { id = 3608204, text = "Margor, make them bleed!" },
            { id = 3608206, text = "Moving in for the kill!" },
            { id = 3608208, text = "You killed my favorite!" },
            { id = 3608209, text = "You killed my sweetest friend!" },
        } },
    } },
    { who = "Venthyr Inquisitor", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 3447057, text = "Live your life wisely, or we will meet again." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3447051, text = "And what secret shall be your soul's undoing?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3447053, text = "Darkest greetings, maw walker." },
            { id = 3447047, text = "Do you seek redemption?" },
            { id = 3447049, text = "Have you come to confess?" },
            { id = 3447055, text = "What sin shall we redeem first?" },
