        { name = "Conversation", family = "Feelings", lines = {
            { id = 773859, text = "How can Orvaldin help ya?" },
            { id = 851770, text = "If we survive this, maybe someday I call you friend." },
            { id = 851774, text = "It be done! Razorheel is ours! The Warchief probably see the fires all the way from Grommash Hold." },
            { id = 851772, text = "Look at us three, back to the sands of old Durotar. It be just like old times." },
            { id = 851782, text = "Regroup! We've pressed the advantage! Before the war chief fortifies Razorheel, we take it for the revolution and claws off the road to the Barrens!" },
            { id = 851766, text = "Very well. You earn me trust. I will put me faith in the Alliance to do the right thing." },
            { id = 851786, text = "We need German!" },
            { id = 851788, text = "You set one foot in Orgrimmar, he'll scream gonna bury a knife in your neck." },
