    { who = "Vorrik", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2005648, text = "You have my gratitude for removing that infestation." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2005647, text = "I owe you my life. Meet inside the temple, it's not safe here." },
            { id = 2005652, text = "I was there when Sefralis sacrificed herself to stop Mithrax." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2005655, text = "Wait, who are these intruders? They are corrupting Sethralis!" },
