        { name = "Greetings", family = "Manners", lines = {
            { id = 2005654, text = "Ah, her sanctum should be just up ahead." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1995966, text = "Korthik raised an army of like-minded Sethrak, and they began to slaughter those who opposed them. Salthis was the first to fall, but not before safeguarding his key." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2005653, text = "If not for her, the world would have fallen to chaos." },
            { id = 2005651, text = "Must you pick at every corpse for treasure? Cephralus is our true goal." },
            { id = 2005649, text = "Now please, make haste. I sense a growing darkness taking hold of the temple." },
            { id = 2005657, text = "She sacrificed herself to stop Mithrax, but with her death, the jungles of Voldune withered to sand." },
            { id = 2005656, text = "This temple is the resting place of Sethralis, a powerful loa that protected my people from destruction long ago." },
            { id = 2005650, text = "Well, you certainly have a knack for destruction." },
        } },
    } },
