    { who = "Vulpera", tier = "creature", ctype = "Humanoid", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 2003816, text = "Ah, I will repay this debt. You have my word." },
            { id = 2003810, text = "Don't know who you are or what you want, but thanks." },
            { id = 2003815, text = "I will repay this debt. You have my word." },
