    { who = "Vulpera Military Guard F Horde", tier = "character", groups = {
        { name = "Loyalty", family = "Manners", lines = {
            { id = 3085512, text = "for the Horde." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
