    { who = "Warguard Rakera", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 2004391, text = "I have no idea what this weapon is, or where to find it, but it can't be good if Jacrazet is hiding its existence from the king." },
            { id = 2004387, text = "I told Kazuya to keep moving. We need to stop Jacrezette before it's too late." },
            { id = 2004382, text = "I write this as I sit in a cage with a dozen other exiles traveling to the sands where we will live out our days, however numbered they may be. The air, heavy with heat, tells me we're close." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 2004381, text = "We are all Acunda." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2004389, text = "It is as I suspected. General Jacrazet has troops in the desert, unbeknownst to the king." },
            { id = 2004386, text = "It's over, Jacrazette. Your plan has failed." },
            { id = 2004390, text = "They scour the dunes, searching for a weapon that can destroy the city, killing any who get in their way." },
            { id = 2004392, text = "We must find a weapon before Jacques Razzel has a chance to get his hands on it." },
            { id = 2004388, text = "We need to catch up with her. Let's go." },
        } },
    } },
    { who = "Warlord Breka Grimaxe", tier = "character", groups = {
