        { name = "Loyalty", family = "Manners", lines = {
            { id = 3583252, text = "Then we must take action. Remember that when we band together, the Horde can conquer any challenge." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3584020, text = "Fireblast takes no time to cast. Use it when your foe is already upon you." },
            { id = 3584022, text = "Good! Fireblast's instant cast makes it perfect to use in melee range. Let's practice this again!" },
            { id = 3583248, text = "Shuja, the Horde is strong, not when we fight alone, but when we stand united. Now, tell me what's happened here." },
            { id = 3584024, text = "You can cast Fire Blast instantly, making it the best option when your foe is close to you." },
