    { who = "Warren Ashton", tier = "character", groups = {
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1969901, text = "Come on! Over here! We've got work to do!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1969894, text = "Fascinating. A remarkable formulation. Very flammable." },
            { id = 1969899, text = "Inquisitor, it will be my distinct pleasure to assist you and the Lady Lucille in this task." },
            { id = 1969898, text = "Lady Lucille thinks it might be useful, I assume? Well, let's see it!" },
            { id = 1969904, text = "Ow! I believe so! Thank you, Martin." },
            { id = 1969897, text = "So I gathered. But why me?" },
