    { who = "Wrathion", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 574273, text = "Best of luck, Rogue. Whatever the outcome, you are truly a champion." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 574353, text = "I do not share my father's madness." },
            { id = 631292, text = "I had them killed. All of them." },
            { id = 574357, text = "I must remain hidden so that I remain free." },
            { id = 574271, text = "I wish I could help, but my father is the one dragon I fear." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 574267, text = "Don't underestimate my father. Even if you were to crush his body, the core of his madness and rage will still struggle to destroy you." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 574355, text = "A new era is beginning." },
            { id = 574261, text = "Dalaran? He's been hidden there this whole time." },
            { id = 631290, text = "Did you hear what happened to the rest of the Black Dragonflight?" },
            { id = 574253, text = "Excellent work, friend. You've proven that a single skilled assassin can strike a decisive blow where a whole army may fail." },
            { id = 574269, text = "He will not be defeated until he is utterly annihilated." },
            { id = 574255, text = "If you wish to continue our work, we will need some additional supplies." },
            { id = 574257, text = "Incredible! Few assassins would be clever enough to infiltrate Nalis' wards and use her own magic against her." },
            { id = 574259, text = "Perhaps. For that reason, we will need to gather more supplies." },
            { id = 574275, text = "That's right, mortal. The prize you seek no longer sleeps within a shell. Here I am, in the flesh." },
            { id = 574265, text = "There's no need to worry, Farad. This next mission is, quite likely, suicide." },
            { id = 631288, text = "This is an awfully one-sided conversation." },
            { id = 574263, text = "You slew him right in the purple parlor? Incredible. Simply incredible." },
        } },
    } },
    { who = "Wrathiondrake", tier = "character", groups = {
        { name = "Boasts", family = "Menace", lines = {
            { id = 4709552, text = "I am beginning to understand what drove my father mad." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4709537, text = "Azeroth faces many threats." },
            { id = 4709550, text = "Be careful who you make fun of in Pandaria" },
            { id = 4709536, text = "Every action has consequences." },
            { id = 4709535, text = "The Black Dragonflight will be redeemed." },
            { id = 4709551, text = "You do realize I am a dragon, yes? That I can breathe fire? Just make a sure." },
        } },
    } },
    { who = "Wrath-Scryer Soccothrates", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 603047, text = "HYAH!" },
            { id = 603056, text = "RRRAAAGH!" },
            { id = 603044, text = "YEAH!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 564695, text = "Yes, that was quite satisfying." },
