    { who = "Xuen", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 852201, text = "Ah, the young black dragon graces my temple. The deeds of you and your champion are quickly becoming Pandaren legend." },
            { id = 852197, text = "Black Prince, you are very strong, but what good is strength without the vision to guide it?" },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 852181, text = "Seek out your true enemy. Do not be fooled by his false images." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 852187, text = "Stay behind your foe. He cannot see you. Move quickly." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 626577, text = "Welcome." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 852191, text = "The elements will not die. Make use of your time before they rise again." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 852185, text = "Disarm him if you can. Use every advantage." },
            { id = 852189, text = "Dodge his attacks! Use his strength against him!" },
            { id = 626571, text = "Good travels." },
            { id = 852193, text = "Let the challenge begin. Hero, you must defeat the Black Prince in close quarters combat." },
            { id = 626581, text = "Mmm, yes." },
            { id = 626569, text = "Remember, strength comes in many forms." },
            { id = 626579, text = "Show me your strength." },
            { id = 626587, text = "Strength is more than how hard you hit, your strikes must have control and purpose." },
            { id = 852203, text = "Tell me, young prince, what is the nature of strength?" },
            { id = 626573, text = "Test your might." },
            { id = 852183, text = "The dragon is stronger than you, hero. Do not let him finish his attacks." },
            { id = 626589, text = "You can also just go for the groin." },
            { id = 626585, text = "You must have the mastery to move where you choose to move, and the wit to move before your opponent." },
            { id = 852195, text = "You, Wrathion, will be blindfolded." },
        } },
    } },
    { who = "Xykaz", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4280094, text = "You are too late! Zymox has already..." },
            { id = 4280062, text = "You will keep Progenitor's secrets no longer!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4280090, text = "I will break into it again, but first I will break you!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4280083, text = "A scrap of this power is worth more than all of you!" },
            { id = 4280059, text = "Cartel Al! You sit upon a wealth of knowledge and do nothing!" },
        } },
    } },
    { who = "Xymox", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4291869, text = "You cannot even control where you stand!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4291865, text = "Ephemera is unbridled power!" },
            { id = 4291868, text = "Gravity bends to my will!" },
            { id = 4291860, text = "Haha! Your agony amuses me!" },
            { id = 4291835, text = "Maw Walker, is there no end to your incessant hounding?" },
            { id = 4291862, text = "Minions, secure the artifact!" },
            { id = 4291867, text = "Only I command this, Emera!" },
            { id = 4291861, text = "Reveal your secrets to me!" },
            { id = 4291864, text = "There is no limit to the wealth I can obtain!" },
            { id = 4291859, text = "This stasis field should keep you busy!" },
            { id = 4291863, text = "What wonders! I want more!" },
            { id = 4291866, text = "You should appreciate my artistry!" },
        } },
    } },
    { who = "Xynam", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 4075536, text = "IT IS OUT OF CONTROL!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4075535, text = "Cartel's eye is not responsible for any loss of limb that occurs during this demonstration." },
            { id = 4075534, text = "Someone is stealing the merchandise! Stop her!" },
            { id = 4075532, text = "What? More chaos?" },
            { id = 4075533, text = "With controls this easy, even a dredger could do it!" },
        } },
    } },
    { who = "Xynoc", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 4075551, text = "Now for the item you have all been awaiting, the allegedly demon-cursed edge of oblivion!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 4075553, text = "Wait, how did that beast escape from its cage?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 4075549, text = "Imbecile! Turn it off!" },
            { id = 4075558, text = "Oh no! The axe has possessed her! Take cover!" },
            { id = 4075557, text = "Our rampaging beasts, ruining your day. We have the solution!" },
            { id = 4075555, text = "Our signature is a fair trade, especially if it results in your departure." },
            { id = 4075556, text = "Someone stop that outlaw! This is a disaster!" },
            { id = 4075550, text = "Thank you all! That concludes our demonstration!" },
            { id = 4075548, text = "Watch as my assistant activates this Bastion Centurion for maximum destruction!" },
            { id = 4075552, text = "We'll start the bidding at five thousand. Do I hear five thousand? I hear five six thousand. Yes, six!" },
            { id = 4075554, text = "You saved our menagerie. Well, what is left of it?" },
        } },
    } },
