        { name = "Farewells", family = "Manners", lines = {
            { id = 626635, text = "Farewell." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 626637, text = "Keep the shadows at bay." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 626671, text = "Even the light can run out of patience." },
            { id = 626661, text = "How may I help you?" },
            { id = 626659, text = "May the light guide you." },
            { id = 626685, text = "Our duties await." },
            { id = 626681, text = "Our enemies shall fall before us." },
            { id = 1411464, text = "This cage may be strong, but remember, a Murloc's mind is weak and easily controlled." },
            { id = 626669, text = "What is it?" },
            { id = 626683, text = "You lead, I'll follow." },
        } },
    } },
    { who = "Yazma", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1860206, text = "I WILL TEAR YOUR SOUL APART!" },
            { id = 1860207, text = "LET YOUR SOUL BE SHATTERED!" },
            { id = 1860205, text = "YOUR SOUL IS MINE!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1860208, text = "Dazar will awaken soon, but you will not live to see it!" },
            { id = 1860247, text = "My thanks for killing the priestess. You have only succeeded in strengthening my hold on the temple." },
            { id = 1860204, text = "Now you are under my power!" },
            { id = 1860248, text = "Rezan was a powerful Loa. Perhaps you will make a worthy sacrifice for Zul." },
            { id = 1860210, text = "You have made a fine sacrifice!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1860212, text = "I will put your blood to good use, now that you no longer need it." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 1860209, text = "Fools, the world will rip your spirits apart!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1860246, text = "Impressive. You made it farther than I thought, but I will still be drinking your blood." },
            { id = 1860211, text = "Your blood is mine!" },
        } },
    } },
    { who = "Ymiron the Fallen King", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1274919, text = "COWER BEFORE ME!" },
            { id = 1274933, text = "Not again! THE BARON CASHED THEIR SOULS INTO THE TIMES!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1274927, text = "You have not won! The naggle far comes for you!" },
            { id = 1274931, text = "You have not won! You have only secured your own doom!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1274935, text = "Another drop in the Sea of Souls!" },
            { id = 1274917, text = "The shadows of Helheim cut deeper than steel!" },
            { id = 1274915, text = "The shadows of the underworld bend to me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1274925, text = "Know the bitter chill of death as I have!" },
            { id = 1274929, text = "The winds of the frozen north still howl in these veins!" },
        } },
    } },
    { who = "Yoggsaron", tier = "character", groups = {
