    { who = "Yorah", tier = "character", groups = {
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3488616, text = "Divine Shield will protect you against the altar's dark magic." },
            { id = 3488614, text = "Light be with you, brave paladin." },
