    { who = "Yotnar", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1241995, text = "I hope you are ready to face your first trial, outsider." },
            { id = 1241961, text = "The gods will not tolerate your actions, Raikou. You will answer for your heresy!" },
            { id = 1242005, text = "You have passed the trial of might, outsider. Seek me at the vault's entrance and I will grant you the blessing of the Watchers." },
            { id = 1242007, text = "You have shown true valor today, and for this I shall grant you a boon." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1241997, text = "As the keeper of this vault, it is my duty to test the might of those who wish to proceed." },
            { id = 1241973, text = "If you wish to claim the Aegis, seek these ancient rulers and prove to them your merit." },
            { id = 1241975, text = "Only those deemed worthy shall pass the trial of valor." },
            { id = 1241991, text = "Seek their blessing to pass the trial of will." },
            { id = 1242003, text = "That is enough, outsider!" },
            { id = 1241987, text = "The foreign year are the oldest and wisest dragons in Stormheim." },
            { id = 1241989, text = "To fly with them is to sail amongst the gods themselves." },
        } },
    } },
    { who = "Yrel", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1055673, text = "FOR THE LIGHT!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1055670, text = "It is over. Their defenses are shattered. We have won this battle, but without the artifact we have far to go. Let us rally back at your garrison, Commander. We must plan our next course of attack." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1055676, text = "Why did you join us, Calia? If we are such an inconvenience, why not leave us to our own devices, hm?" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1055677, text = "Perhaps we should deprive them of their allies. The ogres here in Nagrand are vulnerable now." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1055667, text = "Brace yourself, champion! The light is with you! I will not let you fall!" },
            { id = 1055672, text = "Phelan? What are you doing here?" },
            { id = 1055675, text = "Prophet Velen trusted me to turn the iron horde from Kerabore. I can handle the jungle!" },
            { id = 1055668, text = "The artifact! What has he done?! We must restore it! We must get it to safety!" },
            { id = 1055674, text = "We do not fear you!" },
            { id = 1055671, text = "We should have brought an army to fight the Iron Horde." },
            { id = 1055666, text = "We will never surrender to you! Champion, now is the time. Use the artifact!" },
        } },
    } },
    { who = "Yrgrim the Truthseeker", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 1390378, text = "I am beaten. You are indeed worthy. Were Tyr alive, he would make you his champion. I hereby bestow Truthguard upon you. Use it to defend Azeroth from its enemies." },
            { id = 1390369, text = "I am Yirgrim, champion of Tyr. Let us see if you are worthy to bear his shield." },
            { id = 1390368, text = "I bid you greetings, opener of doors. You are the first." },
            { id = 1388640, text = "You are shorter than I expected." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1390379, text = "I am weary. With a worthy successor, my long vigil is at an end. Fight for Truth and Justice, champion. In Tyr's name." },
            { id = 1390372, text = "I have not faced so noble a challenger in millennia!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 1388639, text = "Hail, Seeker of Truth!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1390373, text = "A good start! You'll fight well!" },
            { id = 1390371, text = "Let us begin!" },
            { id = 1388641, text = "Let us talk." },
            { id = 1390370, text = "Long have I waited for one who proves worthy. Face me in battle, that we might test your heart." },
        } },
    } },
    { who = "Ysera", tier = "character", groups = {
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 564892, text = "AAARGH!" },
            { id = 564893, text = "AHHH!" },
            { id = 564897, text = "HA!" },
            { id = 564896, text = "HAH!" },
            { id = 564906, text = "YEAH!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1241301, text = "Fighting this is futile, hero! None can resist the master!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1241311, text = "Kill these intruders, my children! Your queen commands it!" },
            { id = 1241303, text = "Strike now focus on the night elves champion" },
        } },
        { name = "Pain", family = "Hurt and dying", lines = {
            { id = 564890, text = "OH!" },
            { id = 564895, text = "OW!" },
            { id = 564891, text = "UGH!" },
        } },
        { name = "Falling in battle", family = "Hurt and dying", lines = {
            { id = 564888, text = "He was the Earthen Ring's most powerful shaman, and the ceremony cannot continue without him. But we must be prepared to accept that he may be lost forever." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 564900, text = "Welcome, son of Durotan, and to you, Agralan of the Frostwolves." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 564905, text = "For the first time, the Earthen Ring and the Cenarion Circle will unite to restore this great tree, thereby healing the whole of Azeroth." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1241315, text = "Breathe deep, hero! Taste the essence of the Emerald Nightmare!" },
            { id = 564894, text = "Friends, we have gathered here today to heal this world that we've sacrificed so much to save." },
            { id = 572876, text = "Much remains to be done." },
            { id = 1241305, text = "Press onward, demons! Destroy the temple!" },
            { id = 1241309, text = "Slay the night elves and their champion! Water the land with blood!" },
            { id = 572878, text = "The dream gives us shelter, the dream gives us hope." },
            { id = 572874, text = "The dreamer has awoken." },
            { id = 1241313, text = "To me, my flight! Eradicate these pests!" },
        } },
    } },
    { who = "Ysondre", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1349979, text = "ALL WILL SECUMB TO THE NIGHTMARE!" },
            { id = 1349971, text = "NO ONE RESISTS THE NIGHTMARE!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 1349963, text = "Come forth, dreamers, and claim your vengeance!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1349961, text = "At last, the long dream comes." },
            { id = 1349972, text = "Give yourself over as I did!" },
            { id = 1349978, text = "It fades. It all fades away." },
            { id = 1349973, text = "The nightmare is inescapable." },
            { id = 1349977, text = "The strands of life have been severed! The dreamers must be avenged!" },
        } },
    } },
    { who = "Ytekhi", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 5833963, text = "KA-HET IS KOR-VAN" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 5833973, text = "Don't panic, it's just me." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 5833969, text = "Look what the Weave brought!" },
            { id = 5833965, text = "May your threads hold strong." },
            { id = 5833971, text = "We meet again!" },
            { id = 5833967, text = "We've protect you." },
        } },
    } },
    { who = "Yulon", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 852235, text = "Ah, the dragon child and the hero. Together you will achieve great things." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 626783, text = "I will guide your way." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 852233, text = "Seek out your true enemy. Do not be fooled by his false images." },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 852245, text = "Come forward, I will give you my blessing." },
            { id = 852231, text = "Do not allow the elements to engage you." },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 626779, text = "Greetings, little one." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 626775, text = "Farewell, little one." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 852225, text = "The elements are undying. Make use of your time before they rise again." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 852229, text = "Be aware of your surroundings." },
            { id = 852241, text = "But true wisdom comes from knowing what is right and sometimes doing nothing at all." },
            { id = 852247, text = "Let the challenge begin. Hero, you must defeat the Black Prince in combat." },
            { id = 626781, text = "May joy be in your heart." },
            { id = 626771, text = "May your journey be joyful." },
            { id = 852239, text = "Spoken like a true child of the aspects, always seeking to change the world." },
            { id = 852237, text = "Tell me, dragon child, what is the nature of wisdom?" },
            { id = 852243, text = "To learn that is to learn true wisdom." },
            { id = 852227, text = "Use movement to your advantage. Do not allow the dragon child to get close." },
            { id = 626773, text = "Wisdom guide your path." },
        } },
    } },
    { who = "Zabra Hexx", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1411966, text = "GIVE INTO MADNESS!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1411967, text = "Your will is mine to bend!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 1416801, text = "I choose to believe that fate has brought us together." },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 1411969, text = "You're no match for my power!" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 1411968, text = "The shadows claim you!" },
            { id = 1411965, text = "The shadows guide me!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 1411970, text = "Death takes you!" },
            { id = 1412030, text = "I'll be alright." },
            { id = 1411462, text = "It feels like these pawns of mine haven't moved in years. Come, let's find some place to talk where we won't be caught by a basilisk's gaze." },
            { id = 1412029, text = "It's only a little pain. I'll catch up!" },
            { id = 1412031, text = "Ugh, death. Ah, old friend. Not today." },
        } },
    } },
    { who = "Zaela", tier = "character", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 900143, text = "FOR THE TRUE HEARD!" },
