            { id = 5017672, text = "Shh! I took on a more mature visage form to do business! Please don't blow my cover!" },
            { id = 5014840, text = "So long, friend!" },
            { id = 5017663, text = "Ugh! Wait... ...Senegos? What are you doing all the way out here?" },
