    { who = "Zevkall", tier = "character", groups = {
        { name = "Threats", family = "Menace", lines = {
            { id = 5782058, text = "I noticed you trying to defend your own obsolescence, you dusty agent!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 5768078, text = "My orders were clear, and yet more Overcrawlers regularly slipped from our grasp." },
