        { name = "Conversation", family = "Feelings", lines = {
            { id = 5768083, text = "And if you breathe a word of this to anyone, you're next." },
            { id = 5768082, text = "Clean up this refuse and get it out of my sight!" },
            { id = 5768080, text = "Failure. Unacceptable. Not only does this shame you, it shames me." },
            { id = 5768081, text = "Which means no one will hear of it." },
        } },
    } },
