        { name = "Victory", family = "Fighting", lines = {
            { id = 6179472, text = "That was you?" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 6178555, text = "How's about a tour?" },
            { id = 6178615, text = "Imagine how much black blood that baby has dug up, am I right?" },
            { id = 6178585, text = "Let me just clock out over here." },
            { id = 6178461, text = "Meet me by the South Gate, friend. I'll clock out and clue you in." },
            { id = 6178618, text = "Oh, it's, uh, it's low on coolant." },
            { id = 6178627, text = "Okay, let's go!" },
            { id = 6178612, text = "On your left, Venture's new Mach 78 Black Blood Extractor. Whoo! Give it a whirl!" },
            { id = 6178588, text = "So let's get what you need, eh? I accept gold as a tip. You know, if my info's useful." },
