-- fileDataId -> text, for showing what a pinned line says without walking the
-- lists. Built once at load because the panel asks per row, per refresh.
GameVoices.ById = {}
-- fileDataId -> who says it.
GameVoices.SpeakerById = {}
-- How many lines the catalogue holds, for /toa voice to report.
GameVoices.COUNT = 0

for _, char in ipairs(GameVoices.Characters) do
    char.count = 0
    for _, group in ipairs(char.groups) do
        char.count = char.count + #group.lines
        for _, entry in ipairs(group.lines) do
            GameVoices.ById[entry.id] = entry.text
            GameVoices.SpeakerById[entry.id] = char.who
        end
    end
    GameVoices.COUNT = GameVoices.COUNT + char.count
end

-- Walk every line, optionally narrowed to one speaker and/or one group. The
-- single place that knows the shape of the table, so the filters below cannot
-- disagree with each other about it.
local function each(who, group, fn, family)
    for _, char in ipairs(GameVoices.Characters) do
        if not who or who == "" or char.who == who then
            for _, g in ipairs(char.groups) do
                if (not group or group == "" or g.name == group)
                    and (not family or family == ""
                         or (g.family or "Other") == family) then
                    for _, entry in ipairs(g.lines) do
                        if fn(entry, char, g) then return end
                    end
                end
            end
        end
    end
end

-- The group picker offers families and groups in one list, so what comes back
-- from it may be either. Splitting it here means no caller has to know which
-- level the player clicked. A bare name with no prefix is read as a group,
-- which is what every older caller passes.
local function selector(sel)
    if type(sel) ~= "string" or sel == "" then return nil, nil end
    local kind, name = sel:match("^(%a+):(.*)$")
    if kind == "family" then return nil, name end
    if kind == "group" then return name, nil end
    return sel, nil
end

-- Everyone with lines, in the order they are listed.
function GameVoices.Speakers()
    local out = {}
    for _, char in ipairs(GameVoices.Characters) do
        out[#out + 1] = { who = char.who, count = char.count }
    end
    return out
end

-- The groups one speaker has, in the order the generator put them. Asking for
-- nobody in particular merges them, so the picker can still offer "all the
-- battle cries in the game" before you have chosen a character.
function GameVoices.Groups(who)
    local out, seen = {}, {}
    for _, char in ipairs(GameVoices.Characters) do
        if not who or who == "" or char.who == who then
            for _, g in ipairs(char.groups) do
                local at = seen[g.name]
                if at then
                    out[at].count = out[at].count + #g.lines
                else
                    out[#out + 1] = { name = g.name, count = #g.lines }
                    seen[g.name] = #out
                end
            end
        end
    end
    return out
end

-- Thirty-one headings is more than anyone reads down, so they collapse into
-- seven families and browsing goes family -> group -> line. Counts come along
-- because a family with four lines in it should look different from one with
-- four hundred before you click it.
function GameVoices.Families(who)
    local out, seen = {}, {}
    for _, char in ipairs(GameVoices.Characters) do
        if not who or who == "" or char.who == who then
            for _, g in ipairs(char.groups) do
                local fam = g.family or "Other"
                local at = seen[fam]
                if at then
                    out[at].count = out[at].count + #g.lines
                else
                    out[#out + 1] = { name = fam, count = #g.lines }
                    seen[fam] = #out
                end
            end
        end
    end
    return out
end

-- Blizzard's race token -> the name this table files that race under. Keyed on
-- the token rather than the localised name so it still matches on a client
-- running in another language.
local RACE_TOKEN = {
    Human = "Human", Orc = "Orc", Dwarf = "Dwarf", NightElf = "Night Elf",
    Scourge = "Forsaken", Undead = "Forsaken", Tauren = "Tauren",
    Gnome = "Gnome", Troll = "Troll", Goblin = "Goblin",
    BloodElf = "Blood Elf", Draenei = "Draenei", Worgen = "Worgen",
    Pandaren = "Pandaren", Nightborne = "Nightborne", VoidElf = "Void Elf",
    HighmountainTauren = "Highmountain Tauren",
    LightforgedDraenei = "Lightforged Draenei",
    ZandalariTroll = "Zandalari Troll", KulTiran = "Kul Tiran",
    DarkIronDwarf = "Dark Iron Dwarf", Vulpera = "Vulpera",
    MagharOrc = "Mag'har Orc", Mechagnome = "Mechagnome",
    Dracthyr = "Dracthyr", EarthenDwarf = "Earthen", Earthen = "Earthen",
}

-- The voices the logged-in character actually uses, so the browser can open on
-- them instead of on a wall of fifty-seven speakers. Matched on race and body
-- type, not on the display name: the name is written to be read, and matching
-- against prose is how a rename quietly breaks a filter.
--
-- Returns an empty list for a race with no recordings, which the caller shows
-- as "no lines for your race" rather than as an empty browser.
function GameVoices.MyVoices()
    local out = {}
    if type(UnitRace) ~= "function" then return out end
    local _, token = UnitRace("player")
    local race = RACE_TOKEN[token or ""]
    if not race then return out end

    local sex = type(UnitSex) == "function" and UnitSex("player") or nil
    sex = (sex == 3 and "female") or (sex == 2 and "male") or nil

    for _, char in ipairs(GameVoices.Characters) do
        if char.race == race and (not sex or char.sex == sex) then
            out[#out + 1] = char.who
        end
    end
    return out
end

-- One flat list for the group picker, read as two levels: each family, then
-- its own groups indented under it. Flat because the control is a dropdown,
-- indented because seven families and thirty-one groups are not the same kind
-- of choice and should not look like one.
--
-- Entries carry a prefixed id so the caller can tell which level was picked
-- without matching the label back against a list of family names.
function GameVoices.BrowseList(who)
    local famCount, groupCount = {}, {}
    for _, char in ipairs(GameVoices.Characters) do
        if not who or who == "" or char.who == who then
            for _, g in ipairs(char.groups) do
                local fam = g.family or "Other"
                famCount[fam] = (famCount[fam] or 0) + #g.lines
                groupCount[fam] = groupCount[fam] or {}
                groupCount[fam][g.name] = (groupCount[fam][g.name] or 0) + #g.lines
            end
        end
    end

    local out = {}
    for _, fam in ipairs(GameVoices.FAMILY_ORDER) do
        if famCount[fam] then
            out[#out + 1] = { id = "family:" .. fam, level = 1,
                label = string.format("%s (%d)", fam, famCount[fam]) }
            local mine = groupCount[fam]
            local listed = {}
            for _, g in ipairs(GameVoices.GROUP_ORDER) do
                if mine[g] then
                    listed[g] = true
                    out[#out + 1] = { id = "group:" .. g, level = 2,
                        label = string.format("    %s (%d)", g, mine[g]) }
                end
            end
            -- A group the order list has never heard of still appears, after
            -- its siblings, so a new heading from a changed classifier is
            -- visible rather than silently unreachable.
            for g, n in pairs(mine) do
                if not listed[g] then
                    out[#out + 1] = { id = "group:" .. g, level = 2,
                        label = string.format("    %s (%d)", g, n) }
                end
            end
        end
    end
    return out
end

-- Which shelf a speaker sits on, and who is on a given shelf. Two questions
-- rather than one nested list, because they are two decisions: a player
-- narrows to a kind of speaker first, and only then reads names. Nesting them
-- in one control means scrolling past every heading to reach the one you want.
--
-- The shelves are not invented here. Which of them a speaker belongs on gets
-- decided when its name is decided, in tools/naming.ps1, and the creature
-- types are World of Warcraft's own -- the word already printed on the
-- tooltip, not a scheme a player has to learn from this addon.
GameVoices.TIER_ORDER = { "player", "character", "creature" }
GameVoices.TIER_LABEL = {
    -- Every playable race, not only the one you rolled. "Your voice" below is
    -- the narrower question and gets a shelf of its own.
    player    = "Player races",
    character = "Named characters",
    creature  = "Creatures and peoples",
}
GameVoices.CTYPE_ORDER = {
    "Humanoid", "Beast", "Undead", "Demon", "Dragonkin",
    "Elemental", "Giant", "Mechanical", "Aberration", "Critter",
}
-- Creature buckets that name a trade rather than a creature -- Guards,
-- Pirates, Mages. They are a real answer to "who do I want to sound like",
-- so they get a shelf instead of being left at the bottom untitled.
local NO_CTYPE = "Roles and trades"
GameVoices.MINE = "mine"

local function categoryOf(char)
    local tier = char.tier or "character"
    if tier == "creature" then return "creature/" .. (char.ctype or NO_CTYPE) end
    return tier
end

local function categoryLabel(key)
    local ct = key:match("^creature/(.+)$")
    if ct then return ct end
    return GameVoices.TIER_LABEL[key] or key
end

local function mineSet()
    local mine = {}
    for _, who in ipairs(GameVoices.MyVoices()) do mine[who] = true end
    return mine
end

-- The categories that actually have somebody in them, in a stated order. A
-- shelf with nothing on it is not offered: an empty choice in a picker is a
-- dead end that looks like a live one.
--
-- "Your voice" leads and deliberately repeats what is also under Player
-- races. It is the shelf most people open this window for, and making them
-- find their own race among fifty-seven others to save a duplicate entry is a
-- trade in the wrong direction.
function GameVoices.Categories()
    local n, order = {}, {}
    local mine, mineN = mineSet(), 0
    for _, char in ipairs(GameVoices.Characters) do
        if char.count > 0 then
            if mine[char.who] then mineN = mineN + 1 end
            local k = categoryOf(char)
            if not n[k] then order[#order + 1] = k n[k] = 0 end
            n[k] = n[k] + 1
        end
    end

    local out, taken = {}, {}
    local function take(key, label)
        if n[key] and not taken[key] then
            taken[key] = true
            out[#out + 1] = { id = key, n = n[key],
                label = string.format("%s (%d)", label or categoryLabel(key), n[key]) }
        end
    end

    if mineN > 0 then
        out[#out + 1] = { id = GameVoices.MINE, n = mineN,
            label = string.format("Your voice (%d)", mineN) }
    end
    for _, tier in ipairs(GameVoices.TIER_ORDER) do
        if tier == "creature" then
            for _, ct in ipairs(GameVoices.CTYPE_ORDER) do take("creature/" .. ct) end
            take("creature/" .. NO_CTYPE)
            -- A type the order list has never heard of still appears, so a new
            -- one from a changed classifier is visible rather than unreachable.
            for _, key in ipairs(order) do
                if key:find("^creature/") then take(key) end
            end
        else
            take(tier)
        end
    end
    for _, key in ipairs(order) do take(key) end
    return out
end

-- Who is on one shelf, narrowed by anything typed in the search box.
--
-- Ordered by how much a speaker can say, because with thousands of them the
-- question "who is worth picking" is answered by that and by nothing else.
-- Alphabetical puts Aargoss and his twelve lines above Sylvanas and her two
-- hundred and seventy-nine, which is a list sorted for the file rather than
-- for the person reading it. Ties fall back to the name so the order is
-- stable between builds.
function GameVoices.SpeakerList(category, query)
    local words = {}
    for w in tostring(query or ""):lower():gmatch("%S+") do words[#words + 1] = w end

    local cat = category or ""
    local mine = (cat == GameVoices.MINE) and mineSet() or nil

    local out = {}
    for _, char in ipairs(GameVoices.Characters) do
        if char.count > 0 then
            local here = (cat == "")
                or (mine and mine[char.who])
                or (not mine and categoryOf(char) == cat)
            if here then
                local keep = true
                local hay = char.who:lower()
                for _, w in ipairs(words) do
                    if not hay:find(w, 1, true) then keep = false break end
                end
                if keep then
                    out[#out + 1] = { who = char.who, count = char.count,
                        category = categoryOf(char),
                        label = string.format("%s (%d)", char.who, char.count) }
                end
            end
        end
    end

    table.sort(out, function(x, y)
        if x.count ~= y.count then return x.count > y.count end
        return x.who < y.who
    end)
    return out
end

-- Browsing, not searching. A catalogue this size is navigated by narrowing --
-- pick a category, pick a speaker, pick a kind of line -- because guessing a
-- word that might appear in a line you have never read is not a way to find
-- anything. The query is an extra sieve on top, for when you do know.
--
-- The query matches the speaker as well as the line, which is what lets a
-- half-remembered name work: "artha" finds Arthas by name even though none of
-- his lines contain the word.
function GameVoices.Filter(opts)
    opts = opts or {}
    local limit = opts.limit or 5000
    local words = {}
    for w in tostring(opts.query or ""):lower():gmatch("%S+") do words[#words + 1] = w end

    local group, family = selector(opts.group)
    local out, truncated = {}, false
    each(opts.who, group, function(entry, char, g)
        local keep = true
        if #words > 0 then
            local hay = entry.text:lower() .. " " .. char.who:lower()
            for _, w in ipairs(words) do
                if not hay:find(w, 1, true) then keep = false break end
            end
        end
        if keep then
            out[#out + 1] = { id = entry.id, text = entry.text,
                              who = char.who, group = g.name }
            if #out >= limit then truncated = true return true end
        end
    end, family)
    return out, truncated
end

-- Plain words, no facets. Kept because "find me the line with this in it" is
-- still worth one call when you already know the words.
function GameVoices.Search(query, limit)
    return GameVoices.Filter{ query = query, limit = limit }
end
